import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Stamp {
  id: string;
  originalX: number;
  originalY: number;
  width: number;
  height: number;
  dataUrl: string; // The cutout transparent image
  isExcluded: boolean;
  // For editor state
  scale: number;
  offsetX: number;
  offsetY: number;
}

export interface MetaData {
  stampNameJa: string;
  stampDescJa: string;
  stampNameEn: string;
  stampDescEn: string;
}

export enum AppStep {
  UPLOAD = 'UPLOAD',
  PROCESSING = 'PROCESSING',
  EDIT = 'EDIT',
  EXPORT = 'EXPORT',
}

export interface ProcessedResult {
  stamps: Stamp[];
  originalWidth: number;
  originalHeight: number;
}

export const TARGET_WIDTH = 370;
export const TARGET_HEIGHT = 320;
export const MAIN_WIDTH = 240;
export const MAIN_HEIGHT = 240;
export const TAB_WIDTH = 96;
export const TAB_HEIGHT = 74;

import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';

/**
 * Main function to process the uploaded image.
 * 1. Estimates background color.
 * 2. Removes background (Flood fill).
 * 3. Detects individual stamp blobs.
 * 4. Extracts them into Stamp objects.
 */
export async function processUploadedImage(file: File): Promise<{ stamps: Stamp[], width: number, height: number }> {
  const img = await loadImage(file);
  const canvas = document.createElement('canvas');
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Could not get canvas context');

  ctx.drawImage(img, 0, 0);
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

  // 1 & 2. Remove Background
  const processedImageData = removeBackground(imageData);
  ctx.putImageData(processedImageData, 0, 0);

  // 3 & 4. Detect and Extract Stamps
  const stamps = extractStamps(processedImageData, canvas);

  return {
    stamps,
    width: img.width,
    height: img.height,
  };
}

function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = URL.createObjectURL(file);
  });
}

function removeBackground(imageData: ImageData): ImageData {
  const { width, height, data } = imageData;
  // Sample corners to find background color
  const corners = [
    0, // Top-left
    (width - 1) * 4, // Top-right
    (height - 1) * width * 4, // Bottom-left
    (height * width - 1) * 4 // Bottom-right
  ];

  // Use Top-Left as primary reference for simplicity in this MVP
  // Ideally we would cluster colors, but usually top-left is background.
  const bgR = data[0];
  const bgG = data[1];
  const bgB = data[2];
  // const bgA = data[3];

  const tolerance = 40; // Color distance tolerance

  // Flood fill algorithm to remove continuous background
  // We use a stack-based approach
  const stack: [number, number][] = [];
  const visited = new Uint8Array(width * height);

  // Start from all edges to catch background that surrounds stamps
  for (let x = 0; x < width; x++) {
    stack.push([x, 0]);
    stack.push([x, height - 1]);
  }
  for (let y = 0; y < height; y++) {
    stack.push([0, y]);
    stack.push([width - 1, y]);
  }

  const getIdx = (x: number, y: number) => (y * width + x) * 4;
  const colorMatch = (idx: number) => {
    const r = data[idx];
    const g = data[idx + 1];
    const b = data[idx + 2];
    const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
    return diff < tolerance * 3;
  };

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;
    if (x < 0 || x >= width || y < 0 || y >= height) continue;
    if (visited[y * width + x]) continue;

    const idx = getIdx(x, y);

    // If it's already transparent, consider it visited but don't stop (unless we want to?)
    // If it matches background color, make it transparent and continue
    if (colorMatch(idx)) {
      data[idx + 3] = 0; // Set Alpha to 0
      visited[y * width + x] = 1;

      stack.push([x + 1, y]);
      stack.push([x - 1, y]);
      stack.push([x, y + 1]);
      stack.push([x, y - 1]);
    }
  }

  return imageData;
}

function extractStamps(imageData: ImageData, sourceCanvas: HTMLCanvasElement): Stamp[] {
  const { width, height, data } = imageData;
  const visited = new Uint8Array(width * height);
  const boxes: { x: number, y: number, w: number, h: number }[] = [];

  // Iterate to find islands of non-transparent pixels
  for (let y = 0; y < height; y+=4) { // Skip lines for speed optimization
    for (let x = 0; x < width; x+=4) {
      const idx = (y * width + x) * 4;
      if (data[idx + 3] > 0 && !visited[y * width + x]) {
        // Found a solid pixel, flood fill to find the bounding box of this component
        const box = findBoundingBox(x, y, width, height, data, visited);
        if (box.w > 20 && box.h > 20) { // Filter tiny noise
           boxes.push(box);
        }
      }
    }
  }

  // Merge overlapping boxes (simple heuristic)
  const mergedBoxes = mergeBoxes(boxes);

  // Sort boxes (Grid order: Top-to-bottom, then Left-to-right)
  // We cluster by Y to define "rows"
  mergedBoxes.sort((a, b) => a.y - b.y);

  // Simple row clustering
  const rows: typeof mergedBoxes[] = [];
  let currentRow: typeof mergedBoxes = [];
  let lastY = -1000;

  mergedBoxes.forEach(box => {
    // If the top of this box is significantly lower than the last one, new row
    if (currentRow.length === 0) {
      currentRow.push(box);
      lastY = box.y;
    } else {
      const yDiff = Math.abs(box.y - lastY);
      if (yDiff < box.h / 2) { // Same row if Y aligns roughly
        currentRow.push(box);
      } else {
        rows.push(currentRow);
        currentRow = [box];
        lastY = box.y;
      }
    }
  });
  if (currentRow.length > 0) rows.push(currentRow);

  // Flatten and sort each row by X
  const sortedBoxes = rows.flatMap(row => row.sort((a, b) => a.x - b.x));

  // Create Stamp objects
  return sortedBoxes.map((box, index) => {
    // Cutout the image
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = box.w;
    tempCanvas.height = box.h;
    const tCtx = tempCanvas.getContext('2d');

    // Draw only the specific region
    tCtx?.drawImage(sourceCanvas, box.x, box.y, box.w, box.h, 0, 0, box.w, box.h);

    // Fit into 370x320 logic is handled in the UI/Editor generally, 
    // but here we just store the clean cutout.
    // However, to make it ready for "default view", let's create a nice centered version.
    // For the raw dataUrl, we keep the tight crop so the user can position it.

    return {
      id: `stamp-${index}`,
      originalX: box.x,
      originalY: box.y,
      width: box.w,
      height: box.h,
      dataUrl: tempCanvas.toDataURL('image/png'),
      isExcluded: false,
      scale: 1, // Default scale
      offsetX: 0,
      offsetY: 0
    };
  });
}

function findBoundingBox(startX: number, startY: number, w: number, h: number, data: Uint8ClampedArray, visited: Uint8Array) {
  let minX = startX, maxX = startX, minY = startY, maxY = startY;
  const stack = [[startX, startY]];
  visited[startY * w + startX] = 1;

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;

    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;

    // Check 4 neighbors
    const neighbors = [
      [x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]
    ];

    for (const [nx, ny] of neighbors) {
      if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
        if (!visited[ny * w + nx]) {
           const idx = (ny * w + nx) * 4;
           if (data[idx + 3] > 10) { // If visible
             visited[ny * w + nx] = 1;
             stack.push([nx, ny]);
           }
        }
      }
    }
  }

  return { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

function mergeBoxes(boxes: { x: number, y: number, w: number, h: number }[]) {
  // Simple intersection merge O(N^2) - okay for N < 100
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < boxes.length; i++) {
      for (let j = i + 1; j < boxes.length; j++) {
        const a = boxes[i];
        const b = boxes[j];
        if (rectIntersect(a, b)) {
          // Merge b into a
          const newX = Math.min(a.x, b.x);
          const newY = Math.min(a.y, b.y);
          const newMaxX = Math.max(a.x + a.w, b.x + b.w);
          const newMaxY = Math.max(a.y + a.h, b.y + b.h);

          boxes[i] = { x: newX, y: newY, w: newMaxX - newX, h: newMaxY - newY };
          boxes.splice(j, 1);
          changed = true;
          j--;
        }
      }
    }
  }
  return boxes;
}

function rectIntersect(a: { x: number, y: number, w: number, h: number }, b: { x: number, y: number, w: number, h: number }) {
  // Add a small padding for merging close elements (like text below image)
  const padding = 10;
  return (a.x < b.x + b.w + padding && a.x + a.w + padding > b.x &&
          a.y < b.y + b.h + padding && a.y + a.h + padding > b.y);
}

import { GoogleGenAI } from "@google/genai";

export async function translateMeta(
  jaName: string,
  jaDesc: string
): Promise<{ enName: string; enDesc: string }> {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
You are a professional translator for LINE Stickers.
Translate the following Japanese Sticker Name and Description into English.
The English should be natural, catchy, and suitable for the global sales market.

Input:
Name (JA): ${jaName}
Description (JA): ${jaDesc}

Output Format (JSON):
{
  "enName": "...",
  "enDesc": "..."
}
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const text = response.text;
    if (!text) return { enName: '', enDesc: '' };

    const json = JSON.parse(text);
    return {
      enName: json.enName || '',
      enDesc: json.enDesc || ''
    };

  } catch (error) {
    console.error("Translation error:", error);
    return { enName: "", enDesc: "" };
  }
}

import JSZip from 'jszip';
import { saveAs } from 'file-saver'; // We will need to use a CDN or assume standard file-saver behavior
// Since we can't easily install file-saver in this environment, we'll use a helper download function
import { Stamp, MetaData, TARGET_WIDTH, TARGET_HEIGHT, MAIN_WIDTH, MAIN_HEIGHT, TAB_WIDTH, TAB_HEIGHT } from '../types';

export const createAndDownloadZip = async (
  stamps: Stamp[],
  mainStamp: Stamp | null,
  tabStamp: Stamp | null,
  metaData: MetaData,
  renumber: boolean
) => {
  const zip = new JSZip();
  const folder = zip.folder("stickers");

  if (!folder) return;

  // 1. Add Stamps
  let counter = 1;
  for (const stamp of stamps) {
    if (stamp.isExcluded) continue;

    // Process final image for the stamp (apply offset/scale and fit to 370x320)
    const blob = await createFinalImageBlob(stamp, TARGET_WIDTH, TARGET_HEIGHT);
    if (!blob) continue;

    const fileName = renumber 
      ? `${String(counter).padStart(2, '0')}.png` 
      : `${stamp.id.replace('stamp-', '').padStart(2, '0')}.png`;

    folder.file(fileName, blob);
    counter++;
  }

  // 2. Add Main
  if (mainStamp) {
    const mainBlob = await createFinalImageBlob(mainStamp, MAIN_WIDTH, MAIN_HEIGHT);
    if (mainBlob) zip.file("main.png", mainBlob);
  }

  // 3. Add Tab
  if (tabStamp) {
    const tabBlob = await createFinalImageBlob(tabStamp, TAB_WIDTH, TAB_HEIGHT);
    if (tabBlob) zip.file("tab.png", tabBlob);
  }

  // 4. Add Meta.txt
  const dateStr = new Date().toISOString().split('T')[0];
  const txtContent = `AppName: スタンプ切り出しくん
CreatedAt: ${dateStr} (JST)

[Japanese]
Name: ${metaData.stampNameJa}
Description: ${metaData.stampDescJa}

[English]
Name: ${metaData.stampNameEn}
Description: ${metaData.stampDescEn}
`;
  zip.file("meta.txt", txtContent);

  // Generate and download
  const content = await zip.generateAsync({ type: "blob" });

  // Simple download trigger
  const link = document.createElement('a');
  link.href = URL.createObjectURL(content);
  link.download = `stickers_${dateStr}.zip`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

// Helper: Takes a stamp state and renders it into the final PNG blob
async function createFinalImageBlob(stamp: Stamp, targetW: number, targetH: number): Promise<Blob | null> {
  return new Promise((resolve) => {
    const canvas = document.createElement('canvas');
    canvas.width = targetW;
    canvas.height = targetH;
    const ctx = canvas.getContext('2d');
    if (!ctx) return resolve(null);

    const img = new Image();
    img.onload = () => {
      // Clear
      ctx.clearRect(0, 0, targetW, targetH);

      // Calculate centered position based on scale
      // The stamp.width/height are the crop sizes.
      // stamp.scale is applied to that.
      const drawnW = stamp.width * stamp.scale;
      const drawnH = stamp.height * stamp.scale;

      // Center + Offset
      const centerX = targetW / 2;
      const centerY = targetH / 2;

      const x = centerX - (drawnW / 2) + stamp.offsetX;
      const y = centerY - (drawnH / 2) + stamp.offsetY;

      ctx.drawImage(img, x, y, drawnW, drawnH);

      canvas.toBlob((blob) => {
        resolve(blob);
      }, 'image/png');
    };
    img.src = stamp.dataUrl;
  });
}

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw } from 'lucide-react';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
}

export const StampEditorModal: React.FC<Props> = ({ stamp, isOpen, onClose, onSave }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [scale, setScale] = useState(stamp.scale);
  const [offset, setOffset] = useState({ x: stamp.offsetX, y: stamp.offsetY });
  const [mode, setMode] = useState<'move' | 'eraser'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  // We need to keep a working copy of the image data for the eraser
  // Since modifying the original DataURL is expensive, we draw on a canvas
  // and export a new DataURL on save.
  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);

  useEffect(() => {
    if (isOpen) {
      setScale(stamp.scale);
      setOffset({ x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
    }
  }, [isOpen, stamp]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, offset, workingDataUrl]);

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Background Grid (Checkerboard)
    drawCheckerboard(ctx, canvas.width, canvas.height);

    // Draw Guide Box (Target Size)
    // We want the canvas to represent the TARGET_WIDTH x TARGET_HEIGHT view
    // The image is drawn relative to that

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        const x = centerX - (drawnW / 2) + offset.x;
        const y = centerY - (drawnH / 2) + offset.y;

        ctx.save();
        ctx.drawImage(img, x, y, drawnW, drawnH);
        ctx.restore();

        // Draw Border
        ctx.strokeStyle = '#10b981'; // Green-500
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);
    };
    img.src = workingDataUrl;
  };

  const drawCheckerboard = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    const size = 10;
    for(let y=0; y<h; y+=size) {
      for(let x=0; x<w; x+=size) {
        ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
        ctx.fillRect(x, y, size, size);
      }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    const rect = canvasRef.current!.getBoundingClientRect();
    setLastPos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'eraser') {
      // Eraser logic: We need to modify the actual image data.
      // This is tricky because the image is scaled and offset.
      // We need to map mouse coordinates back to the source image coordinates.
      applyEraser(x, y);
    }
    setLastPos({ x, y });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     // To implement eraser properly on the scaled/translated image,
     // we'd need an OffscreenCanvas holding the source image,
     // apply the erase operation there, and update workingDataUrl.
     // For this MVP, let's just do a simple "Overlay White" or "Clear Rect" on a temporary canvas?
     // Actually, we want transparency.

     // 1. Create a temp canvas with the current source image
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;

     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);

       // 2. Calculate position on source image
       // CanvasX = CenterX - (DrawnW/2) + OffsetX + SourceX * Scale
       // SourceX * Scale = CanvasX - CenterX + (DrawnW/2) - OffsetX
       const centerX = TARGET_WIDTH / 2;
       const centerY = TARGET_HEIGHT / 2;
       const drawnW = stamp.width * scale;
       const drawnH = stamp.height * scale;

       const startXOnCanvas = centerX - (drawnW/2) + offset.x;
       const startYOnCanvas = centerY - (drawnH/2) + offset.y;

       const sourceX = (canvasX - startXOnCanvas) / scale;
       const sourceY = (canvasY - startYOnCanvas) / scale;

       const sourceEraserSize = eraserSize / scale;

       // 3. Erase (Composite Destination-Out)
       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();

       // 4. Update state
       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const handleSave = () => {
    onSave({
      ...stamp,
      scale,
      offsetX: offset.x,
      offsetY: offset.y,
      dataUrl: workingDataUrl
    });
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full flex flex-col max-h-[90vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl">
          <h3 className="font-bold text-gray-700">スタンプ編集</h3>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 flex flex-col items-center gap-6">
          {/* Canvas Area */}
          <div className="relative shadow-md border border-gray-200" style={{ width: TARGET_WIDTH, height: TARGET_HEIGHT }}>
            <canvas 
              ref={canvasRef}
              width={TARGET_WIDTH}
              height={TARGET_HEIGHT}
              className={`cursor-${mode === 'move' ? 'move' : 'crosshair'} touch-none`}
              onMouseDown={handleMouseDown}
              onMouseMove={handleMouseMove}
              onMouseUp={handleMouseUp}
              onMouseLeave={handleMouseUp}
            />
          </div>

          {/* Tools */}
          <div className="flex flex-wrap gap-4 justify-center w-full">
             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button 
                  onClick={() => setMode('move')} 
                  className={`p-2 rounded ${mode === 'move' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                  title="移動"
                >
                  <Move size={20} />
                </button>
                <button 
                  onClick={() => setMode('eraser')} 
                  className={`p-2 rounded ${mode === 'eraser' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                  title="消しゴム"
                >
                  <Eraser size={20} />
                </button>
             </div>

             {mode === 'eraser' && (
               <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                 <span className="text-xs text-gray-500">サイズ</span>
                 <input 
                   type="range" 
                   min="5" 
                   max="50" 
                   value={eraserSize} 
                   onChange={(e) => setEraserSize(Number(e.target.value))} 
                   className="w-24 accent-primary-500"
                 />
               </div>
             )}

             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button onClick={() => setScale(s => Math.max(0.1, s - 0.1))} className="p-1 hover:bg-white rounded"><ZoomOut size={16}/></button>
                <span className="text-sm font-mono w-12 text-center">{(scale * 100).toFixed(0)}%</span>
                <button onClick={() => setScale(s => s + 0.1)} className="p-1 hover:bg-white rounded"><ZoomIn size={16}/></button>
             </div>

             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button 
                    onClick={() => {
                        setScale(1);
                        setOffset({x:0, y:0});
                        setWorkingDataUrl(stamp.dataUrl); // Reset image data too
                    }}
                    className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                >
                    <RotateCcw size={14} /> リセット
                </button>
             </div>
          </div>
        </div>

        <div className="p-4 border-t flex justify-end gap-3 bg-gray-50 rounded-b-xl">
          <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
          <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
            <Check size={18} /> 完了
          </button>
        </div>
      </div>
    </div>
  );
};

