import JSZip from 'jszip';
import { Stamp, MetaData, TARGET_WIDTH, TARGET_HEIGHT, MAIN_WIDTH, MAIN_HEIGHT, TAB_WIDTH, TAB_HEIGHT } from '../types';

export const createAndDownloadZip = async (
  stamps: Stamp[],
  mainStamp: Stamp | null,
  tabStamp: Stamp | null,
  metaData: MetaData,
  renumber: boolean
) => {
  const zip = new JSZip();
  // Removed the subfolder creation to place files in the root
  // const folder = zip.folder("stickers"); 

  // 1. Add Stamps
  let counter = 1;
  for (const stamp of stamps) {
    if (stamp.isExcluded) continue;

    // Process final image for the stamp (apply offset/scale and fit to 370x320)
    const blob = await createFinalImageBlob(stamp, TARGET_WIDTH, TARGET_HEIGHT);
    if (!blob) continue;

    const fileName = renumber 
      ? `${String(counter).padStart(2, '0')}.png` 
      : `${stamp.id.replace('stamp-', '').padStart(2, '0')}.png`;

    // Add directly to zip root
    zip.file(fileName, blob);
    counter++;
  }

  // 2. Add Main
  if (mainStamp) {
    const mainBlob = await createFinalImageBlob(mainStamp, MAIN_WIDTH, MAIN_HEIGHT);
    if (mainBlob) zip.file("main.png", mainBlob);
  }

  // 3. Add Tab
  if (tabStamp) {
    const tabBlob = await createFinalImageBlob(tabStamp, TAB_WIDTH, TAB_HEIGHT);
    if (tabBlob) zip.file("tab.png", tabBlob);
  }

  // 4. Add Meta.txt
  const dateStr = new Date().toISOString().split('T')[0];
  const txtContent = `AppName: スタンプ切り出しくん
CreatedAt: ${dateStr} (JST)

[Japanese]
Name: ${metaData.stampNameJa}
Description: ${metaData.stampDescJa}

[English]
Name: ${metaData.stampNameEn}
Description: ${metaData.stampDescEn}
`;
  zip.file("meta.txt", txtContent);

  // Generate and download
  const content = await zip.generateAsync({ type: "blob" });

  // Simple download trigger
  const link = document.createElement('a');
  link.href = URL.createObjectURL(content);
  link.download = `stickers_${dateStr}.zip`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

// Helper: Takes a stamp state and renders it into the final PNG blob
async function createFinalImageBlob(stamp: Stamp, targetW: number, targetH: number): Promise<Blob | null> {
  return new Promise((resolve) => {
    const canvas = document.createElement('canvas');
    canvas.width = targetW;
    canvas.height = targetH;
    const ctx = canvas.getContext('2d');
    if (!ctx) return resolve(null);

    const img = new Image();
    img.onload = () => {
      // Clear
      ctx.clearRect(0, 0, targetW, targetH);

      // Calculate centered position based on scale
      // The stamp.width/height are the crop sizes.
      // stamp.scale is applied to that.
      const drawnW = stamp.width * stamp.scale;
      const drawnH = stamp.height * stamp.scale;

      // Center + Offset
      const centerX = targetW / 2;
      const centerY = targetH / 2;

      const x = centerX - (drawnW / 2) + stamp.offsetX;
      const y = centerY - (drawnH / 2) + stamp.offsetY;

      ctx.drawImage(img, x, y, drawnW, drawnH);

      canvas.toBlob((blob) => {
        resolve(blob);
      }, 'image/png');
    };
    img.src = stamp.dataUrl;
  });
}

import { GoogleGenAI } from "@google/genai";

export async function translateMeta(
  jaName: string,
  jaDesc: string
): Promise<{ enName: string; enDesc: string }> {
  if (!process.env.API_KEY) {
    console.error("API Key is missing.");
    return { enName: '', enDesc: '' };
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
You are a professional translator for LINE Stickers.
Translate the following Japanese Sticker Name and Description into English.
The English should be natural, catchy, and suitable for the global sales market.

Input:
Name (JA): ${jaName}
Description (JA): ${jaDesc}

Output Format:
Return ONLY a raw JSON object. Do not include markdown formatting like \`\`\`json.
{
  "enName": "...",
  "enDesc": "..."
}
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    let text = response.text;
    if (!text) return { enName: '', enDesc: '' };

    // Cleanup potential markdown backticks if the model ignores the instruction
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    const json = JSON.parse(text);
    return {
      enName: json.enName || '',
      enDesc: json.enDesc || ''
    };

  } catch (error) {
    console.error("Translation error:", error);
    return { enName: "", enDesc: "" };
  }
}

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2 } from 'lucide-react';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
}

export const StampEditorModal: React.FC<Props> = ({ stamp, isOpen, onClose, onSave }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [scale, setScale] = useState(stamp.scale);
  const [offset, setOffset] = useState({ x: stamp.offsetX, y: stamp.offsetY });
  const [mode, setMode] = useState<'move' | 'eraser' | 'wand'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  // We need to keep a working copy of the image data for the eraser/wand
  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);

  useEffect(() => {
    if (isOpen) {
      // Auto-fit logic: If the stamp is larger than the view, scale it down
      let initialScale = stamp.scale;

      // Only apply auto-fit if it's the initial default scale (1)
      if (stamp.scale === 1) {
        const padding = 40;
        const fitW = (TARGET_WIDTH - padding) / stamp.width;
        const fitH = (TARGET_HEIGHT - padding) / stamp.height;
        // Use the smaller scale to fit entirely, but cap at 1.0 if it's small enough
        initialScale = Math.min(fitW, fitH, 1);
        // Round nicely
        initialScale = Math.floor(initialScale * 100) / 100;
        if (initialScale <= 0) initialScale = 0.5;
      }

      setScale(initialScale);
      setOffset({ x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
    }
  }, [isOpen, stamp]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, offset, workingDataUrl]);

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Background Grid (Checkerboard)
    drawCheckerboard(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        const x = centerX - (drawnW / 2) + offset.x;
        const y = centerY - (drawnH / 2) + offset.y;

        ctx.save();
        // Use nearest neighbor for pixel art sharpness or high quality for photos?
        // Default is fine usually.
        ctx.drawImage(img, x, y, drawnW, drawnH);
        ctx.restore();

        // Draw Border (The output area)
        ctx.strokeStyle = '#10b981'; // Green-500
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);
    };
    img.src = workingDataUrl;
  };

  const drawCheckerboard = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    const size = 10;
    for(let y=0; y<h; y+=size) {
      for(let x=0; x<w; x+=size) {
        ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
        ctx.fillRect(x, y, size, size);
      }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (mode === 'wand') {
      applyMagicWand(x, y);
    } else {
      setIsDragging(true);
      setLastPos({ x, y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    }
    setLastPos({ x, y });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  // Maps Canvas Coordinates -> Source Image Coordinates
  const getSourceCoords = (canvasX: number, canvasY: number) => {
    const centerX = TARGET_WIDTH / 2;
    const centerY = TARGET_HEIGHT / 2;
    const drawnW = stamp.width * scale;
    const drawnH = stamp.height * scale;

    const startXOnCanvas = centerX - (drawnW/2) + offset.x;
    const startYOnCanvas = centerY - (drawnH/2) + offset.y;

    const sourceX = Math.floor((canvasX - startXOnCanvas) / scale);
    const sourceY = Math.floor((canvasY - startYOnCanvas) / scale);

    return { sourceX, sourceY };
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;

     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);

       const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
       const sourceEraserSize = eraserSize / scale;

       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();

       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const applyMagicWand = (canvasX: number, canvasY: number) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
    if(!ctx) return;

    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);

      const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
      if (sourceX < 0 || sourceX >= stamp.width || sourceY < 0 || sourceY >= stamp.height) return;

      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;

      // Get target color
      const targetIdx = (sourceY * width + sourceX) * 4;
      const tR = data[targetIdx];
      const tG = data[targetIdx + 1];
      const tB = data[targetIdx + 2];
      const tA = data[targetIdx + 3];

      if (tA === 0) return; // Already transparent

      const tolerance = 30;
      const stack = [[sourceX, sourceY]];
      const visited = new Uint8Array(width * height);

      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= width || y < 0 || y >= height) continue;
        if (visited[y * width + x]) continue;

        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        if (a === 0) continue; // Boundary

        const diff = Math.abs(r - tR) + Math.abs(g - tG) + Math.abs(b - tB);
        if (diff < tolerance * 3) {
           data[idx + 3] = 0; // Make transparent
           visited[y * width + x] = 1;
           stack.push([x + 1, y]);
           stack.push([x - 1, y]);
           stack.push([x, y + 1]);
           stack.push([x, y - 1]);
        }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const handleSave = () => {
    onSave({
      ...stamp,
      scale,
      offsetX: offset.x,
      offsetY: offset.y,
      dataUrl: workingDataUrl
    });
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full flex flex-col max-h-[90vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl">
          <h3 className="font-bold text-gray-700">スタンプ編集</h3>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 flex flex-col items-center gap-6">
          {/* Canvas Area */}
          <div className="relative shadow-md border border-gray-200" style={{ width: TARGET_WIDTH, height: TARGET_HEIGHT }}>
            <canvas 
              ref={canvasRef}
              width={TARGET_WIDTH}
              height={TARGET_HEIGHT}
              className={`cursor-${mode === 'move' ? 'move' : mode === 'wand' ? 'crosshair' : 'crosshair'} touch-none`}
              onMouseDown={handleMouseDown}
              onMouseMove={handleMouseMove}
              onMouseUp={handleMouseUp}
              onMouseLeave={handleMouseUp}
            />
          </div>

          <p className="text-xs text-gray-500">
             {mode === 'move' ? 'ドラッグで移動' : mode === 'wand' ? 'クリックして連続した色を透過（穴など）' : 'ドラッグで消去'}
          </p>

          {/* Tools */}
          <div className="flex flex-wrap gap-4 justify-center w-full">
             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button 
                  onClick={() => setMode('move')} 
                  className={`p-2 rounded ${mode === 'move' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                  title="移動"
                >
                  <Move size={20} />
                </button>
                <button 
                  onClick={() => setMode('wand')} 
                  className={`p-2 rounded ${mode === 'wand' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                  title="自動透過 (クリック)"
                >
                  <Wand2 size={20} />
                </button>
                <button 
                  onClick={() => setMode('eraser')} 
                  className={`p-2 rounded ${mode === 'eraser' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                  title="消しゴム"
                >
                  <Eraser size={20} />
                </button>
             </div>

             {mode === 'eraser' && (
               <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                 <span className="text-xs text-gray-500">サイズ</span>
                 <input 
                   type="range" 
                   min="5" 
                   max="50" 
                   value={eraserSize} 
                   onChange={(e) => setEraserSize(Number(e.target.value))} 
                   className="w-24 accent-primary-500"
                 />
               </div>
             )}

             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button onClick={() => setScale(s => Math.max(0.1, s - 0.1))} className="p-1 hover:bg-white rounded"><ZoomOut size={16}/></button>
                <span className="text-sm font-mono w-12 text-center">{(scale * 100).toFixed(0)}%</span>
                <button onClick={() => setScale(s => s + 0.1)} className="p-1 hover:bg-white rounded"><ZoomIn size={16}/></button>
             </div>

             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button 
                    onClick={() => {
                        setScale(1);
                        setOffset({x:0, y:0});
                        setWorkingDataUrl(stamp.dataUrl); // Reset image data too
                    }}
                    className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                >
                    <RotateCcw size={14} /> リセット
                </button>
             </div>
          </div>
        </div>

        <div className="p-4 border-t flex justify-end gap-3 bg-gray-50 rounded-b-xl">
          <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
          <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
            <Check size={18} /> 完了
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { X, Crop, Check } from 'lucide-react';
import { Stamp } from '../types';

interface Props {
  originalImageUrl: string;
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (cropData: Stamp) => void;
}

export const ManualCropModal: React.FC<Props> = ({ originalImageUrl, isOpen, onClose, onConfirm }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);
  const [selection, setSelection] = useState<{ x: number, y: number, w: number, h: number } | null>(null);
  const [isSelecting, setIsSelecting] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    if (isOpen) {
        setSelection(null);
    }
  }, [isOpen]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!imgRef.current) return;
    const rect = imgRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setIsSelecting(true);
    setStartPos({ x, y });
    setSelection({ x, y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isSelecting || !imgRef.current) return;
    const rect = imgRef.current.getBoundingClientRect();
    const currentX = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
    const currentY = Math.max(0, Math.min(e.clientY - rect.top, rect.height));

    const w = currentX - startPos.x;
    const h = currentY - startPos.y;

    setSelection({
      x: w > 0 ? startPos.x : currentX,
      y: h > 0 ? startPos.y : currentY,
      w: Math.abs(w),
      h: Math.abs(h)
    });
  };

  const handleMouseUp = () => {
    setIsSelecting(false);
  };

  const handleCrop = () => {
    if (!selection || !imgRef.current || selection.w < 10 || selection.h < 10) {
        alert("範囲を選択してください");
        return;
    }

    // Convert display coordinates to natural image coordinates
    const scaleX = imgRef.current.naturalWidth / imgRef.current.width;
    const scaleY = imgRef.current.naturalHeight / imgRef.current.height;

    const realX = Math.floor(selection.x * scaleX);
    const realY = Math.floor(selection.y * scaleY);
    const realW = Math.floor(selection.w * scaleX);
    const realH = Math.floor(selection.h * scaleY);

    // Create Canvas to extract and process
    const canvas = document.createElement('canvas');
    canvas.width = realW;
    canvas.height = realH;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Draw the cropped area
    ctx.drawImage(imgRef.current, realX, realY, realW, realH, 0, 0, realW, realH);

    // Auto-remove background (Simple corner flood fill like automatic process)
    const imageData = ctx.getImageData(0, 0, realW, realH);
    const data = imageData.data;

    // Sample corners to find background color
    const corners = [0, (realW - 1) * 4, (realH - 1) * realW * 4, (realH * realW - 1) * 4];
    const bgR = data[0];
    const bgG = data[1];
    const bgB = data[2];
    const tolerance = 40;

    const stack: [number, number][] = [];
    const visited = new Uint8Array(realW * realH);

    // Start from edges
    for (let x = 0; x < realW; x++) { stack.push([x, 0]); stack.push([x, realH - 1]); }
    for (let y = 0; y < realH; y++) { stack.push([0, y]); stack.push([realW - 1, y]); }

    while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= realW || y < 0 || y >= realH) continue;
        if (visited[y * realW + x]) continue;

        const idx = (y * realW + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);

        if (diff < tolerance * 3) {
            data[idx + 3] = 0; // Transparent
            visited[y * realW + x] = 1;
            stack.push([x + 1, y]); stack.push([x - 1, y]); stack.push([x, y + 1]); stack.push([x, y - 1]);
        }
    }

    ctx.putImageData(imageData, 0, 0);

    const stampId = `stamp-manual-${Date.now()}`;
    const newStamp: Stamp = {
        id: stampId,
        originalX: realX,
        originalY: realY,
        width: realW,
        height: realH,
        dataUrl: canvas.toDataURL('image/png'),
        isExcluded: false,
        scale: 1,
        offsetX: 0,
        offsetY: 0
    };

    onConfirm(newStamp);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col h-[90vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
            <div className="flex items-center gap-2">
                <Crop className="text-primary-600" />
                <div>
                    <h3 className="font-bold text-gray-700">手動で切り出し (再選択)</h3>
                    <p className="text-xs text-gray-500">元画像からスタンプにしたい範囲をドラッグしてください</p>
                </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
        </div>

        <div className="flex-1 overflow-auto p-4 bg-gray-900 flex items-center justify-center relative select-none" ref={containerRef}>
            <div className="relative inline-block">
                <img 
                    ref={imgRef}
                    src={originalImageUrl} 
                    className="max-w-full max-h-full object-contain pointer-events-none" // pointer-events handled by overlay
                    alt="Original"
                />
                {/* Overlay for selection */}
                <div 
                    className="absolute inset-0 cursor-crosshair"
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                >
                    {selection && (
                        <div 
                            className="absolute border-2 border-white shadow-[0_0_0_9999px_rgba(0,0,0,0.5)]"
                            style={{
                                left: selection.x,
                                top: selection.y,
                                width: selection.w,
                                height: selection.h
                            }}
                        />
                    )}
                </div>
            </div>
        </div>

        <div className="p-4 border-t flex justify-end gap-3 bg-gray-50 rounded-b-xl shrink-0">
          <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
          <button onClick={handleCrop} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
            <Check size={18} /> この範囲で作成
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Upload, Download, Loader2, Image as ImageIcon, Grid, Languages, Trash2, CheckCircle2, RotateCw } from 'lucide-react';
import { AppStep, Stamp, MetaData } from './types';
import { processUploadedImage } from './lib/imageProcessing';
import { translateMeta } from './lib/gemini';
import { createAndDownloadZip } from './lib/zipService';
import { StampEditorModal } from './components/StampEditorModal';
import { ManualCropModal } from './components/ManualCropModal';

function App() {
  const [step, setStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [stamps, setStamps] = useState<Stamp[]>([]);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);

  const [mainId, setMainId] = useState<string | null>(null);
  const [tabId, setTabId] = useState<string | null>(null);

  // Meta Data
  const [meta, setMeta] = useState<MetaData>({
    stampNameJa: '', stampDescJa: '', stampNameEn: '', stampDescEn: ''
  });
  const [isTranslating, setIsTranslating] = useState(false);

  // Editor State
  const [editingStamp, setEditingStamp] = useState<Stamp | null>(null);
  const [isManualCropping, setIsManualCropping] = useState(false);
  const [targetReplaceId, setTargetReplaceId] = useState<string | null>(null);

  // Export Settings
  const [renumber, setRenumber] = useState(true);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Store original for manual cropping
    setOriginalImageUrl(URL.createObjectURL(file));

    setIsProcessing(true);
    setStep(AppStep.PROCESSING);

    try {
      const result = await processUploadedImage(file);
      setStamps(result.stamps);

      // Auto-select Main/Tab (First one by default)
      if (result.stamps.length > 0) {
        setMainId(result.stamps[0].id);
        setTabId(result.stamps[0].id);
      }

      setStep(AppStep.EDIT);
    } catch (err) {
      console.error(err);
      alert('画像処理に失敗しました。別の画像を試してください。');
      setStep(AppStep.UPLOAD);
    } finally {
      setIsProcessing(false);
    }
  };

  const updateStamp = (updatedStamp: Stamp) => {
    setStamps(prev => prev.map(s => s.id === updatedStamp.id ? updatedStamp : s));
  };

  const handleTranslation = async () => {
    if (!meta.stampNameJa) return alert('日本語のスタンプ名を入力してください');
    setIsTranslating(true);
    const result = await translateMeta(meta.stampNameJa, meta.stampDescJa);
    setMeta(prev => ({ ...prev, ...result }));
    setIsTranslating(false);
  };

  const handleExport = async () => {
    if (!mainId || !tabId) return alert('メイン画像とタブ画像を選択してください');

    const mainStamp = stamps.find(s => s.id === mainId) || null;
    const tabStamp = stamps.find(s => s.id === tabId) || null;

    await createAndDownloadZip(stamps, mainStamp, tabStamp, meta, renumber);
  };

  const toggleExclude = (id: string) => {
    setStamps(prev => prev.map(s => s.id === id ? { ...s, isExcluded: !s.isExcluded } : s));
  };

  const openManualCrop = (replaceId?: string) => {
    if (!originalImageUrl) return;
    setTargetReplaceId(replaceId || null);
    setIsManualCropping(true);
  };

  const handleManualCropConfirm = (newStamp: Stamp) => {
    if (targetReplaceId) {
        // Replace existing
        setStamps(prev => prev.map(s => s.id === targetReplaceId ? { ...newStamp, id: s.id } : s));
    } else {
        // Add new
        setStamps(prev => [...prev, newStamp]);
    }
    setIsManualCropping(false);
    setTargetReplaceId(null);
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b border-primary-100 py-4 px-6 sticky top-0 z-10 shadow-sm">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
            <div className="flex items-center gap-2">
                <div className="bg-primary-500 p-2 rounded-lg text-white">
                    <Grid size={24} />
                </div>
                <h1 className="text-xl font-bold text-gray-800">スタンプ切り出しくん</h1>
            </div>
            <div className="flex gap-2">
                {step !== AppStep.UPLOAD && (
                    <button 
                        onClick={() => {
                            if(confirm('最初に戻りますか？作業内容は失われます。')) window.location.reload();
                        }}
                        className="text-sm text-gray-500 hover:text-gray-800 px-3 py-1"
                    >
                        最初に戻る
                    </button>
                )}
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto p-6">

        {/* Step 1: Upload */}
        {step === AppStep.UPLOAD && (
          <div className="flex flex-col items-center justify-center py-20 animate-fade-in">
            <div className="bg-white p-12 rounded-3xl shadow-xl text-center border-4 border-dashed border-primary-200 hover:border-primary-400 transition-colors cursor-pointer relative max-w-2xl w-full">
              <input 
                type="file" 
                accept="image/png, image/jpeg" 
                onChange={handleFileUpload}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
              />
              <div className="bg-primary-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-primary-600">
                <Upload size={40} />
              </div>
              <h2 className="text-2xl font-bold text-gray-700 mb-2">画像をここにドロップ</h2>
              <p className="text-gray-500 mb-6">またはクリックしてファイルを選択 (PNG推奨)</p>
              <div className="inline-block bg-primary-600 text-white px-6 py-3 rounded-full font-bold shadow-lg shadow-primary-200">
                画像を選択する
              </div>
              <p className="text-xs text-gray-400 mt-8">
                グリッド状に並んだスタンプ画像をアップロードしてください。<br/>
                自動で背景を透過し、個別に切り出します。
              </p>
            </div>
          </div>
        )}

        {/* Step 2: Processing */}
        {step === AppStep.PROCESSING && (
          <div className="flex flex-col items-center justify-center py-40">
            <Loader2 size={60} className="text-primary-500 animate-spin mb-6" />
            <h2 className="text-2xl font-bold text-gray-700">AIが解析中...</h2>
            <p className="text-gray-500">背景の除去とスタンプの切り出しを行っています</p>
          </div>
        )}

        {/* Step 3: Edit & Export */}
        {step === AppStep.EDIT && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

            {/* Left Col: Stamps Grid */}
            <div className="lg:col-span-2 space-y-6">
              <div className="flex items-center justify-between bg-white p-4 rounded-xl shadow-sm border border-primary-100">
                <h2 className="font-bold text-lg flex items-center gap-2">
                  <ImageIcon className="text-primary-500" />
                  切り出し結果 ({stamps.length}個)
                </h2>
                <div className="flex gap-2">
                    <button 
                        onClick={() => openManualCrop()}
                        className="text-xs flex items-center gap-1 bg-primary-50 text-primary-600 px-3 py-1.5 rounded-full hover:bg-primary-100 font-bold"
                    >
                         <RotateCw size={14} /> 新規追加
                    </button>
                    <div className="text-sm text-gray-500 flex items-center">
                        クリックして編集 / チェックを外して除外
                    </div>
                </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                {stamps.map((stamp, index) => (
                    <div key={stamp.id} className={`relative group bg-white rounded-xl shadow border-2 transition-all ${stamp.isExcluded ? 'opacity-50 border-gray-200' : 'border-transparent hover:border-primary-300'}`}>
                        {/* Background Checkers for preview */}
                        <div 
                            className="w-full aspect-square rounded-lg overflow-hidden relative cursor-pointer bg-[url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')]"
                            onClick={() => setEditingStamp(stamp)}
                        >
                            <img 
