import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2 } from 'lucide-react';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  previewBg: string; // 'checker' | '#ffffff' | '#000000' etc
}

export const StampEditorModal: React.FC<Props> = ({ stamp, isOpen, onClose, onSave, previewBg }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [scale, setScale] = useState(stamp.scale);
  const [offset, setOffset] = useState({ x: stamp.offsetX, y: stamp.offsetY });
  const [mode, setMode] = useState<'move' | 'eraser' | 'wand'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  // We need to keep a working copy of the image data for the eraser/wand
  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);

  useEffect(() => {
    if (isOpen) {
      // Auto-fit logic: If the stamp is larger than the view, scale it down
      let initialScale = stamp.scale;

      // Only apply auto-fit if it's the initial default scale (1)
      if (stamp.scale === 1) {
        const padding = 40;
        const fitW = (TARGET_WIDTH - padding) / stamp.width;
        const fitH = (TARGET_HEIGHT - padding) / stamp.height;
        // Use the smaller scale to fit entirely, but cap at 1.0 if it's small enough
        initialScale = Math.min(fitW, fitH, 1);
        // Round nicely
        initialScale = Math.floor(initialScale * 100) / 100;
        if (initialScale <= 0) initialScale = 0.5;
      }

      setScale(initialScale);
      setOffset({ x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
    }
  }, [isOpen, stamp]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, offset, workingDataUrl, previewBg]);

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Background
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        const x = centerX - (drawnW / 2) + offset.x;
        const y = centerY - (drawnH / 2) + offset.y;

        ctx.save();
        ctx.drawImage(img, x, y, drawnW, drawnH);
        ctx.restore();

        // Draw Border (The output area)
        ctx.strokeStyle = '#10b981'; // Green-500
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);
    };
    img.src = workingDataUrl;
  };

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (mode === 'wand') {
      applyMagicWand(x, y);
    } else {
      setIsDragging(true);
      setLastPos({ x, y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    }
    setLastPos({ x, y });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  // Maps Canvas Coordinates -> Source Image Coordinates
  const getSourceCoords = (canvasX: number, canvasY: number) => {
    const centerX = TARGET_WIDTH / 2;
    const centerY = TARGET_HEIGHT / 2;
    const drawnW = stamp.width * scale;
    const drawnH = stamp.height * scale;

    const startXOnCanvas = centerX - (drawnW/2) + offset.x;
    const startYOnCanvas = centerY - (drawnH/2) + offset.y;

    const sourceX = Math.floor((canvasX - startXOnCanvas) / scale);
    const sourceY = Math.floor((canvasY - startYOnCanvas) / scale);

    return { sourceX, sourceY };
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;

     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);

       const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
       const sourceEraserSize = eraserSize / scale;

       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();

       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const applyMagicWand = (canvasX: number, canvasY: number) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
    if(!ctx) return;

    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);

      const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
      if (sourceX < 0 || sourceX >= stamp.width || sourceY < 0 || sourceY >= stamp.height) return;

      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;

      // Get target color
      const targetIdx = (sourceY * width + sourceX) * 4;
      const tR = data[targetIdx];
      const tG = data[targetIdx + 1];
      const tB = data[targetIdx + 2];
      const tA = data[targetIdx + 3];

      if (tA === 0) return; // Already transparent

      const tolerance = 30;
      const stack = [[sourceX, sourceY]];
      const visited = new Uint8Array(width * height);

      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= width || y < 0 || y >= height) continue;
        if (visited[y * width + x]) continue;

        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        if (a === 0) continue; // Boundary

        const diff = Math.abs(r - tR) + Math.abs(g - tG) + Math.abs(b - tB);
        if (diff < tolerance * 3) {
           data[idx + 3] = 0; // Make transparent
           visited[y * width + x] = 1;
           stack.push([x + 1, y]);
           stack.push([x - 1, y]);
           stack.push([x, y + 1]);
           stack.push([x, y - 1]);
        }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const handleSave = () => {
    onSave({
      ...stamp,
      scale,
      offsetX: offset.x,
      offsetY: offset.y,
      dataUrl: workingDataUrl
    });
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full flex flex-col max-h-[90vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl">
          <h3 className="font-bold text-gray-700">スタンプ編集</h3>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 flex flex-col items-center gap-6">
          {/* Canvas Area */}
          <div className="relative shadow-md border border-gray-200" style={{ width: TARGET_WIDTH, height: TARGET_HEIGHT }}>
            <canvas 
              ref={canvasRef}
              width={TARGET_WIDTH}
              height={TARGET_HEIGHT}
              className={`cursor-${mode === 'move' ? 'move' : mode === 'wand' ? 'crosshair' : 'crosshair'} touch-none`}
              onMouseDown={handleMouseDown}
              onMouseMove={handleMouseMove}
              onMouseUp={handleMouseUp}
              onMouseLeave={handleMouseUp}
            />
          </div>

          <p className="text-xs text-gray-500">
             {mode === 'move' ? 'ドラッグで移動' : mode === 'wand' ? 'クリックして連続した色を透過（穴など）' : 'ドラッグで消去'}
          </p>

          {/* Tools */}
          <div className="flex flex-wrap gap-4 justify-center w-full">
             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button 
                  onClick={() => setMode('move')} 
                  className={`p-2 rounded ${mode === 'move' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                  title="移動"
                >
                  <Move size={20} />
                </button>
                <button 
                  onClick={() => setMode('wand')} 
                  className={`p-2 rounded ${mode === 'wand' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                  title="自動透過 (クリック)"
                >
                  <Wand2 size={20} />
                </button>
                <button 
                  onClick={() => setMode('eraser')} 
                  className={`p-2 rounded ${mode === 'eraser' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                  title="消しゴム"
                >
                  <Eraser size={20} />
                </button>
             </div>

             {mode === 'eraser' && (
               <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                 <span className="text-xs text-gray-500">サイズ</span>
                 <input 
                   type="range" 
                   min="5" 
                   max="50" 
                   value={eraserSize} 
                   onChange={(e) => setEraserSize(Number(e.target.value))} 
                   className="w-24 accent-primary-500"
                 />
               </div>
             )}

             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button onClick={() => setScale(s => Math.max(0.1, s - 0.1))} className="p-1 hover:bg-white rounded"><ZoomOut size={16}/></button>
                <span className="text-sm font-mono w-12 text-center">{(scale * 100).toFixed(0)}%</span>
                <button onClick={() => setScale(s => s + 0.1)} className="p-1 hover:bg-white rounded"><ZoomIn size={16}/></button>
             </div>

             <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                <button 
                    onClick={() => {
                        setScale(1);
                        setOffset({x:0, y:0});
                        setWorkingDataUrl(stamp.dataUrl); // Reset image data too
                    }}
                    className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                >
                    <RotateCcw size={14} /> リセット
                </button>
             </div>
          </div>
        </div>

        <div className="p-4 border-t flex justify-end gap-3 bg-gray-50 rounded-b-xl">
          <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
          <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
            <Check size={18} /> 完了
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Upload, Download, Loader2, Image as ImageIcon, Grid, Languages, Trash2, CheckCircle2, RotateCw, Palette } from 'lucide-react';
import { AppStep, Stamp, MetaData, TARGET_WIDTH, TARGET_HEIGHT } from './types';
import { processUploadedImage } from './lib/imageProcessing';
import { translateMeta } from './lib/gemini';
import { createAndDownloadZip } from './lib/zipService';
import { StampEditorModal } from './components/StampEditorModal';
import { ManualCropModal } from './components/ManualCropModal';

function App() {
  const [step, setStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [stamps, setStamps] = useState<Stamp[]>([]);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);

  const [mainId, setMainId] = useState<string | null>(null);
  const [tabId, setTabId] = useState<string | null>(null);

  // Meta Data
  const [meta, setMeta] = useState<MetaData>({
    stampNameJa: '', stampDescJa: '', stampNameEn: '', stampDescEn: ''
  });
  const [isTranslating, setIsTranslating] = useState(false);

  // Editor State
  const [editingStamp, setEditingStamp] = useState<Stamp | null>(null);
  const [isManualCropping, setIsManualCropping] = useState(false);
  const [targetReplaceId, setTargetReplaceId] = useState<string | null>(null);
  const [previewBg, setPreviewBg] = useState<string>('checker');

  // Export Settings
  const [renumber, setRenumber] = useState(true);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Store original for manual cropping
    setOriginalImageUrl(URL.createObjectURL(file));

    setIsProcessing(true);
    setStep(AppStep.PROCESSING);

    try {
      const result = await processUploadedImage(file);
      setStamps(result.stamps);

      // Auto-select Main/Tab (First one by default)
      if (result.stamps.length > 0) {
        setMainId(result.stamps[0].id);
        setTabId(result.stamps[0].id);
      }

      setStep(AppStep.EDIT);
    } catch (err) {
      console.error(err);
      alert('画像処理に失敗しました。別の画像を試してください。');
      setStep(AppStep.UPLOAD);
    } finally {
      setIsProcessing(false);
    }
  };

  const updateStamp = (updatedStamp: Stamp) => {
    setStamps(prev => prev.map(s => s.id === updatedStamp.id ? updatedStamp : s));
  };

  const handleTranslation = async () => {
    if (!meta.stampNameJa) return alert('日本語のスタンプ名を入力してください');
    setIsTranslating(true);
    const result = await translateMeta(meta.stampNameJa, meta.stampDescJa);
    setMeta(prev => ({ ...prev, ...result }));
    setIsTranslating(false);
  };

  const handleExport = async () => {
    if (!mainId || !tabId) return alert('メイン画像とタブ画像を選択してください');

    const mainStamp = stamps.find(s => s.id === mainId) || null;
    const tabStamp = stamps.find(s => s.id === tabId) || null;

    await createAndDownloadZip(stamps, mainStamp, tabStamp, meta, renumber);
  };

  const toggleExclude = (id: string) => {
    setStamps(prev => prev.map(s => s.id === id ? { ...s, isExcluded: !s.isExcluded } : s));
  };

  const openManualCrop = (replaceId?: string) => {
    if (!originalImageUrl) return;
    setTargetReplaceId(replaceId || null);
    setIsManualCropping(true);
  };

  const handleManualCropConfirm = (newStamp: Stamp) => {
    if (targetReplaceId) {
        // Replace existing
        setStamps(prev => prev.map(s => s.id === targetReplaceId ? { ...newStamp, id: s.id } : s));
    } else {
        // Add new
        setStamps(prev => [...prev, newStamp]);
    }
    setIsManualCropping(false);
    setTargetReplaceId(null);
  };

  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' }, // Checker representation
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#85c6f0', label: '青(LINE)', color: 'bg-[#85c6f0]' }, // LINE default chat bg color approximation
    { value: '#fecaca', label: '赤', color: 'bg-red-200' },
  ];

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b border-primary-100 py-4 px-6 sticky top-0 z-10 shadow-sm">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
            <div className="flex items-center gap-2">
                <div className="bg-primary-500 p-2 rounded-lg text-white">
                    <Grid size={24} />
                </div>
                <h1 className="text-xl font-bold text-gray-800">スタンプ切り出しくん</h1>
            </div>
            <div className="flex gap-2">
                {step !== AppStep.UPLOAD && (
                    <button 
                        onClick={() => {
                            if(confirm('最初に戻りますか？作業内容は失われます。')) window.location.reload();
                        }}
                        className="text-sm text-gray-500 hover:text-gray-800 px-3 py-1"
                    >
                        最初に戻る
                    </button>
                )}
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto p-6">

        {/* Step 1: Upload */}
        {step === AppStep.UPLOAD && (
          <div className="flex flex-col items-center justify-center py-20 animate-fade-in">
            <div className="bg-white p-12 rounded-3xl shadow-xl text-center border-4 border-dashed border-primary-200 hover:border-primary-400 transition-colors cursor-pointer relative max-w-2xl w-full">
              <input 
                type="file" 
                accept="image/png, image/jpeg" 
                onChange={handleFileUpload}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
              />
              <div className="bg-primary-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-primary-600">
                <Upload size={40} />
              </div>
              <h2 className="text-2xl font-bold text-gray-700 mb-2">画像をここにドロップ</h2>
              <p className="text-gray-500 mb-6">またはクリックしてファイルを選択 (PNG推奨)</p>
              <div className="inline-block bg-primary-600 text-white px-6 py-3 rounded-full font-bold shadow-lg shadow-primary-200">
                画像を選択する
              </div>
              <p className="text-xs text-gray-400 mt-8">
                グリッド状に並んだスタンプ画像をアップロードしてください。<br/>
                自動で背景を透過し、個別に切り出します。
              </p>
            </div>
          </div>
        )}

        {/* Step 2: Processing */}
        {step === AppStep.PROCESSING && (
          <div className="flex flex-col items-center justify-center py-40">
            <Loader2 size={60} className="text-primary-500 animate-spin mb-6" />
            <h2 className="text-2xl font-bold text-gray-700">AIが解析中...</h2>
            <p className="text-gray-500">背景の除去とスタンプの切り出しを行っています</p>
          </div>
        )}

        {/* Step 3: Edit & Export */}
        {step === AppStep.EDIT && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

            {/* Left Col: Stamps Grid */}
            <div className="lg:col-span-2 space-y-6">

              {/* Toolbar */}
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between bg-white p-4 rounded-xl shadow-sm border border-primary-100 gap-4">
                <h2 className="font-bold text-lg flex items-center gap-2">
                  <ImageIcon className="text-primary-500" />
                  切り出し結果 ({stamps.length}個)
                </h2>

                <div className="flex flex-wrap gap-4 items-center w-full sm:w-auto">
                    {/* Background Selector */}
                    <div className="flex items-center gap-2 bg-gray-50 p-1.5 rounded-lg border border-gray-200">
                        <Palette size={16} className="text-gray-400 ml-1" />
                        {backgroundOptions.map(opt => (
                            <button
                                key={opt.value}
                                onClick={() => setPreviewBg(opt.value)}
                                className={`w-6 h-6 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                                title={opt.label}
                                style={opt.value === 'checker' ? {
                                    backgroundImage: `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')`
                                } : {}}
                            />
                        ))}
                    </div>

                    <div className="flex gap-2 ml-auto">
                        <button 
                            onClick={() => openManualCrop()}
                            className="text-xs flex items-center gap-1 bg-primary-50 text-primary-600 px-3 py-1.5 rounded-full hover:bg-primary-100 font-bold"
                        >
                            <RotateCw size={14} /> 新規追加
                        </button>
                    </div>
                </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                {stamps.map((stamp, index) => {
                    // Calculate preview transforms for exact WYSIWYG
                    const centerX = TARGET_WIDTH / 2;
                    const centerY = TARGET_HEIGHT / 2;
                    const drawnW = stamp.width * stamp.scale;
                    const drawnH = stamp.height * stamp.scale;
                    const finalX = centerX - (drawnW / 2) + stamp.offsetX;
                    const finalY = centerY - (drawnH / 2) + stamp.offsetY;

                    return (
                        <div key={stamp.id} className={`relative group bg-white rounded-xl shadow border-2 transition-all ${stamp.isExcluded ? 'opacity-50 border-gray-200' : 'border-transparent hover:border-primary-300'}`}>
                            {/* 
                                Preview Container: aspect-[37/32] ensures it matches the target aspect ratio.
                                Use SVG to render the image with the exact same coordinates as the canvas.
                                This guarantees WYSIWYG.
                            */}
                            <div 
                                className="w-full aspect-[37/32] rounded-lg overflow-hidden relative cursor-pointer"
                                style={{
                                    backgroundColor: previewBg === 'checker' ? undefined : previewBg,
                                    backgroundImage: previewBg === 'checker' ? `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')` : undefined
                                }}
                                onClick={() => setEditingStamp(stamp)}
                            >
                                <svg 
                                    viewBox={`0 0 ${TARGET_WIDTH} ${TARGET_HEIGHT}`} 
                                    className="w-full h-full pointer-events-none"
                                    preserveAspectRatio="xMidYMid meet"
                                >
                                    <image 
                                        href={stamp.dataUrl} 
                                        x={finalX} 
                                        y={finalY} 
                                        width={drawnW} 
                                        height={drawnH} 
                                    />
                                </svg>

                                {/* Overlay Edit Hint */}
                                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 flex items-center justify-center transition-colors">
                                    <span className="opacity-0 group-hover:opacity-100 bg-white/90 text-xs px-2 py-1 rounded-full font-bold shadow-sm">編集</span>
                                </div>
                            </div>

                            {/* Controls */}
                            <div className="absolute top-2 left-2 z-10">
                                <input 
                                    type="checkbox" 
                                    checked={!stamp.isExcluded} 
                                    onChange={(e) => { e.stopPropagation(); toggleExclude(stamp.id); }}
                                    className="w-5 h-5 rounded border-gray-300 text-primary-600 focus:ring-primary-500 cursor-pointer shadow-sm"
                                />
                            </div>
                            <div className="absolute top-2 right-2 flex gap-1 z-10">
                                {mainId === stamp.id && <span className="bg-yellow-400 text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow">MAIN</span>}
                                {tabId === stamp.id && <span className="bg-blue-400 text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow">TAB</span>}
                            </div>

                            {/* Recrop Button */}
                            <div className="absolute bottom-2 right-2 z-10 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button 
                                    onClick={(e) => { e.stopPropagation(); openManualCrop(stamp.id); }}
                                    className="bg-white text-gray-600 p-1.5 rounded-full shadow hover:bg-gray-100 hover:text-primary-600"
                                    title="元画像から範囲を指定し直す"
                                >
                                    <RotateCw size={14} />
                                </button>
                            </div>

                            <div className="p-2 text-center text-xs text-gray-400 font-mono">
                                {stamp.isExcluded ? '除外' : `No.${String(index + 1).padStart(2,'0')}`}
                            </div>
                        </div>
                    );
                })}
              </div>
            </div>

            {/* Right Col: Settings & Export */}
            <div className="lg:col-span-1 space-y-6">

                {/* Main/Tab Selection */}
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-primary-100">
                    <h3 className="font-bold text-gray-700 flex items-center gap-2 mb-4">
                        <CheckCircle2 className="text-primary-500" size={20} />
                        代表画像設定
                    </h3>

                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-600 mb-1">メイン画像 (240x240)</label>
                            <select 
                                className="w-full border-gray-300 rounded-lg shadow-sm focus:ring-primary-500 focus:border-primary-500"
                                value={mainId || ''}
                                onChange={(e) => setMainId(e.target.value)}
                            >
                                {stamps.map((s, i) => !s.isExcluded && (
                                    <option key={s.id} value={s.id}>No.{i+1} のスタンプ</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-600 mb-1">タブ画像 (96x74)</label>
                            <select 
                                className="w-full border-gray-300 rounded-lg shadow-sm focus:ring-primary-500 focus:border-primary-500"
                                value={tabId || ''}
                                onChange={(e) => setTabId(e.target.value)}
                            >
                                {stamps.map((s, i) => !s.isExcluded && (
                                    <option key={s.id} value={s.id}>No.{i+1} のスタンプ</option>
                                ))}
                            </select>
                        </div>
                    </div>
                </div>

                {/* Translation / Meta */}
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-primary-100">
                     <h3 className="font-bold text-gray-700 flex items-center gap-2 mb-4">
                        <Languages className="text-primary-500" size={20} />
                        テキスト設定
                    </h3>
                    <div className="space-y-4">
                        <div>
                            <label className="text-xs font-bold text-gray-500">スタンプ名 (日本語)</label>
                            <input 
                                type="text" 
                                className="w-full border-gray-300 rounded-md text-sm mt-1"
                                placeholder="例：かわいいうさぎスタンプ"
                                value={meta.stampNameJa}
                                onChange={e => setMeta({...meta, stampNameJa: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="text-xs font-bold text-gray-500">説明文 (日本語)</label>
                            <textarea 
                                className="w-full border-gray-300 rounded-md text-sm mt-1"
                                rows={3}
                                placeholder="例：日常で使いやすいかわいいうさぎです。"
                                value={meta.stampDescJa}
                                onChange={e => setMeta({...meta, stampDescJa: e.target.value})}
                            />
                        </div>

                        <button 
                            onClick={handleTranslation}
                            disabled={isTranslating}
                            className="w-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white py-2 rounded-lg font-bold text-sm shadow hover:shadow-lg transition disabled:opacity-50"
                        >
                            {isTranslating ? 'AI翻訳中...' : 'AIで英語に自動翻訳'}
                        </button>

                        <div className="pt-2 border-t border-dashed">
                             <label className="text-xs font-bold text-gray-500">Name (English)</label>
                             <input 
                                type="text" 
                                className="w-full border-gray-300 rounded-md text-sm mt-1 bg-gray-50"
                                value={meta.stampNameEn}
                                onChange={e => setMeta({...meta, stampNameEn: e.target.value})}
                             />
                        </div>
                        <div>
                             <label className="text-xs font-bold text-gray-500">Description (English)</label>
                             <textarea 
                                className="w-full border-gray-300 rounded-md text-sm mt-1 bg-gray-50"
                                rows={3}
                                value={meta.stampDescEn}
                                onChange={e => setMeta({...meta, stampDescEn: e.target.value})}
                             />
                        </div>
                    </div>
                </div>

                {/* Download */}
                <div className="bg-primary-50 p-6 rounded-2xl shadow-inner border border-primary-100">
                    <h3 className="font-bold text-primary-800 flex items-center gap-2 mb-4">
                        <Download className="text-primary-600" size={20} />
                        書き出し
                    </h3>

                    <div className="flex items-center gap-2 mb-4">
                        <input 
                            type="checkbox" 
                            id="renumber"
                            checked={renumber} 
                            onChange={e => setRenumber(e.target.checked)}
                            className="rounded text-primary-600 focus:ring-primary-500"
                        />
                        <label htmlFor="renumber" className="text-sm text-gray-700">番号を振り直す (01.png〜)</label>
                    </div>

                    <button 
                        onClick={handleExport}
                        className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold py-3 rounded-xl shadow-lg shadow-primary-200 transition-all flex items-center justify-center gap-2"
                    >
                        <Download size={20} />
                        ZIPをダウンロード
                    </button>
                    <p className="text-xs text-center text-primary-600/70 mt-2">
                        スタンプ画像・メイン・タブ・テキストが含まれます
                    </p>
                </div>

            </div>
          </div>
        )}
      </main>

      {/* Editor Modal */}
      {editingStamp && (
        <StampEditorModal 
            stamp={editingStamp}
            isOpen={!!editingStamp}
            onClose={() => setEditingStamp(null)}
            onSave={updateStamp}
            previewBg={previewBg}
        />
      )}

      {/* Manual Crop Modal */}
      {isManualCropping && originalImageUrl && (
        <ManualCropModal
            originalImageUrl={originalImageUrl}
            isOpen={isManualCropping}
            onClose={() => setIsManualCropping(false)}
            onConfirm={handleManualCropConfirm}
        />
      )}
    </div>
  );
}

export default App;

export interface Stamp {
  id: string;
  originalX: number;
  originalY: number;
  width: number;
  height: number;
  dataUrl: string; // The cutout transparent image
  isExcluded: boolean;
  // For editor state (370x320)
  scale: number;
  offsetX: number;
  offsetY: number;
}

export interface ExportConfig {
  id: string;
  scale: number;
  offsetX: number;
  offsetY: number;
}

export interface MetaData {
  stampNameJa: string;
  stampDescJa: string;
  stampNameEn: string;
  stampDescEn: string;
}

export enum AppStep {
  UPLOAD = 'UPLOAD',
  PROCESSING = 'PROCESSING',
  EDIT = 'EDIT',
  EXPORT = 'EXPORT',
}

export interface ProcessedResult {
  stamps: Stamp[];
  originalWidth: number;
  originalHeight: number;
}

export const TARGET_WIDTH = 370;
export const TARGET_HEIGHT = 320;
export const MAIN_WIDTH = 240;
export const MAIN_HEIGHT = 240;
export const TAB_WIDTH = 96;
export const TAB_HEIGHT = 74;

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2, Palette } from 'lucide-react';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  initialPreviewBg?: string; 
  targetWidth?: number; // Configurable for Main/Tab editing
  targetHeight?: number;
}

export const StampEditorModal: React.FC<Props> = ({ 
  stamp, 
  isOpen, 
  onClose, 
  onSave, 
  initialPreviewBg = 'checker',
  targetWidth = TARGET_WIDTH,
  targetHeight = TARGET_HEIGHT
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Stamp state (Applied to the image)
  const [scale, setScale] = useState(stamp.scale);
  const [offset, setOffset] = useState({ x: stamp.offsetX, y: stamp.offsetY });

  // Editor View state
  const [viewZoom, setViewZoom] = useState(1);
  const [previewBg, setPreviewBg] = useState(initialPreviewBg);

  const [mode, setMode] = useState<'move' | 'eraser' | 'wand'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  // We need to keep a working copy of the image data for the eraser/wand
  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);

  useEffect(() => {
    if (isOpen) {
      setScale(stamp.scale);
      setOffset({ x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
    }
  }, [isOpen, stamp]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, offset, workingDataUrl, previewBg, targetWidth, targetHeight]);

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Background
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        const x = centerX - (drawnW / 2) + offset.x;
        const y = centerY - (drawnH / 2) + offset.y;

        ctx.save();
        ctx.drawImage(img, x, y, drawnW, drawnH);
        ctx.restore();

        // Draw Border (The output area)
        ctx.strokeStyle = '#10b981'; // Green-500
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);
    };
    img.src = workingDataUrl;
  };

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    // Account for View Zoom
    const x = (e.clientX - rect.left) / viewZoom;
    const y = (e.clientY - rect.top) / viewZoom;

    if (mode === 'wand') {
      applyMagicWand(x, y);
    } else {
      setIsDragging(true);
      setLastPos({ x, y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (e.clientX - rect.left) / viewZoom;
    const y = (e.clientY - rect.top) / viewZoom;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    }
    setLastPos({ x, y });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  // Maps Canvas Coordinates -> Source Image Coordinates
  const getSourceCoords = (canvasX: number, canvasY: number) => {
    const centerX = targetWidth / 2;
    const centerY = targetHeight / 2;
    const drawnW = stamp.width * scale;
    const drawnH = stamp.height * scale;

    const startXOnCanvas = centerX - (drawnW/2) + offset.x;
    const startYOnCanvas = centerY - (drawnH/2) + offset.y;

    const sourceX = Math.floor((canvasX - startXOnCanvas) / scale);
    const sourceY = Math.floor((canvasY - startYOnCanvas) / scale);

    return { sourceX, sourceY };
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;

     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);

       const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
       const sourceEraserSize = eraserSize / scale;

       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();

       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const applyMagicWand = (canvasX: number, canvasY: number) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
    if(!ctx) return;

    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);

      const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
      if (sourceX < 0 || sourceX >= stamp.width || sourceY < 0 || sourceY >= stamp.height) return;

      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;

      // Get target color
      const targetIdx = (sourceY * width + sourceX) * 4;
      const tR = data[targetIdx];
      const tG = data[targetIdx + 1];
      const tB = data[targetIdx + 2];
      const tA = data[targetIdx + 3];

      if (tA === 0) return; // Already transparent

      const tolerance = 30;
      const stack = [[sourceX, sourceY]];
      const visited = new Uint8Array(width * height);

      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= width || y < 0 || y >= height) continue;
        if (visited[y * width + x]) continue;

        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        if (a === 0) continue; // Boundary

        const diff = Math.abs(r - tR) + Math.abs(g - tG) + Math.abs(b - tB);
        if (diff < tolerance * 3) {
           data[idx + 3] = 0; // Make transparent
           visited[y * width + x] = 1;
           stack.push([x + 1, y]);
           stack.push([x - 1, y]);
           stack.push([x, y + 1]);
           stack.push([x, y - 1]);
        }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const handleSave = () => {
