import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';

/**
 * Main function to process the uploaded image.
 * 1. Estimates background color.
 * 2. Removes background (Flood fill).
 * 3. Detects individual stamp blobs.
 * 4. Extracts them into Stamp objects.
 */
export async function processUploadedImage(file: File): Promise<{ stamps: Stamp[], width: number, height: number }> {
  const img = await loadImage(file);
  const canvas = document.createElement('canvas');
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Could not get canvas context');

  ctx.drawImage(img, 0, 0);
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

  // 1 & 2. Remove Background
  const processedImageData = removeBackground(imageData);
  ctx.putImageData(processedImageData, 0, 0);

  // 3 & 4. Detect and Extract Stamps
  const stamps = extractStamps(processedImageData, canvas);

  return {
    stamps,
    width: img.width,
    height: img.height,
  };
}

function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = URL.createObjectURL(file);
  });
}

function removeBackground(imageData: ImageData): ImageData {
  const { width, height, data } = imageData;
  // Sample corners to find background color
  const corners = [
    0, // Top-left
    (width - 1) * 4, // Top-right
    (height - 1) * width * 4, // Bottom-left
    (height * width - 1) * 4 // Bottom-right
  ];

  // Use Top-Left as primary reference for simplicity in this MVP
  const bgR = data[0];
  const bgG = data[1];
  const bgB = data[2];

  const tolerance = 40; // Color distance tolerance

  // Flood fill algorithm to remove continuous background
  const stack: [number, number][] = [];
  const visited = new Uint8Array(width * height);

  // Start from all edges
  for (let x = 0; x < width; x++) {
    stack.push([x, 0]);
    stack.push([x, height - 1]);
  }
  for (let y = 0; y < height; y++) {
    stack.push([0, y]);
    stack.push([width - 1, y]);
  }

  const getIdx = (x: number, y: number) => (y * width + x) * 4;
  const colorMatch = (idx: number) => {
    const r = data[idx];
    const g = data[idx + 1];
    const b = data[idx + 2];
    const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
    return diff < tolerance * 3;
  };

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;
    if (x < 0 || x >= width || y < 0 || y >= height) continue;
    if (visited[y * width + x]) continue;

    const idx = getIdx(x, y);

    if (colorMatch(idx)) {
      data[idx + 3] = 0; // Set Alpha to 0
      visited[y * width + x] = 1;

      stack.push([x + 1, y]);
      stack.push([x - 1, y]);
      stack.push([x, y + 1]);
      stack.push([x, y - 1]);
    }
  }

  return imageData;
}

function extractStamps(imageData: ImageData, sourceCanvas: HTMLCanvasElement): Stamp[] {
  const { width, height, data } = imageData;
  const visited = new Uint8Array(width * height);
  const boxes: { x: number, y: number, w: number, h: number }[] = [];

  // Iterate to find islands of non-transparent pixels
  for (let y = 0; y < height; y+=4) { // Skip lines for speed optimization
    for (let x = 0; x < width; x+=4) {
      const idx = (y * width + x) * 4;
      if (data[idx + 3] > 0 && !visited[y * width + x]) {
        const box = findBoundingBox(x, y, width, height, data, visited);
        if (box.w > 20 && box.h > 20) {
           boxes.push(box);
        }
      }
    }
  }

  const mergedBoxes = mergeBoxes(boxes);

  // Sort boxes
  mergedBoxes.sort((a, b) => a.y - b.y);

  const rows: typeof mergedBoxes[] = [];
  let currentRow: typeof mergedBoxes = [];
  let lastY = -1000;

  mergedBoxes.forEach(box => {
    if (currentRow.length === 0) {
      currentRow.push(box);
      lastY = box.y;
    } else {
      const yDiff = Math.abs(box.y - lastY);
      if (yDiff < box.h / 2) {
        currentRow.push(box);
      } else {
        rows.push(currentRow);
        currentRow = [box];
        lastY = box.y;
      }
    }
  });
  if (currentRow.length > 0) rows.push(currentRow);

  const sortedBoxes = rows.flatMap(row => row.sort((a, b) => a.x - b.x));

  return sortedBoxes.map((box, index) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = box.w;
    tempCanvas.height = box.h;
    const tCtx = tempCanvas.getContext('2d');

    tCtx?.drawImage(sourceCanvas, box.x, box.y, box.w, box.h, 0, 0, box.w, box.h);

    // Calculate initial scale to fit TARGET_WIDTH/HEIGHT
    const padding = 20;
    const availW = TARGET_WIDTH - padding;
    const availH = TARGET_HEIGHT - padding;

    let scale = Math.min(availW / box.w, availH / box.h);
    // Use scale up to 1.0 (100%), if it is smaller than target, we don't necessarily upscale unless user wants to.
    // But for preview consistency, let's keep it max 1.0. 
    // Actually, if the stamp is HUGE, scale < 1. If stamp is TINY, scale > 1 might be blurry.
    if (scale > 1) scale = 1;

    return {
      id: `stamp-${index}`,
      originalX: box.x,
      originalY: box.y,
      width: box.w,
      height: box.h,
      dataUrl: tempCanvas.toDataURL('image/png'),
      isExcluded: false,
      scale: scale, 
      offsetX: 0,
      offsetY: 0
    };
  });
}

function findBoundingBox(startX: number, startY: number, w: number, h: number, data: Uint8ClampedArray, visited: Uint8Array) {
  let minX = startX, maxX = startX, minY = startY, maxY = startY;
  const stack = [[startX, startY]];
  visited[startY * w + startX] = 1;

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;

    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;

    const neighbors = [
      [x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]
    ];

    for (const [nx, ny] of neighbors) {
      if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
        if (!visited[ny * w + nx]) {
           const idx = (ny * w + nx) * 4;
           if (data[idx + 3] > 10) { 
             visited[ny * w + nx] = 1;
             stack.push([nx, ny]);
           }
        }
      }
    }
  }

  return { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

function mergeBoxes(boxes: { x: number, y: number, w: number, h: number }[]) {
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < boxes.length; i++) {
      for (let j = i + 1; j < boxes.length; j++) {
        const a = boxes[i];
        const b = boxes[j];
        if (rectIntersect(a, b)) {
          const newX = Math.min(a.x, b.x);
          const newY = Math.min(a.y, b.y);
          const newMaxX = Math.max(a.x + a.w, b.x + b.w);
          const newMaxY = Math.max(a.y + a.h, b.y + b.h);

          boxes[i] = { x: newX, y: newY, w: newMaxX - newX, h: newMaxY - newY };
          boxes.splice(j, 1);
          changed = true;
          j--;
        }
      }
    }
  }
  return boxes;
}

function rectIntersect(a: { x: number, y: number, w: number, h: number }, b: { x: number, y: number, w: number, h: number }) {
  // Increased padding to merge text and illustrations that are slightly apart.
  const padding = 50; 
  return (a.x < b.x + b.w + padding && a.x + a.w + padding > b.x &&
          a.y < b.y + b.h + padding && a.y + a.h + padding > b.y);
}

import React, { useRef, useState, useEffect } from 'react';
import { X, Crop, Check } from 'lucide-react';
import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';

interface Props {
  originalImageUrl: string;
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (cropData: Stamp) => void;
}

export const ManualCropModal: React.FC<Props> = ({ originalImageUrl, isOpen, onClose, onConfirm }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);
  const [selection, setSelection] = useState<{ x: number, y: number, w: number, h: number } | null>(null);
  const [isSelecting, setIsSelecting] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    if (isOpen) {
        setSelection(null);
    }
  }, [isOpen]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!imgRef.current) return;
    const rect = imgRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setIsSelecting(true);
    setStartPos({ x, y });
    setSelection({ x, y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isSelecting || !imgRef.current) return;
    const rect = imgRef.current.getBoundingClientRect();
    const currentX = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
    const currentY = Math.max(0, Math.min(e.clientY - rect.top, rect.height));

    const w = currentX - startPos.x;
    const h = currentY - startPos.y;

    setSelection({
      x: w > 0 ? startPos.x : currentX,
      y: h > 0 ? startPos.y : currentY,
      w: Math.abs(w),
      h: Math.abs(h)
    });
  };

  const handleMouseUp = () => {
    setIsSelecting(false);
  };

  const handleCrop = () => {
    if (!selection || !imgRef.current || selection.w < 10 || selection.h < 10) {
        alert("範囲を選択してください");
        return;
    }

    // Convert display coordinates to natural image coordinates
    const scaleX = imgRef.current.naturalWidth / imgRef.current.width;
    const scaleY = imgRef.current.naturalHeight / imgRef.current.height;

    const realX = Math.floor(selection.x * scaleX);
    const realY = Math.floor(selection.y * scaleY);
    const realW = Math.floor(selection.w * scaleX);
    const realH = Math.floor(selection.h * scaleY);

    // Create Canvas to extract and process
    const canvas = document.createElement('canvas');
    canvas.width = realW;
    canvas.height = realH;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Draw the cropped area
    ctx.drawImage(imgRef.current, realX, realY, realW, realH, 0, 0, realW, realH);

    // Auto-remove background (Simple corner flood fill like automatic process)
    const imageData = ctx.getImageData(0, 0, realW, realH);
    const data = imageData.data;

    // Sample corners to find background color
    const corners = [0, (realW - 1) * 4, (realH - 1) * realW * 4, (realH * realW - 1) * 4];
    const bgR = data[0];
    const bgG = data[1];
    const bgB = data[2];
    const tolerance = 40;

    const stack: [number, number][] = [];
    const visited = new Uint8Array(realW * realH);

    // Start from edges
    for (let x = 0; x < realW; x++) { stack.push([x, 0]); stack.push([x, realH - 1]); }
    for (let y = 0; y < realH; y++) { stack.push([0, y]); stack.push([realW - 1, y]); }

    while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= realW || y < 0 || y >= realH) continue;
        if (visited[y * realW + x]) continue;

        const idx = (y * realW + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);

        if (diff < tolerance * 3) {
            data[idx + 3] = 0; // Transparent
            visited[y * realW + x] = 1;
            stack.push([x + 1, y]); stack.push([x - 1, y]); stack.push([x, y + 1]); stack.push([x, y - 1]);
        }
    }

    ctx.putImageData(imageData, 0, 0);

    // Calculate initial scale to fit TARGET_WIDTH/HEIGHT
    const padding = 20;
    const availW = TARGET_WIDTH - padding;
    const availH = TARGET_HEIGHT - padding;
    let scale = Math.min(availW / realW, availH / realH);
    if (scale > 1) scale = 1;

    const stampId = `stamp-manual-${Date.now()}`;
    const newStamp: Stamp = {
        id: stampId,
        originalX: realX,
        originalY: realY,
        width: realW,
        height: realH,
        dataUrl: canvas.toDataURL('image/png'),
        isExcluded: false,
        scale: scale,
        offsetX: 0,
        offsetY: 0
    };

    onConfirm(newStamp);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col h-[90vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
            <div className="flex items-center gap-2">
                <Crop className="text-primary-600" />
                <div>
                    <h3 className="font-bold text-gray-700">手動で切り出し (再選択)</h3>
                    <p className="text-xs text-gray-500">元画像からスタンプにしたい範囲をドラッグしてください</p>
                </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
        </div>

        {/* Change: Remove items-center justify-center from the scrollable container to prevent top/left clipping when scrolled */}
        <div className="flex-1 overflow-auto p-4 bg-gray-900 relative select-none" ref={containerRef}>
            {/* Wrap in a flex container that grows to ensure centering only if image is smaller than container */}
            <div className="min-w-full min-h-full flex items-center justify-center">
                <div className="relative inline-block">
                    <img 
                        ref={imgRef}
                        src={originalImageUrl} 
                        className="max-w-none pointer-events-none" // Use max-w-none to allow natural size scrolling
                        style={{ maxWidth: '100%' }}
                        alt="Original"
                    />
                    {/* Overlay for selection */}
                    <div 
                        className="absolute inset-0 cursor-crosshair"
                        onMouseDown={handleMouseDown}
                        onMouseMove={handleMouseMove}
                        onMouseUp={handleMouseUp}
                        onMouseLeave={handleMouseUp}
                    >
                        {selection && (
                            <div 
                                className="absolute border-2 border-white shadow-[0_0_0_9999px_rgba(0,0,0,0.5)]"
                                style={{
                                    left: selection.x,
                                    top: selection.y,
                                    width: selection.w,
                                    height: selection.h
                                }}
                            />
                        )}
                    </div>
                </div>
            </div>
        </div>

        <div className="p-4 border-t flex justify-end gap-3 bg-gray-50 rounded-b-xl shrink-0">
          <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
          <button onClick={handleCrop} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
            <Check size={18} /> この範囲で作成
          </button>
        </div>
      </div>
    </div>
  );
};

// Developed by yayoi, 2026.
