          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t py-4 text-center text-gray-400 text-xs mt-auto">
          Developed by yayoi, 2026.
      </footer>

      {/* Standard Stamp Editor Modal */}
