        <StampEditorModal 
            stamp={editingStamp}
            isOpen={!!editingStamp}
            onClose={() => setEditingStamp(null)}
            onSave={updateStamp}
            initialPreviewBg={previewBg}
            targetWidth={TARGET_WIDTH}
            targetHeight={TARGET_HEIGHT}
        />
      )}

      {/* Main/Tab Special Editor Modal */}
      {(editingSpecialType === 'main' && mainConfig) && (
          <StampEditorModal 
            // We construct a temporary 'Stamp' object from the config + source dataUrl
            // Priority: Custom Edited URL -> Original Stamp URL
            stamp={{
                ...stamps.find(s => s.id === mainConfig.id)!,
                scale: mainConfig.scale,
                offsetX: mainConfig.offsetX,
                offsetY: mainConfig.offsetY,
                dataUrl: mainConfig.customDataUrl || stamps.find(s => s.id === mainConfig.id)!.dataUrl
            }}
            isOpen={true}
            onClose={() => setEditingSpecialType(null)}
            onSave={(updated) => {
                updateSpecialConfig(updated);
                setEditingSpecialType(null);
            }}
            initialPreviewBg={previewBg}
            targetWidth={MAIN_WIDTH}
            targetHeight={MAIN_HEIGHT}
        />
      )}
      {(editingSpecialType === 'tab' && tabConfig) && (
          <StampEditorModal 
            stamp={{
                ...stamps.find(s => s.id === tabConfig.id)!,
                scale: tabConfig.scale,
                offsetX: tabConfig.offsetX,
                offsetY: tabConfig.offsetY,
                dataUrl: tabConfig.customDataUrl || stamps.find(s => s.id === tabConfig.id)!.dataUrl
            }}
            isOpen={true}
            onClose={() => setEditingSpecialType(null)}
            onSave={(updated) => {
                updateSpecialConfig(updated);
                setEditingSpecialType(null);
            }}
            initialPreviewBg={previewBg}
            targetWidth={TAB_WIDTH}
            targetHeight={TAB_HEIGHT}
        />
      )}

      {/* Manual Crop Modal */}
      {isManualCropping && originalImageUrl && (
        <ManualCropModal
            originalImageUrl={originalImageUrl}
            isOpen={isManualCropping}
            onClose={() => setIsManualCropping(false)}
            onConfirm={handleManualCropConfirm}
        />
      )}
    </div>
  );
}

