import { GoogleGenAI } from "@google/genai";

// Use stable models only to avoid "model not found" errors
const MODELS = [
  "gemini-1.5-flash",
  "gemini-1.5-pro",
];

export async function translateMeta(
  jaName: string,
  jaDesc: string
): Promise<{ enName: string; enDesc: string }> {
  // Try to get API key from process.env (Node/AI Studio) or import.meta.env (Vite)
  // @ts-ignore
  const apiKey = process.env.API_KEY || (typeof import.meta !== 'undefined' && (import.meta as any).env?.VITE_GEMINI_API_KEY);

  if (!apiKey) {
    console.error("API Key is missing. Please set process.env.API_KEY or VITE_GEMINI_API_KEY.");
    throw new Error("APIキーが設定されていません。環境変数をご確認ください。");
  }

  const ai = new GoogleGenAI({ apiKey });

  // Helper to translate a single text with retry logic
  async function translateText(text: string): Promise<string> {
    if (!text || text.trim() === "") return "";

    const prompt = `You are a professional translator.
Translate the following Japanese into natural English.
Return ONLY the translation text. No explanations.

Japanese:
${text}`;

    let lastError = null;

    for (const model of MODELS) {
      try {
        console.log(`Trying translation with model: ${model}`);
        const response = await ai.models.generateContent({
          model: model,
          contents: {
            parts: [{ text: prompt }]
          },
          config: {
            temperature: 0.1, // Low temp for deterministic result
            maxOutputTokens: 512,
          }
        });

        // Robust text extraction
        let translatedText = "";

        // 1. Check response.text property (Standard for @google/genai)
        if (response.text) {
            translatedText = response.text;
        } 
        // 2. Fallback: Check candidates deeply
        else if (response.candidates && response.candidates.length > 0) {
             const parts = response.candidates[0].content?.parts;
             if (parts && parts.length > 0 && parts[0].text) {
                 translatedText = parts[0].text;
             }
        }

        if (translatedText && translatedText.trim().length > 0) {
            console.log(`Translation success (${model}):`, translatedText);
            return translatedText.trim();
        } else {
            console.warn(`Model ${model} returned empty text.`);
        }

      } catch (error) {
        console.warn(`Failed with model ${model}:`, error);
        lastError = error;
      }
    }

    console.error("All translation models failed.");
    // If all models fail, throw the last error to be caught by the caller
    throw lastError || new Error("Translation failed with all models.");
  }

  try {
    const [enName, enDesc] = await Promise.all([
        translateText(jaName),
        translateText(jaDesc)
    ]);

    return { enName, enDesc };

  } catch (error) {
    console.error("translateMeta fatal error:", error);
    // Re-throw so UI can handle it
    throw error;
  }
}

import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';

/**
 * Main function to process the uploaded image.
 * 1. Estimates background color.
 * 2. Removes background (Flood fill).
 * 3. Detects individual stamp blobs.
 * 4. Extracts them into Stamp objects.
 */
export async function processUploadedImage(file: File): Promise<{ stamps: Stamp[], width: number, height: number }> {
  const img = await loadImage(file);
  const canvas = document.createElement('canvas');
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Could not get canvas context');

  ctx.drawImage(img, 0, 0);
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

  // 1 & 2. Remove Background
  const processedImageData = removeBackground(imageData);
  ctx.putImageData(processedImageData, 0, 0);

  // 3 & 4. Detect and Extract Stamps
  const stamps = extractStamps(processedImageData, canvas);

  return {
    stamps,
    width: img.width,
    height: img.height,
  };
}

function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = URL.createObjectURL(file);
  });
}

function removeBackground(imageData: ImageData): ImageData {
  const { width, height, data } = imageData;
  // Sample corners to find background color
  const corners = [
    0, // Top-left
    (width - 1) * 4, // Top-right
    (height - 1) * width * 4, // Bottom-left
    (height * width - 1) * 4 // Bottom-right
  ];

  // Use Top-Left as primary reference for simplicity in this MVP
  const bgR = data[0];
  const bgG = data[1];
  const bgB = data[2];

  const tolerance = 40; // Color distance tolerance

  // Flood fill algorithm to remove continuous background
  const stack: [number, number][] = [];
  const visited = new Uint8Array(width * height);

  // Start from all edges
  for (let x = 0; x < width; x++) {
    stack.push([x, 0]);
    stack.push([x, height - 1]);
  }
  for (let y = 0; y < height; y++) {
    stack.push([0, y]);
    stack.push([width - 1, y]);
  }

  const getIdx = (x: number, y: number) => (y * width + x) * 4;
  const colorMatch = (idx: number) => {
    const r = data[idx];
    const g = data[idx + 1];
    const b = data[idx + 2];
    const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
    return diff < tolerance * 3;
  };

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;
    if (x < 0 || x >= width || y < 0 || y >= height) continue;
    if (visited[y * width + x]) continue;

    const idx = getIdx(x, y);

    if (colorMatch(idx)) {
      data[idx + 3] = 0; // Set Alpha to 0
      visited[y * width + x] = 1;

      stack.push([x + 1, y]);
      stack.push([x - 1, y]);
      stack.push([x, y + 1]);
      stack.push([x, y - 1]);
    }
  }

  return imageData;
}

function extractStamps(imageData: ImageData, sourceCanvas: HTMLCanvasElement): Stamp[] {
  const { width, height, data } = imageData;
  const visited = new Uint8Array(width * height);
  const boxes: { x: number, y: number, w: number, h: number }[] = [];

  // Iterate to find islands of non-transparent pixels
  for (let y = 0; y < height; y+=4) { // Skip lines for speed optimization
    for (let x = 0; x < width; x+=4) {
      const idx = (y * width + x) * 4;
      if (data[idx + 3] > 0 && !visited[y * width + x]) {
        const box = findBoundingBox(x, y, width, height, data, visited);
        if (box.w > 20 && box.h > 20) {
           boxes.push(box);
        }
      }
    }
  }

  const mergedBoxes = mergeBoxes(boxes);

  // Sort boxes
  mergedBoxes.sort((a, b) => a.y - b.y);

  const rows: typeof mergedBoxes[] = [];
  let currentRow: typeof mergedBoxes = [];
  let lastY = -1000;

  mergedBoxes.forEach(box => {
    if (currentRow.length === 0) {
      currentRow.push(box);
      lastY = box.y;
    } else {
      const yDiff = Math.abs(box.y - lastY);
      if (yDiff < box.h / 2) {
        currentRow.push(box);
      } else {
        rows.push(currentRow);
        currentRow = [box];
        lastY = box.y;
      }
    }
  });
  if (currentRow.length > 0) rows.push(currentRow);

  const sortedBoxes = rows.flatMap(row => row.sort((a, b) => a.x - b.x));

  return sortedBoxes.map((box, index) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = box.w;
    tempCanvas.height = box.h;
    const tCtx = tempCanvas.getContext('2d');

    tCtx?.drawImage(sourceCanvas, box.x, box.y, box.w, box.h, 0, 0, box.w, box.h);

    // Calculate initial scale to fit TARGET_WIDTH/HEIGHT
    const padding = 20;
    const availW = TARGET_WIDTH - padding;
    const availH = TARGET_HEIGHT - padding;

    let scale = Math.min(availW / box.w, availH / box.h);
    // Use scale up to 1.0 (100%), if it is smaller than target, we don't necessarily upscale unless user wants to.
    // But for preview consistency, let's keep it max 1.0. 
    // Actually, if the stamp is HUGE, scale < 1. If stamp is TINY, scale > 1 might be blurry.
    if (scale > 1) scale = 1;

    return {
      id: `stamp-${index}`,
      originalX: box.x,
      originalY: box.y,
      width: box.w,
      height: box.h,
      dataUrl: tempCanvas.toDataURL('image/png'),
      isExcluded: false,
      scale: scale, 
      offsetX: 0,
      offsetY: 0
    };
  });
}

function findBoundingBox(startX: number, startY: number, w: number, h: number, data: Uint8ClampedArray, visited: Uint8Array) {
  let minX = startX, maxX = startX, minY = startY, maxY = startY;
  const stack = [[startX, startY]];
  visited[startY * w + startX] = 1;

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;

    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;

    const neighbors = [
      [x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]
    ];

    for (const [nx, ny] of neighbors) {
      if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
        if (!visited[ny * w + nx]) {
           const idx = (ny * w + nx) * 4;
           if (data[idx + 3] > 10) { 
             visited[ny * w + nx] = 1;
             stack.push([nx, ny]);
           }
        }
      }
    }
  }

  return { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

function mergeBoxes(boxes: { x: number, y: number, w: number, h: number }[]) {
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < boxes.length; i++) {
      for (let j = i + 1; j < boxes.length; j++) {
        const a = boxes[i];
        const b = boxes[j];
        if (rectIntersect(a, b)) {
          const newX = Math.min(a.x, b.x);
          const newY = Math.min(a.y, b.y);
          const newMaxX = Math.max(a.x + a.w, b.x + b.w);
          const newMaxY = Math.max(a.y + a.h, b.y + b.h);

          boxes[i] = { x: newX, y: newY, w: newMaxX - newX, h: newMaxY - newY };
          boxes.splice(j, 1);
          changed = true;
          j--;
        }
      }
    }
  }
  return boxes;
}

function rectIntersect(a: { x: number, y: number, w: number, h: number }, b: { x: number, y: number, w: number, h: number }) {
  // Increased padding to merge text and illustrations that are slightly apart.
  const padding = 80; 
  return (a.x < b.x + b.w + padding && a.x + a.w + padding > b.x &&
          a.y < b.y + b.h + padding && a.y + a.h + padding > b.y);
}

import { GoogleGenAI } from "@google/genai";

export async function translateMeta(
  jaName: string,
  jaDesc: string
): Promise<{ enName: string; enDesc: string }> {
  // Try to get API key from process.env (Node/AI Studio) or import.meta.env (Vite)
  // @ts-ignore
  const apiKey = process.env.API_KEY || (typeof import.meta !== 'undefined' && (import.meta as any).env?.VITE_GEMINI_API_KEY);

  if (!apiKey) {
    throw new Error("APIキーが見つかりません。環境変数(API_KEY または VITE_GEMINI_API_KEY)を設定してください。");
  }

  const ai = new GoogleGenAI({ apiKey });

  // Use the most stable standard model
  const MODEL_NAME = "gemini-1.5-flash";

  async function translateText(text: string): Promise<string> {
    if (!text || text.trim() === "") return "";

    const prompt = `You are a professional translator.
Translate the following Japanese into natural English.
Return ONLY the translation text. No explanations.

Japanese:
${text}`;

    try {
        const response = await ai.models.generateContent({
          model: MODEL_NAME,
          contents: {
            parts: [{ text: prompt }]
          },
          config: {
            temperature: 0.1,
            maxOutputTokens: 512,
          }
        });

        // 1. Try standard text property
        if (response.text) {
            return response.text.trim();
        } 
        // 2. Try candidates parsing
        else if (response.candidates && response.candidates.length > 0) {
             const parts = response.candidates[0].content?.parts;
             if (parts && parts.length > 0 && parts[0].text) {
                 return parts[0].text.trim();
             }
        }

        return "";
    } catch (error: any) {
        console.warn(`Translation failed for text: "${text.substring(0, 10)}..."`, error);
        // Throwing error here will be caught by translateMeta's Promise.all
        throw new Error(`Gemini API Error: ${error.message || 'Unknown error'}`);
    }
  }

  try {
    const [enName, enDesc] = await Promise.all([
        translateText(jaName),
        translateText(jaDesc)
    ]);

    return { enName, enDesc };

  } catch (error) {
    console.error("translateMeta fatal error:", error);
    throw error;
  }
}

