            }}
            isOpen={true}
            onClose={() => setEditingSpecialType(null)}
            onSave={(updated) => {
                updateSpecialConfig(updated);
                setEditingSpecialType(null);
            }}
            initialPreviewBg={previewBg}
            targetWidth={TAB_WIDTH}
            targetHeight={TAB_HEIGHT}
        />
      )}

      {/* Manual Crop Modal */}
      {isManualCropping && (
        <ManualCropModal
            sourceImages={sourceImages}
            isOpen={isManualCropping}
            onClose={() => setIsManualCropping(false)}
            onConfirm={handleManualCropConfirm}
            onAddSource={handleAddSourceFromModal}
        />
      )}
    </div>
  );
}

