                  <div className="mt-4 pt-4 border-t flex justify-end">
                      <button onClick={() => setShowSourceSelectModal(false)} className="text-gray-500 hover:text-gray-700 text-sm font-bold px-4 py-2 hover:bg-gray-100 rounded-lg transition">
                          キャンセル
