      {/* 2. Process Method Selection Modal */}
      {showProcessSelection && selectedSourceForNewStamp && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-60 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full p-6 text-center animate-fade-in relative">
                  <button 
                    onClick={() => {
                        setShowProcessSelection(false);
                        setShowSourceSelectModal(true); // Back to source select
