                             <textarea 
                                className="w-full bg-primary-50 border-primary-200 rounded-md text-sm focus:ring-primary-500 focus:border-primary-500"
                                rows={3}
                                maxLength={160}
                                value={meta.stampDescEn}
                                onChange={e => setMeta({...meta, stampDescEn: e.target.value})}
                             />
                        </div>
                    </div>
                </div>

                {/* Download */}
                <div className="bg-primary-50 p-6 rounded-2xl shadow-inner border border-primary-100 space-y-4">
                    <div>
                        <h3 className="font-bold text-primary-800 flex items-center gap-2 mb-4">
                            <Download className="text-primary-600" size={20} />
                            書き出し
                        </h3>

                        <div className="flex items-center gap-2 mb-4">
                            <input 
                                type="checkbox" 
                                id="renumber"
                                checked={renumber} 
                                onChange={e => setRenumber(e.target.checked)}
                                className="rounded text-primary-600 focus:ring-primary-500"
                            />
                            <label htmlFor="renumber" className="text-sm text-gray-700">番号を振り直す (01.png〜)</label>
                        </div>

                        <button 
                            onClick={handleExport}
                            className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold py-3 rounded-xl shadow-lg shadow-primary-200 transition-all flex items-center justify-center gap-2"
                        >
                            <Download size={20} />
                            ZIPをダウンロード
                        </button>
                        <p className="text-xs text-center text-primary-600/70 mt-2">
                            スタンプ画像・メイン・タブ・テキストが含まれます
                        </p>
                    </div>

                    <div className="pt-4 border-t border-primary-200/50 space-y-3">
                        <a 
                            href="https://creator.line.me/ja/stickermaker/" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="w-full bg-white text-[#06C755] border border-[#06C755] hover:bg-[#06C755] hover:text-white font-bold py-3 rounded-xl shadow transition-all flex items-center justify-center gap-2 md:hidden"
                        >
                            <Smartphone size={18} />
                            LINEスタンプメーカー
                        </a>
                        <a 
                            href="https://creator.line.me/ja/" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="w-full bg-white text-gray-600 border border-gray-300 hover:bg-gray-100 font-bold py-3 rounded-xl shadow transition-all flex items-center justify-center gap-2"
                        >
                            <ExternalLink size={18} />
                            クリエイターズマーケット
                        </a>
                        <p className="text-xs text-center text-gray-500 mt-2">
                            スタンプ申請はこちら
                        </p>
                    </div>
                </div>

            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-transparent py-4 text-center text-gray-400 text-xs mt-auto">
          Developed by yayoi, 2026.
      </footer>

      {/* 1. Source Selection Modal (New Step) */}
      {showSourceSelectModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-60 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full p-6 animate-fade-in flex flex-col max-h-[90vh]">
                  <div className="flex justify-between items-center mb-4">
                     <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                         <Images size={20} className="text-primary-500"/>
                         使用する画像を選択
                     </h3>
                     <button onClick={() => setShowSourceSelectModal(false)} className="p-1 hover:bg-gray-100 rounded-full">
                         <XIcon size={20} className="text-gray-400" />
                     </button>
                  </div>

                  <div className="flex-1 overflow-y-auto min-h-[200px] p-2">
                      <div className="mb-4">
                        <label className="w-full bg-primary-50 border-2 border-dashed border-primary-300 hover:border-primary-500 hover:bg-primary-100 text-primary-600 rounded-xl p-4 flex flex-col items-center justify-center cursor-pointer transition-all h-24">
                            <div className="flex items-center gap-2 font-bold">
                                <Plus size={24} />
                                新しい画像をアップロード
                            </div>
                            <input 
                                type="file" 
                                accept="image/png, image/jpeg" 
                                onChange={handleUploadForNewStamp}
                                className="hidden"
                            />
                        </label>
                      </div>

                      <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                          {sourceImages.map(img => (
                              <button 
                                key={img.id}
                                onClick={() => handleSelectExistingSource(img)}
                                className="aspect-square rounded-lg border-2 border-transparent hover:border-primary-500 hover:ring-2 hover:ring-primary-100 overflow-hidden relative group transition-all"
                              >
                                  <img src={img.url} alt="source" className="w-full h-full object-cover" />
                                  <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center">
                                      <span className="opacity-0 group-hover:opacity-100 bg-white/90 text-xs px-2 py-1 rounded-full font-bold shadow-sm text-primary-700">選択</span>
                                  </div>
                              </button>
                          ))}
                      </div>
                      {sourceImages.length === 0 && (
                          <div className="flex flex-col items-center justify-center py-4 text-gray-400">
                              <p className="text-xs">アップロード済みの画像はありません</p>
                          </div>
                      )}
                  </div>

                  <div className="mt-4 pt-4 border-t flex justify-end">
                      <button onClick={() => setShowSourceSelectModal(false)} className="text-gray-500 hover:text-gray-700 text-sm font-bold px-4 py-2 hover:bg-gray-100 rounded-lg transition">
                          キャンセル
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* 2. Process Method Selection Modal */}
      {showProcessSelection && selectedSourceForNewStamp && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-60 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full p-6 text-center animate-fade-in relative">
                  <button 
                    onClick={() => {
                        setShowProcessSelection(false);
                        setShowSourceSelectModal(true); // Back to source select
                    }}
                    className="absolute top-4 left-4 text-gray-400 hover:text-gray-600"
                  >
                      <ArrowLeft size={20} />
                  </button>

                  <h3 className="text-lg font-bold text-gray-800 mb-2 mt-2">画像の処理方法を選択</h3>
                  <div className="mb-6 flex justify-center">
                    <img src={selectedSourceForNewStamp.url} className="h-24 w-auto object-contain rounded border border-gray-200" alt="preview" />
                  </div>

                  <div className="space-y-3">
                      <button 
                        onClick={() => processNewImage('auto')}
                        className="w-full flex items-center justify-center gap-2 bg-primary-600 hover:bg-primary-700 text-white font-bold py-3 rounded-xl transition"
                      >
                          <Wand2 size={18} />
                          自動切り出し
                      </button>
                      <button 
                        onClick={() => processNewImage('manual')}
                        className="w-full flex items-center justify-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 font-bold py-3 rounded-xl transition"
                      >
                          <Crop size={18} />
                          手動で範囲指定
                      </button>
                  </div>

                  <button 
                    onClick={() => { setShowProcessSelection(false); setSelectedSourceForNewStamp(null); }}
                    className="mt-4 text-sm text-gray-400 hover:text-gray-600 underline"
                  >
                      キャンセル
                  </button>
              </div>
          </div>
      )}

      {/* Standard Stamp Editor Modal */}
      {editingStamp && (
        <StampEditorModal 
            stamp={editingStamp}
            isOpen={!!editingStamp}
            onClose={() => setEditingStamp(null)}
            onSave={updateStamp}
            initialPreviewBg={previewBg}
            targetWidth={TARGET_WIDTH}
            targetHeight={TARGET_HEIGHT}
        />
      )}

      {/* Main/Tab Special Editor Modal */}
      {(editingSpecialType === 'main' && mainConfig) && (
          <StampEditorModal 
            // We construct a temporary 'Stamp' object from the config + source dataUrl
            // Priority: Custom Edited URL -> Original Stamp URL
            stamp={{
                ...stamps.find(s => s.id === mainConfig.id)!,
                scale: mainConfig.scale,
                offsetX: mainConfig.offsetX,
                offsetY: mainConfig.offsetY,
                dataUrl: mainConfig.customDataUrl || stamps.find(s => s.id === mainConfig.id)!.dataUrl
            }}
            isOpen={true}
            onClose={() => setEditingSpecialType(null)}
            onSave={(updated) => {
                updateSpecialConfig(updated);
                setEditingSpecialType(null);
            }}
            initialPreviewBg={previewBg}
            targetWidth={MAIN_WIDTH}
            targetHeight={MAIN_HEIGHT}
        />
      )}
      {(editingSpecialType === 'tab' && tabConfig) && (
          <StampEditorModal 
            stamp={{
                ...stamps.find(s => s.id === tabConfig.id)!,
                scale: tabConfig.scale,
                offsetX: tabConfig.offsetX,
                offsetY: tabConfig.offsetY,
                dataUrl: tabConfig.customDataUrl || stamps.find(s => s.id === tabConfig.id)!.dataUrl
            }}
            isOpen={true}
            onClose={() => setEditingSpecialType(null)}
            onSave={(updated) => {
                updateSpecialConfig(updated);
                setEditingSpecialType(null);
            }}
            initialPreviewBg={previewBg}
            targetWidth={TAB_WIDTH}
            targetHeight={TAB_HEIGHT}
        />
      )}

      {/* Manual Crop Modal */}
      {isManualCropping && (
        <ManualCropModal
            sourceImages={sourceImages}
            isOpen={isManualCropping}
            onClose={() => setIsManualCropping(false)}
            onConfirm={handleManualCropConfirm}
            onAddSource={handleAddSourceFromModal}
        />
      )}
    </div>
  );
}

export default App;

// Developed by yayoi, 2026.
