                             <input 
                                type="text" 
                                className="w-full bg-primary-50 border-primary-200 rounded-md text-sm focus:ring-primary-500 focus:border-primary-500"
                                maxLength={40}
                                value={meta.stampNameEn}
                                onChange={e => setMeta({...meta, stampNameEn: e.target.value})}
                             />
                        </div>
                        <div>
                             <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">スタンプ説明文(English)</label>
                                    <CopyButton text={meta.stampDescEn} />
                                </div>
                                <TextCounter current={meta.stampDescEn.length} min={10} max={160} />
                            </div>
                             <textarea 
                                className="w-full bg-primary-50 border-primary-200 rounded-md text-sm focus:ring-primary-500 focus:border-primary-500"
                                rows={3}
                                maxLength={160}
                                value={meta.stampDescEn}
                                onChange={e => setMeta({...meta, stampDescEn: e.target.value})}
                             />
                        </div>
                    </div>
                </div>

                {/* Download */}
                <div className="bg-primary-50 p-6 rounded-2xl shadow-inner border border-primary-100 space-y-4">
                    <div>
                        <h3 className="font-bold text-primary-800 flex items-center gap-2 mb-4">
                            <Download className="text-primary-600" size={20} />
                            書き出し
                        </h3>

                        <div className="flex items-center gap-2 mb-4">
                            <input 
                                type="checkbox" 
                                id="renumber"
                                checked={renumber} 
                                onChange={e => setRenumber(e.target.checked)}
                                className="rounded text-primary-600 focus:ring-primary-500"
                            />
                            <label htmlFor="renumber" className="text-sm text-gray-700">番号を振り直す (01.png〜)</label>
                        </div>

                        <button 
                            onClick={handleExport}
                            className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold py-3 rounded-xl shadow-lg shadow-primary-200 transition-all flex items-center justify-center gap-2"
                        >
                            <Download size={20} />
                            ZIPをダウンロード
                        </button>
                        <p className="text-xs text-center text-primary-600/70 mt-2">
                            スタンプ画像・メイン・タブ・テキストが含まれます
                        </p>
                    </div>

                    <div className="pt-4 border-t border-primary-200/50 space-y-3">
                        <a 
                            href="https://creator.line.me/ja/stickermaker/" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="w-full bg-white text-[#06C755] border border-[#06C755] hover:bg-[#06C755] hover:text-white font-bold py-3 rounded-xl shadow transition-all flex items-center justify-center gap-2 md:hidden"
                        >
                            <Smartphone size={18} />
                            LINEスタンプメーカー
                        </a>
                        <a 
                            href="https://creator.line.me/ja/" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="w-full bg-white text-gray-600 border border-gray-300 hover:bg-gray-100 font-bold py-3 rounded-xl shadow transition-all flex items-center justify-center gap-2"
                        >
                            <ExternalLink size={18} />
                            クリエイターズマーケット
                        </a>
                        <p className="text-xs text-center text-gray-500 mt-2">
                            スタンプ申請はこちら
                        </p>
                    </div>
                </div>

            </div>
          </div>
        )}
      </main>

      {/* Floating Add Button */}
      {step === AppStep.EDIT && (
        <button 
          onClick={handleOpenNewStampFlow}
          className="fixed bottom-8 right-8 z-40 bg-primary-600 hover:bg-primary-700 text-white font-bold py-4 px-6 rounded-full shadow-2xl transition-all hover:scale-105 active:scale-95 flex items-center gap-2 ring-4 ring-white"
        >
            <Plus size={24} />
            <span className="hidden sm:inline">新規画像追加</span>
        </button>
      )}

      {/* Modals */}
      {editingStamp && (
        <StampEditorModal
          stamp={editingStamp}
          isOpen={!!editingStamp}
          onClose={() => {
              setEditingStamp(null);
              setEditingSpecialType(null);
          }}
          onSave={(updated) => {
              if (editingSpecialType) {
                  updateSpecialConfig(updated);
              } else {
                  updateStamp(updated);
              }
          }}
          onReCrop={() => handleReCropFromEditor(editingStamp)}
          initialPreviewBg={previewBg}
          targetWidth={editingSpecialType === 'main' ? MAIN_WIDTH : (editingSpecialType === 'tab' ? TAB_WIDTH : TARGET_WIDTH)}
          targetHeight={editingSpecialType === 'main' ? MAIN_HEIGHT : (editingSpecialType === 'tab' ? TAB_HEIGHT : TARGET_HEIGHT)}
        />
      )}

      <ManualCropModal
        sourceImages={sourceImages}
        isOpen={isManualCropping}
        onClose={() => {
            setIsManualCropping(false);
            setManualCropInitialSourceId(undefined);
            setTargetReplaceId(null);
        }}
        onConfirm={handleManualCropConfirm}
        onAddSource={handleAddSourceFromModal}
        initialSourceId={manualCropInitialSourceId}
      />

      {/* Helper Modals for New Stamp Flow */}
       {showSourceSelectModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4 animate-fade-in">
             <div className="bg-white rounded-xl p-6 max-w-lg w-full shadow-2xl">
                 <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg text-gray-700">画像を選択</h3>
                    <button onClick={() => setShowSourceSelectModal(false)} className="p-1 hover:bg-gray-100 rounded-full"><XIcon size={20}/></button>
                 </div>
                 <div className="grid grid-cols-3 sm:grid-cols-4 gap-3 mb-6">
                     {sourceImages.map(img => (
                         <button key={img.id} onClick={() => handleSelectExistingSource(img)} className="aspect-square relative border-2 border-transparent hover:border-primary-500 rounded-lg overflow-hidden transition group">
                             <img src={img.url} className="w-full h-full object-cover" />
                             <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                         </button>
                     ))}
                     <label className="aspect-square border-2 border-dashed border-gray-300 flex flex-col items-center justify-center text-gray-500 cursor-pointer hover:bg-primary-50 hover:border-primary-300 rounded-lg transition">
                         <Upload size={24} className="mb-1"/>
                         <span className="text-[10px] font-bold">追加</span>
                         <input type="file" className="hidden" accept="image/png, image/jpeg" onChange={handleUploadForNewStamp}/>
                     </label>
                 </div>
             </div>
        </div>
      )}

      {showProcessSelection && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4 animate-fade-in">
              <div className="bg-white rounded-xl p-6 max-w-md w-full shadow-2xl">
                  <h3 className="font-bold text-lg mb-6 text-center text-gray-700">切り出し方法</h3>
                  <div className="space-y-3">
                      <button onClick={() => processNewImage('auto')} className="w-full py-4 bg-primary-600 text-white rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-primary-700 shadow transition transform active:scale-95">
                          <Wand2 size={20} />
                          <div>
                              <div className="text-sm">自動で切り出す</div>
                              <div className="text-[10px] font-normal opacity-80">背景を自動除去</div>
                          </div>
                      </button>
                      <button onClick={() => processNewImage('manual')} className="w-full py-4 bg-white border-2 border-gray-200 text-gray-700 rounded-xl font-bold flex items-center justify-center gap-2 hover:border-primary-500 hover:text-primary-600 transition transform active:scale-95">
                          <Crop size={20} />
                           <div>
                              <div className="text-sm">手動で指定する</div>
                              <div className="text-[10px] font-normal opacity-60">四角形で範囲選択</div>
                          </div>
                      </button>
                  </div>
                  <button onClick={() => setShowProcessSelection(false)} className="w-full mt-6 py-2 text-gray-400 hover:text-gray-600 text-sm font-bold">キャンセル</button>
              </div>
          </div>
      )}

    </div>
  );
}

