                           <div>
                              <div className="text-sm">手動で指定する</div>
                              <div className="text-[10px] font-normal opacity-60">四角形で範囲選択</div>
                          </div>
                      </button>
                  </div>
                  <button onClick={() => setShowProcessSelection(false)} className="w-full mt-6 py-2 text-gray-400 hover:text-gray-600 text-sm font-bold">キャンセル</button>
              </div>
          </div>
      )}

    </div>
  );
}

