                            className="w-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white py-2 rounded-lg font-bold text-sm shadow hover:shadow-lg transition disabled:opacity-50"
                        >
                            {isTranslating ? 'AI翻訳中...' : '英語に翻訳'}
                        </button>

                        <div className="pt-2 border-t border-dashed">
                             <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">タイトル(English)</label>
                                    <CopyButton text={meta.stampNameEn} />
                                </div>
                                <TextCounter current={meta.stampNameEn.length} min={2} max={40} />
                            </div>
                             <input 
                                type="text" 
                                className="w-full bg-primary-50 border-primary-200 rounded-md text-sm focus:ring-primary-500 focus:border-primary-500"
                                maxLength={40}
                                value={meta.stampNameEn}
                                onChange={e => setMeta({...meta, stampNameEn: e.target.value})}
