                    </div>

                    <div className="pt-4 border-t border-primary-200/50 space-y-3">
                        <a 
                            href="https://creator.line.me/ja/stickermaker/" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="w-full bg-white text-[#06C755] border border-[#06C755] hover:bg-[#06C755] hover:text-white font-bold py-3 rounded-xl shadow transition-all flex items-center justify-center gap-2 md:hidden"
                        >
                            <Smartphone size={18} />
                            LINEスタンプメーカー
                        </a>
                        <a 
                            href="https://creator.line.me/ja/" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="w-full bg-white text-gray-600 border border-gray-300 hover:bg-gray-100 font-bold py-3 rounded-xl shadow transition-all flex items-center justify-center gap-2"
                        >
                            <ExternalLink size={18} />
