      </main>

      {/* Modals */}
      {editingStamp && (
        <StampEditorModal
          stamp={editingStamp}
          isOpen={!!editingStamp}
          onClose={() => {
              setEditingStamp(null);
              setEditingSpecialType(null);
          }}
          onSave={(updated) => {
              if (editingSpecialType) {
                  updateSpecialConfig(updated);
              } else {
                  updateStamp(updated);
              }
          }}
          onReCrop={() => handleReCropFromEditor(editingStamp)}
          initialPreviewBg={previewBg}
          targetWidth={editingSpecialType === 'main' ? MAIN_WIDTH : (editingSpecialType === 'tab' ? TAB_WIDTH : TARGET_WIDTH)}
          targetHeight={editingSpecialType === 'main' ? MAIN_HEIGHT : (editingSpecialType === 'tab' ? TAB_HEIGHT : TARGET_HEIGHT)}
          initialScale={
              editingSpecialType === 'main' ? mainConfig?.scale : 
              editingSpecialType === 'tab' ? tabConfig?.scale : 
              undefined
          }
          initialOffset={
              editingSpecialType === 'main' ? {x: mainConfig?.offsetX || 0, y: mainConfig?.offsetY || 0} :
              editingSpecialType === 'tab' ? {x: tabConfig?.offsetX || 0, y: tabConfig?.offsetY || 0} :
              undefined
          }
        />
      )}

      <ManualCropModal
        sourceImages={sourceImages}
        isOpen={isManualCropping}
        onClose={() => {
            setIsManualCropping(false);
            setManualCropInitialSourceId(undefined);
            setTargetReplaceId(null);
        }}
        onConfirm={handleManualCropConfirm}
        onAddSource={handleAddSourceFromModal}
        initialSourceId={manualCropInitialSourceId}
      />

      {/* Helper Modals for New Stamp Flow */}
       {showSourceSelectModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4 animate-fade-in">
             <div className="bg-white rounded-xl p-6 max-w-lg w-full shadow-2xl">
                 <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg text-gray-700">画像を選択</h3>
                    <button onClick={() => setShowSourceSelectModal(false)} className="p-1 hover:bg-gray-100 rounded-full"><XIcon size={20}/></button>
                 </div>
                 <div className="grid grid-cols-3 sm:grid-cols-4 gap-3 mb-6">
                     {sourceImages.map(img => (
                         <button key={img.id} onClick={() => handleSelectExistingSource(img)} className="aspect-square relative border-2 border-transparent hover:border-primary-500 rounded-lg overflow-hidden transition group">
                             <img src={img.url} className="w-full h-full object-cover" />
                             <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                         </button>
                     ))}
                     <label className="aspect-square border-2 border-dashed border-gray-300 flex flex-col items-center justify-center text-gray-500 cursor-pointer hover:bg-primary-50 hover:border-primary-300 rounded-lg transition">
                         <Upload size={24} className="mb-1"/>
                         <span className="text-[10px] font-bold">追加</span>
                         <input type="file" className="hidden" accept="image/png, image/jpeg" onChange={handleUploadForNewStamp}/>
                     </label>
                 </div>
