        </div>
      )}

      {showProcessSelection && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4 animate-fade-in">
              <div className="bg-white rounded-xl p-6 max-w-md w-full shadow-2xl">
                  <h3 className="font-bold text-lg mb-6 text-center text-gray-700">切り出し方法</h3>
                  <div className="space-y-3">
                      <button onClick={() => processNewImage('auto')} className="w-full py-4 bg-primary-600 text-white rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-primary-700 shadow transition transform active:scale-95">
                          <Wand2 size={20} />
                          <div>
                              <div className="text-sm">自動で切り出す</div>
                              <div className="text-[10px] font-normal opacity-80">背景を自動除去</div>
                          </div>
                      </button>
                      <button onClick={() => processNewImage('manual')} className="w-full py-4 bg-white border-2 border-gray-200 text-gray-700 rounded-xl font-bold flex items-center justify-center gap-2 hover:border-primary-500 hover:text-primary-600 transition transform active:scale-95">
                          <Crop size={20} />
                           <div>
                              <div className="text-sm">手動で指定する</div>
                              <div className="text-[10px] font-normal opacity-60">四角形で範囲選択</div>
                          </div>
                      </button>
