/**
 * Main function to process the uploaded image.
 * 1. Estimates background color.
 * 2. Removes background (Flood fill).
 * 3. Detects individual stamp blobs.
 * 4. Extracts them into Stamp objects.
 */
export async function processUploadedImage(file: File, sourceImageId: string): Promise<{ stamps: Stamp[], width: number, height: number }> {
  const img = await loadImage(file);
  const canvas = document.createElement('canvas');
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Could not get canvas context');

  // Draw original raw image
  ctx.drawImage(img, 0, 0);

  // Clone raw canvas for "originalDataUrl" generation later
  const rawCanvas = document.createElement('canvas');
  rawCanvas.width = img.width;
  rawCanvas.height = img.height;
  const rawCtx = rawCanvas.getContext('2d');
  if (rawCtx) rawCtx.drawImage(canvas, 0, 0);

  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

  // 1 & 2. Remove Background (Modifies imageData in place)
  const processedImageData = removeBackground(imageData);
  ctx.putImageData(processedImageData, 0, 0);

  // 3 & 4. Detect and Extract Stamps (Pass both processed and raw canvas)
  const stamps = extractStamps(processedImageData, canvas, rawCanvas, sourceImageId);

  return {
    stamps,
    width: img.width,
    height: img.height,
  };
}

/**
 * Re-processes a single stamp's raw image with a new tolerance value.
 */
export async function reprocessStampWithTolerance(
  originalDataUrl: string, 
  tolerance: number
): Promise<string> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (!ctx) return reject('No context');

      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;
      const w = canvas.width;
      const h = canvas.height;

      // Simple corner detection for background
      // Use Top-Left corner as base
      const bgR = data[0];
      const bgG = data[1];
      const bgB = data[2];

      const stack: [number, number][] = [];
      const visited = new Uint8Array(w * h);

      // Seed all 4 corners
      stack.push([0, 0]);
      stack.push([w-1, 0]);
      stack.push([0, h-1]);
      stack.push([w-1, h-1]);

      const tol = tolerance * 3; 

      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= w || y < 0 || y >= h) continue;

        const idx = (y * w + x);
        if (visited[idx]) continue;

        const pixelIdx = idx * 4;
        const r = data[pixelIdx];
        const g = data[pixelIdx + 1];
        const b = data[pixelIdx + 2];

        // Check if pixel is already visited or not matching
        // But here we just check color diff because we are re-processing from RAW (opaque)
        const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);

        if (diff < tol) {
           data[pixelIdx + 3] = 0; // Transparent
           visited[idx] = 1;

           // Add neighbors
           if (x + 1 < w) stack.push([x + 1, y]);
           if (x - 1 >= 0) stack.push([x - 1, y]);
           if (y + 1 < h) stack.push([x, y + 1]);
           if (y - 1 >= 0) stack.push([x, y - 1]);
        }
      }

      ctx.putImageData(imageData, 0, 0);
      resolve(canvas.toDataURL('image/png'));
    };
    img.onerror = reject;
    img.src = originalDataUrl;
  });
}

function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = URL.createObjectURL(file);
  });
}

function removeBackground(imageData: ImageData): ImageData {
  const { width, height, data } = imageData;

  // Robust Background Detection:
  const bg = getDominantBackgroundColor(data, width, height);
  const bgR = bg.r;
  const bgG = bg.g;
  const bgB = bg.b;

  // Initial tolerance
  const tolerance = 50; 

  // Flood fill algorithm to remove continuous background
  const stack: [number, number][] = [];
  const visited = new Uint8Array(width * height);

  const getIdx = (x: number, y: number) => (y * width + x) * 4;

  const isCloseToBg = (idx: number) => {
     const r = data[idx];
     const g = data[idx + 1];
     const b = data[idx + 2];
     const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
     return diff < tolerance * 3;
  };

  // Add all edge pixels that look like background to the stack
  for (let x = 0; x < width; x++) {
      [0, height - 1].forEach(y => {
          const idx = getIdx(x, y);
          if (isCloseToBg(idx)) {
              stack.push([x, y]);
              visited[y * width + x] = 1;
          }
      });
  }
  for (let y = 0; y < height; y++) {
      [0, width - 1].forEach(x => {
          const idx = getIdx(x, y);
          if (visited[y * width + x]) return; // Already visited
          if (isCloseToBg(idx)) {
              stack.push([x, y]);
              visited[y * width + x] = 1;
          }
      });
  }

  // Flood Fill
  while (stack.length > 0) {
    const [x, y] = stack.pop()!;

    // Process current pixel
    const idx = getIdx(x, y);
    data[idx + 3] = 0; // Set Alpha to 0

    // Check neighbors
    const neighbors = [
        [x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]
    ];

    for(const [nx, ny] of neighbors) {
        if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
            if (!visited[ny * width + nx]) {
                const nIdx = getIdx(nx, ny);
                if (isCloseToBg(nIdx)) {
                    visited[ny * width + nx] = 1;
                    stack.push([nx, ny]);
                }
            }
        }
    }
  }

  return imageData;
}

function getDominantBackgroundColor(data: Uint8ClampedArray, width: number, height: number): {r: number, g: number, b: number} {
    const samples: {r: number, g: number, b: number}[] = [];
    const step = 5; // Optimization: sample every 5th pixel

    // Sample Top and Bottom rows
    for(let x=0; x<width; x+=step) {
        let idx = (0 * width + x) * 4;
        samples.push({r: data[idx], g: data[idx+1], b: data[idx+2]});
        idx = ((height-1) * width + x) * 4;
        samples.push({r: data[idx], g: data[idx+1], b: data[idx+2]});
    }
    // Sample Left and Right cols
    for(let y=0; y<height; y+=step) {
        let idx = (y * width + 0) * 4;
        samples.push({r: data[idx], g: data[idx+1], b: data[idx+2]});
        idx = (y * width + (width-1)) * 4;
        samples.push({r: data[idx], g: data[idx+1], b: data[idx+2]});
    }

    // Quantize and count
    const counts: {[key: string]: number} = {};
    let maxCount = 0;
    let dominantStr = "255,255,255"; // Default white

    samples.forEach(s => {
        // Round to nearest 10 to group similar colors
        const r = Math.round(s.r / 10) * 10;
        const g = Math.round(s.g / 10) * 10;
        const b = Math.round(s.b / 10) * 10;
        const key = `${r},${g},${b}`;
        counts[key] = (counts[key] || 0) + 1;
        if (counts[key] > maxCount) {
            maxCount = counts[key];
            dominantStr = key;
        }
    });

    const [r, g, b] = dominantStr.split(',').map(Number);
    return {r, g, b};
}

function extractStamps(imageData: ImageData, sourceCanvas: HTMLCanvasElement, rawCanvas: HTMLCanvasElement, sourceImageId: string): Stamp[] {
  const { width, height, data } = imageData;
  const visited = new Uint8Array(width * height);
  const boxes: { x: number, y: number, w: number, h: number }[] = [];

  // Iterate to find islands of non-transparent pixels
  // Optimization: skip 4 pixels
  for (let y = 0; y < height; y+=4) { 
    for (let x = 0; x < width; x+=4) {
      const idx = (y * width + x) * 4;
      if (data[idx + 3] > 0 && !visited[y * width + x]) {
        const box = findBoundingBox(x, y, width, height, data, visited);
        // Only keep boxes that are reasonably sized
        if (box.w > 20 && box.h > 20) {
           boxes.push(box);
        }
      }
    }
  }

  const mergedBoxes = mergeBoxes(boxes);

  // Sort boxes (Grid order: Top-Left to Bottom-Right)
  mergedBoxes.sort((a, b) => a.y - b.y);

  const rows: typeof mergedBoxes[] = [];
  let currentRow: typeof mergedBoxes = [];
  let lastY = -1000;

  // Group by rough Y position
  mergedBoxes.forEach(box => {
    if (currentRow.length === 0) {
      currentRow.push(box);
      lastY = box.y;
    } else {
      // If box is roughly on the same line (center is close)
      const centerY = box.y + box.h/2;
      const lastCenterY = lastY + currentRow[0].h/2; // rough approx

      const yDiff = Math.abs(box.y - lastY);

      if (yDiff < box.h / 2) {
        currentRow.push(box);
      } else {
        rows.push(currentRow);
        currentRow = [box];
        lastY = box.y;
      }
    }
  });
  if (currentRow.length > 0) rows.push(currentRow);

  const sortedBoxes = rows.flatMap(row => row.sort((a, b) => a.x - b.x));

  return sortedBoxes.map((box, index) => {
    // 1. Create Transparent Stamp (processed)
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = box.w;
    tempCanvas.height = box.h;
    const tCtx = tempCanvas.getContext('2d');
    tCtx?.drawImage(sourceCanvas, box.x, box.y, box.w, box.h, 0, 0, box.w, box.h);

    // 2. Create Original Raw Stamp (for restoration)
    const rawTempCanvas = document.createElement('canvas');
    rawTempCanvas.width = box.w;
    rawTempCanvas.height = box.h;
    const rawTCtx = rawTempCanvas.getContext('2d');
    rawTCtx?.drawImage(rawCanvas, box.x, box.y, box.w, box.h, 0, 0, box.w, box.h);

    // Calculate initial scale to fit TARGET_WIDTH/HEIGHT
    const padding = 20;
    const availW = TARGET_WIDTH - padding;
    const availH = TARGET_HEIGHT - padding;

    let scale = Math.min(availW / box.w, availH / box.h);
    if (scale > 1) scale = 1;

    return {
      id: `stamp-${sourceImageId}-${index}`,
      sourceImageId,
      originalX: box.x,
      originalY: box.y,
      width: box.w,
      height: box.h,
      dataUrl: tempCanvas.toDataURL('image/png'),
      originalDataUrl: rawTempCanvas.toDataURL('image/png'),
      isExcluded: false,
      scale: scale, 
      rotation: 0, // Initialize rotation
      offsetX: 0,
      offsetY: 0,
      currentTolerance: 50
    };
  });
}

function findBoundingBox(startX: number, startY: number, w: number, h: number, data: Uint8ClampedArray, visited: Uint8Array) {
  let minX = startX, maxX = startX, minY = startY, maxY = startY;
  const stack = [[startX, startY]];
  visited[startY * w + startX] = 1;

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;

    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;

    const neighbors = [
      [x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]
    ];

    for (const [nx, ny] of neighbors) {
      if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
        if (!visited[ny * w + nx]) {
           const idx = (ny * w + nx) * 4;
           if (data[idx + 3] > 10) { // If pixel is not fully transparent
             visited[ny * w + nx] = 1;
             stack.push([nx, ny]);
           }
        }
      }
    }
  }

  return { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

function mergeBoxes(boxes: { x: number, y: number, w: number, h: number }[]) {
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < boxes.length; i++) {
      for (let j = i + 1; j < boxes.length; j++) {
        const a = boxes[i];
        const b = boxes[j];
        if (rectIntersect(a, b)) {
          const newX = Math.min(a.x, b.x);
          const newY = Math.min(a.y, b.y);
          const newMaxX = Math.max(a.x + a.w, b.x + b.w);
          const newMaxY = Math.max(a.y + a.h, b.y + b.h);

          boxes[i] = { x: newX, y: newY, w: newMaxX - newX, h: newMaxY - newY };
          boxes.splice(j, 1);
          changed = true;
          j--;
        }
      }
    }
  }
  return boxes;
}

function rectIntersect(a: { x: number, y: number, w: number, h: number }, b: { x: number, y: number, w: number, h: number }) {
  // Adjusted padding: too high merges distinct stamps, too low splits single stamps.
  // 40 seems to be a balanced value for standard illustration gaps.
  const padding = 40; 
  return (a.x < b.x + b.w + padding && a.x + a.w + padding > b.x &&
          a.y < b.y + b.h + padding && a.y + a.h + padding > b.y);
}

import JSZip from 'jszip';
import { Stamp, MetaData, ExportConfig, TARGET_WIDTH, TARGET_HEIGHT, MAIN_WIDTH, MAIN_HEIGHT, TAB_WIDTH, TAB_HEIGHT } from '../types';

export const createAndDownloadZip = async (
  stamps: Stamp[],
  mainConfig: ExportConfig | null,
  tabConfig: ExportConfig | null,
  metaData: MetaData,
  renumber: boolean
) => {
  const zip = new JSZip();

  // 1. Add Stamps
  let counter = 1;
  for (const stamp of stamps) {
    if (stamp.isExcluded) continue;

    // Process final image for the stamp
    const config: ExportConfig = {
        id: stamp.id,
        scale: stamp.scale,
        rotation: stamp.rotation,
        offsetX: stamp.offsetX,
        offsetY: stamp.offsetY,
        // Stamps themselves don't use customDataUrl here, they use stamp.dataUrl
    };
    // For regular stamps, we use stamp.dataUrl directly
    const blob = await createFinalImageBlob(stamp.dataUrl, config, TARGET_WIDTH, TARGET_HEIGHT);
    if (!blob) continue;

    const fileName = renumber 
      ? `${String(counter).padStart(2, '0')}.png` 
      : `${stamp.id.replace(/stamp-.*?-/, '')}.png`; // Simplified replace logic

    zip.file(fileName, blob);
    counter++;
  }

  // 2. Add Main
  if (mainConfig) {
    const mainStamp = stamps.find(s => s.id === mainConfig.id);
    if (mainStamp) {
        // Use customDataUrl if edited (eraser), otherwise original stamp dataUrl
        const sourceUrl = mainConfig.customDataUrl || mainStamp.dataUrl;
        const mainBlob = await createFinalImageBlob(sourceUrl, mainConfig, MAIN_WIDTH, MAIN_HEIGHT);
        if (mainBlob) zip.file("main.png", mainBlob);
    }
  }

  // 3. Add Tab
  if (tabConfig) {
    const tabStamp = stamps.find(s => s.id === tabConfig.id);
    if (tabStamp) {
        const sourceUrl = tabConfig.customDataUrl || tabStamp.dataUrl;
        const tabBlob = await createFinalImageBlob(sourceUrl, tabConfig, TAB_WIDTH, TAB_HEIGHT);
        if (tabBlob) zip.file("tab.png", tabBlob);
    }
  }

  // 4. Add Meta.txt
  const dateStr = new Date().toISOString().split('T')[0];
  const txtContent = `AppName: スタンプ切り出しくん
CreatedAt: ${dateStr} (JST)

[Japanese]
Name: ${metaData.stampNameJa}
Description: ${metaData.stampDescJa}

[English]
Name: ${metaData.stampNameEn}
Description: ${metaData.stampDescEn}
`;
  zip.file("meta.txt", txtContent);

  // Generate and download
  const content = await zip.generateAsync({ type: "blob" });

  // Simple download trigger
  const link = document.createElement('a');
  link.href = URL.createObjectURL(content);
  link.download = `stickers_${dateStr}.zip`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

// Helper: Takes image URL + config and renders it into the final PNG blob
export async function createFinalImageBlob(
    imageUrl: string,
    config: ExportConfig,
    targetW: number, 
    targetH: number
): Promise<Blob | null> {
  return new Promise((resolve) => {
    const canvas = document.createElement('canvas');
    canvas.width = targetW;
    canvas.height = targetH;
    const ctx = canvas.getContext('2d');
    if (!ctx) return resolve(null);

    const img = new Image();
    img.onload = () => {
      // Clear
      ctx.clearRect(0, 0, targetW, targetH);

      // Calculate drawn size based on original image size * config scale
      // Note: img.width/height here are from the source image (the cutout)
      const drawnW = img.width * config.scale;
      const drawnH = img.height * config.scale;

      // Center + Offset
      const centerX = targetW / 2;
      const centerY = targetH / 2;

      const x = centerX - (drawnW / 2) + config.offsetX;
      const y = centerY - (drawnH / 2) + config.offsetY;

      // Apply rotation if exists
      if (config.rotation) {
          const cx = centerX + config.offsetX;
          const cy = centerY + config.offsetY;
          ctx.save();
          ctx.translate(cx, cy);
          ctx.rotate((config.rotation * Math.PI) / 180);
          ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);
          ctx.restore();
      } else {
          ctx.drawImage(img, x, y, drawnW, drawnH);
      }

      canvas.toBlob((blob) => {
        resolve(blob);
      }, 'image/png');
    };
    img.src = imageUrl; 
  });
}

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2, Palette, Pencil, Sliders, RotateCw, Undo, Redo } from 'lucide-react';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  onReCrop?: () => void; // Optional for Main/Tab which can't be re-cropped
  initialPreviewBg?: string; 
  targetWidth?: number; // Configurable for Main/Tab editing
  targetHeight?: number;
  initialScale?: number;
  initialRotation?: number;
  initialOffset?: { x: number, y: number };
}

interface HistoryState {
    scale: number;
    rotation: number;
    offset: { x: number, y: number };
    dataUrl: string;
    tolerance: number;
}

export const StampEditorModal: React.FC<Props> = ({ 
  stamp, 
  isOpen, 
  onClose, 
  onSave, 
  onReCrop,
  initialPreviewBg = 'checker',
  targetWidth = TARGET_WIDTH,
  targetHeight = TARGET_HEIGHT,
  initialScale,
  initialRotation,
  initialOffset
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Stamp state (Applied to the image)
  // Use overrides if provided (for Main/Tab editing), otherwise use stamp's own state
  const [scale, setScale] = useState(initialScale ?? stamp.scale);
  const [rotation, setRotation] = useState(initialRotation ?? stamp.rotation ?? 0);
  const [offset, setOffset] = useState(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });

  // History State
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Editor View state
  const [viewZoom, setViewZoom] = useState(1);
  const [previewBg, setPreviewBg] = useState(initialPreviewBg);

  const [mode, setMode] = useState<'move' | 'eraser' | 'wand' | 'restore'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [isRotating, setIsRotating] = useState(false);
  const [activeHandle, setActiveHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | 'rot' | null>(null);

  // Cursor visual state
  const [cursorPos, setCursorPos] = useState<{x: number, y: number} | null>(null);

  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  // Pinch Zoom/Rotate State for Mobile
  const [pinchStartDist, setPinchStartDist] = useState<number | null>(null);
  const [pinchStartScale, setPinchStartScale] = useState<number>(0);
  const [pinchStartAngle, setPinchStartAngle] = useState<number | null>(null);
  const [pinchStartRotation, setPinchStartRotation] = useState<number>(0);

  // Continuous Press for Zoom Buttons
  const zoomIntervalRef = useRef<number | null>(null);

  // Tolerance state (0-100)
  const [tolerance, setTolerance] = useState(stamp.currentTolerance || 50);

  // We need to keep a working copy of the image data for the eraser/wand
  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);
  // Keep original data url loaded for restore
  const [originalImage, setOriginalImage] = useState<HTMLImageElement | null>(null);

  useEffect(() => {
    if (isOpen) {
      setScale(initialScale ?? stamp.scale);
      setRotation(initialRotation ?? stamp.rotation ?? 0);
      setOffset(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
      setTolerance(stamp.currentTolerance || 50);

      // Initialize History
      const initialState = {
          scale: initialScale ?? stamp.scale,
          rotation: initialRotation ?? stamp.rotation ?? 0,
          offset: initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY },
          dataUrl: stamp.dataUrl,
          tolerance: stamp.currentTolerance || 50
      };
      setHistory([initialState]);
      setHistoryIndex(0);

      if (stamp.originalDataUrl) {
          const img = new Image();
          img.src = stamp.originalDataUrl;
          img.onload = () => setOriginalImage(img);
      } else {
          setOriginalImage(null);
      }
    }
  }, [isOpen, stamp, initialScale, initialRotation, initialOffset]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, rotation, offset, workingDataUrl, previewBg, targetWidth, targetHeight, cursorPos, mode, eraserSize]); 

  const addToHistory = (newState: Partial<HistoryState>) => {
      const currentState = {
          scale,
          rotation,
          offset,
          dataUrl: workingDataUrl,
          tolerance,
          ...newState
      };

      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(currentState);

      // Limit history size to prevent memory issues with many dataUrls
      if (newHistory.length > 20) {
          newHistory.shift();
      }

      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);
  };

  const undo = () => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setScale(prevState.scale);
          setRotation(prevState.rotation);
          setOffset(prevState.offset);
          setWorkingDataUrl(prevState.dataUrl);
          setTolerance(prevState.tolerance);
          setHistoryIndex(prevIndex);
      }
  };

  const redo = () => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setScale(nextState.scale);
          setRotation(nextState.rotation);
          setOffset(nextState.offset);
          setWorkingDataUrl(nextState.dataUrl);
          setTolerance(nextState.tolerance);
          setHistoryIndex(nextIndex);
      }
  };

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Background
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        // Center of the canvas + offset
        const cx = canvas.width / 2 + offset.x;
        const cy = canvas.height / 2 + offset.y;

        ctx.save();

        // Translate to image center and rotate
        ctx.translate(cx, cy);
        ctx.rotate((rotation * Math.PI) / 180);

        // Draw image centered at origin
        ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);

        ctx.restore();

        // Draw Border (The output area)
        ctx.strokeStyle = '#10b981'; // Green-500
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);

        // Draw Handles if in Move Mode
        if (mode === 'move') {
            // Need to transform handle positions
            const corners = [
                { x: -drawnW/2, y: -drawnH/2, id: 'tl' },
                { x: drawnW/2, y: -drawnH/2, id: 'tr' },
                { x: -drawnW/2, y: drawnH/2, id: 'bl' },
                { x: drawnW/2, y: drawnH/2, id: 'br' }
            ];

            // Rotation handle at top
            corners.push({ x: 0, y: -drawnH/2 - 25, id: 'rot' });

            const angle = (rotation * Math.PI) / 180;
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);

            const transformedHandles = corners.map(c => ({
                x: cx + (c.x * cos - c.y * sin),
                y: cy + (c.x * sin + c.y * cos),
                id: c.id
            }));

            // Draw connecting line for rotation handle
            if (rotation !== undefined) {
               const topCenter = { x: 0, y: -drawnH/2 };
               const tx = cx + (topCenter.x * cos - topCenter.y * sin);
               const ty = cy + (topCenter.x * sin + topCenter.y * cos);
               const rotHandle = transformedHandles.find(h => h.id === 'rot');
               if (rotHandle) {
                   ctx.beginPath();
                   ctx.moveTo(tx, ty);
                   ctx.lineTo(rotHandle.x, rotHandle.y);
                   ctx.strokeStyle = '#3b82f6';
                   ctx.lineWidth = 1;
                   ctx.stroke();
               }
            }

            drawHandles(ctx, transformedHandles);
        }

        // Draw Cursor if in Eraser/Restore Mode
        if ((mode === 'eraser' || mode === 'restore') && cursorPos) {
            ctx.beginPath();
            ctx.arc(cursorPos.x, cursorPos.y, eraserSize / 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
        }
    };
    img.src = workingDataUrl;
  };

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  const drawHandles = (ctx: CanvasRenderingContext2D, handles: {x: number, y: number, id: string}[]) => {
      const handleSize = 10;
      ctx.lineWidth = 2;

      handles.forEach(h => {
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#3b82f6'; 

          if (h.id === 'rot') {
              ctx.beginPath();
              ctx.arc(h.x, h.y, handleSize / 1.5, 0, Math.PI * 2); // Smaller circular handle for rotation
              ctx.fillStyle = '#3b82f6'; // Filled blue
              ctx.fill();
          } else {
              ctx.beginPath();
              ctx.arc(h.x, h.y, handleSize / 2, 0, Math.PI * 2);
              ctx.fill();
              ctx.stroke();
          }
      });
  };

  // --- Pointer/Touch Events ---

  const getClientCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
      if ('touches' in e) {
          return { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else {
          return { x: (e as React.MouseEvent).clientX, y: (e as React.MouseEvent).clientY };
      }
  };

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchstart') e.preventDefault();

    // Check for Pinch/Rotate Start (2 fingers)
    if ('touches' in e && e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;

        setPinchStartDist(dist);
        setPinchStartScale(scale);
        setPinchStartAngle(angle);
        setPinchStartRotation(rotation);

        setIsDragging(false);
        setIsResizing(false);
        setIsRotating(false);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;

    // Check Handles first if in Move mode
    if (mode === 'move') {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;

        // Handle logic needs to respect rotation
        const angle = (rotation * Math.PI) / 180;
        const cos = Math.cos(angle);
        const sin = Math.sin(angle);

        const corners = [
            { x: -drawnW/2, y: -drawnH/2, id: 'tl' },
            { x: drawnW/2, y: -drawnH/2, id: 'tr' },
            { x: -drawnW/2, y: drawnH/2, id: 'bl' },
            { x: drawnW/2, y: drawnH/2, id: 'br' },
            { x: 0, y: -drawnH/2 - 25, id: 'rot' }
        ];

        const handleRadius = 20; // Hit area

        for (const c of corners) {
            const hx = cx + (c.x * cos - c.y * sin);
            const hy = cy + (c.x * sin + c.y * cos);
            if (Math.hypot(x - hx, y - hy) < handleRadius) {
                if (c.id === 'rot') {
                    setIsRotating(true);
                    setActiveHandle('rot');
                } else {
                    setIsResizing(true);
                    setActiveHandle(c.id as any);
                }
                addToHistory({});
                return;
            }
        }
    }

    if (mode === 'wand') {
      addToHistory({});
      applyMagicWand(x, y);
    } else if (mode === 'restore') {
      addToHistory({});
      setIsDragging(true);
      applyRestore(x, y); // Apply on click too
    } else if (mode === 'eraser') {
      addToHistory({});
      setIsDragging(true);
      applyEraser(x, y); // Apply on click too
    } else {
      // Move mode
      addToHistory({});
      setIsDragging(true);
      setLastPos({ x, y });
    }
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchmove') e.preventDefault();

    // Handle Pinch Zoom/Rotate logic
    if ('touches' in e && e.touches.length === 2 && pinchStartDist !== null) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];

        // Zoom
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const scaleFactor = dist / pinchStartDist;
        const newScale = Math.max(0.01, pinchStartScale * scaleFactor);

        // Rotate
        if (pinchStartAngle !== null) {
            const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
            const deltaAngle = angle - pinchStartAngle;
            setRotation(pinchStartRotation + deltaAngle);
        }

        setScale(newScale);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;

    // Update cursor pos for visualization
    setCursorPos({ x, y });

    const cx = targetWidth / 2 + offset.x;
    const cy = targetHeight / 2 + offset.y;

    if (isRotating && activeHandle === 'rot') {
        const angle = Math.atan2(y - cy, x - cx) * 180 / Math.PI;
        // The handle is at -90 degrees (top). So if pointer is at -90, rotation is 0.
        // pointer angle = rotation - 90
        // rotation = pointer angle + 90
        setRotation(angle + 90);
        return;
    }

    if (isResizing && activeHandle) {
        // Simple scaling based on distance from center
        const currentDist = Math.hypot(x - cx, y - cy);

        // Original diagonal half length (unscaled)
        const baseDiagonal = Math.hypot(stamp.width, stamp.height) / 2;
        const newScale = Math.max(0.01, currentDist / baseDiagonal);

        setScale(newScale);
        return;
    }

    if (!isDragging) return;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    } else if (mode === 'restore') {
      applyRestore(x, y);
    }
    setLastPos({ x, y });
  };

  const handlePointerUp = () => {
    setIsDragging(false);
    setIsResizing(false);
    setIsRotating(false);
    setActiveHandle(null);
    setPinchStartDist(null);
    setPinchStartAngle(null);
  };

  const handlePointerLeave = () => {
      setCursorPos(null);
      handlePointerUp();
  };

  // Maps Canvas Coordinates -> Source Image Coordinates
  // Accounts for Offset, Scale, AND Rotation
  const getSourceCoords = (canvasX: number, canvasY: number) => {
    const cx = targetWidth / 2 + offset.x;
    const cy = targetHeight / 2 + offset.y;

    // 1. Translate back to origin relative to image center
    const dx = canvasX - cx;
    const dy = canvasY - cy;

    // 2. Rotate back by -rotation
    const angle = -(rotation * Math.PI) / 180;
    const rx = dx * Math.cos(angle) - dy * Math.sin(angle);
    const ry = dx * Math.sin(angle) + dy * Math.cos(angle);

    // 3. Scale back
    const sx = rx / scale;
    const sy = ry / scale;

    // 4. Translate to top-left of source image (which is drawn centered at 0,0 in local space)
    // Source image dimensions are stamp.width x stamp.height
    // Center is w/2, h/2
    const sourceX = Math.floor(sx + stamp.width / 2);
    const sourceY = Math.floor(sy + stamp.height / 2);

    return { sourceX, sourceY };
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;

     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);

       const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
       const sourceEraserSize = eraserSize / scale;

       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();

       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const applyRestore = (canvasX: number, canvasY: number) => {
    if (!originalImage) return;

    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.onload = () => {
        ctx.drawImage(img, 0, 0);

        const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
        const sourceBrushSize = eraserSize / scale;
        const radius = sourceBrushSize / 2;

        ctx.save();
        ctx.beginPath();
        ctx.arc(sourceX, sourceY, radius, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(originalImage, 0, 0);
        ctx.restore();

        setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const applyMagicWand = (canvasX: number, canvasY: number) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
    if(!ctx) return;

    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);

      const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
      if (sourceX < 0 || sourceX >= stamp.width || sourceY < 0 || sourceY >= stamp.height) return;

      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;

      // Get target color
      const targetIdx = (sourceY * width + sourceX) * 4;
      const tR = data[targetIdx];
      const tG = data[targetIdx + 1];
      const tB = data[targetIdx + 2];
      const tA = data[targetIdx + 3];

      if (tA === 0) return; // Already transparent

      const tolerance = 30;
      const stack = [[sourceX, sourceY]];
      const visited = new Uint8Array(width * height);

      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= width || y < 0 || y >= height) continue;
        if (visited[y * width + x]) continue;

        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        if (a === 0) continue; 

        const diff = Math.abs(r - tR) + Math.abs(g - tG) + Math.abs(b - tB);
        if (diff < tolerance * 3) {
           data[idx + 3] = 0; // Make transparent
           visited[y * width + x] = 1;
           stack.push([x + 1, y]);
           stack.push([x - 1, y]);
           stack.push([x, y + 1]);
           stack.push([x, y - 1]);
        }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const handleToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      addToHistory({ tolerance: Number(e.target.value) });
      const newTolerance = Number(e.target.value);
      setTolerance(newTolerance);

      if (!originalImage) return;

      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = stamp.width;
      tempCanvas.height = stamp.height;
      const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;

      ctx.drawImage(originalImage, 0, 0);

      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;

      const bgR = data[0];
      const bgG = data[1];
      const bgB = data[2];

      const stack: [number, number][] = [];
      const visited = new Uint8Array(width * height);

      stack.push([0, 0]);
      stack.push([width-1, 0]);
      stack.push([0, height-1]);
      stack.push([width-1, height-1]);

      while(stack.length > 0) {
          const [x, y] = stack.pop()!;
          if(x < 0 || x >= width || y < 0 || y >= height) continue;

          const idx = (y*width+x);
          if(visited[idx]) continue;
          visited[idx] = 1;

          const pixelIdx = idx * 4;
          const r = data[pixelIdx];
          const g = data[pixelIdx+1];
          const b = data[pixelIdx+2];

          const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);

          if(diff < newTolerance * 3) {
              data[pixelIdx+3] = 0;

              if (x + 1 < width) stack.push([x + 1, y]);
              if (x - 1 >= 0) stack.push([x - 1, y]);
              if (y + 1 < height) stack.push([x, y + 1]);
              if (y - 1 >= 0) stack.push([x, y - 1]);
          }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
  };

  const handleSave = () => {
    onSave({
      ...stamp,
      scale,
      rotation,
      offsetX: offset.x,
      offsetY: offset.y,
      dataUrl: workingDataUrl,
      currentTolerance: tolerance
    });
    onClose();
  };

  const startZoom = (direction: 'in' | 'out') => {
      if (direction === 'in') setScale(s => s + 0.01);
      else setScale(s => Math.max(0.01, s - 0.01));
      addToHistory({ scale: direction === 'in' ? scale + 0.01 : scale - 0.01 });

      zoomIntervalRef.current = window.setInterval(() => {
         setScale(s => {
             const ns = direction === 'in' ? s + 0.02 : Math.max(0.01, s - 0.02);
             return ns;
         });
      }, 50);
  };
  const stopZoom = () => {
      if (zoomIntervalRef.current) {
          clearInterval(zoomIntervalRef.current);
          zoomIntervalRef.current = null;
          addToHistory({});
      }
  };


  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' },
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#85c6f0', label: '青(LINE)', color: 'bg-[#85c6f0]' },
    { value: '#fecaca', label: '赤', color: 'bg-red-200' },
  ];

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col max-h-[95vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
          <h3 className="font-bold text-gray-700">スタンプ編集 ({targetWidth}x{targetHeight})</h3>
          <div className="flex items-center gap-2">
               {/* Background Selector in Header */}
               <div className="flex items-center gap-1 bg-white p-1 rounded-lg border border-gray-200 mr-2 md:mr-4">
                    <span className="hidden md:inline text-xs text-gray-400 font-bold px-1">背景色</span>
                    {backgroundOptions.map(opt => (
                        <button
                            key={opt.value}
                            onClick={() => setPreviewBg(opt.value)}
                            className={`w-5 h-5 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                            title={opt.label}
                            style={opt.value === 'checker' ? {
                                backgroundImage: `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')`
                            } : {}}
                        />
                    ))}
                </div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
          </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col">
            {/* Toolbar Top */}
            <div className="p-2 bg-gray-50 border-b flex flex-wrap justify-center gap-2 md:gap-4 items-center">
                 {/* View Zoom Control */}
                 <div className="flex items-center gap-1 md:gap-2 bg-white px-2 py-1 rounded shadow-sm">
                    <span className="text-xs text-gray-500 hidden sm:inline">表示倍率:</span>
                    <button onClick={() => setViewZoom(z => Math.max(0.5, z - 0.25))} className="p-1 hover:bg-gray-100 rounded"><ZoomOut size={16}/></button>
                    <span className="text-sm font-mono w-10 text-center">{(viewZoom * 100).toFixed(0)}%</span>
                    <button onClick={() => setViewZoom(z => Math.min(3, z + 0.25))} className="p-1 hover:bg-gray-100 rounded"><ZoomIn size={16}/></button>
                 </div>

                 {/* Undo/Redo */}
                 <div className="flex items-center gap-1">
                     <button 
                        onClick={undo} 
                        disabled={historyIndex <= 0}
                        className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"
                        title="元に戻す"
                     >
                         <Undo size={18} />
                     </button>
                     <button 
                        onClick={redo} 
                        disabled={historyIndex >= history.length - 1}
                        className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"
                        title="やり直す"
                     >
                         <Redo size={18} />
                     </button>
                 </div>

                 {/* Re-crop Button */}
                 {onReCrop && (
                    <button 
                        onClick={onReCrop}
                        className="flex items-center gap-1 text-xs bg-white text-gray-700 px-3 py-1.5 rounded shadow-sm hover:bg-gray-100 border border-gray-200"
                        title="元画像から範囲を指定し直す"
                    >
                        <RotateCw size={14} />
                        <span className="hidden sm:inline">再切り出し</span>
                    </button>
                 )}
            </div>

            {/* Scrollable Canvas Area */}
            {/* Fix: Use flex with margin-auto to allow scrolling but center content when small */}
            <div className="flex-1 overflow-auto bg-gray-100 flex p-8">
                <div 
                    className="relative shadow-md border border-gray-200 bg-white m-auto" 
                    style={{ 
                        width: targetWidth * viewZoom, 
                        height: targetHeight * viewZoom,
                        flexShrink: 0 // Prevent shrinking
                    }}
                >
                    <canvas 
                    ref={canvasRef}
                    width={targetWidth}
                    height={targetHeight}
                    className={`origin-top-left ${mode === 'move' ? 'cursor-move' : 'cursor-crosshair'} touch-none`}
                    style={{
                        transform: `scale(${viewZoom})`,
                        width: targetWidth,
                        height: targetHeight
                    }}
                    onMouseDown={handlePointerDown}
                    onMouseMove={handlePointerMove}
                    onMouseUp={handlePointerUp}
                    onMouseLeave={handlePointerLeave}
                    onTouchStart={handlePointerDown}
                    onTouchMove={handlePointerMove}
                    onTouchEnd={handlePointerUp}
                    />
                </div>
            </div>
        </div>

        {/* Footer Tools */}
        <div className="p-4 border-t bg-white rounded-b-xl shrink-0">
          <div className="flex flex-col gap-4">

             {/* Tolerance Slider */}
             {originalImage && (
                <div className="flex items-center gap-4 bg-yellow-50 p-3 rounded-lg border border-yellow-100">
                    <div className="flex items-center gap-2 text-yellow-700 font-bold text-sm min-w-[120px]">
                        <Sliders size={16} />
                        背景除去の強さ
                    </div>
                    <input 
                        type="range" 
                        min="1" 
                        max="100" 
                        value={tolerance} 
                        onChange={handleToleranceChange}
                        className="w-full accent-yellow-500"
                        title="左にすると除去が弱く（色が戻る）、右にすると強くなります"
                    />
                    <span className="text-xs text-yellow-700 w-8 text-right">{tolerance}</span>
                </div>
             )}

             <div className="flex flex-wrap gap-4 justify-center items-center">
                 {/* Mode Selection */}
                 <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                    <button 
                    onClick={() => setMode('move')} 
                    className={`p-2 rounded ${mode === 'move' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="移動"
                    >
                    <Move size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('wand')} 
                    className={`p-2 rounded ${mode === 'wand' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="自動透過 (クリック)"
                    >
                    <Wand2 size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('eraser')} 
                    className={`p-2 rounded ${mode === 'eraser' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="消しゴム"
                    >
                    <Eraser size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('restore')} 
                    disabled={!originalImage}
                    className={`p-2 rounded ${mode === 'restore' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'} disabled:opacity-30`}
                    title="復元 (元の色に戻す)"
                    >
                    <Pencil size={20} />
                    </button>

                    {/* Integrated Size Slider for Eraser/Restore */}
                    {(mode === 'eraser' || mode === 'restore') && (
                        <>
                            <div className="w-px h-6 bg-gray-300 mx-1"></div>
                            <span className="text-xs text-gray-500">サイズ</span>
                            <input 
                            type="range" 
                            min="5" 
                            max="50" 
                            value={eraserSize} 
                            onChange={(e) => setEraserSize(Number(e.target.value))} 
                            className="w-24 accent-primary-500"
                            />
                        </>
                    )}
                 </div>

                {/* Stamp Scale Control */}
                <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                    <span className="text-xs text-gray-500">画像サイズ</span>
                    <button 
                        onMouseDown={() => startZoom('out')} 
                        onMouseUp={stopZoom} 
                        onMouseLeave={stopZoom}
                        onTouchStart={() => startZoom('out')}
                        onTouchEnd={stopZoom}
                        className="p-1 hover:bg-white rounded touch-none"
                    >
                        <ZoomOut size={16}/>
                    </button>

                    <input 
                        type="range" 
                        min="0.1" 
                        max="2.0" 
                        step="0.01" 
                        value={scale} 
                        onChange={(e) => {
                            setScale(Number(e.target.value));
                        }}
                        onMouseUp={() => addToHistory({ scale })}
                        onTouchEnd={() => addToHistory({ scale })}
                        className="w-20 accent-primary-600 h-2"
                    />

                    <button 
                        onMouseDown={() => startZoom('in')} 
                        onMouseUp={stopZoom} 
                        onMouseLeave={stopZoom}
                        onTouchStart={() => startZoom('in')}
                        onTouchEnd={stopZoom}
                        className="p-1 hover:bg-white rounded touch-none"
                    >
                        <ZoomIn size={16}/>
                    </button>
                </div>

                <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                    <button 
                        onClick={() => {
                            // Reset
                            addToHistory({});
                            setScale(initialScale ?? stamp.scale);
                            setRotation(initialRotation ?? stamp.rotation ?? 0);
                            setOffset(initialOffset ?? {x:0, y:0});
                            setTolerance(stamp.currentTolerance || 50);
                            setWorkingDataUrl(stamp.dataUrl); 
                        }}
                        className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                    >
                        <RotateCcw size={14} /> リセット
                    </button>
                </div>
             </div>

             <div className="flex justify-end gap-3 pt-2 border-t border-dashed">
                <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
                <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
                    <Check size={18} /> 完了
                </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// Developed by yayoi, 2026.
