                             <input 
                                type="text" 
                                className="w-full bg-primary-50 border-primary-200 rounded-md text-sm focus:ring-primary-500 focus:border-primary-500"
                                maxLength={40}
                                value={meta.stampNameEn}
                                onChange={e => setMeta({...meta, stampNameEn: e.target.value})}
                             />
                        </div>
                        <div>
                             <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">スタンプ説明文(English)</label>
                                    <CopyButton text={meta.stampDescEn} />
                                </div>
                                <TextCounter current={meta.stampDescEn.length} min={10} max={160} />
                            </div>
                             <textarea 
                                className="w-full bg-primary-50 border-primary-200 rounded-md text-sm focus:ring-primary-500 focus:border-primary-500"
                                rows={3}
                                maxLength={160}
                                value={meta.stampDescEn}
                                onChange={e => setMeta({...meta, stampDescEn: e.target.value})}
                             />
                        </div>
                    </div>
                </div>

                {/* Download */}
                <div className="bg-primary-50 p-6 rounded-2xl shadow-inner border border-primary-100 space-y-4">
                    <div>
                        <h3 className="font-bold text-primary-800 flex items-center gap-2 mb-4">
                            <Download className="text-primary-600" size={20} />
                            書き出し
                        </h3>

                        <div className="flex items-center gap-2 mb-4">
                            <input 
                                type="checkbox" 
                                id="renumber"
                                checked={renumber} 
                                onChange={e => setRenumber(e.target.checked)}
                                className="rounded text-primary-600 focus:ring-primary-500"
                            />
