                                    <image 
                                        href={stamp.dataUrl} 
                                        x={finalX} 
                                        y={finalY} 
                                        width={drawnW} 
                                        height={drawnH}
                                        transform={rotation ? `rotate(${rotation}, ${cx}, ${cy})` : undefined}
                                    />
                                </svg>

