  const bgB = bg.b;

  // Initial tolerance set to 20 as requested
  const tolerance = 20; 
  const tol = tolerance * 3;
  const len = data.length;

  // Global Replacement: Remove background color from everywhere in the image
  for(let i = 0; i < len; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];

      const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);

      if (diff < tol) {
          data[i + 3] = 0; // Set Alpha to 0
      }
