  while (stack.length > 0) {
    const [x, y] = stack.pop()!;

    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;

    const neighbors = [
      [x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]
    ];

    for (const [nx, ny] of neighbors) {
      if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
        if (!visited[ny * w + nx]) {
           const idx = (ny * w + nx) * 4;
           if (data[idx + 3] > 10) { // If pixel is not fully transparent
             visited[ny * w + nx] = 1;
             stack.push([nx, ny]);
           }
