  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  // Pinch Zoom/Rotate State for Mobile
  const [pinchStartDist, setPinchStartDist] = useState<number | null>(null);
  const [pinchStartScale, setPinchStartScale] = useState<number>(0);
  const [pinchStartAngle, setPinchStartAngle] = useState<number | null>(null);
  const [pinchStartRotation, setPinchStartRotation] = useState<number>(0);

  // Continuous Press for Zoom Buttons
  const zoomIntervalRef = useRef<number | null>(null);

  // Tolerance state (0-100)
  const [tolerance, setTolerance] = useState(stamp.currentTolerance || 50);

  // We need to keep a working copy of the image data for the eraser/wand
  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);
  // Keep original data url loaded for restore
  const [originalImage, setOriginalImage] = useState<HTMLImageElement | null>(null);

  useEffect(() => {
    if (isOpen) {
      setScale(initialScale ?? stamp.scale);
      setRotation(initialRotation ?? stamp.rotation ?? 0);
      setOffset(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
      setTolerance(stamp.currentTolerance || 50);

      // Initialize History
      const initialState = {
          scale: initialScale ?? stamp.scale,
          rotation: initialRotation ?? stamp.rotation ?? 0,
          offset: initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY },
          dataUrl: stamp.dataUrl,
          tolerance: stamp.currentTolerance || 50
      };
      setHistory([initialState]);
      setHistoryIndex(0);

      if (stamp.originalDataUrl) {
          const img = new Image();
          img.src = stamp.originalDataUrl;
          img.onload = () => setOriginalImage(img);
      } else {
          setOriginalImage(null);
      }
    }
  }, [isOpen, stamp, initialScale, initialRotation, initialOffset]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, rotation, offset, workingDataUrl, previewBg, targetWidth, targetHeight, cursorPos, mode, eraserSize]); 

  const addToHistory = (newState: Partial<HistoryState>) => {
      const currentState = {
          scale,
          rotation,
          offset,
          dataUrl: workingDataUrl,
          tolerance,
          ...newState
      };

      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(currentState);

      // Limit history size to prevent memory issues with many dataUrls
      if (newHistory.length > 20) {
          newHistory.shift();
      }

      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);
  };

  const undo = () => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setScale(prevState.scale);
          setRotation(prevState.rotation);
          setOffset(prevState.offset);
          setWorkingDataUrl(prevState.dataUrl);
          setTolerance(prevState.tolerance);
          setHistoryIndex(prevIndex);
      }
  };

  const redo = () => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setScale(nextState.scale);
          setRotation(nextState.rotation);
          setOffset(nextState.offset);
          setWorkingDataUrl(nextState.dataUrl);
          setTolerance(nextState.tolerance);
          setHistoryIndex(nextIndex);
      }
  };

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Background
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        // Center of the canvas + offset
        const cx = canvas.width / 2 + offset.x;
        const cy = canvas.height / 2 + offset.y;

        ctx.save();

        // Translate to image center and rotate
        ctx.translate(cx, cy);
        ctx.rotate((rotation * Math.PI) / 180);

        // Draw image centered at origin
        ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);

        ctx.restore();

        // Draw Border (The output area)
        ctx.strokeStyle = '#10b981'; // Green-500
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);

        // Draw Handles if in Move Mode
        if (mode === 'move') {
            // Need to transform handle positions
            const corners = [
                { x: -drawnW/2, y: -drawnH/2, id: 'tl' },
                { x: drawnW/2, y: -drawnH/2, id: 'tr' },
                { x: -drawnW/2, y: drawnH/2, id: 'bl' },
                { x: drawnW/2, y: drawnH/2, id: 'br' }
            ];

            // Rotation handle at top
            corners.push({ x: 0, y: -drawnH/2 - 25, id: 'rot' });

            const angle = (rotation * Math.PI) / 180;
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);

            const transformedHandles = corners.map(c => ({
                x: cx + (c.x * cos - c.y * sin),
                y: cy + (c.x * sin + c.y * cos),
                id: c.id
            }));

            // Draw connecting line for rotation handle
            if (rotation !== undefined) {
               const topCenter = { x: 0, y: -drawnH/2 };
               const tx = cx + (topCenter.x * cos - topCenter.y * sin);
               const ty = cy + (topCenter.x * sin + topCenter.y * cos);
               const rotHandle = transformedHandles.find(h => h.id === 'rot');
               if (rotHandle) {
                   ctx.beginPath();
                   ctx.moveTo(tx, ty);
                   ctx.lineTo(rotHandle.x, rotHandle.y);
                   ctx.strokeStyle = '#3b82f6';
                   ctx.lineWidth = 1;
                   ctx.stroke();
               }
            }

            drawHandles(ctx, transformedHandles);
        }

        // Draw Cursor if in Eraser/Restore Mode
        if ((mode === 'eraser' || mode === 'restore') && cursorPos) {
            ctx.beginPath();
            ctx.arc(cursorPos.x, cursorPos.y, eraserSize / 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
        }
    };
    img.src = workingDataUrl;
  };

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  const drawHandles = (ctx: CanvasRenderingContext2D, handles: {x: number, y: number, id: string}[]) => {
      const handleSize = 10;
      ctx.lineWidth = 2;

      handles.forEach(h => {
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#3b82f6'; 

          if (h.id === 'rot') {
              ctx.beginPath();
              ctx.arc(h.x, h.y, handleSize / 1.5, 0, Math.PI * 2); // Smaller circular handle for rotation
              ctx.fillStyle = '#3b82f6'; // Filled blue
              ctx.fill();
          } else {
              ctx.beginPath();
              ctx.arc(h.x, h.y, handleSize / 2, 0, Math.PI * 2);
              ctx.fill();
              ctx.stroke();
          }
      });
  };

  // --- Pointer/Touch Events ---

  const getClientCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
      if ('touches' in e) {
          return { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else {
          return { x: (e as React.MouseEvent).clientX, y: (e as React.MouseEvent).clientY };
      }
  };

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchstart') e.preventDefault();

    // Check for Pinch/Rotate Start (2 fingers)
    if ('touches' in e && e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;

        setPinchStartDist(dist);
        setPinchStartScale(scale);
        setPinchStartAngle(angle);
        setPinchStartRotation(rotation);

        setIsDragging(false);
        setIsResizing(false);
        setIsRotating(false);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;

    // Check Handles first if in Move mode
    if (mode === 'move') {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;

        // Handle logic needs to respect rotation
        const angle = (rotation * Math.PI) / 180;
        const cos = Math.cos(angle);
        const sin = Math.sin(angle);

        const corners = [
            { x: -drawnW/2, y: -drawnH/2, id: 'tl' },
            { x: drawnW/2, y: -drawnH/2, id: 'tr' },
            { x: -drawnW/2, y: drawnH/2, id: 'bl' },
            { x: drawnW/2, y: drawnH/2, id: 'br' },
            { x: 0, y: -drawnH/2 - 25, id: 'rot' }
        ];

        const handleRadius = 20; // Hit area

        for (const c of corners) {
            const hx = cx + (c.x * cos - c.y * sin);
            const hy = cy + (c.x * sin + c.y * cos);
            if (Math.hypot(x - hx, y - hy) < handleRadius) {
                if (c.id === 'rot') {
                    setIsRotating(true);
                    setActiveHandle('rot');
                } else {
                    setIsResizing(true);
                    setActiveHandle(c.id as any);
                }
                addToHistory({});
                return;
            }
        }
    }

    if (mode === 'wand') {
      addToHistory({});
      applyMagicWand(x, y);
    } else if (mode === 'restore') {
      addToHistory({});
      setIsDragging(true);
      applyRestore(x, y); // Apply on click too
    } else if (mode === 'eraser') {
      addToHistory({});
      setIsDragging(true);
      applyEraser(x, y); // Apply on click too
    } else {
      // Move mode
      addToHistory({});
      setIsDragging(true);
      setLastPos({ x, y });
    }
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchmove') e.preventDefault();

    // Handle Pinch Zoom/Rotate logic
    if ('touches' in e && e.touches.length === 2 && pinchStartDist !== null) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];

        // Zoom
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const scaleFactor = dist / pinchStartDist;
        const newScale = Math.max(0.01, pinchStartScale * scaleFactor);

        // Rotate
        if (pinchStartAngle !== null) {
            const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
            const deltaAngle = angle - pinchStartAngle;
            setRotation(pinchStartRotation + deltaAngle);
        }

        setScale(newScale);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;

    // Update cursor pos for visualization
    setCursorPos({ x, y });

    const cx = targetWidth / 2 + offset.x;
    const cy = targetHeight / 2 + offset.y;

    if (isRotating && activeHandle === 'rot') {
        const angle = Math.atan2(y - cy, x - cx) * 180 / Math.PI;
        // The handle is at -90 degrees (top). So if pointer is at -90, rotation is 0.
        // pointer angle = rotation - 90
        // rotation = pointer angle + 90
        setRotation(angle + 90);
        return;
    }

    if (isResizing && activeHandle) {
        // Simple scaling based on distance from center
        const currentDist = Math.hypot(x - cx, y - cy);

        // Original diagonal half length (unscaled)
        const baseDiagonal = Math.hypot(stamp.width, stamp.height) / 2;
        const newScale = Math.max(0.01, currentDist / baseDiagonal);

        setScale(newScale);
        return;
    }

    if (!isDragging) return;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    } else if (mode === 'restore') {
      applyRestore(x, y);
    }
    setLastPos({ x, y });
  };

  const handlePointerUp = () => {
    setIsDragging(false);
    setIsResizing(false);
    setIsRotating(false);
    setActiveHandle(null);
    setPinchStartDist(null);
    setPinchStartAngle(null);
  };

  const handlePointerLeave = () => {
      setCursorPos(null);
      handlePointerUp();
  };

  // Maps Canvas Coordinates -> Source Image Coordinates
  // Accounts for Offset, Scale, AND Rotation
  const getSourceCoords = (canvasX: number, canvasY: number) => {
    const cx = targetWidth / 2 + offset.x;
    const cy = targetHeight / 2 + offset.y;

    // 1. Translate back to origin relative to image center
    const dx = canvasX - cx;
    const dy = canvasY - cy;

    // 2. Rotate back by -rotation
    const angle = -(rotation * Math.PI) / 180;
    const rx = dx * Math.cos(angle) - dy * Math.sin(angle);
    const ry = dx * Math.sin(angle) + dy * Math.cos(angle);

    // 3. Scale back
    const sx = rx / scale;
    const sy = ry / scale;

    // 4. Translate to top-left of source image (which is drawn centered at 0,0 in local space)
    // Source image dimensions are stamp.width x stamp.height
    // Center is w/2, h/2
    const sourceX = Math.floor(sx + stamp.width / 2);
    const sourceY = Math.floor(sy + stamp.height / 2);

    return { sourceX, sourceY };
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;

     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);

       const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
       const sourceEraserSize = eraserSize / scale;

       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();

       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const applyRestore = (canvasX: number, canvasY: number) => {
    if (!originalImage) return;

    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.onload = () => {
        ctx.drawImage(img, 0, 0);

        const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
        const sourceBrushSize = eraserSize / scale;
        const radius = sourceBrushSize / 2;

        ctx.save();
        ctx.beginPath();
        ctx.arc(sourceX, sourceY, radius, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(originalImage, 0, 0);
        ctx.restore();

        setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const applyMagicWand = (canvasX: number, canvasY: number) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
    if(!ctx) return;

    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);

      const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
      if (sourceX < 0 || sourceX >= stamp.width || sourceY < 0 || sourceY >= stamp.height) return;

      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;

      // Get target color
      const targetIdx = (sourceY * width + sourceX) * 4;
      const tR = data[targetIdx];
      const tG = data[targetIdx + 1];
      const tB = data[targetIdx + 2];
      const tA = data[targetIdx + 3];

      if (tA === 0) return; // Already transparent

      // Use the global tolerance slider value for Wand action as well, to allow adjustment
      const diffThreshold = tolerance * 3;
      const stack = [[sourceX, sourceY]];
      const visited = new Uint8Array(width * height);

      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= width || y < 0 || y >= height) continue;
        if (visited[y * width + x]) continue;

        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        if (a === 0) continue; 

        const diff = Math.abs(r - tR) + Math.abs(g - tG) + Math.abs(b - tB);
        if (diff < diffThreshold) {
           data[idx + 3] = 0; // Make transparent
           visited[y * width + x] = 1;
           stack.push([x + 1, y]);
           stack.push([x - 1, y]);
           stack.push([x, y + 1]);
           stack.push([x, y - 1]);
        }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const handleToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      addToHistory({ tolerance: Number(e.target.value) });
      const newTolerance = Number(e.target.value);
      setTolerance(newTolerance);

      if (!originalImage) return;

      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = stamp.width;
      tempCanvas.height = stamp.height;
      const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;

      ctx.drawImage(originalImage, 0, 0);

      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;

      // Simple background detection from corner (assuming crop has bg at TL)
      const bgR = data[0];
      const bgG = data[1];
      const bgB = data[2];

      const limit = newTolerance * 3;
      const len = data.length;

      // Global Replacement: Remove matching color everywhere
      for (let i = 0; i < len; i += 4) {
          const r = data[i];
          const g = data[i+1];
          const b = data[i+2];

          const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);

          if (diff < limit) {
              data[i+3] = 0;
          }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
  };

  const handleSave = () => {
    onSave({
      ...stamp,
      scale,
      rotation,
      offsetX: offset.x,
      offsetY: offset.y,
      dataUrl: workingDataUrl,
      currentTolerance: tolerance
    });
    onClose();
  };

  const startZoom = (direction: 'in' | 'out') => {
      if (direction === 'in') setScale(s => s + 0.01);
      else setScale(s => Math.max(0.01, s - 0.01));
      addToHistory({ scale: direction === 'in' ? scale + 0.01 : scale - 0.01 });

      zoomIntervalRef.current = window.setInterval(() => {
         setScale(s => {
             const ns = direction === 'in' ? s + 0.02 : Math.max(0.01, s - 0.02);
             return ns;
         });
      }, 50);
  };
  const stopZoom = () => {
      if (zoomIntervalRef.current) {
          clearInterval(zoomIntervalRef.current);
          zoomIntervalRef.current = null;
          addToHistory({});
      }
  };


  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' },
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#85c6f0', label: '青(LINE)', color: 'bg-[#85c6f0]' },
    { value: '#fecaca', label: '赤', color: 'bg-red-200' },
  ];

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col max-h-[95vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
          <h3 className="font-bold text-gray-700">スタンプ編集 ({targetWidth}x{targetHeight})</h3>
          <div className="flex items-center gap-2">
               {/* Background Selector in Header */}
               <div className="flex items-center gap-1 bg-white p-1 rounded-lg border border-gray-200 mr-2 md:mr-4">
                    <span className="hidden md:inline text-xs text-gray-400 font-bold px-1">背景色</span>
                    {backgroundOptions.map(opt => (
                        <button
                            key={opt.value}
                            onClick={() => setPreviewBg(opt.value)}
                            className={`w-5 h-5 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                            title={opt.label}
                            style={opt.value === 'checker' ? {
                                backgroundImage: `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')`
                            } : {}}
                        />
                    ))}
                </div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
          </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col">
            {/* Toolbar Top */}
            <div className="p-2 bg-gray-50 border-b flex flex-wrap justify-center gap-2 md:gap-4 items-center">
                 {/* View Zoom Control */}
                 <div className="flex items-center gap-1 md:gap-2 bg-white px-2 py-1 rounded shadow-sm">
                    <span className="text-xs text-gray-500 hidden sm:inline">表示倍率:</span>
                    <button onClick={() => setViewZoom(z => Math.max(0.5, z - 0.25))} className="p-1 hover:bg-gray-100 rounded"><ZoomOut size={16}/></button>
                    <span className="text-sm font-mono w-10 text-center">{(viewZoom * 100).toFixed(0)}%</span>
                    <button onClick={() => setViewZoom(z => Math.min(3, z + 0.25))} className="p-1 hover:bg-gray-100 rounded"><ZoomIn size={16}/></button>
                 </div>

                 {/* Undo/Redo */}
                 <div className="flex items-center gap-1">
                     <button 
                        onClick={undo} 
                        disabled={historyIndex <= 0}
                        className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"
                        title="元に戻す"
                     >
                         <Undo size={18} />
                     </button>
                     <button 
                        onClick={redo} 
                        disabled={historyIndex >= history.length - 1}
                        className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"
                        title="やり直す"
                     >
                         <Redo size={18} />
                     </button>
                 </div>

                 {/* Re-crop Button */}
                 {onReCrop && (
                    <button 
                        onClick={onReCrop}
