                        />
                        <span className="text-xs text-gray-400">強</span>
                        <input
                            type="number"
                            min="1"
                            max="100"
                            value={globalTolerance}
                            onChange={handleGlobalToleranceChange}
                            className="w-16 text-center text-sm font-bold text-primary-600 bg-white border border-gray-200 rounded-md py-1"
