                                maxLength={160}
                                value={meta.stampDescJa}
                                onChange={e => setMeta({...meta, stampDescJa: e.target.value})}
                            />
                            {/* Toggleable Hint */}
                            <div className="mt-2">
                                <button 
                                    onClick={() => setDescriptionHintOpen(!descriptionHintOpen)}
                                    className="flex items-center gap-1 text-xs text-primary-600 font-bold hover:text-primary-700"
                                >
                                    {descriptionHintOpen ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
