import React, { useState, useRef, useEffect } from 'react';
import { Upload, Download, Loader2, Image as ImageIcon, Grid, Languages, Settings, ExternalLink, Plus, X as XIcon, Save, GripVertical, Smartphone, Copy, Check, Wand2, Crop, Sliders, ChevronDown, ChevronUp, Info, CheckCircle2, RotateCw, Layers, Minus, Plus as PlusIcon } from 'lucide-react';
import { AppStep, Stamp, MetaData, ExportConfig, SourceImage, TARGET_WIDTH, TARGET_HEIGHT, MAIN_WIDTH, MAIN_HEIGHT, TAB_WIDTH, TAB_HEIGHT } from './types';
import { processUploadedImage, reprocessStampWithTolerance } from './lib/imageProcessing';
import { translateMeta } from './lib/gemini';
import { createAndDownloadZip, createFinalImageBlob } from './lib/zipService';
import { StampEditorModal } from './components/StampEditorModal';
import { ManualCropModal } from './components/ManualCropModal';

export default function App() {
  const [step, setStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [stamps, setStamps] = useState<Stamp[]>([]);

  // Store multiple source images
  const [sourceImages, setSourceImages] = useState<SourceImage[]>([]);

  // Main/Tab Configuration
  const [mainConfig, setMainConfig] = useState<ExportConfig | null>(null);
  const [tabConfig, setTabConfig] = useState<ExportConfig | null>(null);

  // Meta Data
  const [meta, setMeta] = useState<MetaData>({
    stampNameJa: '', stampDescJa: '', stampNameEn: '', stampDescEn: ''
  });
  const [isTranslating, setIsTranslating] = useState(false);
  const [descriptionHintOpen, setDescriptionHintOpen] = useState(false);

  // Editor State
  const [editingStamp, setEditingStamp] = useState<Stamp | null>(null);
  const [isManualCropping, setIsManualCropping] = useState(false);
  const [manualCropInitialSourceId, setManualCropInitialSourceId] = useState<string | undefined>(undefined);
  const [targetReplaceId, setTargetReplaceId] = useState<string | null>(null);
  const [previewBg, setPreviewBg] = useState<string>('checker');

  // Global Settings
  const [globalTolerance, setGlobalTolerance] = useState(20);
  const [gapTolerance, setGapTolerance] = useState(15); // New state for merge gap
  const [isRegenerating, setIsRegenerating] = useState(false);

  // New Image Processing State
  const [showSourceSelectModal, setShowSourceSelectModal] = useState(false);
  const [selectedSourceForNewStamp, setSelectedSourceForNewStamp] = useState<SourceImage | null>(null);
  const [showProcessSelection, setShowProcessSelection] = useState(false);

  // State for Main/Tab Editor
  const [editingSpecialType, setEditingSpecialType] = useState<'main' | 'tab' | null>(null);

  // Export Settings
  const [renumber, setRenumber] = useState(true);

  // Drag and Drop Refs
  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // Ref to access latest stamps in async callbacks without adding to dependency array
  const stampsRef = useRef(stamps);
  useEffect(() => { stampsRef.current = stamps; }, [stamps]);

  // Debounced Bulk Processing Effect (Tolerance - Background Removal)
  useEffect(() => {
      const timer = setTimeout(async () => {
          const currentStamps = stampsRef.current;
          if (currentStamps.length === 0) return;

          // Check if any stamp needs update (compare currentTolerance with globalTolerance)
          // Also checks if originalDataUrl exists (it should for stamps)
          const needsUpdate = currentStamps.some(s => s.originalDataUrl && s.currentTolerance !== globalTolerance);

          if (!needsUpdate) return;

          try {
              const updates = new Map<string, Stamp>();

              // Process in parallel
              await Promise.all(currentStamps.map(async (stamp) => {
                  // Only reprocess if tolerance matches target and differs from current
                  // Note: stamp.currentTolerance might be undefined for old stamps, treat as diff
                  if (stamp.originalDataUrl && stamp.currentTolerance !== globalTolerance) {
                      const newDataUrl = await reprocessStampWithTolerance(stamp.originalDataUrl, globalTolerance);
                      updates.set(stamp.id, {
                          ...stamp,
                          dataUrl: newDataUrl,
                          currentTolerance: globalTolerance
                      });
                  }
              }));

              if (updates.size > 0) {
                  // Update state using functional update to respect current order/existence
                  setStamps(prev => prev.map(s => updates.get(s.id) || s));
              }
          } catch (err) {
              console.error("Bulk processing failed", err);
          }
      }, 100); // 100ms debounce for snappier response

      return () => clearTimeout(timer);
  }, [globalTolerance]);

  // Debounced Re-generation Effect (Gap - Merge Logic)
  // This is destructive to the auto-generated list as it re-runs detection
  useEffect(() => {
      const timer = setTimeout(async () => {
          if (sourceImages.length === 0) return;

          setIsRegenerating(true);
          try {
              let newAutoStamps: Stamp[] = [];

              // Re-process all source images
              for (const src of sourceImages) {
                  // Pass both globalTolerance (for bg) and gapTolerance (for merge)
                  const result = await processUploadedImage(src.file, src.id, globalTolerance, gapTolerance);
                  newAutoStamps.push(...result.stamps);
              }

              // Preserve Manual Stamps (identified by ID prefix)
              const manualStamps = stampsRef.current.filter(s => s.id.startsWith('stamp-manual-'));

              setStamps([...newAutoStamps, ...manualStamps]);

              // Reset Main/Tab if they point to non-existent stamps
              // (Optional refinement: try to map them but IDs change so it's hard)

          } catch (err) {
              console.error("Regeneration failed", err);
          } finally {
              setIsRegenerating(false);
          }
      }, 500); // 500ms debounce for heavy operation

      return () => clearTimeout(timer);
  }, [gapTolerance]);

  // Helper to read file dims
  const getImageDims = (file: File): Promise<{w:number, h:number}> => {
      return new Promise((resolve) => {
          const img = new Image();
          img.onload = () => resolve({w: img.width, h: img.height});
          img.src = URL.createObjectURL(file);
      });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0) return;

    // Filter valid images
    const validFiles = files.filter(f => f.type === 'image/png' || f.type === 'image/jpeg');
    if (validFiles.length === 0) return alert('PNGまたはJPEG画像を選択してください');

    const remainingSlots = 5 - sourceImages.length;
    const filesToAdd = validFiles.slice(0, remainingSlots);

    if (filesToAdd.length < validFiles.length) {
        alert('画像は最大5枚までです');
    }

    const newSources: SourceImage[] = [];
    for (const file of filesToAdd) {
        const url = URL.createObjectURL(file);
        const {w, h} = await getImageDims(file);
        newSources.push({
            id: Math.random().toString(36).substring(7),
            url,
            file,
            width: w,
            height: h
        });
    }

    setSourceImages(prev => [...prev, ...newSources]);
  };

  const removeSourceImage = (id: string) => {
      setSourceImages(prev => prev.filter(img => img.id !== id));
  };

  const startProcessing = async () => {
      if (sourceImages.length === 0) return;

      setIsProcessing(true);
      setStep(AppStep.PROCESSING);

      try {
          let allStamps: Stamp[] = [];
          for (const source of sourceImages) {
             // Pass current settings
             const result = await processUploadedImage(source.file, source.id, globalTolerance, gapTolerance);
             allStamps = [...allStamps, ...result.stamps];
          }
          setStamps(allStamps);

          if (allStamps.length > 0) {
              setDefaultMainTab(allStamps[0]);
          }

          setStep(AppStep.EDIT);
      } catch(err) {
          console.error(err);
          alert('処理に失敗しました');
          setStep(AppStep.UPLOAD);
      } finally {
          setIsProcessing(false);
      }
  };

  // Callback from ManualCropModal when user adds a NEW file directly inside modal
  const handleAddSourceFromModal = async (file: File) => {
      const url = URL.createObjectURL(file);
      const {w, h} = await getImageDims(file);
      const newSource = {
          id: Math.random().toString(36).substring(7),
          url,
          file,
          width: w,
          height: h
      };
      setSourceImages(prev => [...prev, newSource]);
      return newSource.id; 
  };

  // --- New Add Stamp Flow ---

  // 1. Click "New Add" -> Open Source Selector
  const handleOpenNewStampFlow = () => {
      setShowSourceSelectModal(true);
  };

  // 2. Select Existing Image -> Open Process Selector
  const handleSelectExistingSource = (source: SourceImage) => {
      setSelectedSourceForNewStamp(source);
      setShowSourceSelectModal(false);
      setShowProcessSelection(true);
  };

  // 2. Upload New Image -> Open Process Selector
  const handleUploadForNewStamp = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      // Add to sources
      const url = URL.createObjectURL(file);
      const {w, h} = await getImageDims(file);
      const newSource: SourceImage = {
          id: Math.random().toString(36).substring(7),
          url,
          file,
          width: w,
          height: h
      };
      setSourceImages(prev => [...prev, newSource]);

      // Select it and move to next step
      setSelectedSourceForNewStamp(newSource);
      setShowSourceSelectModal(false);
      setShowProcessSelection(true);
      e.target.value = ''; // Reset input to allow re-selecting same file
  };

  // 3. Process Execution
  const processNewImage = async (method: 'auto' | 'manual') => {
      if (!selectedSourceForNewStamp) return;

      setShowProcessSelection(false);
      setIsProcessing(true); 

      try {
        if (method === 'auto') {
            const result = await processUploadedImage(selectedSourceForNewStamp.file, selectedSourceForNewStamp.id, globalTolerance, gapTolerance);
            setStamps(prev => [...prev, ...result.stamps]);
        } else {
            // Manual
            // Wait a bit for UI to settle
            setTimeout(() => {
                // Open manual crop for specific source
                openManualCrop(undefined, selectedSourceForNewStamp.id); 
            }, 100);
        }

      } catch(e) {
          console.error(e);
          alert('処理に失敗しました');
      } finally {
          setIsProcessing(false);
          setSelectedSourceForNewStamp(null);
      }
  };

  const handleGlobalToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setGlobalTolerance(Number(e.target.value));
  };

  const handleGapToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setGapTolerance(Number(e.target.value));
  };

  const setDefaultMainTab = (stamp: Stamp) => {
      setMainConfig({
          id: stamp.id,
          scale: calculateFitScale(stamp.width, stamp.height, MAIN_WIDTH, MAIN_HEIGHT),
          offsetX: 0, 
          offsetY: 0,
          rotation: 0
      });
      setTabConfig({
          id: stamp.id,
          scale: calculateFitScale(stamp.width, stamp.height, TAB_WIDTH, TAB_HEIGHT),
          offsetX: 0,
          offsetY: 0,
          rotation: 0
      });
  };

  const calculateFitScale = (w: number, h: number, targetW: number, targetH: number) => {
      const scaleW = targetW / w;
      const scaleH = targetH / h;
      // Allow scale > 1 for small images to fill the target area, 
      // otherwise small crops appear tiny in Main/Tab
      return Math.min(scaleW, scaleH);
  };

  const updateStamp = (updatedStamp: Stamp) => {
    setStamps(prev => prev.map(s => s.id === updatedStamp.id ? updatedStamp : s));
  };

  const updateSpecialConfig = (updatedStamp: Stamp) => {
      if (editingSpecialType === 'main' && mainConfig) {
          setMainConfig({
              ...mainConfig,
              scale: updatedStamp.scale,
              rotation: updatedStamp.rotation,
              offsetX: updatedStamp.offsetX,
              offsetY: updatedStamp.offsetY,
              customDataUrl: updatedStamp.dataUrl,
              textObjects: updatedStamp.textObjects // Update Text Objects
          });
      } else if (editingSpecialType === 'tab' && tabConfig) {
          setTabConfig({
              ...tabConfig,
              scale: updatedStamp.scale,
              rotation: updatedStamp.rotation,
              offsetX: updatedStamp.offsetX,
              offsetY: updatedStamp.offsetY,
              customDataUrl: updatedStamp.dataUrl,
              textObjects: updatedStamp.textObjects // Update Text Objects
          });
      }
  };

  const validateText = () => {
      const errors = [];
      if (meta.stampNameJa.length < 2) errors.push('日本語タイトルは2文字以上必要です。');
      if (meta.stampDescJa.length < 10) errors.push('日本語説明文は10文字以上必要です。');
      return errors;
  };

  const handleTranslation = async () => {
    const errors = validateText();
    if (errors.length > 0) {
        return alert(errors.join('\n'));
    }

    setIsTranslating(true);
    try {
        const result = await translateMeta(meta.stampNameJa, meta.stampDescJa);
        setMeta(prev => ({ 
            ...prev, 
            stampNameEn: result.enName || prev.stampNameEn,
            stampDescEn: result.enDesc || prev.stampDescEn
        }));
    } catch (e: any) {
        console.error("Translation failed:", e);
        if (e.message && e.message.includes('permission denied')) {
            alert(`翻訳エラー: APIキーの権限がありませんでした。\n\n※スマホからアクセスしている場合、セキュリティ設定（IP制限など）によりブロックされている可能性があります。\nPC環境で再度お試しください。`);
        } else {
            alert(`翻訳に失敗しました。\nエラー: ${e.message || '不明なエラー'}\n\n※APIキーが正しく設定されているか確認してください。`);
        }
    } finally {
        setIsTranslating(false);
    }
  };

  const handleExport = async () => {
    if (!mainConfig || !tabConfig) return alert('メイン画像とタブ画像を選択してください');

    const errors = validateText();
    if (errors.length > 0) {
        if (!confirm(`以下の問題がありますが、続行しますか？\n\n${errors.join('\n')}\n\n※LINEスタンプの申請にはこれらの条件を満たす必要があります。`)) {
            return;
        }
    }

    await createAndDownloadZip(stamps, mainConfig, tabConfig, meta, renumber);
  };

  const downloadSingleStamp = async (stamp: Stamp) => {
      // Pass textObjects if any
      const config: ExportConfig = {
          id: stamp.id,
          scale: stamp.scale,
          rotation: stamp.rotation,
          offsetX: stamp.offsetX,
          offsetY: stamp.offsetY,
          textObjects: stamp.textObjects
      };

      const blob = await createFinalImageBlob(
          stamp.dataUrl, 
          config,
          TARGET_WIDTH,
          TARGET_HEIGHT
      );
      if (!blob) return;

      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `stamp_${stamp.id}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const downloadSpecialStamp = async (config: ExportConfig | null, width: number, height: number, filename: string) => {
      if (!config) return;

      // Get data source. Priority: Custom Edited -> Original
      const stamp = stamps.find(s => s.id === config.id);
      if (!stamp) return;

      const sourceUrl = config.customDataUrl || stamp.dataUrl;

      const blob = await createFinalImageBlob(
          sourceUrl,
          config,
          width,
          height
      );
      if (!blob) return;

      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const toggleExclude = (id: string) => {
    setStamps(prev => prev.map(s => s.id === id ? { ...s, isExcluded: !s.isExcluded } : s));
  };

  // Modified to optionally accept a default source ID
  const openManualCrop = (replaceId?: string, defaultSourceId?: string) => {
    if (sourceImages.length === 0) return;
    setTargetReplaceId(replaceId || null);
    setManualCropInitialSourceId(defaultSourceId);
    setIsManualCropping(true);
  };

  const handleManualCropConfirm = (newStamp: Stamp) => {
    if (targetReplaceId) {
        // If replacing an existing stamp (re-crop), update it
        // AND immediately re-open the editor with the new stamp data
        const updatedStamp = { ...newStamp, id: targetReplaceId };

        setStamps(prev => prev.map(s => s.id === targetReplaceId ? updatedStamp : s));

        // Re-open editor immediately
        // Note: setStamps is async, but we have the object here.
        setEditingStamp(updatedStamp);
    } else {
        setStamps(prev => [...prev, newStamp]);
    }

    setIsManualCropping(false);
    setTargetReplaceId(null);
    setManualCropInitialSourceId(undefined);
  };

  const handleMainSelect = (id: string) => {
      const s = stamps.find(stamp => stamp.id === id);
      if(s) {
          setMainConfig({
              id: s.id,
              scale: calculateFitScale(s.width, s.height, MAIN_WIDTH, MAIN_HEIGHT),
              offsetX: 0,
              offsetY: 0,
              customDataUrl: undefined,
              rotation: 0
          });
      }
  };

  const handleTabSelect = (id: string) => {
      const s = stamps.find(stamp => stamp.id === id);
      if(s) {
          setTabConfig({
              id: s.id,
              scale: calculateFitScale(s.width, s.height, TAB_WIDTH, TAB_HEIGHT),
              offsetX: 0,
              offsetY: 0,
              customDataUrl: undefined,
              rotation: 0
          });
      }
  };

  const handleReCropFromEditor = (stamp: Stamp) => {
      // Close editor (by App logic this happens when setEditingStamp(null))
      setEditingStamp(null);
      // Wait for close then open ManualCrop
      setTimeout(() => {
          openManualCrop(stamp.id, stamp.sourceImageId);
      }, 100);
  };

  // --- Drag and Drop Handlers ---
  const handleDragStart = (e: React.DragEvent<HTMLDivElement>, position: number) => {
    dragItem.current = position;
    e.dataTransfer.effectAllowed = "move";
    e.currentTarget.style.opacity = '0.5';
  };

  const handleDragEnter = (e: React.DragEvent<HTMLDivElement>, position: number) => {
    dragOverItem.current = position;
    e.preventDefault();
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
  };

  const handleDragEnd = (e: React.DragEvent<HTMLDivElement>) => {
    e.currentTarget.style.opacity = '1';

    if (dragItem.current !== null && dragOverItem.current !== null && dragItem.current !== dragOverItem.current) {
        const newStamps = [...stamps];
        const draggedItemContent = newStamps[dragItem.current];
        newStamps.splice(dragItem.current, 1);
        newStamps.splice(dragOverItem.current, 0, draggedItemContent);
        setStamps(newStamps);
    }

    dragItem.current = null;
    dragOverItem.current = null;
  };

  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' }, 
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#ff00ff', label: 'マゼンタ', color: 'bg-[#ff00ff]' },
    { value: '#60a5fa', label: '青', color: 'bg-[#60a5fa]' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#16a34a', label: '緑', color: 'bg-[#16a34a]' },
    { value: '#f97316', label: 'オレンジ', color: 'bg-[#f97316]' },
  ];

  const TextCounter = ({ current, min, max }: { current: number, min: number, max: number }) => {
    const isError = current < min;
    const isMax = current >= max;
    return (
        <div className="flex items-center gap-1 text-xs">
            {isError && <span className="text-red-500 font-bold mr-1">あと{min - current}文字</span>}
            {isMax && <span className="text-red-500 font-bold mr-1">上限です</span>}
            <span className={isMax ? "text-red-500 font-bold" : (isError ? "text-orange-500" : "text-gray-400")}>
                {current}/{max}
            </span>
        </div>
    );
  };

  const CopyButton = ({ text }: { text: string }) => {
      const [copied, setCopied] = useState(false);
      const handleCopy = () => {
          if (!text) return;
          navigator.clipboard.writeText(text).then(() => {
              setCopied(true);
              setTimeout(() => setCopied(false), 2000);
          });
      };

      return (
          <button 
            onClick={handleCopy} 
            className="text-gray-400 hover:text-primary-600 p-1 rounded hover:bg-primary-50 transition"
            title="コピー"
            type="button"
          >
              {copied ? <Check size={14} className="text-green-500" /> : <Copy size={14} />}
          </button>
      );
  };

  // Preview component for Main/Tab
  const CanvasPreview = ({ config, width, height, onClick }: { config: ExportConfig | null, width: number, height: number, onClick?: () => void }) => {
      const canvasRef = useRef<HTMLCanvasElement>(null);
      const s = config ? stamps.find(x => x.id === config.id) : null;

      useEffect(() => {
          if (!canvasRef.current || !config || !s) return;
          const ctx = canvasRef.current.getContext('2d');
          if (!ctx) return;

          const img = new Image();
          img.onload = () => {
              ctx.clearRect(0, 0, width, height);

              // Draw background (checkerboard)
              const size = 10;
              for(let y=0; y<height; y+=size) {
                  for(let x=0; x<width; x+=size) {
                      ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                      ctx.fillRect(x, y, size, size);
                  }
              }

              // Draw Image with config
              const drawnW = img.width * config.scale;
              const drawnH = img.height * config.scale;
              const centerX = width / 2;
              const centerY = height / 2;
              const x = centerX - (drawnW / 2) + config.offsetX;
              const y = centerY - (drawnH / 2) + config.offsetY;

              if (config.rotation) {
                  const cx = centerX + config.offsetX;
                  const cy = centerY + config.offsetY;
                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.rotate((config.rotation * Math.PI) / 180);
                  ctx.drawImage(img, -drawnW/2, -drawnH/2, drawnW, drawnH);
                  ctx.restore();
              } else {
                  ctx.drawImage(img, x, y, drawnW, drawnH);
              }

              // Draw Text Preview
              if (config.textObjects) {
                  // We need to scale text positions because config scale is for image fitting, 
                  // but canvas here is small preview.
                  // Wait, text positions are relative to the TARGET size (370x320).
                  // But here we are drawing on MAIN (240x240) or TAB (96x74).
                  // The textObjects in config are "already adjusted" for the target size?
                  // No, textObjects are stored in Stamp coordinates (TARGET_WIDTH/HEIGHT).
                  // But Main/Tab are different sizes.
                  // If we support text on Main/Tab, they should be independent objects or scaled.
                  // Current implementation: TextObjects are copied from Stamp to Config.
                  // Since Main/Tab are "special exports", ideally we should re-layout text or
                  // just scale the Whole Canvas (Stamp + Text) to fit Main/Tab?
                  // The current logic `createFinalImageBlob` draws text using absolute coordinates.
                  // If we use Stamp's text on Main/Tab, coordinates (e.g. x=300) might be outside Main(240).
                  // 
                  // FOR NOW: CanvasPreview for Main/Tab does NOT show text to avoid confusion, 
                  // or shows it scaled?
                  // Let's rely on `createFinalImageBlob` behavior.
                  // But here we are manually drawing. 
                  // Let's skip text in small preview for now to keep it simple, 
                  // or try to reuse drawTextOnCanvas but we need to handle coordinate space.
                  // 
                  // Actually, Main/Tab editing modal allows editing text directly on that size.
                  // So textObjects in config are relative to Main/Tab size.
                  if (config.textObjects) {
                       config.textObjects.forEach(t => {
                           // Import drawTextOnCanvas dynamically or duplicate logic?
                           // We can't import inside useEffect easily.
                           // Let's just do simple fillText for preview.
                           ctx.fillStyle = t.color;
                           ctx.font = `${t.fontSize}px sans-serif`;
                           ctx.fillText(t.text.substring(0, 5), t.x, t.y);
                       });
                  }
              }
          };
          // Priority: Custom Edited -> Stamp Processed
          img.src = config.customDataUrl || s.dataUrl;

      }, [config, s, width, height]);

      if (!config || !s) {
          return (
             <div 
                className="mt-2 border border-gray-200 rounded bg-gray-50 flex items-center justify-center text-xs text-gray-400"
                style={{ width: width / 2, height: height / 2 }}
             >
                 プレビュー
             </div>
          );
      }

      return (
          <div className="mt-2 flex justify-center bg-gray-100 rounded border border-gray-200 p-2 cursor-pointer hover:ring-2 hover:ring-primary-300 transition relative group" onClick={onClick}>
             <canvas 
                ref={canvasRef} 
                width={width} 
                height={height}
                className="shadow-sm bg-white"
                style={{
                    maxWidth: '100%',
                    height: 'auto',
                    maxHeight: '120px' 
                }}
             />
             <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 flex items-center justify-center transition-colors pointer-events-none">
                <span className="opacity-0 group-hover:opacity-100 bg-white/90 text-xs px-2 py-1 rounded-full font-bold shadow-sm text-gray-700">編集</span>
             </div>
          </div>
      );
  };

  // Stamp Count Logic
  const validStampsCount = stamps.filter(s => !s.isExcluded).length;
  const allowedCounts = [8, 16, 24, 32, 40];
  const nextTarget = allowedCounts.find(c => c >= validStampsCount) || 40;
  const isExactCount = allowedCounts.includes(validStampsCount);
  const isOverLimit = validStampsCount > 40;

  return (
    <div className="min-h-screen pb-20 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-primary-100 py-3 px-6 sticky top-0 z-40 shadow-sm">
        <div className="max-w-6xl mx-auto w-full">
            <div className="flex flex-col gap-3">
                <div className="flex items-center gap-2">
                    <div className="bg-primary-500 p-2 rounded-lg text-white">
                        <Grid size={24} />
                    </div>
                    <h1 className="text-xl font-bold text-gray-800">スタンプ切り出しくん</h1>
                </div>

                 {/* Header Controls for Edit Step - Moved below title */}
                {step === AppStep.EDIT && (
                    <div className="flex flex-wrap items-center gap-x-6 gap-y-3 animate-fade-in border-t border-primary-50 pt-2">
                        {/* Background Selector */}
                        <div className="flex items-center gap-2">
                            <span className="text-xs font-bold text-gray-500">背景色</span>
                            <div className="flex items-center gap-1 bg-white p-1 rounded-lg border border-gray-200">
                                {backgroundOptions.map(opt => (
                                    <button
                                        key={opt.value}
                                        onClick={() => setPreviewBg(opt.value)}
                                        className={`w-6 h-6 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                                        title={opt.label}
                                        style={opt.value === 'checker' ? {
                                            backgroundImage: `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')`,
                                            backgroundRepeat: 'repeat',
                                            backgroundSize: '10px 10px'
                                        } : {}}
                                    />
                                ))}
                            </div>
                        </div>

                        <div className="hidden sm:block h-6 w-px bg-gray-200"></div>

                        {/* Merge Strength Slider (Gap) */}
                        <div className="flex items-center gap-2">
                            <div className="flex items-center gap-1 text-xs font-bold text-gray-500">
                                <Layers size={14} />
                                <span className="hidden sm:inline">まとめる強さ</span>
                                <span className="sm:hidden">まとめ</span>
                            </div>
                            <div className="flex items-center gap-1 bg-gray-50 rounded-lg p-1 border border-gray-200">
                                <button 
                                    onClick={() => setGapTolerance(Math.max(0, gapTolerance - 1))}
                                    className="w-6 h-6 flex items-center justify-center bg-white border border-gray-200 rounded hover:bg-gray-100 text-gray-600 font-bold"
                                ><Minus size={12} /></button>
                                <input 
                                    type="range" 
                                    min="0" 
                                    max="50" 
                                    value={gapTolerance} 
                                    onChange={handleGapToleranceChange}
                                    className="w-16 accent-primary-500 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer"
                                    title="文字とイラストが離れている場合に数値を上げてください"
                                />
                                <button 
                                    onClick={() => setGapTolerance(Math.min(50, gapTolerance + 1))}
                                    className="w-6 h-6 flex items-center justify-center bg-white border border-gray-200 rounded hover:bg-gray-100 text-gray-600 font-bold"
                                ><PlusIcon size={12} /></button>
                            </div>
                             {isRegenerating && (
                                <Loader2 size={14} className="animate-spin text-primary-500" />
                            )}
                        </div>

                        {/* Bulk Tolerance Slider */}
                        <div className="flex items-center gap-2">
                            <div className="flex items-center gap-1 text-xs font-bold text-gray-500">
                                <Sliders size={14} />
                                <span className="hidden sm:inline">一括透過</span>
                                <span className="sm:hidden">透過</span>
                            </div>
                            <div className="flex items-center gap-1 bg-gray-50 rounded-lg p-1 border border-gray-200">
                                <button 
                                    onClick={() => setGlobalTolerance(Math.max(1, globalTolerance - 1))}
                                    className="w-6 h-6 flex items-center justify-center bg-white border border-gray-200 rounded hover:bg-gray-100 text-gray-600 font-bold"
                                ><Minus size={12} /></button>
                                <input 
                                    type="range" 
                                    min="1" 
                                    max="100" 
                                    value={globalTolerance} 
                                    onChange={handleGlobalToleranceChange}
                                    className="w-16 accent-primary-500 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer"
                                />
                                <button 
                                    onClick={() => setGlobalTolerance(Math.min(100, globalTolerance + 1))}
                                    className="w-6 h-6 flex items-center justify-center bg-white border border-gray-200 rounded hover:bg-gray-100 text-gray-600 font-bold"
                                ><PlusIcon size={12} /></button>
                            </div>
                        </div>

                        <div className="hidden sm:block h-6 w-px bg-gray-200"></div>

                        {/* Add Image Button */}
                        <button 
                            type="button"
                            onClick={handleOpenNewStampFlow}
                            className="flex items-center gap-1 bg-primary-600 hover:bg-primary-700 text-white font-bold py-1.5 px-3 rounded-full shadow transition-all text-xs sm:text-sm ml-auto sm:ml-0"
                        >
                            <Plus size={16} />
                            画像を追加
                        </button>
                    </div>
                )}
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto p-6 w-full flex-grow">

        {/* Step 1: Upload */}
        {step === AppStep.UPLOAD && (
          <div className="flex flex-col items-center justify-center py-20 animate-fade-in gap-8">
            <div className="bg-white p-12 rounded-3xl shadow-xl text-center border-4 border-dashed border-primary-200 hover:border-primary-400 transition-colors cursor-pointer relative max-w-2xl w-full">
              <input 
                type="file" 
                multiple
                accept="image/png, image/jpeg" 
                onChange={handleFileUpload}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                disabled={sourceImages.length >= 5}
              />
              <div className="bg-primary-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-primary-600">
                <Upload size={40} />
              </div>
              <h2 className="text-2xl font-bold text-gray-700 mb-2">画像をここにドロップ</h2>
              <p className="text-gray-500 mb-6">またはクリックして選択 (最大5枚)</p>
              <div className="inline-block bg-primary-600 text-white px-6 py-3 rounded-full font-bold shadow-lg shadow-primary-200">
                画像を追加する
              </div>
              <p className="text-xs text-gray-400 mt-8">
                スタンプにしたい画像をアップロードしてください。<br/>
                自動で背景を透過し、個別に切り出します。
              </p>
            </div>

            {/* Uploaded Images Preview */}
            {sourceImages.length > 0 && (
                <div className="w-full max-w-2xl">
                    <div className="flex justify-between items-end mb-2">
                        <h3 className="text-gray-600 font-bold flex items-center gap-2">
                            アップロード済み ({sourceImages.length}/5)
                        </h3>
                    </div>

                    <div className="grid grid-cols-5 gap-4">
                        {sourceImages.map(img => (
                            <div key={img.id} className="relative group aspect-square rounded-xl overflow-hidden shadow-md border bg-white">
                                <img src={img.url} alt="source" className="w-full h-full object-cover" />
                                <button 
                                    onClick={() => removeSourceImage(img.id)}
                                    className="absolute top-1 right-1 bg-black/50 hover:bg-red-500 text-white p-1 rounded-full transition"
                                >
                                    <XIcon size={12} />
                                </button>
                            </div>
                        ))}
                        {sourceImages.length < 5 && (
                             <div className="aspect-square rounded-xl border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 relative hover:bg-white hover:border-primary-400 transition">
                                <Plus size={24} />
                                <input 
                                    type="file" 
                                    multiple
                                    accept="image/png, image/jpeg" 
                                    onChange={handleFileUpload}
                                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                />
                             </div>
                        )}
                    </div>

                    <button 
                        onClick={startProcessing}
                        className="w-full mt-6 bg-gradient-to-r from-primary-600 to-primary-500 hover:from-primary-700 hover:to-primary-600 text-white text-lg font-bold py-4 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2"
                    >
                        <Crop size={24} />
                        切り出す
                    </button>
                </div>
            )}
          </div>
        )}

        {/* Step 2: Processing */}
        {step === AppStep.PROCESSING && (
          <div className="flex flex-col items-center justify-center py-40">
            <Loader2 size={60} className="text-primary-500 animate-spin mb-6" />
            <h2 className="text-2xl font-bold text-gray-700">画像を解析中...</h2>
            <p className="text-gray-500">
                {sourceImages.length}枚の画像からスタンプを切り出しています
            </p>
          </div>
        )}

        {/* Step 3: Edit & Export */}
        {step === AppStep.EDIT && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

            {/* Left Col: Stamps Grid */}
            <div className="lg:col-span-2 space-y-6">

              {/* Toolbar */}
              <div className="flex flex-col gap-4 bg-white p-4 rounded-xl shadow-sm border border-primary-100">
                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                    <div>
                        <h2 className="font-bold text-lg flex items-center gap-2">
                        <ImageIcon className="text-primary-500" />
                        切り出し結果 (有効 {validStampsCount}個)
                        </h2>
                        <div className="text-xs text-gray-500 mt-2 bg-blue-50 p-2 rounded border border-blue-100">
                             <div className="flex items-start gap-1">
                                <Info size={14} className="text-blue-500 mt-0.5 shrink-0" />
                                <div>
                                    <span className="font-bold text-blue-600">申請可能個数:</span> 8, 16, 24, 32, 40個<br/>
                                    {isExactCount ? (
                                        <span className="text-green-600 font-bold">現在 {validStampsCount}個 (申請可能です！)</span>
                                    ) : (
                                        <>
                                        {isOverLimit ? (
                                            <span className="text-orange-600 font-bold">40個を超えています。登録時は40個までが対象です。</span>
                                        ) : (
                                            <span className="text-orange-600">次は <span className="font-bold">{nextTarget}個</span> を目指しましょう（あと{nextTarget - validStampsCount}個）</span>
                                        )}
                                        </>
                                    )}
                                    <br/>
                                    <span className="opacity-70">※不足していると申請できません。多い場合は有効なスタンプ順に登録されます。</span>
                                </div>
                             </div>
                        </div>
                    </div>
                </div>
              </div>

              {/* Sort Hint */}
              <div className="flex justify-end">
                  <p className="text-xs text-gray-400">※ドラッグ＆ドロップで並べ替えができます</p>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                {stamps.map((stamp, index) => {
                    // Calculate preview transforms for exact WYSIWYG
                    const centerX = TARGET_WIDTH / 2;
                    const centerY = TARGET_HEIGHT / 2;
                    const drawnW = stamp.width * stamp.scale;
                    const drawnH = stamp.height * stamp.scale;
                    const finalX = centerX - (drawnW / 2) + stamp.offsetX;
                    const finalY = centerY - (drawnH / 2) + stamp.offsetY;

                    const rotation = stamp.rotation || 0;
                    const cx = centerX + stamp.offsetX;
                    const cy = centerY + stamp.offsetY;

                    return (
                        <div 
                            key={stamp.id} 
                            draggable
                            onDragStart={(e) => handleDragStart(e, index)}
                            onDragEnter={(e) => handleDragEnter(e, index)}
                            onDragOver={handleDragOver}
                            onDragEnd={handleDragEnd}
                            className={`bg-white rounded-xl shadow border-2 transition-all overflow-hidden ${stamp.isExcluded ? 'opacity-50 border-gray-200' : 'border-transparent hover:border-primary-300'} cursor-move`}
                        >
                            {/* 
                                Preview Container
                            */}
                            <div 
                                className="w-full aspect-[37/32] relative group"
                                style={{
                                    // Use gray background if checker to make transparent parts visible against it
                                    backgroundColor: previewBg === 'checker' ? '#e5e7eb' : previewBg,
                                    backgroundImage: previewBg === 'checker' ? `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')` : undefined,
                                    backgroundRepeat: 'repeat',
                                    backgroundSize: '10px 10px'
                                }}
                                onClick={() => setEditingStamp(stamp)}
                            >
                                <svg 
                                    viewBox={`0 0 ${TARGET_WIDTH} ${TARGET_HEIGHT}`} 
                                    className="w-full h-full pointer-events-none"
                                    preserveAspectRatio="xMidYMid meet"
                                >
                                    <image 
                                        href={stamp.dataUrl} 
                                        x={finalX} 
                                        y={finalY} 
                                        width={drawnW} 
                                        height={drawnH}
                                        transform={rotation ? `rotate(${rotation}, ${cx}, ${cy})` : undefined}
                                    />
                                    {/* Text Preview in Grid */}
                                    {stamp.textObjects?.map(t => {
                                        // Simple SVG Text for preview
                                        // SVG text is different from Canvas text, so this is an approximation
                                        return (
                                            <text
                                                key={t.id}
                                                x={t.x}
                                                y={t.y}
                                                fontSize={t.fontSize}
                                                fontFamily={t.fontFamily}
                                                fill={t.color}
                                                stroke={t.outlineWidth > 0 ? t.outlineColor : 'none'}
                                                strokeWidth={t.outlineWidth}
                                                strokeLinejoin="round"
                                                paintOrder="stroke"
                                                dominantBaseline="hanging"
                                                writingMode={t.isVertical ? "tb" : "lr"}
                                            >
                                                {t.text}
                                            </text>
                                        );
                                    })}
                                </svg>

                                {/* Overlay Edit Hint */}
                                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 flex items-center justify-center transition-colors cursor-pointer">
                                    <span className="opacity-0 group-hover:opacity-100 bg-white/90 text-xs px-2 py-1 rounded-full font-bold shadow-sm">編集</span>
                                </div>

                                {/* Drag Handle Hint */}
                                <div className="absolute top-2 left-2 bg-white/50 p-1 rounded cursor-move opacity-0 group-hover:opacity-100 transition-opacity">
                                    <GripVertical size={14} className="text-gray-600" />
                                </div>

                                {/* Top Actions: Visible by default on Mobile, Hover on Desktop */}
                                <div className="absolute top-2 right-2 z-10 flex gap-1 opacity-100 lg:opacity-0 lg:group-hover:opacity-100 transition-opacity">
                                    {/* Download Button */}
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); downloadSingleStamp(stamp); }}
                                        className="bg-white text-gray-600 p-1.5 rounded-full shadow hover:bg-gray-100 hover:text-primary-600 cursor-pointer"
                                        title="このスタンプをダウンロード"
                                    >
                                        <Save size={14} />
                                    </button>
                                    {/* Recrop Button */}
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); openManualCrop(stamp.id, stamp.sourceImageId); }}
                                        className="bg-white text-gray-600 p-1.5 rounded-full shadow hover:bg-gray-100 hover:text-primary-600 cursor-pointer"
                                        title="元画像から範囲を指定し直す"
                                    >
                                        <RotateCw size={14} />
                                    </button>
                                </div>
                            </div>

                            {/* Footer: Checkbox, Number, Status */}
                            <div className="px-3 py-2 bg-gray-50 border-t flex items-center justify-between">
                                <input 
                                    type="checkbox" 
                                    checked={!stamp.isExcluded} 
                                    onChange={(e) => { e.stopPropagation(); toggleExclude(stamp.id); }}
                                    className="w-5 h-5 rounded border-gray-300 text-primary-600 focus:ring-primary-500 cursor-pointer shadow-sm"
                                />

                                <div className="font-bold text-gray-500 text-sm">
                                    {stamp.isExcluded ? '除外' : `No.${String(index + 1).padStart(2,'0')}`}
                                </div>

                                <div className="flex gap-1 h-5">
                                    {mainConfig?.id === stamp.id && <span className="bg-yellow-400 text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow flex items-center">MAIN</span>}
                                    {tabConfig?.id === stamp.id && <span className="bg-blue-400 text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow flex items-center">TAB</span>}
                                </div>
                            </div>
                        </div>
                    );
                })}
              </div>
            </div>

            {/* Right Col: Settings & Export */}
            <div className="lg:col-span-1 space-y-6">

                {/* Main/Tab Selection */}
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-primary-100">
                    <h3 className="font-bold text-gray-700 flex items-center gap-2 mb-4">
                        <CheckCircle2 className="text-primary-500" size={20} />
                        代表画像設定
                    </h3>

                    <div className="space-y-4">
                        <div>
                            <div className="flex justify-between items-end mb-1">
                                <label className="block text-sm font-medium text-gray-600">メイン画像 (240x240)</label>
                                <button
                                    onClick={() => downloadSpecialStamp(mainConfig, MAIN_WIDTH, MAIN_HEIGHT, 'main.png')}
                                    disabled={!mainConfig}
                                    className="text-gray-400 hover:text-primary-600 disabled:opacity-30"
                                    title="メイン画像をダウンロード"
                                >
                                    <Save size={18} />
                                </button>
                            </div>
                            <select 
                                className="w-full border-gray-300 rounded-lg shadow-sm focus:ring-primary-500 focus:border-primary-500 mb-2 bg-primary-50"
                                value={mainConfig?.id || ''}
                                onChange={(e) => handleMainSelect(e.target.value)}
                            >
                                {stamps.map((s, i) => !s.isExcluded && (
                                    <option key={s.id} value={s.id}>No.{i+1} のスタンプ</option>
                                ))}
                            </select>
                            <CanvasPreview 
                                config={mainConfig} 
                                width={MAIN_WIDTH} 
                                height={MAIN_HEIGHT} 
                                onClick={() => {
                                    setEditingSpecialType('main');
                                    const s = stamps.find(x => x.id === mainConfig?.id);
                                    if(s) setEditingStamp(s);
                                }} 
                            />
                        </div>
                        <div>
                             <div className="flex justify-between items-end mb-1">
                                <label className="block text-sm font-medium text-gray-600">タブ画像 (96x74)</label>
                                <button
                                    onClick={() => downloadSpecialStamp(tabConfig, TAB_WIDTH, TAB_HEIGHT, 'tab.png')}
                                    disabled={!tabConfig}
                                    className="text-gray-400 hover:text-primary-600 disabled:opacity-30"
                                    title="タブ画像をダウンロード"
                                >
                                    <Save size={18} />
                                </button>
                            </div>
                            <select 
                                className="w-full border-gray-300 rounded-lg shadow-sm focus:ring-primary-500 focus:border-primary-500 mb-2 bg-primary-50"
                                value={tabConfig?.id || ''}
                                onChange={(e) => handleTabSelect(e.target.value)}
                            >
                                {stamps.map((s, i) => !s.isExcluded && (
                                    <option key={s.id} value={s.id}>No.{i+1} のスタンプ</option>
                                ))}
                            </select>
                            <CanvasPreview 
                                config={tabConfig} 
                                width={TAB_WIDTH} 
                                height={TAB_HEIGHT} 
                                onClick={() => {
                                    setEditingSpecialType('tab');
                                    const s = stamps.find(x => x.id === tabConfig?.id);
                                    if(s) setEditingStamp(s);
                                }}
                            />
                        </div>
                    </div>
                </div>

                {/* Translation / Meta */}
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-primary-100">
                     <h3 className="font-bold text-gray-700 flex items-center gap-2 mb-4">
                        <Languages className="text-primary-500" size={20} />
                        スタンプ名・説明文
                    </h3>
                    <div className="space-y-4">
                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">タイトル（スタンプ名）</label>
                                    <CopyButton text={meta.stampNameJa} />
                                </div>
                                <TextCounter current={meta.stampNameJa.length} min={2} max={40} />
                            </div>
                            <input 
                                type="text" 
                                className={`w-full bg-primary-50 border rounded-md text-sm focus:ring-primary-500 focus:border-primary-500 ${meta.stampNameJa.length >= 40 ? 'border-red-300 bg-red-50' : 'border-primary-200'}`}
                                placeholder="例：かわいいうさぎスタンプ"
                                maxLength={40}
                                value={meta.stampNameJa}
                                onChange={e => setMeta({...meta, stampNameJa: e.target.value})}
                            />
                        </div>
                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">スタンプ説明文</label>
                                    <CopyButton text={meta.stampDescJa} />
                                </div>
                                <TextCounter current={meta.stampDescJa.length} min={10} max={160} />
                            </div>
                            <textarea 
                                className={`w-full bg-primary-50 border rounded-md text-sm focus:ring-primary-500 focus:border-primary-500 ${meta.stampDescJa.length >= 160 ? 'border-red-300 bg-red-50' : 'border-primary-200'}`}
                                rows={3}
                                placeholder="例：日常で使いやすいかわいいうさぎです。"
                                maxLength={160}
                                value={meta.stampDescJa}
                                onChange={e => setMeta({...meta, stampDescJa: e.target.value})}
