import JSZip from 'jszip';
import { Stamp, MetaData, ExportConfig, TextObject, TARGET_WIDTH, TARGET_HEIGHT, MAIN_WIDTH, MAIN_HEIGHT, TAB_WIDTH, TAB_HEIGHT } from '../types';

export const createAndDownloadZip = async (
  stamps: Stamp[],
  mainConfig: ExportConfig | null,
  tabConfig: ExportConfig | null,
  metaData: MetaData,
  renumber: boolean
) => {
  const zip = new JSZip();

  // 1. Add Stamps
  let counter = 1;
  for (const stamp of stamps) {
    if (stamp.isExcluded) continue;

    // Process final image for the stamp
    const config: ExportConfig = {
        id: stamp.id,
        scale: stamp.scale,
        rotation: stamp.rotation,
        offsetX: stamp.offsetX,
        offsetY: stamp.offsetY,
        textObjects: stamp.textObjects // Pass text objects
    };
    // For regular stamps, we use stamp.dataUrl directly
    const blob = await createFinalImageBlob(stamp.dataUrl, config, TARGET_WIDTH, TARGET_HEIGHT);
    if (!blob) continue;

    const fileName = renumber 
      ? `${String(counter).padStart(2, '0')}.png` 
      : `${stamp.id.replace(/stamp-.*?-/, '')}.png`; // Simplified replace logic

    zip.file(fileName, blob);
    counter++;
  }

  // 2. Add Main
  if (mainConfig) {
    const mainStamp = stamps.find(s => s.id === mainConfig.id);
    if (mainStamp) {
        // Use customDataUrl if edited (eraser), otherwise original stamp dataUrl
        const sourceUrl = mainConfig.customDataUrl || mainStamp.dataUrl;
        const mainBlob = await createFinalImageBlob(sourceUrl, mainConfig, MAIN_WIDTH, MAIN_HEIGHT);
        if (mainBlob) zip.file("main.png", mainBlob);
    }
  }

  // 3. Add Tab
  if (tabConfig) {
    const tabStamp = stamps.find(s => s.id === tabConfig.id);
    if (tabStamp) {
        const sourceUrl = tabConfig.customDataUrl || tabStamp.dataUrl;
        const tabBlob = await createFinalImageBlob(sourceUrl, tabConfig, TAB_WIDTH, TAB_HEIGHT);
        if (tabBlob) zip.file("tab.png", tabBlob);
    }
  }

  // 4. Add Meta.txt
  const dateStr = new Date().toISOString().split('T')[0];
  const txtContent = `AppName: スタンプ切り出しくん
CreatedAt: ${dateStr} (JST)

[Japanese]
Name: ${metaData.stampNameJa}
Description: ${metaData.stampDescJa}

[English]
Name: ${metaData.stampNameEn}
Description: ${metaData.stampDescEn}
`;
  zip.file("meta.txt", txtContent);

  // Generate and download
  const content = await zip.generateAsync({ type: "blob" });

  // Simple download trigger
  const link = document.createElement('a');
  link.href = URL.createObjectURL(content);
  link.download = `stickers_${dateStr}.zip`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

// Helper: Takes image URL + config and renders it into the final PNG blob
export async function createFinalImageBlob(
    imageUrl: string,
    config: ExportConfig,
    targetW: number, 
    targetH: number
): Promise<Blob | null> {
  return new Promise((resolve) => {
    const canvas = document.createElement('canvas');
    canvas.width = targetW;
    canvas.height = targetH;
    const ctx = canvas.getContext('2d');
    if (!ctx) return resolve(null);

    const img = new Image();
    img.onload = () => {
      // Clear
      ctx.clearRect(0, 0, targetW, targetH);

      // Calculate drawn size based on original image size * config scale
      const drawnW = img.width * config.scale;
      const drawnH = img.height * config.scale;

      // Center + Offset
      const centerX = targetW / 2;
      const centerY = targetH / 2;

      const x = centerX - (drawnW / 2) + config.offsetX;
      const y = centerY - (drawnH / 2) + config.offsetY;

      // 1. Draw Back Text
      if (config.textObjects) {
          config.textObjects.filter(t => t.zIndex === 'back').forEach(textObj => {
              drawTextOnCanvas(ctx, textObj);
          });
      }

      // 2. Draw Image
      if (config.rotation) {
          const cx = centerX + config.offsetX;
          const cy = centerY + config.offsetY;
          ctx.save();
          ctx.translate(cx, cy);
          ctx.rotate((config.rotation * Math.PI) / 180);
          ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);
          ctx.restore();
      } else {
          ctx.drawImage(img, x, y, drawnW, drawnH);
      }

      // 3. Draw Front Text
      if (config.textObjects) {
          config.textObjects.filter(t => t.zIndex !== 'back').forEach(textObj => {
              drawTextOnCanvas(ctx, textObj);
          });
      }

      canvas.toBlob((blob) => {
        resolve(blob);
      }, 'image/png');
    };
    img.src = imageUrl; 
  });
}

// Helper to draw text (Shared logic logic for Canvas rendering)
export function drawTextOnCanvas(ctx: CanvasRenderingContext2D, textObj: TextObject) {
    if (!textObj.text) return;

    ctx.save();
    // Move to text origin
    ctx.translate(textObj.x, textObj.y);
    // Apply rotation
    ctx.rotate((textObj.rotation * Math.PI) / 180);

    ctx.font = `bold ${textObj.fontSize}px '${textObj.fontFamily}'`;
    ctx.textBaseline = 'middle'; // Center vertical alignment helps with rotation/curve
    ctx.textAlign = 'center';    // Draw from center
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';

    const lines = textObj.text.split('\n');
    const lineHeight = textObj.fontSize * 1.2;

    // Calculate total height to center vertically block
    const totalHeight = lineHeight * lines.length;
    const startY = -(totalHeight / 2) + (lineHeight / 2);

    lines.forEach((line, lineIndex) => {
        const lineY = startY + (lineIndex * lineHeight);

        // Curvature Logic (Only for Horizontal)
        // curvature: -100 (up) to 100 (down). 0 is straight.
        if (textObj.curvature !== 0 && !textObj.isVertical) {
            const radius = 10000 / textObj.curvature; // approximates radius
            const anglePerPixel = 1 / radius;

            // Measure total width to center it on the arc
            const totalWidth = ctx.measureText(line).width;
            let currentArcPos = -totalWidth / 2;

            for (const char of line) {
                const charWidth = ctx.measureText(char).width;
                const charMiddle = currentArcPos + charWidth / 2;

                // Calculate angle for this character
                // +90 deg offset because 0 deg is usually 3 o'clock, we want 12 o'clock or 6 o'clock reference
                const angle = charMiddle * anglePerPixel;

                ctx.save();

                // Translate to the curve center point (which is far below or above)
                // y axis is inverted in canvas (down is positive)
                // If curvature > 0 (downward curve), center is at (0, radius) relative to text line
                // If curvature < 0 (upward curve), center is at (0, radius) (radius is negative)

                // Position for this specific line
                ctx.translate(0, lineY + radius); 
                ctx.rotate(angle);
                ctx.translate(0, -radius);

                // Outline
                if (textObj.outlineWidth > 0) {
                    ctx.strokeStyle = textObj.outlineColor;
                    ctx.lineWidth = textObj.outlineWidth;
                    ctx.strokeText(char, 0, 0);
                }
                // Fill
                ctx.fillStyle = textObj.color;
                ctx.fillText(char, 0, 0);

                ctx.restore();
                currentArcPos += charWidth;
            }

        } else if (textObj.isVertical) {
            // Vertical Text (Simple column)
            // Vertical text doesn't support curvature in this implementation for simplicity
            let currentX = 0; // Centered
            // We need to calculate width of this line to center the block? 
            // Simplified: Vertical text is usually single line or just drawn top-down
            // For multiline vertical, we spread them on X
            // Let's assume lines go Right to Left for Vertical
            const verticalSpacing = textObj.fontSize * 1.2;
            const lineX = (lines.length - 1) * verticalSpacing / 2 - (lineIndex * verticalSpacing);

            let charY = -(line.length * textObj.fontSize) / 2 + (textObj.fontSize / 2);

            for (const char of line) {
                let drawChar = char;
                let rotate = 0;
                let offsetX = 0;
                let offsetY = 0;

                if (['ー', '-', '～'].includes(char)) {
                     rotate = 90;
                     // Adjustments for centered rotation
                }
                if (['、', '。'].includes(char)) {
                    offsetX = textObj.fontSize * 0.4;
                    offsetY = -textObj.fontSize * 0.4;
                }

                ctx.save();
                ctx.translate(lineX + offsetX, charY + offsetY);
                if (rotate) ctx.rotate(rotate * Math.PI / 180);

                if (textObj.outlineWidth > 0) {
                     ctx.strokeStyle = textObj.outlineColor;
                     ctx.lineWidth = textObj.outlineWidth;
                     ctx.strokeText(drawChar, 0, 0);
                 }
                 ctx.fillStyle = textObj.color;
                 ctx.fillText(drawChar, 0, 0);
                 ctx.restore();

                 charY += textObj.fontSize;
            }

        } else {
            // Standard Horizontal
            if (textObj.outlineWidth > 0) {
                ctx.strokeStyle = textObj.outlineColor;
                ctx.lineWidth = textObj.outlineWidth;
                ctx.strokeText(line, 0, lineY);
            }
            ctx.fillStyle = textObj.color;
            ctx.fillText(line, 0, lineY);
        }
    });

    ctx.restore();
}

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TextObject, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2, Palette, Pencil, Sliders, RotateCw, Undo, Redo, Type, Trash2, AlignVerticalJustifyCenter, AlignHorizontalJustifyCenter, Plus, Layers, MousePointer2, Minus } from 'lucide-react';
import { drawTextOnCanvas } from '../lib/zipService'; // Import the shared drawing logic

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  onReCrop?: () => void; 
  initialPreviewBg?: string; 
  targetWidth?: number;
  targetHeight?: number;
  initialScale?: number;
  initialRotation?: number;
  initialOffset?: { x: number, y: number };
  initialTextObjects?: TextObject[]; // For Main/Tab editing
}

interface HistoryState {
    scale: number;
    rotation: number;
    offset: { x: number, y: number };
    dataUrl: string;
    tolerance: number;
    textObjects: TextObject[];
}

export const StampEditorModal: React.FC<Props> = ({ 
  stamp, 
  isOpen, 
  onClose, 
  onSave, 
  onReCrop,
  initialPreviewBg = 'checker',
  targetWidth = TARGET_WIDTH,
  targetHeight = TARGET_HEIGHT,
  initialScale,
  initialRotation,
  initialOffset,
  initialTextObjects
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Image State
  const [scale, setScale] = useState(initialScale ?? stamp.scale);
  const [rotation, setRotation] = useState(initialRotation ?? stamp.rotation ?? 0);
  const [offset, setOffset] = useState(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });

  // Text State
  const [textObjects, setTextObjects] = useState<TextObject[]>(initialTextObjects ?? stamp.textObjects ?? []);
  const [selectedTextId, setSelectedTextId] = useState<string | null>(null);

  // History State
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Editor View state
  const [viewZoom, setViewZoom] = useState(1);
  const [previewBg, setPreviewBg] = useState(initialPreviewBg);

  const [mode, setMode] = useState<'move' | 'eraser' | 'wand' | 'restore' | 'text'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [isResizingText, setIsResizingText] = useState(false);

  // Cursor visual state
  const [cursorPos, setCursorPos] = useState<{x: number, y: number} | null>(null);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  const [activeTextHandle, setActiveTextHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  const [tolerance, setTolerance] = useState(stamp.currentTolerance || 50);

  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);
  const [originalImage, setOriginalImage] = useState<HTMLImageElement | null>(null);

  useEffect(() => {
    if (isOpen) {
      setScale(initialScale ?? stamp.scale);
      setRotation(initialRotation ?? stamp.rotation ?? 0);
      setOffset(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
      setTolerance(stamp.currentTolerance || 50);
      setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
      setSelectedTextId(null);

      // Initialize History
      const initialState = {
          scale: initialScale ?? stamp.scale,
          rotation: initialRotation ?? stamp.rotation ?? 0,
          offset: initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY },
          dataUrl: stamp.dataUrl,
          tolerance: stamp.currentTolerance || 50,
          textObjects: initialTextObjects ?? stamp.textObjects ?? []
      };
      setHistory([initialState]);
      setHistoryIndex(0);

      if (stamp.originalDataUrl) {
          const img = new Image();
          img.src = stamp.originalDataUrl;
          img.onload = () => setOriginalImage(img);
      } else {
          setOriginalImage(null);
      }
    }
  }, [isOpen, stamp, initialScale, initialRotation, initialOffset, initialTextObjects]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, rotation, offset, workingDataUrl, previewBg, targetWidth, targetHeight, cursorPos, mode, eraserSize, textObjects, selectedTextId]); 

  const addToHistory = (newState: Partial<HistoryState>) => {
      const currentState = {
          scale,
          rotation,
          offset,
          dataUrl: workingDataUrl,
          tolerance,
          textObjects,
          ...newState
      };

      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(currentState);

      if (newHistory.length > 20) {
          newHistory.shift();
      }

      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);
  };

  const undo = () => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setScale(prevState.scale);
          setRotation(prevState.rotation);
          setOffset(prevState.offset);
          setWorkingDataUrl(prevState.dataUrl);
          setTolerance(prevState.tolerance);
          setTextObjects(prevState.textObjects);
          setHistoryIndex(prevIndex);
      }
  };

  const redo = () => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setScale(nextState.scale);
          setRotation(nextState.rotation);
          setOffset(nextState.offset);
          setWorkingDataUrl(nextState.dataUrl);
          setTolerance(nextState.tolerance);
          setTextObjects(nextState.textObjects);
          setHistoryIndex(nextIndex);
      }
  };

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const cx = canvas.width / 2 + offset.x;
        const cy = canvas.height / 2 + offset.y;

        // 1. Draw Back Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex === 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // 2. Draw Image
        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);
        ctx.restore();

        // 3. Draw Front Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex !== 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // Border
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);

        // Draw Eraser/Wand Cursor
        if ((mode === 'eraser' || mode === 'restore') && cursorPos) {
            ctx.beginPath();
            ctx.arc(cursorPos.x, cursorPos.y, eraserSize / 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
        }
    };
    img.src = workingDataUrl;
  };

  const getTextBoundingBox = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      ctx.font = `bold ${textObj.fontSize}px '${textObj.fontFamily}'`;
      const lines = textObj.text.split('\n');
      const lineHeight = textObj.fontSize * 1.2;

      let w = 0;
      let h = 0;

      if (textObj.isVertical) {
          w = lineHeight * lines.length;
          const maxChars = Math.max(...lines.map(l => l.length));
          h = textObj.fontSize * maxChars;
      } else {
          // Approximate width for curved text or just take max line width
          const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
          w = maxW;
          h = lineHeight * lines.length;

          // If curved, bounds are trickier, but let's use the straight box for handles to keep it simple
          // and predictable for the user.
      }
      return { w, h };
  };

  const drawTextWithSelection = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      drawTextOnCanvas(ctx, textObj);

      // Draw selection box if selected and in text mode
      if (mode === 'text' && selectedTextId === textObj.id) {
          ctx.save();
          // Transform to text local space
          ctx.translate(textObj.x, textObj.y);
          ctx.rotate((textObj.rotation * Math.PI) / 180);

          const { w, h } = getTextBoundingBox(ctx, textObj);
          const hw = w / 2;
          const hh = h / 2;

          // Box
          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 1.5;
          ctx.setLineDash([4, 4]);
          ctx.strokeRect(-hw - 4, -hh - 4, w + 8, h + 8);

          // Handles
          ctx.setLineDash([]);
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#3b82f6';
          const handleSize = 8;

          const corners = [
              { x: -hw - 4, y: -hh - 4 }, // TL
              { x: hw + 4, y: -hh - 4 },  // TR
              { x: -hw - 4, y: hh + 4 },  // BL
              { x: hw + 4, y: hh + 4 },   // BR
          ];

          corners.forEach(c => {
              ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
              ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
          });

          ctx.restore();
      }
  }

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  // --- Text Operations ---
  const handleAddText = () => {
      if (textObjects.length >= 3) {
          alert("テキストは最大3つまでです");
          return;
      }
      const newText: TextObject = {
          id: Date.now().toString(),
          text: "文字",
          x: targetWidth / 2,
          y: targetHeight / 2,
          fontSize: 40,
          fontFamily: 'M PLUS Rounded 1c',
          color: '#000000',
          isVertical: false,
          outlineColor: '#ffffff',
          outlineWidth: 4,
          zIndex: 'front',
          rotation: 0,
          curvature: 0
      };
      const newObjects = [...textObjects, newText];
      setTextObjects(newObjects);
      setSelectedTextId(newText.id);
      addToHistory({ textObjects: newObjects });
  };

  const handleUpdateText = (id: string, updates: Partial<TextObject>) => {
      const newObjects = textObjects.map(t => t.id === id ? { ...t, ...updates } : t);
      setTextObjects(newObjects);
  };

  const handleTextChangeComplete = () => {
      addToHistory({ textObjects });
  };

  const handleDeleteText = () => {
      if (!selectedTextId) return;
      const newObjects = textObjects.filter(t => t.id !== selectedTextId);
      setTextObjects(newObjects);
      setSelectedTextId(null);
      addToHistory({ textObjects: newObjects });
  };

  // --- Pointer/Touch Events ---

  const getClientCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
      if ('touches' in e) {
          return { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else {
          return { x: (e as React.MouseEvent).clientX, y: (e as React.MouseEvent).clientY };
      }
  };

  // Transform screen point to text local space to check collision
  const transformPointToTextSpace = (px: number, py: number, t: TextObject) => {
      // 1. Translate back from origin
      const dx = px - t.x;
      const dy = py - t.y;
      // 2. Rotate back
      const rad = -(t.rotation * Math.PI) / 180;
      const rx = dx * Math.cos(rad) - dy * Math.sin(rad);
      const ry = dx * Math.sin(rad) + dy * Math.cos(rad);
      return { x: rx, y: ry };
  }

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchstart') e.preventDefault();

    // Pinch Check (existing)
    if ('touches' in e && e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
        setPinchStartDist(dist);
        setPinchStartScale(scale);
        setPinchStartAngle(angle);
        setPinchStartRotation(rotation);
        setIsDragging(false);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;

    // --- Text Mode Logic ---
    if (mode === 'text') {
        const ctx = canvasRef.current?.getContext('2d');
        if (!ctx) return;

        // 1. Check Handles if text is selected
        if (selectedTextId) {
            const t = textObjects.find(obj => obj.id === selectedTextId);
            if (t) {
                const { x: localX, y: localY } = transformPointToTextSpace(x, y, t);
                const { w, h } = getTextBoundingBox(ctx, t);
                const hw = w/2;
                const hh = h/2;
                const handleRadius = 15; // Hit area

                // Check corners
                if (Math.hypot(localX - (-hw - 4), localY - (-hh - 4)) < handleRadius) {
                     setActiveTextHandle('tl'); setIsResizingText(true); setLastPos({x, y}); return;
                }
                if (Math.hypot(localX - (hw + 4), localY - (-hh - 4)) < handleRadius) {
                     setActiveTextHandle('tr'); setIsResizingText(true); setLastPos({x, y}); return;
                }
                if (Math.hypot(localX - (-hw - 4), localY - (hh + 4)) < handleRadius) {
                     setActiveTextHandle('bl'); setIsResizingText(true); setLastPos({x, y}); return;
                }
                if (Math.hypot(localX - (hw + 4), localY - (hh + 4)) < handleRadius) {
                     setActiveTextHandle('br'); setIsResizingText(true); setLastPos({x, y}); return;
                }
            }
        }

        // 2. Hit Test Text Body (Front-most first)
        let hitTextId = null;
        for (let i = textObjects.length - 1; i >= 0; i--) {
             const t = textObjects[i];
             const { x: localX, y: localY } = transformPointToTextSpace(x, y, t);
             const { w, h } = getTextBoundingBox(ctx, t);

             // Check if point is inside the centered box
             if (localX >= -w/2 - 10 && localX <= w/2 + 10 &&
                 localY >= -h/2 - 10 && localY <= h/2 + 10) {
                 hitTextId = t.id;
                 break;
             }
        }

        if (hitTextId) {
            setSelectedTextId(hitTextId);
            setIsDragging(true);
            setLastPos({ x, y });
        } else {
            // Clicked empty space in text mode
            // Don't deselect immediately to keep UI available, or deselect?
            // Usually tapping outside deselects
            // setSelectedTextId(null);
        }
        return; // Don't allow image dragging in text mode
    }

    // Move Mode Logic
    if (mode === 'move') {
       setIsDragging(true);
       setLastPos({ x, y });
    }

    // Other Modes
    if (mode === 'wand' || mode === 'restore' || mode === 'eraser') {
       addToHistory({});
       if (mode === 'wand') applyMagicWand(x, y);
       else if (mode === 'eraser') applyEraser(x, y);
       else if (mode === 'restore') applyRestore(x, y);
       setIsDragging(true);
       setLastPos({ x, y });
    }
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchmove') e.preventDefault();

    // Pinch Logic
    if ('touches' in e && e.touches.length === 2 && pinchStartDist !== null) {
        // ... (Keep existing pinch logic)
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const scaleFactor = dist / pinchStartDist;
        const newScale = Math.max(0.01, pinchStartScale * scaleFactor);
        if (pinchStartAngle !== null) {
            const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
            const deltaAngle = angle - pinchStartAngle;
            setRotation(pinchStartRotation + deltaAngle);
        }
        setScale(newScale);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    setCursorPos({ x, y });

    // Text Resizing
    if (isResizingText && selectedTextId) {
        const t = textObjects.find(t => t.id === selectedTextId);
        if (t) {
            // Calculate distance from text center to current mouse
            const dist = Math.hypot(x - t.x, y - t.y);
            // Rough scaling: Base distance is roughly current fontSize * chars
            // Simplified: Just map distance to fontSize with some factor
            // Or better: Relative change
            const prevDist = Math.hypot(lastPos.x - t.x, lastPos.y - t.y);
            const scale = dist / prevDist;
            const newSize = Math.min(150, Math.max(10, t.fontSize * scale));
            handleUpdateText(selectedTextId, { fontSize: newSize });
        }
        setLastPos({ x, y });
        return;
    }

    if (!isDragging) return;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'text' && selectedTextId) {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      handleUpdateText(selectedTextId, { 
          x: textObjects.find(t => t.id === selectedTextId)!.x + dx,
          y: textObjects.find(t => t.id === selectedTextId)!.y + dy
      });
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    } else if (mode === 'restore') {
      applyRestore(x, y);
    }
    setLastPos({ x, y });
  };

  const handlePointerUp = () => {
    setIsDragging(false);
    setIsResizing(false);
    setIsResizingText(false);
    setActiveHandle(null);
    setActiveTextHandle(null);
    setPinchStartDist(null);
    setPinchStartAngle(null);
    if (mode === 'text' && selectedTextId) {
        handleTextChangeComplete();
    }
    if (mode === 'move') {
        addToHistory({});
    }
  };

  const handlePointerLeave = () => {
      setCursorPos(null);
      handlePointerUp();
  };

  // Maps Canvas Coordinates -> Source Image Coordinates
  const getSourceCoords = (canvasX: number, canvasY: number) => {
    const cx = targetWidth / 2 + offset.x;
    const cy = targetHeight / 2 + offset.y;
    const dx = canvasX - cx;
    const dy = canvasY - cy;
    const angle = -(rotation * Math.PI) / 180;
    const rx = dx * Math.cos(angle) - dy * Math.sin(angle);
    const ry = dx * Math.sin(angle) + dy * Math.cos(angle);
    const sx = rx / scale;
    const sy = ry / scale;
    const sourceX = Math.floor(sx + stamp.width / 2);
    const sourceY = Math.floor(sy + stamp.height / 2);
    return { sourceX, sourceY };
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;
     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);
       const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
       const sourceEraserSize = eraserSize / scale;
       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();
       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const applyRestore = (canvasX: number, canvasY: number) => {
    if (!originalImage) return;
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d');
    if (!ctx) return;
    const img = new Image();
    img.onload = () => {
        ctx.drawImage(img, 0, 0);
        const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
        const sourceBrushSize = eraserSize / scale;
        const radius = sourceBrushSize / 2;
        ctx.save();
        ctx.beginPath();
        ctx.arc(sourceX, sourceY, radius, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(originalImage, 0, 0);
        ctx.restore();
        setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const applyMagicWand = (canvasX: number, canvasY: number) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
    if(!ctx) return;
    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);
      const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
      if (sourceX < 0 || sourceX >= stamp.width || sourceY < 0 || sourceY >= stamp.height) return;
      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;
      const targetIdx = (sourceY * width + sourceX) * 4;
      const tR = data[targetIdx];
      const tG = data[targetIdx + 1];
      const tB = data[targetIdx + 2];
      const tA = data[targetIdx + 3];
      if (tA === 0) return;
      const diffThreshold = tolerance * 3;
      const stack = [[sourceX, sourceY]];
      const visited = new Uint8Array(width * height);
      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= width || y < 0 || y >= height) continue;
        if (visited[y * width + x]) continue;
        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];
        if (a === 0) continue; 
        const diff = Math.abs(r - tR) + Math.abs(g - tG) + Math.abs(b - tB);
        if (diff < diffThreshold) {
           data[idx + 3] = 0; 
           visited[y * width + x] = 1;
           stack.push([x + 1, y]);
           stack.push([x - 1, y]);
           stack.push([x, y + 1]);
           stack.push([x, y - 1]);
        }
      }
      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const handleToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      addToHistory({ tolerance: Number(e.target.value) });
      const newTolerance = Number(e.target.value);
      setTolerance(newTolerance);
      if (!originalImage) return;
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = stamp.width;
      tempCanvas.height = stamp.height;
      const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;
      ctx.drawImage(originalImage, 0, 0);
      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const w = stamp.width;
      const h = stamp.height;
      const bgR = data[0];
      const bgG = data[1];
      const bgB = data[2];
      const limit = newTolerance * 3;
      const stack: [number, number][] = [];
      const visited = new Uint8Array(w * h);
      stack.push([0, 0]);
      stack.push([w-1, 0]);
      stack.push([0, h-1]);
      stack.push([w-1, h-1]);
      while(stack.length > 0) {
          const [x, y] = stack.pop()!;
          if (x < 0 || x >= w || y < 0 || y >= h) continue;
          const idx = y * w + x;
          if (visited[idx]) continue;
          const pIdx = idx * 4;
          const r = data[pIdx];
          const g = data[pIdx+1];
          const b = data[pIdx+2];
          const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
          if (diff < limit) {
              data[pIdx+3] = 0;
              visited[idx] = 1;
              stack.push([x+1, y]);
              stack.push([x-1, y]);
              stack.push([x, y+1]);
              stack.push([x, y-1]);
          }
      }
      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
  };

  const handleSave = () => {
    onSave({
      ...stamp,
      scale,
      rotation,
      offsetX: offset.x,
      offsetY: offset.y,
      dataUrl: workingDataUrl,
      currentTolerance: tolerance,
      textObjects: textObjects
    });
    onClose();
  };

  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' }, 
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#ff00ff', label: 'マゼンタ', color: 'bg-[#ff00ff]' },
    { value: '#60a5fa', label: '青', color: 'bg-[#60a5fa]' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#16a34a', label: '緑', color: 'bg-[#16a34a]' },
    { value: '#f97316', label: 'オレンジ', color: 'bg-[#f97316]' },
  ];

  const fontOptions = [
      { value: 'M PLUS Rounded 1c', label: '丸ゴシック' },
      { value: 'Noto Sans JP', label: 'ゴシック' },
      { value: 'Noto Serif JP', label: '明朝' },
  ];

  const textColorOptions = ['#000000', '#FFFFFF', '#ef4444', '#3b82f6', '#10b981', '#f97316', '#ec4899', '#4b3621'];

  const selectedText = textObjects.find(t => t.id === selectedTextId);

  // Common Slider Component with +/- buttons
  const ControlSlider = ({ label, value, min, max, onChange, onCommit, unit = '' }: any) => (
      <div className="flex items-center gap-2 w-full">
          <span className="text-xs text-gray-500 w-12 shrink-0">{label}</span>
          <button 
            onClick={() => {
                const newVal = Math.max(min, value - 1);
                onChange(newVal);
                if(onCommit) onCommit();
            }}
            className="w-6 h-6 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600"
          ><Minus size={12}/></button>
          <input 
            type="range" 
            min={min} 
            max={max} 
            value={value} 
            onChange={(e) => onChange(Number(e.target.value))}
            onMouseUp={onCommit}
            onTouchEnd={onCommit}
            className="flex-1 accent-primary-500 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer"
          />
          <button 
            onClick={() => {
                const newVal = Math.min(max, value + 1);
                onChange(newVal);
                if(onCommit) onCommit();
            }}
            className="w-6 h-6 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600"
          ><Plus size={12}/></button>
          {unit && <span className="text-xs text-gray-400 w-6 text-right">{value}{unit}</span>}
      </div>
  );

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col max-h-[95vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
          <h3 className="font-bold text-gray-700">スタンプ編集 ({targetWidth}x{targetHeight})</h3>
          <div className="flex items-center gap-2">
               <div className="flex items-center gap-1 bg-white p-1 rounded-lg border border-gray-200 mr-2 md:mr-4">
                    <span className="hidden md:inline text-xs text-gray-400 font-bold px-1">背景色</span>
                    {backgroundOptions.map(opt => (
                        <button
                            key={opt.value}
                            onClick={() => setPreviewBg(opt.value)}
                            className={`w-5 h-5 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                            title={opt.label}
                            style={opt.value === 'checker' ? {
