import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TextObject, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2, Palette, Pencil, Sliders, RotateCw, Undo, Redo, Type, Trash2, AlignVerticalJustifyCenter, AlignHorizontalJustifyCenter, Plus, Layers, MousePointer2, Minus } from 'lucide-react';
import { drawTextOnCanvas } from '../lib/zipService'; // Import the shared drawing logic

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  onReCrop?: () => void; 
  initialPreviewBg?: string; 
  targetWidth?: number;
  targetHeight?: number;
  initialScale?: number;
  initialRotation?: number;
  initialOffset?: { x: number, y: number };
  initialTextObjects?: TextObject[]; // For Main/Tab editing
}

interface HistoryState {
    scale: number;
    rotation: number;
    offset: { x: number, y: number };
    dataUrl: string;
    tolerance: number;
    textObjects: TextObject[];
}

export const StampEditorModal: React.FC<Props> = ({ 
  stamp, 
  isOpen, 
  onClose, 
  onSave, 
  onReCrop,
  initialPreviewBg = 'checker',
  targetWidth = TARGET_WIDTH,
  targetHeight = TARGET_HEIGHT,
  initialScale,
  initialRotation,
  initialOffset,
  initialTextObjects
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Image State
  const [scale, setScale] = useState(initialScale ?? stamp.scale);
  const [rotation, setRotation] = useState(initialRotation ?? stamp.rotation ?? 0);
  const [offset, setOffset] = useState(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });

  // Text State
  const [textObjects, setTextObjects] = useState<TextObject[]>(initialTextObjects ?? stamp.textObjects ?? []);
  const [selectedTextId, setSelectedTextId] = useState<string | null>(null);

  // History State
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Editor View state
  const [viewZoom, setViewZoom] = useState(1);
  const [previewBg, setPreviewBg] = useState(initialPreviewBg);

  const [mode, setMode] = useState<'move' | 'eraser' | 'wand' | 'restore' | 'text'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [isResizingText, setIsResizingText] = useState(false);

  // Cursor visual state
  const [cursorPos, setCursorPos] = useState<{x: number, y: number} | null>(null);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  const [activeTextHandle, setActiveTextHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  // Pinch & Resize State
  const [pinchStartDist, setPinchStartDist] = useState<number | null>(null);
  const [pinchStartScale, setPinchStartScale] = useState<number>(1);
  const [pinchStartAngle, setPinchStartAngle] = useState<number | null>(null);
  const [pinchStartRotation, setPinchStartRotation] = useState<number>(0);
  const [isResizing, setIsResizing] = useState(false);
  const [activeHandle, setActiveHandle] = useState<string | null>(null);

  const [tolerance, setTolerance] = useState(stamp.currentTolerance || 50);

  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);
  const [originalImage, setOriginalImage] = useState<HTMLImageElement | null>(null);

  useEffect(() => {
    if (isOpen) {
      setScale(initialScale ?? stamp.scale);
      setRotation(initialRotation ?? stamp.rotation ?? 0);
      setOffset(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
      setTolerance(stamp.currentTolerance || 50);
      setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
      setSelectedTextId(null);

      // Initialize History
      const initialState = {
          scale: initialScale ?? stamp.scale,
          rotation: initialRotation ?? stamp.rotation ?? 0,
          offset: initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY },
          dataUrl: stamp.dataUrl,
          tolerance: stamp.currentTolerance || 50,
          textObjects: initialTextObjects ?? stamp.textObjects ?? []
      };
      setHistory([initialState]);
      setHistoryIndex(0);

      if (stamp.originalDataUrl) {
          const img = new Image();
          img.src = stamp.originalDataUrl;
          img.onload = () => setOriginalImage(img);
      } else {
          setOriginalImage(null);
      }
    }
  }, [isOpen, stamp, initialScale, initialRotation, initialOffset, initialTextObjects]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, rotation, offset, workingDataUrl, previewBg, targetWidth, targetHeight, cursorPos, mode, eraserSize, textObjects, selectedTextId]); 

  const addToHistory = (newState: Partial<HistoryState>) => {
      const currentState = {
          scale,
          rotation,
          offset,
          dataUrl: workingDataUrl,
          tolerance,
          textObjects,
          ...newState
      };

      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(currentState);

      if (newHistory.length > 20) {
          newHistory.shift();
      }

      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);
  };

  const undo = () => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setScale(prevState.scale);
          setRotation(prevState.rotation);
          setOffset(prevState.offset);
          setWorkingDataUrl(prevState.dataUrl);
          setTolerance(prevState.tolerance);
          setTextObjects(prevState.textObjects);
          setHistoryIndex(prevIndex);
      }
  };

  const redo = () => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setScale(nextState.scale);
          setRotation(nextState.rotation);
          setOffset(nextState.offset);
          setWorkingDataUrl(nextState.dataUrl);
          setTolerance(nextState.tolerance);
          setTextObjects(nextState.textObjects);
          setHistoryIndex(nextIndex);
      }
  };

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const cx = canvas.width / 2 + offset.x;
        const cy = canvas.height / 2 + offset.y;

        // 1. Draw Back Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex === 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // 2. Draw Image
        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);
        ctx.restore();

        // 3. Draw Front Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex !== 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // Border
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);

        // Draw Eraser/Wand Cursor
        if ((mode === 'eraser' || mode === 'restore') && cursorPos) {
            ctx.beginPath();
            ctx.arc(cursorPos.x, cursorPos.y, eraserSize / 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
        }
    };
    img.src = workingDataUrl;
  };

  const getTextBoundingBox = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      ctx.font = `bold ${textObj.fontSize}px '${textObj.fontFamily}'`;
      const lines = textObj.text.split('\n');
      const lineHeight = textObj.fontSize * 1.2;

      let w = 0;
      let h = 0;

      if (textObj.isVertical) {
          w = lineHeight * lines.length;
          const maxChars = Math.max(...lines.map(l => l.length));
          h = textObj.fontSize * maxChars;
      } else {
          // Approximate width for curved text or just take max line width
          const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
          w = maxW;
          h = lineHeight * lines.length;

          // If curved, bounds are trickier, but let's use the straight box for handles to keep it simple
          // and predictable for the user.
      }
      return { w, h };
  };

  const drawTextWithSelection = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      drawTextOnCanvas(ctx, textObj);

      // Draw selection box if selected and in text mode
      if (mode === 'text' && selectedTextId === textObj.id) {
          ctx.save();
          // Transform to text local space
          ctx.translate(textObj.x, textObj.y);
          ctx.rotate((textObj.rotation * Math.PI) / 180);

          const { w, h } = getTextBoundingBox(ctx, textObj);
          const hw = w / 2;
          const hh = h / 2;

          // Box
          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 1.5;
          ctx.setLineDash([4, 4]);
          ctx.strokeRect(-hw - 4, -hh - 4, w + 8, h + 8);

          // Handles
          ctx.setLineDash([]);
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#3b82f6';
          const handleSize = 8;

          const corners = [
              { x: -hw - 4, y: -hh - 4 }, // TL
              { x: hw + 4, y: -hh - 4 },  // TR
              { x: -hw - 4, y: hh + 4 },  // BL
              { x: hw + 4, y: hh + 4 },   // BR
          ];

          corners.forEach(c => {
              ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
              ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
          });

          ctx.restore();
      }
  }

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  // --- Text Operations ---
  const handleAddText = () => {
      if (textObjects.length >= 3) {
          alert("テキストは最大3つまでです");
          return;
      }
      const newText: TextObject = {
          id: Date.now().toString(),
          text: "文字",
          x: targetWidth / 2,
          y: targetHeight / 2,
          fontSize: 40,
          fontFamily: 'M PLUS Rounded 1c',
          color: '#000000',
          isVertical: false,
          outlineColor: '#ffffff',
          outlineWidth: 4,
          zIndex: 'front',
          rotation: 0,
          curvature: 0
      };
      const newObjects = [...textObjects, newText];
      setTextObjects(newObjects);
      setSelectedTextId(newText.id);
      addToHistory({ textObjects: newObjects });
  };

  const handleUpdateText = (id: string, updates: Partial<TextObject>) => {
      const newObjects = textObjects.map(t => t.id === id ? { ...t, ...updates } : t);
      setTextObjects(newObjects);
  };

  const handleTextChangeComplete = () => {
      addToHistory({ textObjects });
  };

  const handleDeleteText = () => {
      if (!selectedTextId) return;
      const newObjects = textObjects.filter(t => t.id !== selectedTextId);
      setTextObjects(newObjects);
      setSelectedTextId(null);
      addToHistory({ textObjects: newObjects });
  };

  // --- Pointer/Touch Events ---

  const getClientCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
      if ('touches' in e) {
          return { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else {
          return { x: (e as React.MouseEvent).clientX, y: (e as React.MouseEvent).clientY };
      }
  };

  // Transform screen point to text local space to check collision
  const transformPointToTextSpace = (px: number, py: number, t: TextObject) => {
      // 1. Translate back from origin
      const dx = px - t.x;
      const dy = py - t.y;
      // 2. Rotate back
      const rad = -(t.rotation * Math.PI) / 180;
      const rx = dx * Math.cos(rad) - dy * Math.sin(rad);
      const ry = dx * Math.sin(rad) + dy * Math.cos(rad);
      return { x: rx, y: ry };
  }

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchstart') e.preventDefault();

    // Pinch Check (existing)
    if ('touches' in e && e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
        setPinchStartDist(dist);
        setPinchStartScale(scale);
        setPinchStartAngle(angle);
        setPinchStartRotation(rotation);
        setIsDragging(false);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;

    // --- Text Mode Logic ---
    if (mode === 'text') {
        const ctx = canvasRef.current?.getContext('2d');
        if (!ctx) return;

        // 1. Check Handles if text is selected
        if (selectedTextId) {
            const t = textObjects.find(obj => obj.id === selectedTextId);
            if (t) {
                const { x: localX, y: localY } = transformPointToTextSpace(x, y, t);
                const { w, h } = getTextBoundingBox(ctx, t);
                const hw = w/2;
                const hh = h/2;
                const handleRadius = 15; // Hit area

                // Check corners
                if (Math.hypot(localX - (-hw - 4), localY - (-hh - 4)) < handleRadius) {
                     setActiveTextHandle('tl'); setIsResizingText(true); setLastPos({x, y}); return;
                }
                if (Math.hypot(localX - (hw + 4), localY - (-hh - 4)) < handleRadius) {
                     setActiveTextHandle('tr'); setIsResizingText(true); setLastPos({x, y}); return;
                }
                if (Math.hypot(localX - (-hw - 4), localY - (hh + 4)) < handleRadius) {
                     setActiveTextHandle('bl'); setIsResizingText(true); setLastPos({x, y}); return;
                }
                if (Math.hypot(localX - (hw + 4), localY - (hh + 4)) < handleRadius) {
                     setActiveTextHandle('br'); setIsResizingText(true); setLastPos({x, y}); return;
                }
            }
        }

        // 2. Hit Test Text Body (Front-most first)
        let hitTextId = null;
        for (let i = textObjects.length - 1; i >= 0; i--) {
             const t = textObjects[i];
             const { x: localX, y: localY } = transformPointToTextSpace(x, y, t);
             const { w, h } = getTextBoundingBox(ctx, t);

             // Check if point is inside the centered box
             if (localX >= -w/2 - 10 && localX <= w/2 + 10 &&
                 localY >= -h/2 - 10 && localY <= h/2 + 10) {
                 hitTextId = t.id;
                 break;
             }
        }

        if (hitTextId) {
            setSelectedTextId(hitTextId);
            setIsDragging(true);
            setLastPos({ x, y });
        } else {
            // Clicked empty space in text mode
            // Don't deselect immediately to keep UI available, or deselect?
            // Usually tapping outside deselects
            // setSelectedTextId(null);
        }
        return; // Don't allow image dragging in text mode
    }

    // Move Mode Logic
    if (mode === 'move') {
       setIsDragging(true);
       setLastPos({ x, y });
    }

    // Other Modes
    if (mode === 'wand' || mode === 'restore' || mode === 'eraser') {
       addToHistory({});
       if (mode === 'wand') applyMagicWand(x, y);
       else if (mode === 'eraser') applyEraser(x, y);
       else if (mode === 'restore') applyRestore(x, y);
       setIsDragging(true);
       setLastPos({ x, y });
    }
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchmove') e.preventDefault();

    // Pinch Logic
    if ('touches' in e && e.touches.length === 2 && pinchStartDist !== null) {
        // ... (Keep existing pinch logic)
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const scaleFactor = dist / pinchStartDist;
        const newScale = Math.max(0.01, pinchStartScale * scaleFactor);
        if (pinchStartAngle !== null) {
            const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
            const deltaAngle = angle - pinchStartAngle;
            setRotation(pinchStartRotation + deltaAngle);
        }
        setScale(newScale);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    setCursorPos({ x, y });

    // Text Resizing
    if (isResizingText && selectedTextId) {
        const t = textObjects.find(t => t.id === selectedTextId);
        if (t) {
            // Calculate distance from text center to current mouse
            const dist = Math.hypot(x - t.x, y - t.y);
            // Rough scaling: Base distance is roughly current fontSize * chars
            // Simplified: Just map distance to fontSize with some factor
            // Or better: Relative change
            const prevDist = Math.hypot(lastPos.x - t.x, lastPos.y - t.y);
            const scale = dist / prevDist;
            const newSize = Math.min(150, Math.max(10, t.fontSize * scale));
            handleUpdateText(selectedTextId, { fontSize: newSize });
        }
        setLastPos({ x, y });
        return;
    }

    if (!isDragging) return;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'text' && selectedTextId) {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      handleUpdateText(selectedTextId, { 
          x: textObjects.find(t => t.id === selectedTextId)!.x + dx,
          y: textObjects.find(t => t.id === selectedTextId)!.y + dy
      });
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    } else if (mode === 'restore') {
      applyRestore(x, y);
    }
    setLastPos({ x, y });
  };

  const handlePointerUp = () => {
    setIsDragging(false);
    setIsResizing(false);
    setIsResizingText(false);
    setActiveHandle(null);
    setActiveTextHandle(null);
    setPinchStartDist(null);
    setPinchStartAngle(null);
    if (mode === 'text' && selectedTextId) {
        handleTextChangeComplete();
    }
    if (mode === 'move') {
        addToHistory({});
    }
  };

  const handlePointerLeave = () => {
      setCursorPos(null);
      handlePointerUp();
  };

  // Maps Canvas Coordinates -> Source Image Coordinates
  const getSourceCoords = (canvasX: number, canvasY: number) => {
    const cx = targetWidth / 2 + offset.x;
    const cy = targetHeight / 2 + offset.y;
    const dx = canvasX - cx;
    const dy = canvasY - cy;
    const angle = -(rotation * Math.PI) / 180;
    const rx = dx * Math.cos(angle) - dy * Math.sin(angle);
    const ry = dx * Math.sin(angle) + dy * Math.cos(angle);
    const sx = rx / scale;
    const sy = ry / scale;
    const sourceX = Math.floor(sx + stamp.width / 2);
    const sourceY = Math.floor(sy + stamp.height / 2);
    return { sourceX, sourceY };
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;
     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);
       const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
       const sourceEraserSize = eraserSize / scale;
       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();
       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const applyRestore = (canvasX: number, canvasY: number) => {
    if (!originalImage) return;
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d');
    if (!ctx) return;
    const img = new Image();
    img.onload = () => {
        ctx.drawImage(img, 0, 0);
        const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
        const sourceBrushSize = eraserSize / scale;
        const radius = sourceBrushSize / 2;
        ctx.save();
        ctx.beginPath();
        ctx.arc(sourceX, sourceY, radius, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(originalImage, 0, 0);
        ctx.restore();
        setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const applyMagicWand = (canvasX: number, canvasY: number) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
    if(!ctx) return;
    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);
      const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
      if (sourceX < 0 || sourceX >= stamp.width || sourceY < 0 || sourceY >= stamp.height) return;
      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;
      const targetIdx = (sourceY * width + sourceX) * 4;
      const tR = data[targetIdx];
      const tG = data[targetIdx + 1];
      const tB = data[targetIdx + 2];
      const tA = data[targetIdx + 3];
      if (tA === 0) return;
      const diffThreshold = tolerance * 3;
      const stack = [[sourceX, sourceY]];
      const visited = new Uint8Array(width * height);
      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= width || y < 0 || y >= height) continue;
        if (visited[y * width + x]) continue;
        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];
        if (a === 0) continue; 
        const diff = Math.abs(r - tR) + Math.abs(g - tG) + Math.abs(b - tB);
        if (diff < diffThreshold) {
           data[idx + 3] = 0; 
           visited[y * width + x] = 1;
           stack.push([x + 1, y]);
           stack.push([x - 1, y]);
           stack.push([x, y + 1]);
           stack.push([x, y - 1]);
        }
      }
      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const handleToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      addToHistory({ tolerance: Number(e.target.value) });
      const newTolerance = Number(e.target.value);
      setTolerance(newTolerance);
      if (!originalImage) return;
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = stamp.width;
      tempCanvas.height = stamp.height;
      const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;
      ctx.drawImage(originalImage, 0, 0);
      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const w = stamp.width;
      const h = stamp.height;
      const bgR = data[0];
      const bgG = data[1];
      const bgB = data[2];
      const limit = newTolerance * 3;
      const stack: [number, number][] = [];
      const visited = new Uint8Array(w * h);
      stack.push([0, 0]);
      stack.push([w-1, 0]);
      stack.push([0, h-1]);
      stack.push([w-1, h-1]);
      while(stack.length > 0) {
          const [x, y] = stack.pop()!;
          if (x < 0 || x >= w || y < 0 || y >= h) continue;
          const idx = y * w + x;
          if (visited[idx]) continue;
          const pIdx = idx * 4;
          const r = data[pIdx];
          const g = data[pIdx+1];
          const b = data[pIdx+2];
          const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
          if (diff < limit) {
              data[pIdx+3] = 0;
              visited[idx] = 1;
              stack.push([x+1, y]);
              stack.push([x-1, y]);
              stack.push([x, y+1]);
              stack.push([x, y-1]);
          }
      }
      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
  };

  const handleSave = () => {
    onSave({
      ...stamp,
      scale,
      rotation,
      offsetX: offset.x,
      offsetY: offset.y,
      dataUrl: workingDataUrl,
      currentTolerance: tolerance,
      textObjects: textObjects
    });
    onClose();
  };

  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' }, 
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#ff00ff', label: 'マゼンタ', color: 'bg-[#ff00ff]' },
    { value: '#60a5fa', label: '青', color: 'bg-[#60a5fa]' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#16a34a', label: '緑', color: 'bg-[#16a34a]' },
    { value: '#f97316', label: 'オレンジ', color: 'bg-[#f97316]' },
  ];

  const fontOptions = [
      { value: 'M PLUS Rounded 1c', label: '丸ゴシック' },
      { value: 'Noto Sans JP', label: 'ゴシック' },
      { value: 'Noto Serif JP', label: '明朝' },
  ];

  const textColorOptions = ['#000000', '#FFFFFF', '#ef4444', '#3b82f6', '#10b981', '#f97316', '#ec4899', '#4b3621'];

  const selectedText = textObjects.find(t => t.id === selectedTextId);

  // Common Slider Component with +/- buttons
  const ControlSlider = ({ label, value, min, max, onChange, onCommit, unit = '' }: any) => (
      <div className="flex items-center gap-2 w-full">
          <span className="text-xs text-gray-500 w-12 shrink-0">{label}</span>
          <button 
            onClick={() => {
                const newVal = Math.max(min, value - 1);
                onChange(newVal);
                if(onCommit) onCommit();
            }}
            className="w-6 h-6 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600"
          ><Minus size={12}/></button>
          <input 
            type="range" 
            min={min} 
            max={max} 
            value={value} 
            onChange={(e) => onChange(Number(e.target.value))}
            onMouseUp={onCommit}
            onTouchEnd={onCommit}
            className="flex-1 accent-primary-500 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer"
          />
          <button 
            onClick={() => {
                const newVal = Math.min(max, value + 1);
                onChange(newVal);
                if(onCommit) onCommit();
            }}
            className="w-6 h-6 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600"
          ><Plus size={12}/></button>
          {unit && <span className="text-xs text-gray-400 w-6 text-right">{value}{unit}</span>}
      </div>
  );

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col max-h-[95vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
          <h3 className="font-bold text-gray-700">スタンプ編集 ({targetWidth}x{targetHeight})</h3>
          <div className="flex items-center gap-2">
               <div className="flex items-center gap-1 bg-white p-1 rounded-lg border border-gray-200 mr-2 md:mr-4">
                    <span className="hidden md:inline text-xs text-gray-400 font-bold px-1">背景色</span>
                    {backgroundOptions.map(opt => (
                        <button
                            key={opt.value}
                            onClick={() => setPreviewBg(opt.value)}
                            className={`w-5 h-5 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                            title={opt.label}
                            style={opt.value === 'checker' ? {
                                backgroundImage: `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')`
                            } : {}}
                        />
                    ))}
                </div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
          </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col">
            {/* Toolbar Top */}
            <div className="p-2 bg-gray-50 border-b flex flex-wrap justify-center gap-2 md:gap-4 items-center">
                 {/* View Zoom Control */}
                 <div className="flex items-center gap-1 md:gap-2 bg-white px-2 py-1 rounded shadow-sm">
                    <span className="text-xs text-gray-500 hidden sm:inline">表示倍率:</span>
                    <button onClick={() => setViewZoom(z => Math.max(0.5, z - 0.25))} className="p-1 hover:bg-gray-100 rounded"><ZoomOut size={16}/></button>
                    <span className="text-sm font-mono w-10 text-center">{(viewZoom * 100).toFixed(0)}%</span>
                    <button onClick={() => setViewZoom(z => Math.min(3, z + 0.25))} className="p-1 hover:bg-gray-100 rounded"><ZoomIn size={16}/></button>
                 </div>

                 <div className="flex items-center gap-1">
                     <button onClick={undo} disabled={historyIndex <= 0} className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"><Undo size={18} /></button>
                     <button onClick={redo} disabled={historyIndex >= history.length - 1} className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"><Redo size={18} /></button>
                 </div>

                 {onReCrop && (
                    <button onClick={onReCrop} className="flex items-center gap-1 text-xs bg-white text-gray-700 px-3 py-1.5 rounded shadow-sm hover:bg-gray-100 border border-gray-200">
                        <RotateCw size={14} /> <span className="hidden sm:inline">再切り出し</span>
                    </button>
                 )}
            </div>

            {/* Scrollable Canvas Area */}
            <div className="flex-1 overflow-auto bg-gray-100 flex p-8">
                <div 
                    className="relative shadow-md border border-gray-200 bg-white m-auto" 
                    style={{ 
                        width: targetWidth * viewZoom, 
                        height: targetHeight * viewZoom,
                        flexShrink: 0 // Prevent shrinking
                    }}
                >
                    <canvas 
                    ref={canvasRef}
                    width={targetWidth}
                    height={targetHeight}
                    className={`origin-top-left ${mode === 'move' ? 'cursor-move' : (mode === 'text' ? 'cursor-text' : 'cursor-crosshair')} touch-none`}
                    style={{
                        transform: `scale(${viewZoom})`,
                        width: targetWidth,
                        height: targetHeight
                    }}
                    onMouseDown={handlePointerDown}
                    onMouseMove={handlePointerMove}
                    onMouseUp={handlePointerUp}
                    onMouseLeave={handlePointerLeave}
                    onTouchStart={handlePointerDown}
                    onTouchMove={handlePointerMove}
                    onTouchEnd={handlePointerUp}
                    />
                </div>
            </div>
        </div>

        {/* Footer Tools */}
        <div className="p-4 border-t bg-white rounded-b-xl shrink-0 flex flex-col gap-4 max-h-[50vh] overflow-y-auto">

             {/* Text Edit Panel */}
             {mode === 'text' && selectedText && (
                 <div className="bg-blue-50 p-3 rounded-lg border border-blue-100 flex flex-col gap-3 animate-fade-in">
                     <div className="flex items-center gap-2">
                         <input 
                            type="text" 
                            value={selectedText.text}
                            onChange={(e) => handleUpdateText(selectedText.id, { text: e.target.value })}
                            className="flex-1 border-gray-300 rounded text-sm px-2 py-1"
                            placeholder="テキストを入力"
                         />
                         <button onClick={handleDeleteText} className="text-red-500 p-1 hover:bg-red-100 rounded">
                             <Trash2 size={18} />
                         </button>
                     </div>
                     <div className="flex flex-wrap items-center gap-4">
                         <select 
                            value={selectedText.fontFamily}
                            onChange={(e) => handleUpdateText(selectedText.id, { fontFamily: e.target.value })}
                            className="text-xs border-gray-300 rounded"
                         >
                             {fontOptions.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
                         </select>

                         <button 
                            onClick={() => handleUpdateText(selectedText.id, { isVertical: !selectedText.isVertical })}
                            className={`flex items-center gap-1 text-xs px-2 py-1 rounded border ${selectedText.isVertical ? 'bg-blue-200 border-blue-300' : 'bg-white border-gray-300'}`}
                         >
                             {selectedText.isVertical ? <AlignVerticalJustifyCenter size={14}/> : <AlignHorizontalJustifyCenter size={14}/>}
                             {selectedText.isVertical ? '縦' : '横'}
                         </button>

                         <button 
                            onClick={() => handleUpdateText(selectedText.id, { zIndex: selectedText.zIndex === 'back' ? 'front' : 'back' })}
                            className={`flex items-center gap-1 text-xs px-2 py-1 rounded border ${selectedText.zIndex === 'back' ? 'bg-blue-200 border-blue-300' : 'bg-white border-gray-300'}`}
                         >
                             <Layers size={14}/>
                             {selectedText.zIndex === 'back' ? '背面' : '前面'}
                         </button>

                         {/* Colors */}
                         <div className="flex items-center gap-2">
                             <span className="text-xs text-gray-500">色</span>
                             <div className="flex gap-1 items-center">
                                 {textColorOptions.map(c => (
                                     <button
                                        key={c}
                                        onClick={() => handleUpdateText(selectedText.id, { color: c })}
                                        className={`w-5 h-5 rounded-full border border-gray-300 ${selectedText.color === c ? 'ring-2 ring-blue-500' : ''}`}
                                        style={{ backgroundColor: c }}
                                     />
                                 ))}
                                 <label className="w-5 h-5 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.color}
                                        onChange={(e) => handleUpdateText(selectedText.id, { color: e.target.value })}
                                     />
                                 </label>
                             </div>
                         </div>
                     </div>

                     <div className="flex flex-col gap-2 pt-2 border-t border-blue-200/50">
                          {/* Text Size & Rotation */}
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                              <ControlSlider 
                                label="サイズ" 
                                value={selectedText.fontSize} 
                                min={10} max={150} 
                                onChange={(val: number) => handleUpdateText(selectedText.id, { fontSize: val })}
                                onCommit={handleTextChangeComplete}
                              />
                              <ControlSlider 
                                label="回転" 
                                value={selectedText.rotation} 
                                min={-180} max={180} 
                                onChange={(val: number) => handleUpdateText(selectedText.id, { rotation: val })}
                                onCommit={handleTextChangeComplete}
                                unit="°"
                              />
                          </div>

                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                               <ControlSlider 
                                label="カーブ" 
                                value={selectedText.curvature} 
                                min={-100} max={100} 
                                onChange={(val: number) => handleUpdateText(selectedText.id, { curvature: val })}
                                onCommit={handleTextChangeComplete}
                              />

                              {/* Outline Settings */}
                              <div className="flex items-center gap-2 w-full">
                                    <span className="text-xs text-gray-500 w-12 shrink-0">縁取り</span>
                                    <ControlSlider 
                                        label="" 
                                        value={selectedText.outlineWidth} 
                                        min={0} max={30} 
                                        onChange={(val: number) => handleUpdateText(selectedText.id, { outlineWidth: val })}
                                        onCommit={handleTextChangeComplete}
                                    />
                                    <label className="w-5 h-5 shrink-0 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500 ml-1">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.outlineColor}
                                        onChange={(e) => handleUpdateText(selectedText.id, { outlineColor: e.target.value })}
                                     />
                                    </label>
                              </div>
                          </div>
                     </div>
                 </div>
             )}

             {/* Move Mode Image Controls */}
             {mode === 'move' && (
                 <div className="bg-gray-50 p-3 rounded-lg border border-gray-200 flex flex-col gap-2">
                     <span className="text-xs font-bold text-gray-500 mb-1">画像操作</span>
                     <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <ControlSlider 
                            label="サイズ" 
                            value={Number(scale.toFixed(2))} 
                            min={0.1} max={3.0} 
                            onChange={(val: number) => setScale(val)}
                            onCommit={() => addToHistory({ scale })}
                        />
                        <ControlSlider 
                            label="回転" 
                            value={rotation} 
                            min={-180} max={180} 
                            onChange={(val: number) => setRotation(val)}
                            onCommit={() => addToHistory({ rotation })}
                            unit="°"
                        />
                     </div>
                 </div>
             )}

             {/* Tolerance Slider (Visible only in Wand/Eraser modes) */}
             {(mode === 'wand' || mode === 'eraser') && originalImage && (
                <div className="flex items-center gap-4 bg-yellow-50 p-3 rounded-lg border border-yellow-100">
                    <div className="flex items-center gap-2 text-yellow-700 font-bold text-sm min-w-[120px]">
                        <Sliders size={16} />
                        背景除去
                    </div>
                    <input 
                        type="range" 
                        min="1" 
                        max="100" 
                        value={tolerance} 
                        onChange={handleToleranceChange}
                        className="w-full accent-yellow-500"
                    />
                </div>
             )}

             <div className="flex flex-wrap gap-4 justify-center items-center">
                 {/* Mode Selection */}
                 <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg overflow-x-auto max-w-full">
                    <button 
                    onClick={() => setMode('move')} 
                    className={`p-2 rounded ${mode === 'move' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="画像移動"
                    >
                    <Move size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('text')} 
                    className={`p-2 rounded ${mode === 'text' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="文字入れ"
                    >
                    <Type size={20} />
                    </button>
                    <div className="w-px h-6 bg-gray-300 mx-1"></div>
                    <button 
                    onClick={() => setMode('wand')} 
                    className={`p-2 rounded ${mode === 'wand' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="追加透過"
                    >
                    <Wand2 size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('eraser')} 
                    className={`p-2 rounded ${mode === 'eraser' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="消しゴム"
                    >
                    <Eraser size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('restore')} 
                    disabled={!originalImage}
                    className={`p-2 rounded ${mode === 'restore' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'} disabled:opacity-30`}
                    title="復元"
                    >
                    <Pencil size={20} />
                    </button>

                    {/* Integrated Size Slider */}
                    {(mode === 'eraser' || mode === 'restore') && (
                        <>
                            <div className="w-px h-6 bg-gray-300 mx-1"></div>
                            <input 
                            type="range" 
                            min="5" 
                            max="50" 
                            value={eraserSize} 
                            onChange={(e) => setEraserSize(Number(e.target.value))} 
                            className="w-20 accent-primary-500"
                            />
                        </>
                    )}
                 </div>

                 {/* Text Add Button (only in text mode) */}
                 {mode === 'text' && (
                     <button 
                        onClick={handleAddText}
                        className="bg-blue-600 text-white px-3 py-2 rounded-lg shadow font-bold text-sm flex items-center gap-1 hover:bg-blue-700"
                     >
                         <Plus size={16} /> 文字追加
                     </button>
                 )}

                <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                    <button 
                        onClick={() => {
                            addToHistory({});
                            setScale(initialScale ?? stamp.scale);
                            setRotation(initialRotation ?? stamp.rotation ?? 0);
                            setOffset(initialOffset ?? {x:0, y:0});
                            setTolerance(stamp.currentTolerance || 50);
                            setWorkingDataUrl(stamp.dataUrl); 
                            setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
                        }}
                        className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                    >
                        <RotateCcw size={14} /> <span className="hidden sm:inline">リセット</span>
                    </button>
                </div>
             </div>

             <div className="flex justify-end gap-3 pt-2 border-t border-dashed">
                <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
                <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
                    <Check size={18} /> 完了
                </button>
             </div>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TextObject, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2, Palette, Pencil, Sliders, RotateCw, Undo, Redo, Type, Trash2, AlignVerticalJustifyCenter, AlignHorizontalJustifyCenter, Plus, Layers, MousePointer2, Minus } from 'lucide-react';
import { drawTextOnCanvas } from '../lib/zipService';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  onReCrop?: () => void; 
  initialPreviewBg?: string; 
  targetWidth?: number;
  targetHeight?: number;
  initialScale?: number;
  initialRotation?: number;
  initialOffset?: { x: number, y: number };
  initialTextObjects?: TextObject[]; 
}

interface HistoryState {
    scale: number;
    rotation: number;
    offset: { x: number, y: number };
    dataUrl: string;
    tolerance: number;
    textObjects: TextObject[];
}

export const StampEditorModal: React.FC<Props> = ({ 
  stamp, 
  isOpen, 
  onClose, 
  onSave, 
  onReCrop,
  initialPreviewBg = 'checker',
  targetWidth = TARGET_WIDTH,
  targetHeight = TARGET_HEIGHT,
  initialScale,
  initialRotation,
  initialOffset,
  initialTextObjects
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Image State
  const [scale, setScale] = useState(initialScale ?? stamp.scale);
  const [rotation, setRotation] = useState(initialRotation ?? stamp.rotation ?? 0);
  const [offset, setOffset] = useState(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });

  // Text State
  const [textObjects, setTextObjects] = useState<TextObject[]>(initialTextObjects ?? stamp.textObjects ?? []);
  const [selectedTextId, setSelectedTextId] = useState<string | null>(null);

  // History State
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Editor View state
  const [viewZoom, setViewZoom] = useState(1);
  const [previewBg, setPreviewBg] = useState(initialPreviewBg);

  const [mode, setMode] = useState<'move' | 'eraser' | 'wand' | 'restore' | 'text'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [isResizingText, setIsResizingText] = useState(false);

  // Cursor visual state
  const [cursorPos, setCursorPos] = useState<{x: number, y: number} | null>(null);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  const [activeTextHandle, setActiveTextHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  // Pinch & Resize State
  const [pinchStartDist, setPinchStartDist] = useState<number | null>(null);
  const [pinchStartScale, setPinchStartScale] = useState<number>(1);
  const [pinchStartAngle, setPinchStartAngle] = useState<number | null>(null);
  const [pinchStartRotation, setPinchStartRotation] = useState<number>(0);

  // Image Resizing State
  const [isResizingImage, setIsResizingImage] = useState(false);
  const [activeImageHandle, setActiveImageHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  const [tolerance, setTolerance] = useState(stamp.currentTolerance || 50);

  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);
  const [originalImage, setOriginalImage] = useState<HTMLImageElement | null>(null);

  // Interval ref for continuous button press
  const buttonIntervalRef = useRef<number | null>(null);
  const zoomIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    if (isOpen) {
      setScale(initialScale ?? stamp.scale);
      setRotation(initialRotation ?? stamp.rotation ?? 0);
      setOffset(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
      setTolerance(stamp.currentTolerance || 50);
      setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
      setSelectedTextId(null);

      const initialState = {
          scale: initialScale ?? stamp.scale,
          rotation: initialRotation ?? stamp.rotation ?? 0,
          offset: initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY },
          dataUrl: stamp.dataUrl,
          tolerance: stamp.currentTolerance || 50,
          textObjects: initialTextObjects ?? stamp.textObjects ?? []
      };
      setHistory([initialState]);
      setHistoryIndex(0);

      if (stamp.originalDataUrl) {
          const img = new Image();
          img.src = stamp.originalDataUrl;
          img.onload = () => setOriginalImage(img);
      } else {
          setOriginalImage(null);
      }
    }
  }, [isOpen, stamp, initialScale, initialRotation, initialOffset, initialTextObjects]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, rotation, offset, workingDataUrl, previewBg, targetWidth, targetHeight, cursorPos, mode, eraserSize, textObjects, selectedTextId]); 

  const addToHistory = (newState: Partial<HistoryState>) => {
      const currentState = {
          scale,
          rotation,
          offset,
          dataUrl: workingDataUrl,
          tolerance,
          textObjects,
          ...newState
      };

      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(currentState);
      if (newHistory.length > 20) newHistory.shift();
      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);
  };

  const undo = () => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setScale(prevState.scale);
          setRotation(prevState.rotation);
          setOffset(prevState.offset);
          setWorkingDataUrl(prevState.dataUrl);
          setTolerance(prevState.tolerance);
          setTextObjects(prevState.textObjects);
          setHistoryIndex(prevIndex);
      }
  };

  const redo = () => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setScale(nextState.scale);
          setRotation(nextState.rotation);
          setOffset(nextState.offset);
          setWorkingDataUrl(nextState.dataUrl);
          setTolerance(nextState.tolerance);
          setTextObjects(nextState.textObjects);
          setHistoryIndex(nextIndex);
      }
  };

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const cx = canvas.width / 2 + offset.x;
        const cy = canvas.height / 2 + offset.y;

        // 1. Draw Back Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex === 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // 2. Draw Image
        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);

        // Draw Image Handles (Only in Move Mode)
        if (mode === 'move') {
            // Un-rotate to draw handles aligned with image, or draw them rotated?
            // Usually handles rotate with the image.
            const hw = drawnW / 2;
            const hh = drawnH / 2;
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
            ctx.strokeRect(-hw, -hh, drawnW, drawnH);

            const handleSize = 12; // Visual size
            ctx.fillStyle = '#ffffff';
            // Corners
            const corners = [
                { x: -hw, y: -hh }, { x: hw, y: -hh },
                { x: -hw, y: hh }, { x: hw, y: hh }
            ];
            corners.forEach(c => {
                ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
                ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
            });
        }
        ctx.restore();

        // 3. Draw Front Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex !== 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // Border
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);

        // Draw Eraser/Wand Cursor
        if ((mode === 'eraser' || mode === 'restore') && cursorPos) {
            ctx.beginPath();
            ctx.arc(cursorPos.x, cursorPos.y, eraserSize / 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
        }
    };
    img.src = workingDataUrl;
  };

  const getTextBoundingBox = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      ctx.font = `bold ${textObj.fontSize}px '${textObj.fontFamily}'`;
      const lines = textObj.text.split('\n');
      const lineHeight = textObj.fontSize * 1.2;

      let w = 0;
      let h = 0;

      if (textObj.isVertical) {
          w = lineHeight * lines.length;
          const maxChars = Math.max(...lines.map(l => l.length));
          h = textObj.fontSize * maxChars;
      } else {
          const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
          w = maxW;
          h = lineHeight * lines.length;
      }
      // Add padding for better selection
      return { w: w + 10, h: h + 10 };
  };

  const drawTextWithSelection = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      drawTextOnCanvas(ctx, textObj);

      if (mode === 'text' && selectedTextId === textObj.id) {
          ctx.save();
          ctx.translate(textObj.x, textObj.y);
          ctx.rotate((textObj.rotation * Math.PI) / 180);

          const { w, h } = getTextBoundingBox(ctx, textObj);
          const hw = w / 2;
          const hh = h / 2;

          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 1.5;
          ctx.setLineDash([4, 4]);
          ctx.strokeRect(-hw, -hh, w, h);

          ctx.setLineDash([]);
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#3b82f6';
          const handleSize = 10;

          const corners = [
              { x: -hw, y: -hh }, { x: hw, y: -hh },
              { x: -hw, y: hh }, { x: hw, y: hh },
          ];

          corners.forEach(c => {
              ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
              ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
          });

          ctx.restore();
      }
  }

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  // --- Logic Helpers ---
  const handleUpdateText = (id: string, updates: Partial<TextObject>) => {
      const newObjects = textObjects.map(t => t.id === id ? { ...t, ...updates } : t);
      setTextObjects(newObjects);
  };

  const handleTextChangeComplete = () => {
      addToHistory({ textObjects });
  };

  const handleAddText = () => {
      if (textObjects.length >= 3) {
          alert("テキストは最大3つまでです");
          return;
      }
      const newText: TextObject = {
          id: Date.now().toString(),
          text: "文字",
          x: targetWidth / 2,
          y: targetHeight / 2,
          fontSize: 40,
          fontFamily: 'M PLUS Rounded 1c',
          color: '#000000',
          isVertical: false,
          outlineColor: '#ffffff',
          outlineWidth: 4,
          zIndex: 'front',
          rotation: 0,
          curvature: 0
      };
      const newObjects = [...textObjects, newText];
      setTextObjects(newObjects);
      setSelectedTextId(newText.id);
      addToHistory({ textObjects: newObjects });
      setMode('text'); // Switch to text mode automatically
  };

  const handleDeleteText = () => {
      if (!selectedTextId) return;
      const newObjects = textObjects.filter(t => t.id !== selectedTextId);
      setTextObjects(newObjects);
      setSelectedTextId(null);
      addToHistory({ textObjects: newObjects });
  };

  // --- Pointer/Touch Events ---

  const getClientCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
      if ('touches' in e) {
          return { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else {
          return { x: (e as React.MouseEvent).clientX, y: (e as React.MouseEvent).clientY };
      }
  };

  // Generic Transform: Screen -> Object Local Space
  const transformToLocal = (px: number, py: number, cx: number, cy: number, rot: number) => {
      const dx = px - cx;
      const dy = py - cy;
      const rad = -(rot * Math.PI) / 180;
      const rx = dx * Math.cos(rad) - dy * Math.sin(rad);
      const ry = dx * Math.sin(rad) + dy * Math.cos(rad);
      return { x: rx, y: ry };
  }

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchstart') e.preventDefault();

    // Pinch Check
    if ('touches' in e && e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
        setPinchStartDist(dist);
        setPinchStartScale(scale);
        setPinchStartAngle(angle);
        setPinchStartRotation(rotation);
        setIsDragging(false);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;

    // --- 1. Text Interaction (Priority) ---
    // If in text mode, check text handles then text body
    if (mode === 'text') {
        if (selectedTextId) {
            const t = textObjects.find(obj => obj.id === selectedTextId);
            if (t) {
                const { x: localX, y: localY } = transformToLocal(x, y, t.x, t.y, t.rotation);
                const { w, h } = getTextBoundingBox(ctx, t);
                const hw = w/2; const hh = h/2;
                const handleRadius = 20; // Hit area

                // Check corners
                if (Math.hypot(localX - (-hw), localY - (-hh)) < handleRadius) { setActiveTextHandle('tl'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (hw), localY - (-hh)) < handleRadius) { setActiveTextHandle('tr'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (-hw), localY - (hh)) < handleRadius) { setActiveTextHandle('bl'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (hw), localY - (hh)) < handleRadius) { setActiveTextHandle('br'); setIsResizingText(true); setLastPos({x, y}); return; }
            }
        }

        // Hit Test Text Body (Front-most first)
        for (let i = textObjects.length - 1; i >= 0; i--) {
             const t = textObjects[i];
             const { x: localX, y: localY } = transformToLocal(x, y, t.x, t.y, t.rotation);
             const { w, h } = getTextBoundingBox(ctx, t);
             if (localX >= -w/2 && localX <= w/2 && localY >= -h/2 && localY <= h/2) {
                 setSelectedTextId(t.id);
                 setIsDragging(true);
                 setLastPos({ x, y });
                 return;
             }
        }

        // If clicked empty space in text mode, do nothing (don't move image)
        // Optionally deselect text
        // setSelectedTextId(null); 
        return; 
    }

    // --- 2. Image Interaction (Move Mode) ---
    if (mode === 'move') {
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;
        const { x: localX, y: localY } = transformToLocal(x, y, cx, cy, rotation);
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const hw = drawnW / 2;
        const hh = drawnH / 2;
        const handleRadius = 25; // Hit area

        // Check Image Handles
        if (Math.hypot(localX - (-hw), localY - (-hh)) < handleRadius) { setActiveImageHandle('tl'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (hw), localY - (-hh)) < handleRadius) { setActiveImageHandle('tr'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (-hw), localY - (hh)) < handleRadius) { setActiveImageHandle('bl'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (hw), localY - (hh)) < handleRadius) { setActiveImageHandle('br'); setIsResizingImage(true); setLastPos({x, y}); return; }

        // Clicked Image Body
        setIsDragging(true);
        setLastPos({ x, y });
        return;
    }

    // --- 3. Tool Modes ---
    if (mode === 'wand' || mode === 'restore' || mode === 'eraser') {
       addToHistory({});
       if (mode === 'wand') applyMagicWand(x, y);
       else if (mode === 'eraser') applyEraser(x, y);
       else if (mode === 'restore') applyRestore(x, y);
       setIsDragging(true);
       setLastPos({ x, y });
    }
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchmove') e.preventDefault();

    // Pinch Logic
    if ('touches' in e && e.touches.length === 2 && pinchStartDist !== null) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const scaleFactor = dist / pinchStartDist;
        const newScale = Math.max(0.01, pinchStartScale * scaleFactor);

        // Optional: Rotation via pinch
        /*
        if (pinchStartAngle !== null) {
            const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
            const deltaAngle = angle - pinchStartAngle;
            setRotation(pinchStartRotation + deltaAngle);
        }
        */
        setScale(newScale);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    setCursorPos({ x, y });

    // Text Resizing
    if (isResizingText && selectedTextId) {
        const t = textObjects.find(t => t.id === selectedTextId);
        if (t) {
            const dist = Math.hypot(x - t.x, y - t.y);
            const prevDist = Math.hypot(lastPos.x - t.x, lastPos.y - t.y);
            const scaleFactor = dist / prevDist;
            // Simple proportional scaling
            const newSize = Math.min(200, Math.max(10, t.fontSize * scaleFactor));
            handleUpdateText(selectedTextId, { fontSize: newSize });
        }
        setLastPos({ x, y });
        return;
    }

    // Image Resizing (Handles)
    if (isResizingImage) {
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;
        const dist = Math.hypot(x - cx, y - cy);
        const prevDist = Math.hypot(lastPos.x - cx, lastPos.y - cy);
        const scaleFactor = dist / prevDist;
        const newScale = Math.min(3.0, Math.max(0.01, scale * scaleFactor));
        setScale(newScale);
        setLastPos({ x, y });
        return;
    }

    if (!isDragging) return;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'text' && selectedTextId) {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      handleUpdateText(selectedTextId, { 
          x: textObjects.find(t => t.id === selectedTextId)!.x + dx,
          y: textObjects.find(t => t.id === selectedTextId)!.y + dy
      });
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    } else if (mode === 'restore') {
      applyRestore(x, y);
    }
    setLastPos({ x, y });
  };

  const handlePointerUp = () => {
    if (isDragging && mode === 'move') addToHistory({});
    if (isResizingImage) addToHistory({ scale });
    if (isResizingText && selectedTextId) handleTextChangeComplete();

    setIsDragging(false);
    setIsResizingText(false);
    setIsResizingImage(false);
    setActiveTextHandle(null);
    setActiveImageHandle(null);
    setPinchStartDist(null);
    setPinchStartAngle(null);
  };

  const handlePointerLeave = () => {
      setCursorPos(null);
      handlePointerUp();
  };

  // --- Logic for Eraser/Wand ---
  const getSourceCoords = (canvasX: number, canvasY: number) => {
    const cx = targetWidth / 2 + offset.x;
    const cy = targetHeight / 2 + offset.y;
    const dx = canvasX - cx;
    const dy = canvasY - cy;
    const angle = -(rotation * Math.PI) / 180;
    const rx = dx * Math.cos(angle) - dy * Math.sin(angle);
    const ry = dx * Math.sin(angle) + dy * Math.cos(angle);
    const sx = rx / scale;
    const sy = ry / scale;
    const sourceX = Math.floor(sx + stamp.width / 2);
    const sourceY = Math.floor(sy + stamp.height / 2);
    return { sourceX, sourceY };
  };

  const applyEraser = (canvasX: number, canvasY: number) => {
     const tempCanvas = document.createElement('canvas');
     tempCanvas.width = stamp.width;
     tempCanvas.height = stamp.height;
     const ctx = tempCanvas.getContext('2d');
     if(!ctx) return;
     const img = new Image();
     img.onload = () => {
       ctx.drawImage(img, 0, 0);
       const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
       const sourceEraserSize = eraserSize / scale;
       ctx.globalCompositeOperation = 'destination-out';
       ctx.beginPath();
       ctx.arc(sourceX, sourceY, sourceEraserSize / 2, 0, Math.PI * 2);
       ctx.fill();
       setWorkingDataUrl(tempCanvas.toDataURL());
     };
     img.src = workingDataUrl;
  };

  const applyRestore = (canvasX: number, canvasY: number) => {
    if (!originalImage) return;
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d');
    if (!ctx) return;
    const img = new Image();
    img.onload = () => {
        ctx.drawImage(img, 0, 0);
        const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
        const sourceBrushSize = eraserSize / scale;
        const radius = sourceBrushSize / 2;
        ctx.save();
        ctx.beginPath();
        ctx.arc(sourceX, sourceY, radius, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(originalImage, 0, 0);
        ctx.restore();
        setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const applyMagicWand = (canvasX: number, canvasY: number) => {
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = stamp.width;
    tempCanvas.height = stamp.height;
    const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
    if(!ctx) return;
    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);
      const { sourceX, sourceY } = getSourceCoords(canvasX, canvasY);
      if (sourceX < 0 || sourceX >= stamp.width || sourceY < 0 || sourceY >= stamp.height) return;
      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const width = imageData.width;
      const height = imageData.height;
      const targetIdx = (sourceY * width + sourceX) * 4;
      const tR = data[targetIdx];
      const tG = data[targetIdx + 1];
      const tB = data[targetIdx + 2];
      const tA = data[targetIdx + 3];
      if (tA === 0) return;
      const diffThreshold = tolerance * 3;
      const stack = [[sourceX, sourceY]];
      const visited = new Uint8Array(width * height);
      while (stack.length > 0) {
        const [x, y] = stack.pop()!;
        if (x < 0 || x >= width || y < 0 || y >= height) continue;
        if (visited[y * width + x]) continue;
        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];
        if (a === 0) continue; 
        const diff = Math.abs(r - tR) + Math.abs(g - tG) + Math.abs(b - tB);
        if (diff < diffThreshold) {
           data[idx + 3] = 0; 
           visited[y * width + x] = 1;
           stack.push([x + 1, y]);
           stack.push([x - 1, y]);
           stack.push([x, y + 1]);
           stack.push([x, y - 1]);
        }
      }
      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
    };
    img.src = workingDataUrl;
  };

  const handleToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      addToHistory({ tolerance: Number(e.target.value) });
      const newTolerance = Number(e.target.value);
      setTolerance(newTolerance);
      if (!originalImage) return;
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = stamp.width;
      tempCanvas.height = stamp.height;
      const ctx = tempCanvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;
      ctx.drawImage(originalImage, 0, 0);
      const imageData = ctx.getImageData(0, 0, stamp.width, stamp.height);
      const data = imageData.data;
      const w = stamp.width;
      const h = stamp.height;
      const bgR = data[0];
      const bgG = data[1];
      const bgB = data[2];
      const limit = newTolerance * 3;
      const stack: [number, number][] = [];
      const visited = new Uint8Array(w * h);
      stack.push([0, 0]);
      stack.push([w-1, 0]);
      stack.push([0, h-1]);
      stack.push([w-1, h-1]);
      while(stack.length > 0) {
          const [x, y] = stack.pop()!;
          if (x < 0 || x >= w || y < 0 || y >= h) continue;
          const idx = y * w + x;
          if (visited[idx]) continue;
          const pIdx = idx * 4;
          const r = data[pIdx];
          const g = data[pIdx+1];
          const b = data[pIdx+2];
          const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
          if (diff < limit) {
              data[pIdx+3] = 0;
              visited[idx] = 1;
              stack.push([x+1, y]);
              stack.push([x-1, y]);
              stack.push([x, y+1]);
              stack.push([x, y-1]);
          }
      }
      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(tempCanvas.toDataURL());
  };

  const handleSave = () => {
    onSave({
      ...stamp,
      scale,
      rotation,
      offsetX: offset.x,
      offsetY: offset.y,
      dataUrl: workingDataUrl,
      currentTolerance: tolerance,
      textObjects: textObjects
    });
    onClose();
  };

  // Zoom logic for Viewport
  const startZoom = (direction: 'in' | 'out') => {
      const step = 0.05;
      if (direction === 'in') setViewZoom(z => Math.min(3, z + step));
      else setViewZoom(z => Math.max(0.5, z - step));

      zoomIntervalRef.current = window.setInterval(() => {
         setViewZoom(z => {
             const ns = direction === 'in' ? z + step : Math.max(0.5, z - step);
             return ns;
         });
      }, 50);
  };
  const stopZoom = () => {
      if (zoomIntervalRef.current) {
          clearInterval(zoomIntervalRef.current);
          zoomIntervalRef.current = null;
      }
  };

  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' }, 
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#ff00ff', label: 'マゼンタ', color: 'bg-[#ff00ff]' },
    { value: '#60a5fa', label: '青', color: 'bg-[#60a5fa]' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#16a34a', label: '緑', color: 'bg-[#16a34a]' },
    { value: '#f97316', label: 'オレンジ', color: 'bg-[#f97316]' },
  ];

  const fontOptions = [
      { value: 'M PLUS Rounded 1c', label: '丸ゴシック' },
      { value: 'Noto Sans JP', label: 'ゴシック' },
      { value: 'Noto Serif JP', label: '明朝' },
  ];

  const textColorOptions = ['#000000', '#FFFFFF', '#ef4444', '#3b82f6', '#10b981', '#f97316', '#ec4899', '#4b3621'];

  const selectedText = textObjects.find(t => t.id === selectedTextId);

  // Improved Slider Component with Continuous Buttons
  const ControlSlider = ({ label, value, min, max, step = 1, onChange, onCommit, unit = '' }: any) => {
      const handleButtonDown = (direction: 1 | -1) => {
          const newValue = Math.min(max, Math.max(min, value + (step * direction)));
          onChange(newValue);

          // Delay before rapid fire
          setTimeout(() => {
              if (buttonIntervalRef.current) clearInterval(buttonIntervalRef.current);
              buttonIntervalRef.current = window.setInterval(() => {
                  onChange((prev: number) => {
                      const next = Math.min(max, Math.max(min, prev + (step * direction)));
                      return Number(next.toFixed(2));
                  });
              }, 50);
          }, 300);
      };

      const handleButtonUp = () => {
          if (buttonIntervalRef.current) {
              clearInterval(buttonIntervalRef.current);
              buttonIntervalRef.current = null;
          }
          if (onCommit) onCommit();
      };

      return (
        <div className="flex items-center gap-2 w-full">
            <span className="text-xs text-gray-500 w-12 shrink-0">{label}</span>
            <button 
                onMouseDown={() => handleButtonDown(-1)}
                onMouseUp={handleButtonUp}
                onMouseLeave={handleButtonUp}
                onTouchStart={() => handleButtonDown(-1)}
                onTouchEnd={handleButtonUp}
                className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600 active:bg-gray-300 touch-none"
            ><Minus size={14}/></button>
            <input 
                type="range" 
                min={min} 
                max={max} 
                step={step}
                value={value} 
                onChange={(e) => onChange(Number(e.target.value))}
                onMouseUp={onCommit}
