                              />

                              <div className="flex items-center gap-2 w-full">
                                    <span className="text-xs text-gray-500 w-12 shrink-0">縁取り</span>
                                    <ControlSlider 
                                        label="" 
                                        value={selectedText.outlineWidth} 
                                        min={0} max={30} step={1}
                                        onChange={(val: number) => handleUpdateText(selectedText.id, { outlineWidth: val })}
                                        onCommit={handleTextChangeComplete}
