                                    <label className="w-5 h-5 shrink-0 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500 ml-1">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.outlineColor}
                                        onChange={(e) => handleUpdateText(selectedText.id, { outlineColor: e.target.value })}
