                    title="消しゴム"
                    >
                    <Eraser size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('restore')} 
                    disabled={!originalImage}
                    className={`p-2 rounded ${mode === 'restore' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'} disabled:opacity-30`}
                    title="復元"
                    >
                    <Pencil size={20} />
                    </button>

                    {/* Integrated Size Slider for Brush */}
                    {(mode === 'eraser' || mode === 'restore') && (
                        <>
                            <div className="w-px h-6 bg-gray-300 mx-1"></div>
                            <input 
                            type="range" 
                            min="5" 
                            max="50" 
                            value={eraserSize} 
                            onChange={(e) => setEraserSize(Number(e.target.value))} 
                            className="w-20 accent-primary-500"
                            />
                        </>
                    )}
                 </div>

                 {/* Text Add Button */}
                 {mode === 'text' && (
                     <button 
                        onClick={handleAddText}
                        className="bg-blue-600 text-white px-3 py-2 rounded-lg shadow font-bold text-sm flex items-center gap-1 hover:bg-blue-700"
                     >
                         <Plus size={16} /> 文字追加
                     </button>
                 )}

                <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                    <button 
                        onClick={() => {
                            addToHistory({});
                            setScale(initialScale ?? stamp.scale);
                            setRotation(initialRotation ?? stamp.rotation ?? 0);
                            setOffset(initialOffset ?? {x:0, y:0});
                            setTolerance(stamp.currentTolerance || 50);
                            setWorkingDataUrl(stamp.dataUrl); 
                            setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
                        }}
                        className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                    >
                        <RotateCcw size={14} /> <span className="hidden sm:inline">リセット</span>
                    </button>
                </div>
             </div>

             <div className="flex justify-end gap-3 pt-2 border-t border-dashed">
                <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
                <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
                    <Check size={18} /> 完了
                </button>
             </div>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TextObject, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2, Palette, Pencil, Sliders, RotateCw, Undo, Redo, Type, Trash2, AlignVerticalJustifyCenter, AlignHorizontalJustifyCenter, Plus, Layers, MousePointer2, Minus } from 'lucide-react';
import { drawTextOnCanvas } from '../lib/zipService';
import { reprocessStampWithTolerance } from '../lib/imageProcessing';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  onReCrop?: () => void; 
  initialPreviewBg?: string; 
  targetWidth?: number;
  targetHeight?: number;
  initialScale?: number;
  initialRotation?: number;
  initialOffset?: { x: number, y: number };
  initialTextObjects?: TextObject[]; 
}

interface HistoryState {
    scale: number;
    rotation: number;
    offset: { x: number, y: number };
    dataUrl: string;
    tolerance: number;
    textObjects: TextObject[];
}

export const StampEditorModal: React.FC<Props> = ({ 
  stamp, 
  isOpen, 
  onClose, 
  onSave, 
  onReCrop,
  initialPreviewBg = 'checker',
  targetWidth = TARGET_WIDTH,
  targetHeight = TARGET_HEIGHT,
  initialScale,
  initialRotation,
  initialOffset,
  initialTextObjects
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Image State
  const [scale, setScale] = useState(initialScale ?? stamp.scale);
  const [rotation, setRotation] = useState(initialRotation ?? stamp.rotation ?? 0);
  const [offset, setOffset] = useState(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });

  // Text State
  const [textObjects, setTextObjects] = useState<TextObject[]>(initialTextObjects ?? stamp.textObjects ?? []);
  const [selectedTextId, setSelectedTextId] = useState<string | null>(null);

  // History State
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Editor View state
  const [viewZoom, setViewZoom] = useState(1);
  const [previewBg, setPreviewBg] = useState(initialPreviewBg);

  const [mode, setMode] = useState<'move' | 'eraser' | 'wand' | 'restore' | 'text'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [isResizingText, setIsResizingText] = useState(false);

  // Cursor visual state
  const [cursorPos, setCursorPos] = useState<{x: number, y: number} | null>(null);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  const [activeTextHandle, setActiveTextHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  // Pinch & Resize State
  const [pinchStartDist, setPinchStartDist] = useState<number | null>(null);
  const [pinchStartScale, setPinchStartScale] = useState<number>(1);
  const [pinchStartAngle, setPinchStartAngle] = useState<number | null>(null);
  const [pinchStartRotation, setPinchStartRotation] = useState<number>(0);

  // Image Resizing State
  const [isResizingImage, setIsResizingImage] = useState(false);
  const [activeImageHandle, setActiveImageHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  const [tolerance, setTolerance] = useState(stamp.currentTolerance || 50);

  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);
  const [originalImage, setOriginalImage] = useState<HTMLImageElement | null>(null);

  // Interval ref for continuous button press
  const zoomIntervalRef = useRef<number | null>(null);

  // Debounce for tolerance
  const toleranceTimeoutRef = useRef<number | null>(null);
  // Edit canvas for eraser/restore operations to avoid creating new images constantly
  const editCanvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    if (isOpen) {
      setScale(initialScale ?? stamp.scale);
      setRotation(initialRotation ?? stamp.rotation ?? 0);
      setOffset(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
      setTolerance(stamp.currentTolerance || 50);
      setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
      setSelectedTextId(null);

      const initialState = {
          scale: initialScale ?? stamp.scale,
          rotation: initialRotation ?? stamp.rotation ?? 0,
          offset: initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY },
          dataUrl: stamp.dataUrl,
          tolerance: stamp.currentTolerance || 50,
          textObjects: initialTextObjects ?? stamp.textObjects ?? []
      };
      setHistory([initialState]);
      setHistoryIndex(0);

      if (stamp.originalDataUrl) {
          const img = new Image();
          img.src = stamp.originalDataUrl;
          img.onload = () => setOriginalImage(img);
      } else {
          setOriginalImage(null);
      }
    }
  }, [isOpen, stamp, initialScale, initialRotation, initialOffset, initialTextObjects]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, rotation, offset, workingDataUrl, previewBg, targetWidth, targetHeight, cursorPos, mode, eraserSize, textObjects, selectedTextId]); 

  const addToHistory = (newState: Partial<HistoryState>) => {
      const currentState = {
          scale,
          rotation,
          offset,
          dataUrl: workingDataUrl,
          tolerance,
          textObjects,
          ...newState
      };

      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(currentState);
      if (newHistory.length > 20) newHistory.shift();
      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);
  };

  const undo = () => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setScale(prevState.scale);
          setRotation(prevState.rotation);
          setOffset(prevState.offset);
          setWorkingDataUrl(prevState.dataUrl);
          setTolerance(prevState.tolerance);
          setTextObjects(prevState.textObjects);
          setHistoryIndex(prevIndex);
      }
  };

  const redo = () => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setScale(nextState.scale);
          setRotation(nextState.rotation);
          setOffset(nextState.offset);
          setWorkingDataUrl(nextState.dataUrl);
          setTolerance(nextState.tolerance);
          setTextObjects(nextState.textObjects);
          setHistoryIndex(nextIndex);
      }
  };

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const cx = canvas.width / 2 + offset.x;
        const cy = canvas.height / 2 + offset.y;

        // 1. Draw Back Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex === 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // 2. Draw Image
        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);

        // Draw Image Handles (Only in Move Mode)
        if (mode === 'move') {
            const hw = drawnW / 2;
            const hh = drawnH / 2;
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
            ctx.strokeRect(-hw, -hh, drawnW, drawnH);

            const handleSize = 12; // Visual size
            ctx.fillStyle = '#ffffff';
            // Corners
            const corners = [
                { x: -hw, y: -hh }, { x: hw, y: -hh },
                { x: -hw, y: hh }, { x: hw, y: hh }
            ];
            corners.forEach(c => {
                ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
                ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
            });
        }
        ctx.restore();

        // 3. Draw Front Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex !== 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // Border
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);

        // Draw Eraser/Wand Cursor
        if ((mode === 'eraser' || mode === 'restore') && cursorPos) {
            ctx.beginPath();
            ctx.arc(cursorPos.x, cursorPos.y, eraserSize / 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
        }
    };
    img.src = workingDataUrl;
  };

  const getTextBoundingBox = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      ctx.font = `bold ${textObj.fontSize}px '${textObj.fontFamily}'`;
      const lines = textObj.text.split('\n');
      const lineHeight = textObj.fontSize * 1.2;

      let w = 0;
      let h = 0;

      if (textObj.text.length === 0) {
          // Default box for empty text
          w = 40;
          h = 40;
      } else if (textObj.isVertical) {
          w = lineHeight * lines.length;
          const maxChars = Math.max(...lines.map(l => l.length));
          h = textObj.fontSize * maxChars;
      } else {
          const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
          w = maxW;
          h = lineHeight * lines.length;
      }
      // Add padding for better selection
      return { w: Math.max(20, w + 10), h: Math.max(20, h + 10) };
  };

  const drawTextWithSelection = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      drawTextOnCanvas(ctx, textObj);

      if (mode === 'text' && selectedTextId === textObj.id) {
          ctx.save();
          ctx.translate(textObj.x, textObj.y);
          ctx.rotate((textObj.rotation * Math.PI) / 180);

          const { w, h } = getTextBoundingBox(ctx, textObj);
          const hw = w / 2;
          const hh = h / 2;

          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 1.5;
          ctx.setLineDash([4, 4]);
          ctx.strokeRect(-hw, -hh, w, h);

          ctx.setLineDash([]);
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#3b82f6';
          const handleSize = 10;

          const corners = [
              { x: -hw, y: -hh }, { x: hw, y: -hh },
              { x: -hw, y: hh }, { x: hw, y: hh },
          ];

          corners.forEach(c => {
              ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
              ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
          });

          ctx.restore();
      }
  }

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  // --- Logic Helpers ---
  const handleUpdateText = (id: string, updates: Partial<TextObject>) => {
      const newObjects = textObjects.map(t => t.id === id ? { ...t, ...updates } : t);
      setTextObjects(newObjects);
  };

  const handleTextChangeComplete = () => {
      addToHistory({ textObjects });
  };

  const handleAddText = () => {
      if (textObjects.length >= 3) {
          alert("テキストは最大3つまでです");
          return;
      }
      const newText: TextObject = {
          id: Date.now().toString(),
          text: "", // Default is empty
          x: targetWidth / 2,
          y: targetHeight / 2,
          fontSize: 40,
          fontFamily: 'M PLUS Rounded 1c',
          color: '#000000',
          isVertical: false,
          outlineColor: '#ffffff',
          outlineWidth: 4,
          zIndex: 'front',
          rotation: 0,
          curvature: 0
      };
      const newObjects = [...textObjects, newText];
      setTextObjects(newObjects);
      setSelectedTextId(newText.id);
      addToHistory({ textObjects: newObjects });
      setMode('text'); // Switch to text mode automatically
  };

  const handleDeleteText = () => {
      if (!selectedTextId) return;
      const newObjects = textObjects.filter(t => t.id !== selectedTextId);
      setTextObjects(newObjects);
      setSelectedTextId(null);
      addToHistory({ textObjects: newObjects });
  };

  // --- Tool Implementations ---

  const getLocalImageCoords = (canvasX: number, canvasY: number) => {
      const cx = targetWidth / 2 + offset.x;
      const cy = targetHeight / 2 + offset.y;
      const { x: localX, y: localY } = transformToLocal(canvasX, canvasY, cx, cy, rotation);

      const drawnW = stamp.width * scale;
      const drawnH = stamp.height * scale;

      const imgX = (localX + drawnW / 2) / scale;
      const imgY = (localY + drawnH / 2) / scale;

      return { imgX, imgY, inside: (imgX >= 0 && imgX <= stamp.width && imgY >= 0 && imgY <= stamp.height) };
  };

  const prepareEditCanvas = async () => {
      if (!editCanvasRef.current) {
          editCanvasRef.current = document.createElement('canvas');
          editCanvasRef.current.width = stamp.width;
          editCanvasRef.current.height = stamp.height;
      }
      const ctx = editCanvasRef.current.getContext('2d');
      if (!ctx) return null;

      // Only draw if we haven't already populated it with current workingDataUrl
      // But workingDataUrl changes. So we must load it.
      // To avoid reloading Image every time, we can assume editCanvasRef is kept in sync if we only use it.
      // But for simplicity/robustness:
      return new Promise<CanvasRenderingContext2D | null>((resolve) => {
          const img = new Image();
          img.onload = () => {
              ctx!.globalCompositeOperation = 'source-over';
              ctx!.clearRect(0, 0, stamp.width, stamp.height);
              ctx!.drawImage(img, 0, 0);
              resolve(ctx);
          };
          img.src = workingDataUrl;
      });
  };

  const applyEraser = async (canvasX: number, canvasY: number) => {
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      // Allow erasing slightly outside bounds to catch edges
      if (!inside && (imgX < -50 || imgX > stamp.width + 50 || imgY < -50 || imgY > stamp.height + 50)) return;

      const brushR = (eraserSize / scale) / 2;
      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.arc(imgX, imgY, brushR, 0, Math.PI * 2);
      ctx.fill();

      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const applyRestore = async (canvasX: number, canvasY: number) => {
      if (!originalImage) return;
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      if (!inside && (imgX < -50 || imgX > stamp.width + 50 || imgY < -50 || imgY > stamp.height + 50)) return;

      const brushR = (eraserSize / scale) / 2;
      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      ctx.globalCompositeOperation = 'source-over';
      ctx.save();
      ctx.beginPath();
      ctx.arc(imgX, imgY, brushR, 0, Math.PI * 2);
      ctx.clip();
      ctx.drawImage(originalImage, 0, 0, stamp.width, stamp.height);
      ctx.restore();

      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const applyMagicWand = async (canvasX: number, canvasY: number) => {
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      if (!inside) return;

      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      const w = stamp.width;
      const h = stamp.height;
      const imageData = ctx.getImageData(0, 0, w, h);
      const data = imageData.data;

      const startX = Math.floor(imgX);
      const startY = Math.floor(imgY);
      if (startX < 0 || startX >= w || startY < 0 || startY >= h) return;

      const startIdx = (startY * w + startX) * 4;
      const sr = data[startIdx];
      const sg = data[startIdx + 1];
      const sb = data[startIdx + 2];
      const sa = data[startIdx + 3];

      if (sa === 0) return; // Already transparent

      const tol = 30; // Hardcoded wand tolerance for click

      const stack: [number, number][] = [[startX, startY]];
      const visited = new Uint8Array(w * h);

      // Flood Fill
      while (stack.length > 0) {
          const [x, y] = stack.pop()!;
          const idx = y * w + x;
          if (visited[idx]) continue;

          const pIdx = idx * 4;
          const r = data[pIdx];
          const g = data[pIdx+1];
          const b = data[pIdx+2];
          const a = data[pIdx+3];

          if (a === 0) {
              visited[idx] = 1;
              continue;
          }

          const diff = Math.abs(r - sr) + Math.abs(g - sg) + Math.abs(b - sb);
          if (diff < tol) {
              data[pIdx + 3] = 0; // Make transparent
              visited[idx] = 1;

              if (x > 0) stack.push([x - 1, y]);
              if (x < w - 1) stack.push([x + 1, y]);
              if (y > 0) stack.push([x, y - 1]);
              if (y < h - 1) stack.push([x, y + 1]);
          }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const handleToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const newVal = Number(e.target.value);
      setTolerance(newVal);

      if (toleranceTimeoutRef.current) {
          clearTimeout(toleranceTimeoutRef.current);
      }

      toleranceTimeoutRef.current = window.setTimeout(async () => {
          if (stamp.originalDataUrl) {
              try {
                  const newDataUrl = await reprocessStampWithTolerance(stamp.originalDataUrl, newVal);
                  setWorkingDataUrl(newDataUrl);
              } catch (err) {
                  console.error("Failed to reprocess", err);
              }
          }
      }, 300);
  };

  const handleSave = () => {
      const updatedStamp: Stamp = {
          ...stamp,
          scale,
          rotation,
          offsetX: offset.x,
          offsetY: offset.y,
          dataUrl: workingDataUrl,
          textObjects,
          currentTolerance: tolerance
      };
      onSave(updatedStamp);
      onClose();
  };


  // --- Pointer/Touch Events ---

  const getClientCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
      if ('touches' in e) {
          return { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else {
          return { x: (e as React.MouseEvent).clientX, y: (e as React.MouseEvent).clientY };
      }
  };

  const transformToLocal = (px: number, py: number, cx: number, cy: number, rot: number) => {
      const dx = px - cx;
      const dy = py - cy;
      const rad = -(rot * Math.PI) / 180;
      const rx = dx * Math.cos(rad) - dy * Math.sin(rad);
      const ry = dx * Math.sin(rad) + dy * Math.cos(rad);
      return { x: rx, y: ry };
  }

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchstart') e.preventDefault();

    // Pinch Check
    if ('touches' in e && e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
        setPinchStartDist(dist);
        setPinchStartScale(scale);
        setPinchStartAngle(angle);
        setPinchStartRotation(rotation);
        setIsDragging(false);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;

    // --- 1. Text Interaction (Priority) ---
    if (mode === 'text') {
        if (selectedTextId) {
            const t = textObjects.find(obj => obj.id === selectedTextId);
            if (t) {
                const { x: localX, y: localY } = transformToLocal(x, y, t.x, t.y, t.rotation);
                const { w, h } = getTextBoundingBox(ctx, t);
                const hw = w/2; const hh = h/2;
                const handleRadius = 20;

                if (Math.hypot(localX - (-hw), localY - (-hh)) < handleRadius) { setActiveTextHandle('tl'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (hw), localY - (-hh)) < handleRadius) { setActiveTextHandle('tr'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (-hw), localY - (hh)) < handleRadius) { setActiveTextHandle('bl'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (hw), localY - (hh)) < handleRadius) { setActiveTextHandle('br'); setIsResizingText(true); setLastPos({x, y}); return; }
            }
        }

        for (let i = textObjects.length - 1; i >= 0; i--) {
             const t = textObjects[i];
             const { x: localX, y: localY } = transformToLocal(x, y, t.x, t.y, t.rotation);
             const { w, h } = getTextBoundingBox(ctx, t);
             // Even if text is empty, check bounding box
             if (localX >= -w/2 && localX <= w/2 && localY >= -h/2 && localY <= h/2) {
                 setSelectedTextId(t.id);
                 setIsDragging(true);
                 setLastPos({ x, y });
                 return;
             }
        }
        return; 
    }

    // --- 2. Image Interaction (Move Mode) ---
    if (mode === 'move') {
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;
        const { x: localX, y: localY } = transformToLocal(x, y, cx, cy, rotation);
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const hw = drawnW / 2;
        const hh = drawnH / 2;
        const handleRadius = 25; 

        if (Math.hypot(localX - (-hw), localY - (-hh)) < handleRadius) { setActiveImageHandle('tl'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (hw), localY - (-hh)) < handleRadius) { setActiveImageHandle('tr'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (-hw), localY - (hh)) < handleRadius) { setActiveImageHandle('bl'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (hw), localY - (hh)) < handleRadius) { setActiveImageHandle('br'); setIsResizingImage(true); setLastPos({x, y}); return; }

        setIsDragging(true);
        setLastPos({ x, y });
        return;
    }

    // --- 3. Tool Modes ---
    if (mode === 'wand' || mode === 'restore' || mode === 'eraser') {
       addToHistory({});
       if (mode === 'wand') applyMagicWand(x, y);
       else if (mode === 'eraser') applyEraser(x, y);
       else if (mode === 'restore') applyRestore(x, y);
       setIsDragging(true);
       setLastPos({ x, y });
    }
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchmove') e.preventDefault();

    if ('touches' in e && e.touches.length === 2 && pinchStartDist !== null) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const scaleFactor = dist / pinchStartDist;
        const newScale = Math.max(0.01, pinchStartScale * scaleFactor);
        setScale(newScale);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    setCursorPos({ x, y });

    if (isResizingText && selectedTextId) {
        const t = textObjects.find(t => t.id === selectedTextId);
        if (t) {
            const dist = Math.hypot(x - t.x, y - t.y);
            const prevDist = Math.hypot(lastPos.x - t.x, lastPos.y - t.y);
            const scaleFactor = dist / prevDist;
            const newSize = Math.min(200, Math.max(10, t.fontSize * scaleFactor));
            handleUpdateText(selectedTextId, { fontSize: newSize });
        }
        setLastPos({ x, y });
        return;
    }

    if (isResizingImage) {
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;
        const dist = Math.hypot(x - cx, y - cy);
        const prevDist = Math.hypot(lastPos.x - cx, lastPos.y - cy);
        const scaleFactor = dist / prevDist;
        const newScale = Math.min(3.0, Math.max(0.01, scale * scaleFactor));
        setScale(newScale);
        setLastPos({ x, y });
        return;
    }

    if (!isDragging) return;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'text' && selectedTextId) {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      handleUpdateText(selectedTextId, { 
          x: textObjects.find(t => t.id === selectedTextId)!.x + dx,
          y: textObjects.find(t => t.id === selectedTextId)!.y + dy
      });
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    } else if (mode === 'restore') {
      applyRestore(x, y);
    }
    setLastPos({ x, y });
  };

  const handlePointerUp = () => {
    if (isDragging && mode === 'move') addToHistory({});
    if (isResizingImage) addToHistory({ scale });
    if (isResizingText && selectedTextId) handleTextChangeComplete();

    setIsDragging(false);
    setIsResizingText(false);
    setIsResizingImage(false);
    setActiveTextHandle(null);
    setActiveImageHandle(null);
    setPinchStartDist(null);
    setPinchStartAngle(null);
  };

  const handlePointerLeave = () => {
      setCursorPos(null);
      handlePointerUp();
  };

  const startZoom = (direction: 'in' | 'out') => {
      const step = 0.05;
      if (direction === 'in') setViewZoom(z => Math.min(3, z + step));
      else setViewZoom(z => Math.max(0.5, z - step));

      zoomIntervalRef.current = window.setInterval(() => {
         setViewZoom(z => {
             const ns = direction === 'in' ? z + step : Math.max(0.5, z - step);
             return ns;
         });
      }, 50);
  };
  const stopZoom = () => {
      if (zoomIntervalRef.current) {
          clearInterval(zoomIntervalRef.current);
          zoomIntervalRef.current = null;
      }
  };

  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' }, 
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#ff00ff', label: 'マゼンタ', color: 'bg-[#ff00ff]' },
    { value: '#60a5fa', label: '青', color: 'bg-[#60a5fa]' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#16a34a', label: '緑', color: 'bg-[#16a34a]' },
    { value: '#f97316', label: 'オレンジ', color: 'bg-[#f97316]' },
  ];

  const fontOptions = [
      { value: 'M PLUS Rounded 1c', label: '丸ゴシック' },
      { value: 'Noto Sans JP', label: 'ゴシック' },
      { value: 'Noto Serif JP', label: '明朝' },
  ];

  const textColorOptions = ['#000000', '#FFFFFF', '#ef4444', '#3b82f6', '#10b981', '#f97316', '#ec4899', '#4b3621'];

  const selectedText = textObjects.find(t => t.id === selectedTextId);

  // Improved Slider Component with robust continuous press
  const ControlSlider = ({ label, value, min, max, step = 1, onChange, onCommit, unit = '' }: any) => {
      const intervalRef = useRef<number | null>(null);
      const timeoutRef = useRef<number | null>(null);
      // Keep track of current value in ref to avoid stale closures in intervals
      const valRef = useRef(value);

      useEffect(() => {
          valRef.current = value;
      }, [value]);

      const clearTimers = () => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
          if (intervalRef.current) clearInterval(intervalRef.current);
          timeoutRef.current = null;
          intervalRef.current = null;
      };

      const handleButtonDown = (direction: 1 | -1) => {
          clearTimers();

          // 1. Initial immediate change
          const nextVal = Math.min(max, Math.max(min, valRef.current + (step * direction)));
          // Round to avoid float errors
          const rounded = Number(nextVal.toFixed(2));
          onChange(rounded);

          // 2. Start continuous change after delay
          timeoutRef.current = window.setTimeout(() => {
              intervalRef.current = window.setInterval(() => {
                  const current = valRef.current;
                  const next = Math.min(max, Math.max(min, current + (step * direction)));
                  const r = Number(next.toFixed(2));
                  onChange(r);
              }, 50);
          }, 300);
      };

      const handleButtonUp = () => {
          clearTimers();
          if (onCommit) onCommit();
      };

      return (
        <div className="flex items-center gap-2 w-full">
            <span className="text-xs text-gray-500 w-12 shrink-0">{label}</span>
            <button 
                onMouseDown={() => handleButtonDown(-1)}
                onMouseUp={handleButtonUp}
                onMouseLeave={handleButtonUp}
                onTouchStart={() => handleButtonDown(-1)}
                onTouchEnd={handleButtonUp}
                className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600 active:bg-gray-300 touch-none select-none"
            ><Minus size={14}/></button>
            <input 
                type="range" 
                min={min} 
                max={max} 
                step={step}
                value={value} 
                onChange={(e) => onChange(Number(e.target.value))}
                onMouseUp={onCommit}
                onTouchEnd={onCommit}
                className="flex-1 accent-primary-500 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer"
            />
            <button 
                onMouseDown={() => handleButtonDown(1)}
                onMouseUp={handleButtonUp}
                onMouseLeave={handleButtonUp}
                onTouchStart={() => handleButtonDown(1)}
                onTouchEnd={handleButtonUp}
                className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600 active:bg-gray-300 touch-none select-none"
            ><Plus size={14}/></button>
            {unit && <span className="text-xs text-gray-400 w-8 text-right font-mono">{Math.round(value)}{unit}</span>}
        </div>
      );
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col max-h-[95vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
          <h3 className="font-bold text-gray-700">スタンプ編集 ({targetWidth}x{targetHeight})</h3>
          <div className="flex items-center gap-2">
               <div className="flex items-center gap-1 bg-white p-1 rounded-lg border border-gray-200 mr-2 md:mr-4">
                    <span className="hidden md:inline text-xs text-gray-400 font-bold px-1">背景色</span>
                    {backgroundOptions.map(opt => (
                        <button
                            key={opt.value}
                            onClick={() => setPreviewBg(opt.value)}
                            className={`w-5 h-5 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                            title={opt.label}
                            style={opt.value === 'checker' ? {
                                backgroundImage: `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')`
                            } : {}}
                        />
                    ))}
                </div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
          </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col">
            {/* Toolbar Top */}
            <div className="p-2 bg-gray-50 border-b flex flex-wrap justify-center gap-2 md:gap-4 items-center">
                 <div className="flex items-center gap-1 md:gap-2 bg-white px-2 py-1 rounded shadow-sm">
                    <span className="text-xs text-gray-500 hidden sm:inline">表示倍率:</span>
                    <button 
                        onMouseDown={() => startZoom('out')} 
                        onMouseUp={stopZoom} 
                        onMouseLeave={stopZoom}
                        onTouchStart={() => startZoom('out')}
                        onTouchEnd={stopZoom}
                        className="p-1 hover:bg-gray-100 rounded touch-none"
                    ><ZoomOut size={16}/></button>
                    <span className="text-sm font-mono w-10 text-center">{(viewZoom * 100).toFixed(0)}%</span>
                    <button 
                        onMouseDown={() => startZoom('in')} 
                        onMouseUp={stopZoom} 
                        onMouseLeave={stopZoom}
                        onTouchStart={() => startZoom('in')}
                        onTouchEnd={stopZoom}
                        className="p-1 hover:bg-gray-100 rounded touch-none"
                    ><ZoomIn size={16}/></button>
                 </div>

                 <div className="flex items-center gap-1">
                     <button onClick={undo} disabled={historyIndex <= 0} className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"><Undo size={18} /></button>
                     <button onClick={redo} disabled={historyIndex >= history.length - 1} className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"><Redo size={18} /></button>
                 </div>

                 {onReCrop && (
                    <button onClick={onReCrop} className="flex items-center gap-1 text-xs bg-white text-gray-700 px-3 py-1.5 rounded shadow-sm hover:bg-gray-100 border border-gray-200">
                        <RotateCw size={14} /> <span className="hidden sm:inline">再切り出し</span>
                    </button>
                 )}
            </div>

            {/* Scrollable Canvas Area */}
            <div className="flex-1 overflow-auto bg-gray-100 flex p-8">
                <div 
                    className="relative shadow-md border border-gray-200 bg-white m-auto" 
                    style={{ 
                        width: targetWidth * viewZoom, 
                        height: targetHeight * viewZoom,
                        flexShrink: 0 
                    }}
                >
                    <canvas 
                    ref={canvasRef}
                    width={targetWidth}
                    height={targetHeight}
                    className={`origin-top-left ${mode === 'move' ? 'cursor-move' : (mode === 'text' ? 'cursor-text' : 'cursor-crosshair')} touch-none`}
                    style={{
                        transform: `scale(${viewZoom})`,
                        width: targetWidth,
                        height: targetHeight
                    }}
                    onMouseDown={handlePointerDown}
                    onMouseMove={handlePointerMove}
                    onMouseUp={handlePointerUp}
                    onMouseLeave={handlePointerLeave}
                    onTouchStart={handlePointerDown}
                    onTouchMove={handlePointerMove}
                    onTouchEnd={handlePointerUp}
                    />
                </div>
            </div>
        </div>

        {/* Footer Tools */}
        <div className="p-4 border-t bg-white rounded-b-xl shrink-0 flex flex-col gap-4 max-h-[50vh] overflow-y-auto">

             {/* Text Edit Panel */}
             {mode === 'text' && selectedText && (
                 <div className="bg-blue-50 p-3 rounded-lg border border-blue-100 flex flex-col gap-3 animate-fade-in">
                     <div className="flex items-center gap-2">
                         <input 
                            type="text" 
                            value={selectedText.text}
                            onChange={(e) => handleUpdateText(selectedText.id, { text: e.target.value })}
                            className="flex-1 border-gray-300 rounded text-sm px-2 py-1"
                            placeholder="テキストを入力"
                         />
                         <button onClick={handleDeleteText} className="text-red-500 p-1 hover:bg-red-100 rounded">
                             <Trash2 size={18} />
                         </button>
                     </div>
                     <div className="flex flex-wrap items-center gap-4">
                         <select 
                            value={selectedText.fontFamily}
                            onChange={(e) => handleUpdateText(selectedText.id, { fontFamily: e.target.value })}
                            className="text-xs border-gray-300 rounded"
                         >
                             {fontOptions.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
                         </select>

                         <button 
                            onClick={() => handleUpdateText(selectedText.id, { isVertical: !selectedText.isVertical })}
                            className={`flex items-center gap-1 text-xs px-2 py-1 rounded border ${selectedText.isVertical ? 'bg-blue-200 border-blue-300' : 'bg-white border-gray-300'}`}
                         >
                             {selectedText.isVertical ? <AlignVerticalJustifyCenter size={14}/> : <AlignHorizontalJustifyCenter size={14}/>}
                             {selectedText.isVertical ? '縦' : '横'}
                         </button>

                         <button 
                            onClick={() => handleUpdateText(selectedText.id, { zIndex: selectedText.zIndex === 'back' ? 'front' : 'back' })}
                            className={`flex items-center gap-1 text-xs px-2 py-1 rounded border ${selectedText.zIndex === 'back' ? 'bg-blue-200 border-blue-300' : 'bg-white border-gray-300'}`}
                         >
                             <Layers size={14}/>
                             {selectedText.zIndex === 'back' ? '背面' : '前面'}
                         </button>

                         {/* Colors */}
                         <div className="flex items-center gap-2">
                             <span className="text-xs text-gray-500">色</span>
                             <div className="flex gap-1 items-center">
                                 {textColorOptions.map(c => (
                                     <button
                                        key={c}
                                        onClick={() => handleUpdateText(selectedText.id, { color: c })}
                                        className={`w-5 h-5 rounded-full border border-gray-300 ${selectedText.color === c ? 'ring-2 ring-blue-500' : ''}`}
                                        style={{ backgroundColor: c }}
                                     />
                                 ))}
                                 <label className="w-5 h-5 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.color}
                                        onChange={(e) => handleUpdateText(selectedText.id, { color: e.target.value })}
                                     />
                                 </label>
                             </div>
                         </div>
                     </div>

                     <div className="flex flex-col gap-2 pt-2 border-t border-blue-200/50">
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                              <ControlSlider 
                                label="サイズ" 
                                value={selectedText.fontSize} 
                                min={10} max={200} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { fontSize: val })}
                                onCommit={handleTextChangeComplete}
                              />
                              <ControlSlider 
                                label="回転" 
                                value={selectedText.rotation} 
                                min={-180} max={180} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { rotation: val })}
                                onCommit={handleTextChangeComplete}
                                unit="°"
                              />
                          </div>

                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                               <ControlSlider 
                                label="カーブ" 
                                value={selectedText.curvature} 
                                min={-100} max={100} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { curvature: val })}
                                onCommit={handleTextChangeComplete}
                              />

                              <div className="flex items-center gap-2 w-full">
                                    <span className="text-xs text-gray-500 w-12 shrink-0">縁取り</span>
                                    <ControlSlider 
                                        label="" 
                                        value={selectedText.outlineWidth} 
                                        min={0} max={30} step={1}
                                        onChange={(val: number) => handleUpdateText(selectedText.id, { outlineWidth: val })}
                                        onCommit={handleTextChangeComplete}
                                    />
                                    <label className="w-5 h-5 shrink-0 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500 ml-1">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.outlineColor}
                                        onChange={(e) => handleUpdateText(selectedText.id, { outlineColor: e.target.value })}
                                     />
                                    </label>
                              </div>
                          </div>
                     </div>
                 </div>
             )}

             {/* Move Mode Image Controls */}
             {mode === 'move' && (
                 <div className="bg-gray-50 p-3 rounded-lg border border-gray-200 flex flex-col gap-2">
                     <span className="text-xs font-bold text-gray-500 mb-1">画像操作</span>
                     <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <ControlSlider 
                            label="サイズ" 
                            value={Number(scale.toFixed(2))} 
                            min={0.1} max={3.0} step={0.01}
                            onChange={(val: number) => setScale(val)}
                            onCommit={() => addToHistory({ scale })}
                        />
                        <ControlSlider 
                            label="回転" 
                            value={Math.round(rotation)} 
                            min={-180} max={180} step={1}
                            onChange={(val: number) => setRotation(val)}
                            onCommit={() => addToHistory({ rotation })}
                            unit="°"
                        />
                     </div>
                 </div>
             )}

             {/* Tolerance Slider */}
             {(mode === 'wand' || mode === 'eraser') && originalImage && (
                <div className="flex items-center gap-4 bg-yellow-50 p-3 rounded-lg border border-yellow-100">
                    <div className="flex items-center gap-2 text-yellow-700 font-bold text-sm min-w-[120px]">
                        <Sliders size={16} />
                        背景除去
                    </div>
                    <input 
                        type="range" 
                        min="1" 
                        max="100" 
                        value={tolerance} 
                        onChange={handleToleranceChange}
                        className="w-full accent-yellow-500"
                    />
                </div>
             )}

             <div className="flex flex-wrap gap-4 justify-center items-center">
                 {/* Mode Selection */}
                 <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg overflow-x-auto max-w-full">
                    <button 
                    onClick={() => setMode('move')} 
                    className={`p-2 rounded ${mode === 'move' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="画像移動"
                    >
                    <Move size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('text')} 
                    className={`p-2 rounded ${mode === 'text' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="文字入れ"
                    >
                    <Type size={20} />
                    </button>
                    <div className="w-px h-6 bg-gray-300 mx-1"></div>
                    <button 
                    onClick={() => setMode('wand')} 
                    className={`p-2 rounded ${mode === 'wand' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="追加透過"
                    >
                    <Wand2 size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('eraser')} 
                    className={`p-2 rounded ${mode === 'eraser' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="消しゴム"
                    >
                    <Eraser size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('restore')} 
                    disabled={!originalImage}
                    className={`p-2 rounded ${mode === 'restore' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'} disabled:opacity-30`}
                    title="復元"
                    >
                    <Pencil size={20} />
                    </button>

                    {/* Integrated Size Slider for Brush */}
                    {(mode === 'eraser' || mode === 'restore') && (
                        <>
                            <div className="w-px h-6 bg-gray-300 mx-1"></div>
                            <input 
                            type="range" 
                            min="5" 
                            max="50" 
                            value={eraserSize} 
                            onChange={(e) => setEraserSize(Number(e.target.value))} 
                            className="w-20 accent-primary-500"
                            />
                        </>
                    )}
                 </div>

                 {/* Text Add Button */}
                 {mode === 'text' && (
                     <button 
                        onClick={handleAddText}
                        className="bg-blue-600 text-white px-3 py-2 rounded-lg shadow font-bold text-sm flex items-center gap-1 hover:bg-blue-700"
                     >
                         <Plus size={16} /> 文字追加
                     </button>
                 )}

                <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                    <button 
                        onClick={() => {
                            addToHistory({});
                            setScale(initialScale ?? stamp.scale);
                            setRotation(initialRotation ?? stamp.rotation ?? 0);
                            setOffset(initialOffset ?? {x:0, y:0});
                            setTolerance(stamp.currentTolerance || 50);
                            setWorkingDataUrl(stamp.dataUrl); 
                            setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
                        }}
                        className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                    >
                        <RotateCcw size={14} /> <span className="hidden sm:inline">リセット</span>
                    </button>
                </div>
             </div>

             <div className="flex justify-end gap-3 pt-2 border-t border-dashed">
                <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
                <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
                    <Check size={18} /> 完了
                </button>
             </div>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TextObject, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2, Palette, Pencil, Sliders, RotateCw, Undo, Redo, Type, Trash2, AlignVerticalJustifyCenter, AlignHorizontalJustifyCenter, Plus, Layers, MousePointer2, Minus } from 'lucide-react';
import { drawTextOnCanvas } from '../lib/zipService';
import { reprocessStampWithTolerance } from '../lib/imageProcessing';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  onReCrop?: () => void; 
  initialPreviewBg?: string; 
  targetWidth?: number;
  targetHeight?: number;
  initialScale?: number;
  initialRotation?: number;
  initialOffset?: { x: number, y: number };
  initialTextObjects?: TextObject[]; 
}

interface HistoryState {
    scale: number;
    rotation: number;
    offset: { x: number, y: number };
    dataUrl: string;
    tolerance: number;
    textObjects: TextObject[];
}

export const StampEditorModal: React.FC<Props> = ({ 
  stamp, 
  isOpen, 
  onClose, 
  onSave, 
  onReCrop,
  initialPreviewBg = 'checker',
  targetWidth = TARGET_WIDTH,
  targetHeight = TARGET_HEIGHT,
  initialScale,
  initialRotation,
  initialOffset,
  initialTextObjects
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Image State
  const [scale, setScale] = useState(initialScale ?? stamp.scale);
  const [rotation, setRotation] = useState(initialRotation ?? stamp.rotation ?? 0);
  const [offset, setOffset] = useState(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });

  // Text State
  const [textObjects, setTextObjects] = useState<TextObject[]>(initialTextObjects ?? stamp.textObjects ?? []);
  const [selectedTextId, setSelectedTextId] = useState<string | null>(null);

  // History State
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Editor View state
  const [viewZoom, setViewZoom] = useState(1);
  const [previewBg, setPreviewBg] = useState(initialPreviewBg);

  const [mode, setMode] = useState<'move' | 'eraser' | 'wand' | 'restore' | 'text'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [isResizingText, setIsResizingText] = useState(false);

  // Cursor visual state
  const [cursorPos, setCursorPos] = useState<{x: number, y: number} | null>(null);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  const [activeTextHandle, setActiveTextHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  // Pinch & Resize State
  const [pinchStartDist, setPinchStartDist] = useState<number | null>(null);
  const [pinchStartScale, setPinchStartScale] = useState<number>(1);
  const [pinchStartAngle, setPinchStartAngle] = useState<number | null>(null);
  const [pinchStartRotation, setPinchStartRotation] = useState<number>(0);

  // Image Resizing State
  const [isResizingImage, setIsResizingImage] = useState(false);
  const [activeImageHandle, setActiveImageHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  const [tolerance, setTolerance] = useState(stamp.currentTolerance || 50);

  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);
  const [originalImage, setOriginalImage] = useState<HTMLImageElement | null>(null);

  // Interval ref for continuous button press
  const zoomIntervalRef = useRef<number | null>(null);

  // Debounce for tolerance
  const toleranceTimeoutRef = useRef<number | null>(null);
  // Edit canvas for eraser/restore operations to avoid creating new images constantly
  const editCanvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    if (isOpen) {
      setScale(initialScale ?? stamp.scale);
      setRotation(initialRotation ?? stamp.rotation ?? 0);
      setOffset(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
      setTolerance(stamp.currentTolerance || 50);
      setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
      setSelectedTextId(null);

      const initialState = {
          scale: initialScale ?? stamp.scale,
          rotation: initialRotation ?? stamp.rotation ?? 0,
          offset: initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY },
          dataUrl: stamp.dataUrl,
          tolerance: stamp.currentTolerance || 50,
          textObjects: initialTextObjects ?? stamp.textObjects ?? []
      };
      setHistory([initialState]);
      setHistoryIndex(0);

      if (stamp.originalDataUrl) {
          const img = new Image();
          img.src = stamp.originalDataUrl;
          img.onload = () => setOriginalImage(img);
      } else {
          setOriginalImage(null);
      }
    }
  }, [isOpen, stamp, initialScale, initialRotation, initialOffset, initialTextObjects]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, rotation, offset, workingDataUrl, previewBg, targetWidth, targetHeight, cursorPos, mode, eraserSize, textObjects, selectedTextId]); 

  const addToHistory = (newState: Partial<HistoryState>) => {
      const currentState = {
          scale,
          rotation,
          offset,
          dataUrl: workingDataUrl,
          tolerance,
          textObjects,
          ...newState
      };

      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(currentState);
      if (newHistory.length > 20) newHistory.shift();
      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);
  };

  const undo = () => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setScale(prevState.scale);
          setRotation(prevState.rotation);
          setOffset(prevState.offset);
          setWorkingDataUrl(prevState.dataUrl);
          setTolerance(prevState.tolerance);
          setTextObjects(prevState.textObjects);
          setHistoryIndex(prevIndex);
      }
  };

  const redo = () => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setScale(nextState.scale);
          setRotation(nextState.rotation);
          setOffset(nextState.offset);
          setWorkingDataUrl(nextState.dataUrl);
          setTolerance(nextState.tolerance);
          setTextObjects(nextState.textObjects);
          setHistoryIndex(nextIndex);
      }
  };

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const cx = canvas.width / 2 + offset.x;
        const cy = canvas.height / 2 + offset.y;

        // 1. Draw Back Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex === 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // 2. Draw Image
        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);

        // Draw Image Handles (Only in Move Mode)
        if (mode === 'move') {
            const hw = drawnW / 2;
            const hh = drawnH / 2;
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
            ctx.strokeRect(-hw, -hh, drawnW, drawnH);

            const handleSize = 12; // Visual size
            ctx.fillStyle = '#ffffff';
            // Corners
            const corners = [
                { x: -hw, y: -hh }, { x: hw, y: -hh },
                { x: -hw, y: hh }, { x: hw, y: hh }
            ];
            corners.forEach(c => {
                ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
                ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
            });
        }
        ctx.restore();

        // 3. Draw Front Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex !== 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // Border
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);

        // Draw Eraser/Wand Cursor
        if ((mode === 'eraser' || mode === 'restore') && cursorPos) {
            ctx.beginPath();
            ctx.arc(cursorPos.x, cursorPos.y, eraserSize / 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
        }
    };
    img.src = workingDataUrl;
  };

  const getTextBoundingBox = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      ctx.font = `bold ${textObj.fontSize}px '${textObj.fontFamily}'`;
      const lines = textObj.text.split('\n');
      const lineHeight = textObj.fontSize * 1.2;

      let w = 0;
      let h = 0;

      if (textObj.text.length === 0) {
          // Default box for empty text
          w = 40;
          h = 40;
      } else if (textObj.isVertical) {
          w = lineHeight * lines.length;
          const maxChars = Math.max(...lines.map(l => l.length));
          h = textObj.fontSize * maxChars;
      } else {
          const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
          w = maxW;
          h = lineHeight * lines.length;
      }
      // Add padding for better selection
      return { w: Math.max(20, w + 10), h: Math.max(20, h + 10) };
  };

  const drawTextWithSelection = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      drawTextOnCanvas(ctx, textObj);

      if (mode === 'text' && selectedTextId === textObj.id) {
          ctx.save();
          ctx.translate(textObj.x, textObj.y);
          ctx.rotate((textObj.rotation * Math.PI) / 180);

          const { w, h } = getTextBoundingBox(ctx, textObj);
          const hw = w / 2;
          const hh = h / 2;

          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 1.5;
          ctx.setLineDash([4, 4]);
          ctx.strokeRect(-hw, -hh, w, h);

          ctx.setLineDash([]);
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#3b82f6';
          const handleSize = 10;

          const corners = [
              { x: -hw, y: -hh }, { x: hw, y: -hh },
              { x: -hw, y: hh }, { x: hw, y: hh },
          ];

          corners.forEach(c => {
              ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
              ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
          });

          ctx.restore();
      }
  }

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  // --- Logic Helpers ---
  const handleUpdateText = (id: string, updates: Partial<TextObject>) => {
      const newObjects = textObjects.map(t => t.id === id ? { ...t, ...updates } : t);
      setTextObjects(newObjects);
  };

  const handleTextChangeComplete = () => {
      addToHistory({ textObjects });
  };

  const handleAddText = () => {
      if (textObjects.length >= 3) {
          alert("テキストは最大3つまでです");
          return;
      }
      const newText: TextObject = {
          id: Date.now().toString(),
          text: "", // Default is empty
          x: targetWidth / 2,
          y: targetHeight / 2,
          fontSize: 40,
          fontFamily: 'M PLUS Rounded 1c',
          color: '#000000',
          isVertical: false,
          outlineColor: '#ffffff',
          outlineWidth: 4,
          zIndex: 'front',
          rotation: 0,
          curvature: 0
      };
      const newObjects = [...textObjects, newText];
      setTextObjects(newObjects);
      setSelectedTextId(newText.id);
      addToHistory({ textObjects: newObjects });
      setMode('text'); // Switch to text mode automatically
  };

  const handleDeleteText = () => {
      if (!selectedTextId) return;
      const newObjects = textObjects.filter(t => t.id !== selectedTextId);
      setTextObjects(newObjects);
      setSelectedTextId(null);
      addToHistory({ textObjects: newObjects });
  };

  // --- Tool Implementations ---

  const getLocalImageCoords = (canvasX: number, canvasY: number) => {
      const cx = targetWidth / 2 + offset.x;
      const cy = targetHeight / 2 + offset.y;
      const { x: localX, y: localY } = transformToLocal(canvasX, canvasY, cx, cy, rotation);

      const drawnW = stamp.width * scale;
      const drawnH = stamp.height * scale;

      const imgX = (localX + drawnW / 2) / scale;
      const imgY = (localY + drawnH / 2) / scale;

      return { imgX, imgY, inside: (imgX >= 0 && imgX <= stamp.width && imgY >= 0 && imgY <= stamp.height) };
  };

  const prepareEditCanvas = async () => {
      if (!editCanvasRef.current) {
          editCanvasRef.current = document.createElement('canvas');
          editCanvasRef.current.width = stamp.width;
          editCanvasRef.current.height = stamp.height;
      }
      const ctx = editCanvasRef.current.getContext('2d');
      if (!ctx) return null;

      return new Promise<CanvasRenderingContext2D | null>((resolve) => {
          const img = new Image();
          img.onload = () => {
              ctx!.globalCompositeOperation = 'source-over';
              ctx!.clearRect(0, 0, stamp.width, stamp.height);
              ctx!.drawImage(img, 0, 0);
              resolve(ctx);
          };
          img.src = workingDataUrl;
      });
  };

  const applyEraser = async (canvasX: number, canvasY: number) => {
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      if (!inside && (imgX < -50 || imgX > stamp.width + 50 || imgY < -50 || imgY > stamp.height + 50)) return;

      const brushR = (eraserSize / scale) / 2;
      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.arc(imgX, imgY, brushR, 0, Math.PI * 2);
      ctx.fill();

      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const applyRestore = async (canvasX: number, canvasY: number) => {
      if (!originalImage) return;
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      if (!inside && (imgX < -50 || imgX > stamp.width + 50 || imgY < -50 || imgY > stamp.height + 50)) return;

      const brushR = (eraserSize / scale) / 2;
      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      ctx.globalCompositeOperation = 'source-over';
      ctx.save();
      ctx.beginPath();
      ctx.arc(imgX, imgY, brushR, 0, Math.PI * 2);
      ctx.clip();
      ctx.drawImage(originalImage, 0, 0, stamp.width, stamp.height);
      ctx.restore();

      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const applyMagicWand = async (canvasX: number, canvasY: number) => {
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      if (!inside) return;

      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      const w = stamp.width;
      const h = stamp.height;
      const imageData = ctx.getImageData(0, 0, w, h);
      const data = imageData.data;

      const startX = Math.floor(imgX);
      const startY = Math.floor(imgY);
      if (startX < 0 || startX >= w || startY < 0 || startY >= h) return;

      const startIdx = (startY * w + startX) * 4;
      const sr = data[startIdx];
      const sg = data[startIdx + 1];
      const sb = data[startIdx + 2];
      const sa = data[startIdx + 3];

      if (sa === 0) return; 

      const tol = 30; 

      const stack: [number, number][] = [[startX, startY]];
      const visited = new Uint8Array(w * h);

      while (stack.length > 0) {
          const [x, y] = stack.pop()!;
          const idx = y * w + x;
          if (visited[idx]) continue;

          const pIdx = idx * 4;
          const r = data[pIdx];
          const g = data[pIdx+1];
          const b = data[pIdx+2];
          const a = data[pIdx+3];

          if (a === 0) {
              visited[idx] = 1;
              continue;
          }

          const diff = Math.abs(r - sr) + Math.abs(g - sg) + Math.abs(b - sb);
          if (diff < tol) {
              data[pIdx + 3] = 0; 
              visited[idx] = 1;

              if (x > 0) stack.push([x - 1, y]);
              if (x < w - 1) stack.push([x + 1, y]);
              if (y > 0) stack.push([x, y - 1]);
              if (y < h - 1) stack.push([x, y + 1]);
          }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const handleToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const newVal = Number(e.target.value);
      setTolerance(newVal);

      if (toleranceTimeoutRef.current) {
          clearTimeout(toleranceTimeoutRef.current);
      }

      toleranceTimeoutRef.current = window.setTimeout(async () => {
          if (stamp.originalDataUrl) {
              try {
                  const newDataUrl = await reprocessStampWithTolerance(stamp.originalDataUrl, newVal);
                  setWorkingDataUrl(newDataUrl);
              } catch (err) {
                  console.error("Failed to reprocess", err);
              }
          }
      }, 300);
  };

  const handleSave = () => {
      const updatedStamp: Stamp = {
          ...stamp,
          scale,
          rotation,
          offsetX: offset.x,
          offsetY: offset.y,
          dataUrl: workingDataUrl,
          textObjects,
          currentTolerance: tolerance
      };
      onSave(updatedStamp);
      onClose();
  };


  // --- Pointer/Touch Events ---

  const getClientCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
      if ('touches' in e) {
          return { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else {
          return { x: (e as React.MouseEvent).clientX, y: (e as React.MouseEvent).clientY };
      }
  };

  const transformToLocal = (px: number, py: number, cx: number, cy: number, rot: number) => {
      const dx = px - cx;
      const dy = py - cy;
      const rad = -(rot * Math.PI) / 180;
      const rx = dx * Math.cos(rad) - dy * Math.sin(rad);
      const ry = dx * Math.sin(rad) + dy * Math.cos(rad);
      return { x: rx, y: ry };
  }

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchstart') e.preventDefault();

    // Pinch Check
    if ('touches' in e && e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
        setPinchStartDist(dist);
        setPinchStartScale(scale);
        setPinchStartAngle(angle);
        setPinchStartRotation(rotation);
        setIsDragging(false);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;

    // --- 1. Text Interaction (Priority) ---
    if (mode === 'text') {
        if (selectedTextId) {
            const t = textObjects.find(obj => obj.id === selectedTextId);
            if (t) {
                const { x: localX, y: localY } = transformToLocal(x, y, t.x, t.y, t.rotation);
                const { w, h } = getTextBoundingBox(ctx, t);
                const hw = w/2; const hh = h/2;
                const handleRadius = 20;

                if (Math.hypot(localX - (-hw), localY - (-hh)) < handleRadius) { setActiveTextHandle('tl'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (hw), localY - (-hh)) < handleRadius) { setActiveTextHandle('tr'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (-hw), localY - (hh)) < handleRadius) { setActiveTextHandle('bl'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (hw), localY - (hh)) < handleRadius) { setActiveTextHandle('br'); setIsResizingText(true); setLastPos({x, y}); return; }
            }
        }

        for (let i = textObjects.length - 1; i >= 0; i--) {
             const t = textObjects[i];
             const { x: localX, y: localY } = transformToLocal(x, y, t.x, t.y, t.rotation);
             const { w, h } = getTextBoundingBox(ctx, t);
             // Even if text is empty, check bounding box
             if (localX >= -w/2 && localX <= w/2 && localY >= -h/2 && localY <= h/2) {
                 setSelectedTextId(t.id);
                 setIsDragging(true);
                 setLastPos({ x, y });
                 return;
             }
        }
        return; 
    }

    // --- 2. Image Interaction (Move Mode) ---
    if (mode === 'move') {
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;
        const { x: localX, y: localY } = transformToLocal(x, y, cx, cy, rotation);
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const hw = drawnW / 2;
        const hh = drawnH / 2;
        const handleRadius = 25; 

        if (Math.hypot(localX - (-hw), localY - (-hh)) < handleRadius) { setActiveImageHandle('tl'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (hw), localY - (-hh)) < handleRadius) { setActiveImageHandle('tr'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (-hw), localY - (hh)) < handleRadius) { setActiveImageHandle('bl'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (hw), localY - (hh)) < handleRadius) { setActiveImageHandle('br'); setIsResizingImage(true); setLastPos({x, y}); return; }

        setIsDragging(true);
        setLastPos({ x, y });
        return;
    }

    // --- 3. Tool Modes ---
    if (mode === 'wand' || mode === 'restore' || mode === 'eraser') {
       addToHistory({});
       if (mode === 'wand') applyMagicWand(x, y);
       else if (mode === 'eraser') applyEraser(x, y);
       else if (mode === 'restore') applyRestore(x, y);
       setIsDragging(true);
       setLastPos({ x, y });
    }
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchmove') e.preventDefault();

    if ('touches' in e && e.touches.length === 2 && pinchStartDist !== null) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const scaleFactor = dist / pinchStartDist;
        const newScale = Math.max(0.01, pinchStartScale * scaleFactor);
        setScale(newScale);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    setCursorPos({ x, y });

    if (isResizingText && selectedTextId) {
        const t = textObjects.find(t => t.id === selectedTextId);
        if (t) {
            const dist = Math.hypot(x - t.x, y - t.y);
            const prevDist = Math.hypot(lastPos.x - t.x, lastPos.y - t.y);
            const scaleFactor = dist / prevDist;
            const newSize = Math.min(200, Math.max(10, t.fontSize * scaleFactor));
            handleUpdateText(selectedTextId, { fontSize: newSize });
        }
        setLastPos({ x, y });
        return;
    }

    if (isResizingImage) {
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;
        const dist = Math.hypot(x - cx, y - cy);
        const prevDist = Math.hypot(lastPos.x - cx, lastPos.y - cy);
        const scaleFactor = dist / prevDist;
        const newScale = Math.min(3.0, Math.max(0.01, scale * scaleFactor));
        setScale(newScale);
        setLastPos({ x, y });
        return;
    }

    if (!isDragging) return;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'text' && selectedTextId) {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      handleUpdateText(selectedTextId, { 
          x: textObjects.find(t => t.id === selectedTextId)!.x + dx,
          y: textObjects.find(t => t.id === selectedTextId)!.y + dy
      });
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    } else if (mode === 'restore') {
      applyRestore(x, y);
    }
    setLastPos({ x, y });
  };

  const handlePointerUp = () => {
    if (isDragging && mode === 'move') addToHistory({});
    if (isResizingImage) addToHistory({ scale });
    if (isResizingText && selectedTextId) handleTextChangeComplete();

    setIsDragging(false);
    setIsResizingText(false);
    setIsResizingImage(false);
    setActiveTextHandle(null);
    setActiveImageHandle(null);
    setPinchStartDist(null);
    setPinchStartAngle(null);
  };

  const handlePointerLeave = () => {
      setCursorPos(null);
      handlePointerUp();
  };

  const startZoom = (direction: 'in' | 'out') => {
      const step = 0.05;
      if (direction === 'in') setViewZoom(z => Math.min(3, z + step));
      else setViewZoom(z => Math.max(0.5, z - step));

      zoomIntervalRef.current = window.setInterval(() => {
         setViewZoom(z => {
             const ns = direction === 'in' ? z + step : Math.max(0.5, z - step);
             return ns;
         });
      }, 50);
  };
  const stopZoom = () => {
      if (zoomIntervalRef.current) {
          clearInterval(zoomIntervalRef.current);
          zoomIntervalRef.current = null;
      }
  };

  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' }, 
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#ff00ff', label: 'マゼンタ', color: 'bg-[#ff00ff]' },
    { value: '#60a5fa', label: '青', color: 'bg-[#60a5fa]' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#16a34a', label: '緑', color: 'bg-[#16a34a]' },
    { value: '#f97316', label: 'オレンジ', color: 'bg-[#f97316]' },
  ];

  const fontOptions = [
      { value: 'M PLUS Rounded 1c', label: '丸ゴシック' },
      { value: 'Noto Sans JP', label: 'ゴシック' },
      { value: 'Noto Serif JP', label: '明朝' },
  ];

  const textColorOptions = ['#000000', '#FFFFFF', '#ef4444', '#3b82f6', '#10b981', '#f97316', '#ec4899', '#4b3621'];

  const selectedText = textObjects.find(t => t.id === selectedTextId);

  // Robust Slider Component
  const ControlSlider = ({ label, value, min, max, step = 1, onChange, onCommit, unit = '' }: any) => {
      const intervalRef = useRef<number | null>(null);
      const timeoutRef = useRef<number | null>(null);
      const localValue = useRef(value);

      useEffect(() => {
          localValue.current = value;
      }, [value]);

      const cleanup = () => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
          if (intervalRef.current) clearInterval(intervalRef.current);
          timeoutRef.current = null;
          intervalRef.current = null;
      };

      const handlePointerDown = (e: React.PointerEvent, direction: 1 | -1) => {
          e.preventDefault();
          e.currentTarget.setPointerCapture(e.pointerId); 

          cleanup();

          const update = () => {
             let next = localValue.current + (step * direction);
             next = Math.min(max, Math.max(min, next));

             if (step < 1) next = parseFloat(next.toFixed(2));
             else next = Math.round(next);

             localValue.current = next;
             onChange(next);
          };

          // Immediate update
          update();

          // Schedule repeat with delay
          timeoutRef.current = window.setTimeout(() => {
              intervalRef.current = window.setInterval(update, 100);
          }, 400);
      };

      const handlePointerUp = (e: React.PointerEvent) => {
          e.preventDefault();
          e.currentTarget.releasePointerCapture(e.pointerId);
          cleanup();
          if (onCommit) onCommit();
      };

      return (
        <div className="flex items-center gap-2 w-full">
            <span className="text-xs text-gray-500 w-12 shrink-0">{label}</span>
            <button 
                onPointerDown={(e) => handlePointerDown(e, -1)}
                onPointerUp={handlePointerUp}
                className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600 active:bg-gray-300 touch-none select-none cursor-pointer"
            ><Minus size={14}/></button>
            <input 
                type="range" 
                min={min} 
                max={max} 
                step={step}
                value={value} 
                onChange={(e) => {
                    const v = Number(e.target.value);
                    localValue.current = v;
                    onChange(v);
                }}
                onMouseUp={onCommit}
                onTouchEnd={onCommit}
                className="flex-1 accent-primary-500 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer"
            />
            <button 
                onPointerDown={(e) => handlePointerDown(e, 1)}
                onPointerUp={handlePointerUp}
                className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600 active:bg-gray-300 touch-none select-none cursor-pointer"
            ><Plus size={14}/></button>
            {unit && <span className="text-xs text-gray-400 w-8 text-right font-mono">{step < 1 ? value.toFixed(2) : Math.round(value)}{unit}</span>}
        </div>
      );
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col max-h-[95vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
          <h3 className="font-bold text-gray-700">スタンプ編集 ({targetWidth}x{targetHeight})</h3>
          <div className="flex items-center gap-2">
               <div className="flex items-center gap-1 bg-white p-1 rounded-lg border border-gray-200 mr-2 md:mr-4">
                    <span className="hidden md:inline text-xs text-gray-400 font-bold px-1">背景色</span>
                    {backgroundOptions.map(opt => (
                        <button
                            key={opt.value}
                            onClick={() => setPreviewBg(opt.value)}
                            className={`w-5 h-5 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                            title={opt.label}
                            style={opt.value === 'checker' ? {
                                backgroundImage: `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')`
                            } : {}}
                        />
                    ))}
                </div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
          </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col">
            {/* Toolbar Top */}
            <div className="p-2 bg-gray-50 border-b flex flex-wrap justify-center gap-2 md:gap-4 items-center">
                 <div className="flex items-center gap-1 md:gap-2 bg-white px-2 py-1 rounded shadow-sm">
                    <span className="text-xs text-gray-500 hidden sm:inline">表示倍率:</span>
                    <button 
                        onMouseDown={() => startZoom('out')} 
                        onMouseUp={stopZoom} 
                        onMouseLeave={stopZoom}
                        onTouchStart={() => startZoom('out')}
                        onTouchEnd={stopZoom}
                        className="p-1 hover:bg-gray-100 rounded touch-none"
                    ><ZoomOut size={16}/></button>
                    <span className="text-sm font-mono w-10 text-center">{(viewZoom * 100).toFixed(0)}%</span>
                    <button 
                        onMouseDown={() => startZoom('in')} 
                        onMouseUp={stopZoom} 
                        onMouseLeave={stopZoom}
                        onTouchStart={() => startZoom('in')}
                        onTouchEnd={stopZoom}
                        className="p-1 hover:bg-gray-100 rounded touch-none"
                    ><ZoomIn size={16}/></button>
                 </div>

                 <div className="flex items-center gap-1">
                     <button onClick={undo} disabled={historyIndex <= 0} className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"><Undo size={18} /></button>
                     <button onClick={redo} disabled={historyIndex >= history.length - 1} className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"><Redo size={18} /></button>
                 </div>

                 {onReCrop && (
                    <button onClick={onReCrop} className="flex items-center gap-1 text-xs bg-white text-gray-700 px-3 py-1.5 rounded shadow-sm hover:bg-gray-100 border border-gray-200">
                        <RotateCw size={14} /> <span className="hidden sm:inline">再切り出し</span>
                    </button>
                 )}
            </div>

            {/* Scrollable Canvas Area */}
            <div className="flex-1 overflow-auto bg-gray-100 flex p-8">
                <div 
                    className="relative shadow-md border border-gray-200 bg-white m-auto" 
                    style={{ 
                        width: targetWidth * viewZoom, 
                        height: targetHeight * viewZoom,
                        flexShrink: 0 
                    }}
                >
                    <canvas 
                    ref={canvasRef}
                    width={targetWidth}
                    height={targetHeight}
                    className={`origin-top-left ${mode === 'move' ? 'cursor-move' : (mode === 'text' ? 'cursor-text' : 'cursor-crosshair')} touch-none`}
                    style={{
                        transform: `scale(${viewZoom})`,
                        width: targetWidth,
                        height: targetHeight
                    }}
                    onMouseDown={handlePointerDown}
                    onMouseMove={handlePointerMove}
                    onMouseUp={handlePointerUp}
                    onMouseLeave={handlePointerLeave}
                    onTouchStart={handlePointerDown}
                    onTouchMove={handlePointerMove}
                    onTouchEnd={handlePointerUp}
                    />
                </div>
            </div>
        </div>

        {/* Footer Tools */}
        <div className="p-4 border-t bg-white rounded-b-xl shrink-0 flex flex-col gap-4 max-h-[50vh] overflow-y-auto">

             {/* Text Edit Panel */}
             {mode === 'text' && selectedText && (
                 <div className="bg-blue-50 p-3 rounded-lg border border-blue-100 flex flex-col gap-3 animate-fade-in">
                     <div className="flex items-center gap-2">
                         <input 
                            type="text" 
                            value={selectedText.text}
                            onChange={(e) => handleUpdateText(selectedText.id, { text: e.target.value })}
                            className="flex-1 border-gray-300 rounded text-sm px-2 py-1"
                            placeholder="テキストを入力"
                         />
                         <button onClick={handleDeleteText} className="text-red-500 p-1 hover:bg-red-100 rounded">
                             <Trash2 size={18} />
                         </button>
                     </div>
                     <div className="flex flex-wrap items-center gap-4">
                         <select 
                            value={selectedText.fontFamily}
                            onChange={(e) => handleUpdateText(selectedText.id, { fontFamily: e.target.value })}
                            className="text-xs border-gray-300 rounded"
                         >
                             {fontOptions.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
                         </select>

                         <button 
                            onClick={() => handleUpdateText(selectedText.id, { isVertical: !selectedText.isVertical })}
                            className={`flex items-center gap-1 text-xs px-2 py-1 rounded border ${selectedText.isVertical ? 'bg-blue-200 border-blue-300' : 'bg-white border-gray-300'}`}
                         >
                             {selectedText.isVertical ? <AlignVerticalJustifyCenter size={14}/> : <AlignHorizontalJustifyCenter size={14}/>}
                             {selectedText.isVertical ? '縦' : '横'}
                         </button>

                         <button 
                            onClick={() => handleUpdateText(selectedText.id, { zIndex: selectedText.zIndex === 'back' ? 'front' : 'back' })}
                            className={`flex items-center gap-1 text-xs px-2 py-1 rounded border ${selectedText.zIndex === 'back' ? 'bg-blue-200 border-blue-300' : 'bg-white border-gray-300'}`}
                         >
                             <Layers size={14}/>
                             {selectedText.zIndex === 'back' ? '背面' : '前面'}
                         </button>

                         {/* Colors */}
                         <div className="flex items-center gap-2">
                             <span className="text-xs text-gray-500">色</span>
                             <div className="flex gap-1 items-center">
                                 {textColorOptions.map(c => (
                                     <button
                                        key={c}
                                        onClick={() => handleUpdateText(selectedText.id, { color: c })}
                                        className={`w-5 h-5 rounded-full border border-gray-300 ${selectedText.color === c ? 'ring-2 ring-blue-500' : ''}`}
                                        style={{ backgroundColor: c }}
                                     />
                                 ))}
                                 <label className="w-5 h-5 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.color}
                                        onChange={(e) => handleUpdateText(selectedText.id, { color: e.target.value })}
                                     />
                                 </label>
                             </div>
                         </div>
                     </div>

                     <div className="flex flex-col gap-2 pt-2 border-t border-blue-200/50">
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                              <ControlSlider 
                                label="サイズ" 
                                value={selectedText.fontSize} 
                                min={10} max={200} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { fontSize: val })}
                                onCommit={handleTextChangeComplete}
                              />
                              <ControlSlider 
                                label="回転" 
                                value={selectedText.rotation} 
                                min={-180} max={180} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { rotation: val })}
                                onCommit={handleTextChangeComplete}
                                unit="°"
                              />
                          </div>

                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                               <ControlSlider 
                                label="カーブ" 
                                value={selectedText.curvature} 
                                min={-100} max={100} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { curvature: val })}
                                onCommit={handleTextChangeComplete}
                              />

                              <div className="flex items-center gap-2 w-full">
                                    <span className="text-xs text-gray-500 w-12 shrink-0">縁取り</span>
                                    <ControlSlider 
                                        label="" 
                                        value={selectedText.outlineWidth} 
                                        min={0} max={30} step={1}
                                        onChange={(val: number) => handleUpdateText(selectedText.id, { outlineWidth: val })}
                                        onCommit={handleTextChangeComplete}
                                    />
                                    <label className="w-5 h-5 shrink-0 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500 ml-1">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.outlineColor}
                                        onChange={(e) => handleUpdateText(selectedText.id, { outlineColor: e.target.value })}
                                     />
                                    </label>
                              </div>
                          </div>
                     </div>
                 </div>
             )}

             {/* Move Mode Image Controls */}
             {mode === 'move' && (
                 <div className="bg-gray-50 p-3 rounded-lg border border-gray-200 flex flex-col gap-2">
                     <span className="text-xs font-bold text-gray-500 mb-1">画像操作</span>
                     <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <ControlSlider 
                            label="サイズ" 
                            value={Number(scale.toFixed(2))} 
                            min={0.1} max={3.0} step={0.01}
                            onChange={(val: number) => setScale(val)}
                            onCommit={() => addToHistory({ scale })}
                        />
                        <ControlSlider 
                            label="回転" 
                            value={Math.round(rotation)} 
                            min={-180} max={180} step={1}
                            onChange={(val: number) => setRotation(val)}
                            onCommit={() => addToHistory({ rotation })}
                            unit="°"
                        />
                     </div>
                 </div>
             )}

             {/* Tolerance Slider */}
             {(mode === 'wand' || mode === 'eraser') && originalImage && (
                <div className="flex items-center gap-4 bg-yellow-50 p-3 rounded-lg border border-yellow-100">
                    <div className="flex items-center gap-2 text-yellow-700 font-bold text-sm min-w-[120px]">
                        <Sliders size={16} />
                        背景除去
                    </div>
                    <input 
                        type="range" 
                        min="1" 
                        max="100" 
                        value={tolerance} 
                        onChange={handleToleranceChange}
                        className="w-full accent-yellow-500"
                    />
                </div>
             )}

             <div className="flex flex-wrap gap-4 justify-center items-center">
                 {/* Mode Selection */}
                 <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg overflow-x-auto max-w-full">
                    <button 
                    onClick={() => setMode('move')} 
                    className={`p-2 rounded ${mode === 'move' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="画像移動"
                    >
                    <Move size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('text')} 
                    className={`p-2 rounded ${mode === 'text' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="文字入れ"
                    >
                    <Type size={20} />
                    </button>
                    <div className="w-px h-6 bg-gray-300 mx-1"></div>
                    <button 
                    onClick={() => setMode('wand')} 
                    className={`p-2 rounded ${mode === 'wand' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="追加透過"
                    >
                    <Wand2 size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('eraser')} 
                    className={`p-2 rounded ${mode === 'eraser' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="消しゴム"
                    >
                    <Eraser size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('restore')} 
                    disabled={!originalImage}
                    className={`p-2 rounded ${mode === 'restore' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'} disabled:opacity-30`}
                    title="復元"
                    >
                    <Pencil size={20} />
                    </button>

                    {/* Integrated Size Slider for Brush */}
                    {(mode === 'eraser' || mode === 'restore') && (
                        <>
                            <div className="w-px h-6 bg-gray-300 mx-1"></div>
                            <input 
                            type="range" 
                            min="5" 
                            max="50" 
                            value={eraserSize} 
                            onChange={(e) => setEraserSize(Number(e.target.value))} 
                            className="w-20 accent-primary-500"
                            />
                        </>
                    )}
                 </div>

                 {/* Text Add Button */}
                 {mode === 'text' && (
                     <button 
                        onClick={handleAddText}
                        className="bg-blue-600 text-white px-3 py-2 rounded-lg shadow font-bold text-sm flex items-center gap-1 hover:bg-blue-700"
                     >
                         <Plus size={16} /> 文字追加
                     </button>
                 )}

                <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                    <button 
                        onClick={() => {
                            addToHistory({});
                            setScale(initialScale ?? stamp.scale);
                            setRotation(initialRotation ?? stamp.rotation ?? 0);
                            setOffset(initialOffset ?? {x:0, y:0});
                            setTolerance(stamp.currentTolerance || 50);
                            setWorkingDataUrl(stamp.dataUrl); 
                            setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
                        }}
                        className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                    >
                        <RotateCcw size={14} /> <span className="hidden sm:inline">リセット</span>
                    </button>
                </div>
             </div>

             <div className="flex justify-end gap-3 pt-2 border-t border-dashed">
                <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
                <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
                    <Check size={18} /> 完了
                </button>
             </div>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { Stamp, TextObject, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { ZoomIn, ZoomOut, Move, Eraser, Check, X, RotateCcw, Wand2, Palette, Pencil, Sliders, RotateCw, Undo, Redo, Type, Trash2, AlignVerticalJustifyCenter, AlignHorizontalJustifyCenter, Plus, Layers, MousePointer2, Minus } from 'lucide-react';
import { drawTextOnCanvas } from '../lib/zipService';
import { reprocessStampWithTolerance } from '../lib/imageProcessing';

interface Props {
  stamp: Stamp;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStamp: Stamp) => void;
  onReCrop?: () => void; 
  initialPreviewBg?: string; 
  targetWidth?: number;
  targetHeight?: number;
  initialScale?: number;
  initialRotation?: number;
  initialOffset?: { x: number, y: number };
  initialTextObjects?: TextObject[]; 
}

interface HistoryState {
    scale: number;
    rotation: number;
    offset: { x: number, y: number };
    dataUrl: string;
    tolerance: number;
    textObjects: TextObject[];
}

export const StampEditorModal: React.FC<Props> = ({ 
  stamp, 
  isOpen, 
  onClose, 
  onSave, 
  onReCrop,
  initialPreviewBg = 'checker',
  targetWidth = TARGET_WIDTH,
  targetHeight = TARGET_HEIGHT,
  initialScale,
  initialRotation,
  initialOffset,
  initialTextObjects
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Image State
  const [scale, setScale] = useState(initialScale ?? stamp.scale);
  const [rotation, setRotation] = useState(initialRotation ?? stamp.rotation ?? 0);
  const [offset, setOffset] = useState(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });

  // Text State
  const [textObjects, setTextObjects] = useState<TextObject[]>(initialTextObjects ?? stamp.textObjects ?? []);
  const [selectedTextId, setSelectedTextId] = useState<string | null>(null);

  // History State
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Editor View state
  const [viewZoom, setViewZoom] = useState(1);
  const [previewBg, setPreviewBg] = useState(initialPreviewBg);

  const [mode, setMode] = useState<'move' | 'eraser' | 'wand' | 'restore' | 'text'>('move');
  const [isDragging, setIsDragging] = useState(false);
  const [isResizingText, setIsResizingText] = useState(false);

  // Cursor visual state
  const [cursorPos, setCursorPos] = useState<{x: number, y: number} | null>(null);
  const [lastPos, setLastPos] = useState({ x: 0, y: 0 });
  const [eraserSize, setEraserSize] = useState(20);

  const [activeTextHandle, setActiveTextHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  // Pinch & Resize State
  const [pinchStartDist, setPinchStartDist] = useState<number | null>(null);
  const [pinchStartScale, setPinchStartScale] = useState<number>(1);
  const [pinchStartAngle, setPinchStartAngle] = useState<number | null>(null);
  const [pinchStartRotation, setPinchStartRotation] = useState<number>(0);

  // Image Resizing State
  const [isResizingImage, setIsResizingImage] = useState(false);
  const [activeImageHandle, setActiveImageHandle] = useState<'tl' | 'tr' | 'bl' | 'br' | null>(null);

  const [tolerance, setTolerance] = useState(stamp.currentTolerance || 50);

  const [workingDataUrl, setWorkingDataUrl] = useState(stamp.dataUrl);
  const [originalImage, setOriginalImage] = useState<HTMLImageElement | null>(null);

  // Interval ref for continuous button press
  const zoomIntervalRef = useRef<number | null>(null);

  // Debounce for tolerance
  const toleranceTimeoutRef = useRef<number | null>(null);
  // Edit canvas for eraser/restore operations to avoid creating new images constantly
  const editCanvasRef = useRef<HTMLCanvasElement | null>(null);

  // Cleanup zoom interval on unmount
  useEffect(() => {
      return () => {
          if (zoomIntervalRef.current) clearInterval(zoomIntervalRef.current);
      };
  }, []);

  useEffect(() => {
    if (isOpen) {
      setScale(initialScale ?? stamp.scale);
      setRotation(initialRotation ?? stamp.rotation ?? 0);
      setOffset(initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY });
      setWorkingDataUrl(stamp.dataUrl);
      setMode('move');
      setViewZoom(1);
      setTolerance(stamp.currentTolerance || 50);
      setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
      setSelectedTextId(null);

      const initialState = {
          scale: initialScale ?? stamp.scale,
          rotation: initialRotation ?? stamp.rotation ?? 0,
          offset: initialOffset ?? { x: stamp.offsetX, y: stamp.offsetY },
          dataUrl: stamp.dataUrl,
          tolerance: stamp.currentTolerance || 50,
          textObjects: initialTextObjects ?? stamp.textObjects ?? []
      };
      setHistory([initialState]);
      setHistoryIndex(0);

      if (stamp.originalDataUrl) {
          const img = new Image();
          img.src = stamp.originalDataUrl;
          img.onload = () => setOriginalImage(img);
      } else {
          setOriginalImage(null);
      }
    }
  }, [isOpen, stamp, initialScale, initialRotation, initialOffset, initialTextObjects]);

  useEffect(() => {
    if (!isOpen || !canvasRef.current) return;
    drawCanvas();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, scale, rotation, offset, workingDataUrl, previewBg, targetWidth, targetHeight, cursorPos, mode, eraserSize, textObjects, selectedTextId]); 

  const addToHistory = (newState: Partial<HistoryState>) => {
      const currentState = {
          scale,
          rotation,
          offset,
          dataUrl: workingDataUrl,
          tolerance,
          textObjects,
          ...newState
      };

      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(currentState);
      if (newHistory.length > 20) newHistory.shift();
      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);
  };

  const undo = () => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setScale(prevState.scale);
          setRotation(prevState.rotation);
          setOffset(prevState.offset);
          setWorkingDataUrl(prevState.dataUrl);
          setTolerance(prevState.tolerance);
          setTextObjects(prevState.textObjects);
          setHistoryIndex(prevIndex);
      }
  };

  const redo = () => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setScale(nextState.scale);
          setRotation(nextState.rotation);
          setOffset(nextState.offset);
          setWorkingDataUrl(nextState.dataUrl);
          setTolerance(nextState.tolerance);
          setTextObjects(nextState.textObjects);
          setHistoryIndex(nextIndex);
      }
  };

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBackground(ctx, canvas.width, canvas.height);

    const img = new Image();
    img.onload = () => {
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const cx = canvas.width / 2 + offset.x;
        const cy = canvas.height / 2 + offset.y;

        // 1. Draw Back Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex === 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // 2. Draw Image
        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);

        // Draw Image Handles (Only in Move Mode)
        if (mode === 'move') {
            const hw = drawnW / 2;
            const hh = drawnH / 2;
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
            ctx.strokeRect(-hw, -hh, drawnW, drawnH);

            const handleSize = 12; // Visual size
            ctx.fillStyle = '#ffffff';
            // Corners
            const corners = [
                { x: -hw, y: -hh }, { x: hw, y: -hh },
                { x: -hw, y: hh }, { x: hw, y: hh }
            ];
            corners.forEach(c => {
                ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
                ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
            });
        }
        ctx.restore();

        // 3. Draw Front Text
        textObjects.forEach(textObj => {
             if (textObj.zIndex !== 'back') {
                 drawTextWithSelection(ctx, textObj);
             }
        });

        // Border
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, canvas.width, canvas.height);

        // Draw Eraser/Wand Cursor
        if ((mode === 'eraser' || mode === 'restore') && cursorPos) {
            ctx.beginPath();
            ctx.arc(cursorPos.x, cursorPos.y, eraserSize / 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 0.4;
            ctx.stroke();
        }
    };
    img.src = workingDataUrl;
  };

  const getTextBoundingBox = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      ctx.font = `bold ${textObj.fontSize}px '${textObj.fontFamily}'`;
      const lines = textObj.text.split('\n');
      const lineHeight = textObj.fontSize * 1.2;

      let w = 0;
      let h = 0;

      if (textObj.text.length === 0) {
          // Default box for empty text
          w = 40;
          h = 40;
      } else if (textObj.isVertical) {
          w = lineHeight * lines.length;
          const maxChars = Math.max(...lines.map(l => l.length));
          h = textObj.fontSize * maxChars;
      } else {
          const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
          w = maxW;
          h = lineHeight * lines.length;
      }
      // Add padding for better selection
      return { w: Math.max(20, w + 10), h: Math.max(20, h + 10) };
  };

  const drawTextWithSelection = (ctx: CanvasRenderingContext2D, textObj: TextObject) => {
      drawTextOnCanvas(ctx, textObj);

      if (mode === 'text' && selectedTextId === textObj.id) {
          ctx.save();
          ctx.translate(textObj.x, textObj.y);
          ctx.rotate((textObj.rotation * Math.PI) / 180);

          const { w, h } = getTextBoundingBox(ctx, textObj);
          const hw = w / 2;
          const hh = h / 2;

          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 1.5;
          ctx.setLineDash([4, 4]);
          ctx.strokeRect(-hw, -hh, w, h);

          ctx.setLineDash([]);
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#3b82f6';
          const handleSize = 10;

          const corners = [
              { x: -hw, y: -hh }, { x: hw, y: -hh },
              { x: -hw, y: hh }, { x: hw, y: hh },
          ];

          corners.forEach(c => {
              ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
              ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
          });

          ctx.restore();
      }
  }

  const drawBackground = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (previewBg === 'checker') {
        const size = 10;
        for(let y=0; y<h; y+=size) {
            for(let x=0; x<w; x+=size) {
                ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                ctx.fillRect(x, y, size, size);
            }
        }
    } else {
        ctx.fillStyle = previewBg;
        ctx.fillRect(0, 0, w, h);
    }
  };

  // --- Logic Helpers ---
  const handleUpdateText = (id: string, updates: Partial<TextObject>) => {
      const newObjects = textObjects.map(t => t.id === id ? { ...t, ...updates } : t);
      setTextObjects(newObjects);
  };

  const handleTextChangeComplete = () => {
      addToHistory({ textObjects });
  };

  const handleAddText = () => {
      if (textObjects.length >= 3) {
          alert("テキストは最大3つまでです");
          return;
      }
      const newText: TextObject = {
          id: Date.now().toString(),
          text: "", // Default is empty
          x: targetWidth / 2,
          y: targetHeight / 2,
          fontSize: 40,
          fontFamily: 'M PLUS Rounded 1c',
          color: '#000000',
          isVertical: false,
          outlineColor: '#ffffff',
          outlineWidth: 4,
          zIndex: 'front',
          rotation: 0,
          curvature: 0
      };
      const newObjects = [...textObjects, newText];
      setTextObjects(newObjects);
      setSelectedTextId(newText.id);
      addToHistory({ textObjects: newObjects });
      setMode('text'); // Switch to text mode automatically
  };

  const handleDeleteText = () => {
      if (!selectedTextId) return;
      const newObjects = textObjects.filter(t => t.id !== selectedTextId);
      setTextObjects(newObjects);
      setSelectedTextId(null);
      addToHistory({ textObjects: newObjects });
  };

  // --- Tool Implementations ---

  const getLocalImageCoords = (canvasX: number, canvasY: number) => {
      const cx = targetWidth / 2 + offset.x;
      const cy = targetHeight / 2 + offset.y;
      const { x: localX, y: localY } = transformToLocal(canvasX, canvasY, cx, cy, rotation);

      const drawnW = stamp.width * scale;
      const drawnH = stamp.height * scale;

      const imgX = (localX + drawnW / 2) / scale;
      const imgY = (localY + drawnH / 2) / scale;

      return { imgX, imgY, inside: (imgX >= 0 && imgX <= stamp.width && imgY >= 0 && imgY <= stamp.height) };
  };

  const prepareEditCanvas = async () => {
      if (!editCanvasRef.current) {
          editCanvasRef.current = document.createElement('canvas');
          editCanvasRef.current.width = stamp.width;
          editCanvasRef.current.height = stamp.height;
      }
      const ctx = editCanvasRef.current.getContext('2d');
      if (!ctx) return null;

      return new Promise<CanvasRenderingContext2D | null>((resolve) => {
          const img = new Image();
          img.onload = () => {
              ctx!.globalCompositeOperation = 'source-over';
              ctx!.clearRect(0, 0, stamp.width, stamp.height);
              ctx!.drawImage(img, 0, 0);
              resolve(ctx);
          };
          img.src = workingDataUrl;
      });
  };

  const applyEraser = async (canvasX: number, canvasY: number) => {
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      if (!inside && (imgX < -50 || imgX > stamp.width + 50 || imgY < -50 || imgY > stamp.height + 50)) return;

      const brushR = (eraserSize / scale) / 2;
      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.arc(imgX, imgY, brushR, 0, Math.PI * 2);
      ctx.fill();

      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const applyRestore = async (canvasX: number, canvasY: number) => {
      if (!originalImage) return;
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      if (!inside && (imgX < -50 || imgX > stamp.width + 50 || imgY < -50 || imgY > stamp.height + 50)) return;

      const brushR = (eraserSize / scale) / 2;
      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      ctx.globalCompositeOperation = 'source-over';
      ctx.save();
      ctx.beginPath();
      ctx.arc(imgX, imgY, brushR, 0, Math.PI * 2);
      ctx.clip();
      ctx.drawImage(originalImage, 0, 0, stamp.width, stamp.height);
      ctx.restore();

      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const applyMagicWand = async (canvasX: number, canvasY: number) => {
      const { imgX, imgY, inside } = getLocalImageCoords(canvasX, canvasY);
      if (!inside) return;

      const ctx = await prepareEditCanvas();
      if (!ctx) return;

      const w = stamp.width;
      const h = stamp.height;
      const imageData = ctx.getImageData(0, 0, w, h);
      const data = imageData.data;

      const startX = Math.floor(imgX);
      const startY = Math.floor(imgY);
      if (startX < 0 || startX >= w || startY < 0 || startY >= h) return;

      const startIdx = (startY * w + startX) * 4;
      const sr = data[startIdx];
      const sg = data[startIdx + 1];
      const sb = data[startIdx + 2];
      const sa = data[startIdx + 3];

      if (sa === 0) return; 

      const tol = 30; 

      const stack: [number, number][] = [[startX, startY]];
      const visited = new Uint8Array(w * h);

      while (stack.length > 0) {
          const [x, y] = stack.pop()!;
          const idx = y * w + x;
          if (visited[idx]) continue;

          const pIdx = idx * 4;
          const r = data[pIdx];
          const g = data[pIdx+1];
          const b = data[pIdx+2];
          const a = data[pIdx+3];

          if (a === 0) {
              visited[idx] = 1;
              continue;
          }

          const diff = Math.abs(r - sr) + Math.abs(g - sg) + Math.abs(b - sb);
          if (diff < tol) {
              data[pIdx + 3] = 0; 
              visited[idx] = 1;

              if (x > 0) stack.push([x - 1, y]);
              if (x < w - 1) stack.push([x + 1, y]);
              if (y > 0) stack.push([x, y - 1]);
              if (y < h - 1) stack.push([x, y + 1]);
          }
      }

      ctx.putImageData(imageData, 0, 0);
      setWorkingDataUrl(editCanvasRef.current!.toDataURL());
  };

  const handleToleranceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const newVal = Number(e.target.value);
      setTolerance(newVal);

      if (toleranceTimeoutRef.current) {
          clearTimeout(toleranceTimeoutRef.current);
      }

      toleranceTimeoutRef.current = window.setTimeout(async () => {
          if (stamp.originalDataUrl) {
              try {
                  const newDataUrl = await reprocessStampWithTolerance(stamp.originalDataUrl, newVal);
                  setWorkingDataUrl(newDataUrl);
              } catch (err) {
                  console.error("Failed to reprocess", err);
              }
          }
      }, 300);
  };

  const handleSave = () => {
      const updatedStamp: Stamp = {
          ...stamp,
          scale,
          rotation,
          offsetX: offset.x,
          offsetY: offset.y,
          dataUrl: workingDataUrl,
          textObjects,
          currentTolerance: tolerance
      };
      onSave(updatedStamp);
      onClose();
  };


  // --- Pointer/Touch Events ---

  const getClientCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
      if ('touches' in e) {
          return { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else {
          return { x: (e as React.MouseEvent).clientX, y: (e as React.MouseEvent).clientY };
      }
  };

  const transformToLocal = (px: number, py: number, cx: number, cy: number, rot: number) => {
      const dx = px - cx;
      const dy = py - cy;
      const rad = -(rot * Math.PI) / 180;
      const rx = dx * Math.cos(rad) - dy * Math.sin(rad);
      const ry = dx * Math.sin(rad) + dy * Math.cos(rad);
      return { x: rx, y: ry };
  }

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchstart') e.preventDefault();

    // Pinch Check
    if ('touches' in e && e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
        setPinchStartDist(dist);
        setPinchStartScale(scale);
        setPinchStartAngle(angle);
        setPinchStartRotation(rotation);
        setIsDragging(false);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;

    // --- 1. Text Interaction (Priority) ---
    if (mode === 'text') {
        if (selectedTextId) {
            const t = textObjects.find(obj => obj.id === selectedTextId);
            if (t) {
                const { x: localX, y: localY } = transformToLocal(x, y, t.x, t.y, t.rotation);
                const { w, h } = getTextBoundingBox(ctx, t);
                const hw = w/2; const hh = h/2;
                const handleRadius = 20;

                if (Math.hypot(localX - (-hw), localY - (-hh)) < handleRadius) { setActiveTextHandle('tl'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (hw), localY - (-hh)) < handleRadius) { setActiveTextHandle('tr'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (-hw), localY - (hh)) < handleRadius) { setActiveTextHandle('bl'); setIsResizingText(true); setLastPos({x, y}); return; }
                if (Math.hypot(localX - (hw), localY - (hh)) < handleRadius) { setActiveTextHandle('br'); setIsResizingText(true); setLastPos({x, y}); return; }
            }
        }

        for (let i = textObjects.length - 1; i >= 0; i--) {
             const t = textObjects[i];
             const { x: localX, y: localY } = transformToLocal(x, y, t.x, t.y, t.rotation);
             const { w, h } = getTextBoundingBox(ctx, t);
             // Even if text is empty, check bounding box
             if (localX >= -w/2 && localX <= w/2 && localY >= -h/2 && localY <= h/2) {
                 setSelectedTextId(t.id);
                 setIsDragging(true);
                 setLastPos({ x, y });
                 return;
             }
        }
        return; 
    }

    // --- 2. Image Interaction (Move Mode) ---
    if (mode === 'move') {
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;
        const { x: localX, y: localY } = transformToLocal(x, y, cx, cy, rotation);
        const drawnW = stamp.width * scale;
        const drawnH = stamp.height * scale;
        const hw = drawnW / 2;
        const hh = drawnH / 2;
        const handleRadius = 25; 

        if (Math.hypot(localX - (-hw), localY - (-hh)) < handleRadius) { setActiveImageHandle('tl'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (hw), localY - (-hh)) < handleRadius) { setActiveImageHandle('tr'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (-hw), localY - (hh)) < handleRadius) { setActiveImageHandle('bl'); setIsResizingImage(true); setLastPos({x, y}); return; }
        if (Math.hypot(localX - (hw), localY - (hh)) < handleRadius) { setActiveImageHandle('br'); setIsResizingImage(true); setLastPos({x, y}); return; }

        setIsDragging(true);
        setLastPos({ x, y });
        return;
    }

    // --- 3. Tool Modes ---
    if (mode === 'wand' || mode === 'restore' || mode === 'eraser') {
       addToHistory({});
       if (mode === 'wand') applyMagicWand(x, y);
       else if (mode === 'eraser') applyEraser(x, y);
       else if (mode === 'restore') applyRestore(x, y);
       setIsDragging(true);
       setLastPos({ x, y });
    }
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (e.type === 'touchmove') e.preventDefault();

    if ('touches' in e && e.touches.length === 2 && pinchStartDist !== null) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        const scaleFactor = dist / pinchStartDist;
        const newScale = Math.max(0.01, pinchStartScale * scaleFactor);
        setScale(newScale);
        return;
    }

    const { x: clientX, y: clientY } = getClientCoords(e);
    const rect = canvasRef.current!.getBoundingClientRect();
    const x = (clientX - rect.left) / viewZoom;
    const y = (clientY - rect.top) / viewZoom;
    setCursorPos({ x, y });

    if (isResizingText && selectedTextId) {
        const t = textObjects.find(t => t.id === selectedTextId);
        if (t) {
            const dist = Math.hypot(x - t.x, y - t.y);
            const prevDist = Math.hypot(lastPos.x - t.x, lastPos.y - t.y);
            const scaleFactor = dist / prevDist;
            const newSize = Math.min(200, Math.max(10, t.fontSize * scaleFactor));
            handleUpdateText(selectedTextId, { fontSize: newSize });
        }
        setLastPos({ x, y });
        return;
    }

    if (isResizingImage) {
        const cx = targetWidth / 2 + offset.x;
        const cy = targetHeight / 2 + offset.y;
        const dist = Math.hypot(x - cx, y - cy);
        const prevDist = Math.hypot(lastPos.x - cx, lastPos.y - cy);
        const scaleFactor = dist / prevDist;
        const newScale = Math.min(3.0, Math.max(0.01, scale * scaleFactor));
        setScale(newScale);
        setLastPos({ x, y });
        return;
    }

    if (!isDragging) return;

    if (mode === 'move') {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    } else if (mode === 'text' && selectedTextId) {
      const dx = x - lastPos.x;
      const dy = y - lastPos.y;
      handleUpdateText(selectedTextId, { 
          x: textObjects.find(t => t.id === selectedTextId)!.x + dx,
          y: textObjects.find(t => t.id === selectedTextId)!.y + dy
      });
    } else if (mode === 'eraser') {
      applyEraser(x, y);
    } else if (mode === 'restore') {
      applyRestore(x, y);
    }
    setLastPos({ x, y });
  };

  const handlePointerUp = () => {
    if (isDragging && mode === 'move') addToHistory({});
    if (isResizingImage) addToHistory({ scale });
    if (isResizingText && selectedTextId) handleTextChangeComplete();

    setIsDragging(false);
    setIsResizingText(false);
    setIsResizingImage(false);
    setActiveTextHandle(null);
    setActiveImageHandle(null);
    setPinchStartDist(null);
    setPinchStartAngle(null);
  };

  const handlePointerLeave = () => {
      setCursorPos(null);
      handlePointerUp();
  };

  const handleZoomPointerDown = (e: React.PointerEvent, direction: 'in' | 'out') => {
      e.preventDefault();
      e.currentTarget.setPointerCapture(e.pointerId);

      const step = 0.05;
      const update = () => {
          setViewZoom(z => {
             const ns = direction === 'in' ? Math.min(3, z + step) : Math.max(0.5, z - step);
             return ns;
         });
      };

      // Immediate
      update();

      // Clear existing interval just in case
      if (zoomIntervalRef.current) clearInterval(zoomIntervalRef.current);

      // Start continuous zoom after slight delay (if long press needed) or immediately if simple hold behavior desired.
      // Assuming simple hold behavior here for zoom.
      zoomIntervalRef.current = window.setInterval(update, 50);
  };

  const handleZoomPointerUp = (e: React.PointerEvent) => {
      if (zoomIntervalRef.current) {
          clearInterval(zoomIntervalRef.current);
          zoomIntervalRef.current = null;
      }
  };

  const backgroundOptions = [
    { value: 'checker', label: '透明', color: 'bg-gray-200' }, 
    { value: '#ffffff', label: '白', color: 'bg-white border' },
    { value: '#ff00ff', label: 'マゼンタ', color: 'bg-[#ff00ff]' },
    { value: '#60a5fa', label: '青', color: 'bg-[#60a5fa]' },
    { value: '#000000', label: '黒', color: 'bg-black' },
    { value: '#16a34a', label: '緑', color: 'bg-[#16a34a]' },
    { value: '#f97316', label: 'オレンジ', color: 'bg-[#f97316]' },
  ];

  const fontOptions = [
      { value: 'M PLUS Rounded 1c', label: '丸ゴシック' },
      { value: 'Noto Sans JP', label: 'ゴシック' },
      { value: 'Noto Serif JP', label: '明朝' },
  ];

  const textColorOptions = ['#000000', '#FFFFFF', '#ef4444', '#3b82f6', '#10b981', '#f97316', '#ec4899', '#4b3621'];

  const selectedText = textObjects.find(t => t.id === selectedTextId);

  // Robust Slider Component using Pointer Events
  const ControlSlider = ({ label, value, min, max, step = 1, onChange, onCommit, unit = '' }: any) => {
      const intervalRef = useRef<number | null>(null);
      const timeoutRef = useRef<number | null>(null);
      const localValue = useRef(value);

      useEffect(() => {
          localValue.current = value;
      }, [value]);

      const cleanup = () => {
          if (timeoutRef.current) { clearTimeout(timeoutRef.current); timeoutRef.current = null; }
          if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
      };

      // Cleanup on unmount
      useEffect(() => {
          return () => cleanup();
      }, []);

      const handlePointerDown = (e: React.PointerEvent, direction: 1 | -1) => {
          e.preventDefault();
          e.currentTarget.setPointerCapture(e.pointerId); 
          cleanup();

          const update = () => {
             let next = localValue.current + (step * direction);
             next = Math.min(max, Math.max(min, next));

             if (step < 1) next = parseFloat(next.toFixed(2));
             else next = Math.round(next);

             localValue.current = next;
             onChange(next);
          };

          // Immediate update (single click)
          update();

          // Schedule repeat with delay (long press)
          timeoutRef.current = window.setTimeout(() => {
              intervalRef.current = window.setInterval(update, 100);
          }, 400);
      };

      const handlePointerEnd = (e: React.PointerEvent) => {
          cleanup();
          if (onCommit) onCommit();
      };

      return (
        <div className="flex items-center gap-2 w-full">
            <span className="text-xs text-gray-500 w-12 shrink-0">{label}</span>
            <button 
                onPointerDown={(e) => handlePointerDown(e, -1)}
                onPointerUp={handlePointerEnd}
                onPointerLeave={handlePointerEnd}
                onPointerCancel={handlePointerEnd}
                onLostPointerCapture={handlePointerEnd}
                className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600 active:bg-gray-300 touch-none select-none cursor-pointer"
                style={{ touchAction: 'none' }}
            ><Minus size={14}/></button>
            <input 
                type="range" 
                min={min} 
                max={max} 
                step={step}
                value={value} 
                onChange={(e) => {
                    const v = Number(e.target.value);
                    localValue.current = v;
                    onChange(v);
                }}
                onMouseUp={onCommit}
                onTouchEnd={onCommit}
                className="flex-1 accent-primary-500 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer"
            />
            <button 
                onPointerDown={(e) => handlePointerDown(e, 1)}
                onPointerUp={handlePointerEnd}
                onPointerLeave={handlePointerEnd}
                onPointerCancel={handlePointerEnd}
                onLostPointerCapture={handlePointerEnd}
                className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded hover:bg-gray-200 text-gray-600 active:bg-gray-300 touch-none select-none cursor-pointer"
                style={{ touchAction: 'none' }}
            ><Plus size={14}/></button>
            {unit && <span className="text-xs text-gray-400 w-8 text-right font-mono">{step < 1 ? value.toFixed(2) : Math.round(value)}{unit}</span>}
        </div>
      );
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full flex flex-col max-h-[95vh]">
        <div className="p-4 border-b flex justify-between items-center bg-primary-50 rounded-t-xl shrink-0">
          <h3 className="font-bold text-gray-700">スタンプ編集 ({targetWidth}x{targetHeight})</h3>
          <div className="flex items-center gap-2">
               <div className="flex items-center gap-1 bg-white p-1 rounded-lg border border-gray-200 mr-2 md:mr-4">
                    <span className="hidden md:inline text-xs text-gray-400 font-bold px-1">背景色</span>
                    {backgroundOptions.map(opt => (
                        <button
                            key={opt.value}
                            onClick={() => setPreviewBg(opt.value)}
                            className={`w-5 h-5 rounded-full ${opt.color} ${previewBg === opt.value ? 'ring-2 ring-primary-500 ring-offset-1' : ''}`}
                            title={opt.label}
                            style={opt.value === 'checker' ? {
                                backgroundImage: `url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAYAAACNMs+9AAAAAXNSR0IArs4c6QAAAB5JREFUKFNjYCACAAAHOgD///+F8f///4X/09JvAgBwYw/57yQ+jAAAAABJRU5ErkJggg==')`
                            } : {}}
                        />
                    ))}
                </div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition"><X size={20} /></button>
          </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col">
            {/* Toolbar Top */}
            <div className="p-2 bg-gray-50 border-b flex flex-wrap justify-center gap-2 md:gap-4 items-center">
                 <div className="flex items-center gap-1 md:gap-2 bg-white px-2 py-1 rounded shadow-sm">
                    <span className="text-xs text-gray-500 hidden sm:inline">表示倍率:</span>
                    <button 
                        onPointerDown={(e) => handleZoomPointerDown(e, 'out')} 
                        onPointerUp={handleZoomPointerUp} 
                        onPointerLeave={handleZoomPointerUp}
                        className="p-1 hover:bg-gray-100 rounded touch-none"
                        style={{ touchAction: 'none' }}
                    ><ZoomOut size={16}/></button>
                    <span className="text-sm font-mono w-10 text-center">{(viewZoom * 100).toFixed(0)}%</span>
                    <button 
                        onPointerDown={(e) => handleZoomPointerDown(e, 'in')} 
                        onPointerUp={handleZoomPointerUp} 
                        onPointerLeave={handleZoomPointerUp}
                        className="p-1 hover:bg-gray-100 rounded touch-none"
                        style={{ touchAction: 'none' }}
                    ><ZoomIn size={16}/></button>
                 </div>

                 <div className="flex items-center gap-1">
                     <button onClick={undo} disabled={historyIndex <= 0} className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"><Undo size={18} /></button>
                     <button onClick={redo} disabled={historyIndex >= history.length - 1} className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-white text-gray-600"><Redo size={18} /></button>
                 </div>

                 {onReCrop && (
                    <button onClick={onReCrop} className="flex items-center gap-1 text-xs bg-white text-gray-700 px-3 py-1.5 rounded shadow-sm hover:bg-gray-100 border border-gray-200">
                        <RotateCw size={14} /> <span className="hidden sm:inline">再切り出し</span>
                    </button>
                 )}
            </div>

            {/* Scrollable Canvas Area */}
            <div className="flex-1 overflow-auto bg-gray-100 flex p-8">
                <div 
                    className="relative shadow-md border border-gray-200 bg-white m-auto" 
                    style={{ 
                        width: targetWidth * viewZoom, 
                        height: targetHeight * viewZoom,
                        flexShrink: 0 
                    }}
                >
                    <canvas 
                    ref={canvasRef}
                    width={targetWidth}
                    height={targetHeight}
                    className={`origin-top-left ${mode === 'move' ? 'cursor-move' : (mode === 'text' ? 'cursor-text' : 'cursor-crosshair')} touch-none`}
                    style={{
                        transform: `scale(${viewZoom})`,
                        width: targetWidth,
                        height: targetHeight
                    }}
                    onMouseDown={handlePointerDown}
                    onMouseMove={handlePointerMove}
                    onMouseUp={handlePointerUp}
                    onMouseLeave={handlePointerLeave}
                    onTouchStart={handlePointerDown}
                    onTouchMove={handlePointerMove}
                    onTouchEnd={handlePointerUp}
                    />
                </div>
            </div>
        </div>

        {/* Footer Tools */}
        <div className="p-4 border-t bg-white rounded-b-xl shrink-0 flex flex-col gap-4 max-h-[50vh] overflow-y-auto">

             {/* Text Edit Panel */}
             {mode === 'text' && selectedText && (
                 <div className="bg-blue-50 p-3 rounded-lg border border-blue-100 flex flex-col gap-3 animate-fade-in">
                     <div className="flex items-center gap-2">
                         <input 
                            type="text" 
                            value={selectedText.text}
                            onChange={(e) => handleUpdateText(selectedText.id, { text: e.target.value })}
                            className="flex-1 border-gray-300 rounded text-sm px-2 py-1"
                            placeholder="テキストを入力"
                         />
                         <button onClick={handleDeleteText} className="text-red-500 p-1 hover:bg-red-100 rounded">
                             <Trash2 size={18} />
                         </button>
                     </div>
                     <div className="flex flex-wrap items-center gap-4">
                         <select 
                            value={selectedText.fontFamily}
                            onChange={(e) => handleUpdateText(selectedText.id, { fontFamily: e.target.value })}
                            className="text-xs border-gray-300 rounded"
                         >
                             {fontOptions.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
                         </select>

                         <button 
                            onClick={() => handleUpdateText(selectedText.id, { isVertical: !selectedText.isVertical })}
                            className={`flex items-center gap-1 text-xs px-2 py-1 rounded border ${selectedText.isVertical ? 'bg-blue-200 border-blue-300' : 'bg-white border-gray-300'}`}
                         >
                             {selectedText.isVertical ? <AlignVerticalJustifyCenter size={14}/> : <AlignHorizontalJustifyCenter size={14}/>}
                             {selectedText.isVertical ? '縦' : '横'}
                         </button>

                         <button 
                            onClick={() => handleUpdateText(selectedText.id, { zIndex: selectedText.zIndex === 'back' ? 'front' : 'back' })}
                            className={`flex items-center gap-1 text-xs px-2 py-1 rounded border ${selectedText.zIndex === 'back' ? 'bg-blue-200 border-blue-300' : 'bg-white border-gray-300'}`}
                         >
                             <Layers size={14}/>
                             {selectedText.zIndex === 'back' ? '背面' : '前面'}
                         </button>

                         {/* Colors */}
                         <div className="flex items-center gap-2">
                             <span className="text-xs text-gray-500">色</span>
                             <div className="flex gap-1 items-center">
                                 {textColorOptions.map(c => (
                                     <button
                                        key={c}
                                        onClick={() => handleUpdateText(selectedText.id, { color: c })}
                                        className={`w-5 h-5 rounded-full border border-gray-300 ${selectedText.color === c ? 'ring-2 ring-blue-500' : ''}`}
                                        style={{ backgroundColor: c }}
                                     />
                                 ))}
                                 <label className="w-5 h-5 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.color}
                                        onChange={(e) => handleUpdateText(selectedText.id, { color: e.target.value })}
                                     />
                                 </label>
                             </div>
                         </div>
                     </div>

                     <div className="flex flex-col gap-2 pt-2 border-t border-blue-200/50">
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                              <ControlSlider 
                                label="サイズ" 
                                value={selectedText.fontSize} 
                                min={10} max={200} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { fontSize: val })}
                                onCommit={handleTextChangeComplete}
                              />
                              <ControlSlider 
                                label="回転" 
                                value={selectedText.rotation} 
                                min={-180} max={180} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { rotation: val })}
                                onCommit={handleTextChangeComplete}
                                unit="°"
                              />
                          </div>

                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                               <ControlSlider 
                                label="カーブ" 
                                value={selectedText.curvature} 
                                min={-100} max={100} step={1}
                                onChange={(val: number) => handleUpdateText(selectedText.id, { curvature: val })}
                                onCommit={handleTextChangeComplete}
                              />

                              <div className="flex items-center gap-2 w-full">
                                    <span className="text-xs text-gray-500 w-12 shrink-0">縁取り</span>
                                    <ControlSlider 
                                        label="" 
                                        value={selectedText.outlineWidth} 
                                        min={0} max={30} step={1}
                                        onChange={(val: number) => handleUpdateText(selectedText.id, { outlineWidth: val })}
                                        onCommit={handleTextChangeComplete}
                                    />
                                    <label className="w-5 h-5 shrink-0 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500 ml-1">
                                     <input 
                                        type="color" 
                                        className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                        value={selectedText.outlineColor}
                                        onChange={(e) => handleUpdateText(selectedText.id, { outlineColor: e.target.value })}
                                     />
                                    </label>
                              </div>
                          </div>
                     </div>
                 </div>
             )}

             {/* Move Mode Image Controls */}
             {mode === 'move' && (
                 <div className="bg-gray-50 p-3 rounded-lg border border-gray-200 flex flex-col gap-2">
                     <span className="text-xs font-bold text-gray-500 mb-1">画像操作</span>
                     <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <ControlSlider 
                            label="サイズ" 
                            value={Number(scale.toFixed(2))} 
                            min={0.1} max={3.0} step={0.01}
                            onChange={(val: number) => setScale(val)}
                            onCommit={() => addToHistory({ scale })}
                        />
                        <ControlSlider 
                            label="回転" 
                            value={Math.round(rotation)} 
                            min={-180} max={180} step={1}
                            onChange={(val: number) => setRotation(val)}
                            onCommit={() => addToHistory({ rotation })}
                            unit="°"
                        />
                     </div>
                 </div>
             )}

             {/* Tolerance Slider */}
             {(mode === 'wand' || mode === 'eraser') && originalImage && (
                <div className="flex items-center gap-4 bg-yellow-50 p-3 rounded-lg border border-yellow-100">
                    <div className="flex items-center gap-2 text-yellow-700 font-bold text-sm min-w-[120px]">
                        <Sliders size={16} />
                        背景除去
                    </div>
                    <input 
                        type="range" 
                        min="1" 
                        max="100" 
                        value={tolerance} 
                        onChange={handleToleranceChange}
                        className="w-full accent-yellow-500"
                    />
                </div>
             )}

             <div className="flex flex-wrap gap-4 justify-center items-center">
                 {/* Mode Selection */}
                 <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg overflow-x-auto max-w-full">
                    <button 
                    onClick={() => setMode('move')} 
                    className={`p-2 rounded ${mode === 'move' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="画像移動"
                    >
                    <Move size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('text')} 
                    className={`p-2 rounded ${mode === 'text' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="文字入れ"
                    >
                    <Type size={20} />
                    </button>
                    <div className="w-px h-6 bg-gray-300 mx-1"></div>
                    <button 
                    onClick={() => setMode('wand')} 
                    className={`p-2 rounded ${mode === 'wand' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="追加透過"
                    >
                    <Wand2 size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('eraser')} 
                    className={`p-2 rounded ${mode === 'eraser' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'}`}
                    title="消しゴム"
                    >
                    <Eraser size={20} />
                    </button>
                    <button 
                    onClick={() => setMode('restore')} 
                    disabled={!originalImage}
                    className={`p-2 rounded ${mode === 'restore' ? 'bg-white shadow text-primary-600' : 'text-gray-500 hover:text-gray-700'} disabled:opacity-30`}
                    title="復元"
                    >
                    <Pencil size={20} />
                    </button>

                    {/* Integrated Size Slider for Brush */}
                    {(mode === 'eraser' || mode === 'restore') && (
                        <>
                            <div className="w-px h-6 bg-gray-300 mx-1"></div>
                            <input 
                            type="range" 
                            min="5" 
                            max="50" 
                            value={eraserSize} 
                            onChange={(e) => setEraserSize(Number(e.target.value))} 
                            className="w-20 accent-primary-500"
                            />
                        </>
                    )}
                 </div>

                 {/* Text Add Button */}
                 {mode === 'text' && (
                     <button 
                        onClick={handleAddText}
                        className="bg-blue-600 text-white px-3 py-2 rounded-lg shadow font-bold text-sm flex items-center gap-1 hover:bg-blue-700"
                     >
                         <Plus size={16} /> 文字追加
                     </button>
                 )}

                <div className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                    <button 
                        onClick={() => {
                            addToHistory({});
                            setScale(initialScale ?? stamp.scale);
                            setRotation(initialRotation ?? stamp.rotation ?? 0);
                            setOffset(initialOffset ?? {x:0, y:0});
                            setTolerance(stamp.currentTolerance || 50);
                            setWorkingDataUrl(stamp.dataUrl); 
                            setTextObjects(initialTextObjects ?? stamp.textObjects ?? []);
                        }}
                        className="flex items-center gap-1 text-xs text-gray-600 px-2 py-1 hover:bg-white rounded"
                    >
                        <RotateCcw size={14} /> <span className="hidden sm:inline">リセット</span>
                    </button>
                </div>
             </div>

             <div className="flex justify-end gap-3 pt-2 border-t border-dashed">
                <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition">キャンセル</button>
                <button onClick={handleSave} className="px-6 py-2 bg-primary-600 text-white font-bold rounded-lg shadow hover:bg-primary-700 transition flex items-center gap-2">
                    <Check size={18} /> 完了
                </button>
             </div>
        </div>
      </div>
    </div>
  );
};

payload.text:
■ 概要
StampEditorModal.tsx が巨大になっているため、今後の機能追加（画像レイヤー・手書き等）に
備えてサブコンポーネントに分離します。また types.ts に今後使う型を先に追加します。
※このステップでは見た目・動作は一切変えないでください。リファクタリングのみです。

■ 1. types.ts に以下の型を追加

// 画像レイヤー（ステップ2で使う）
export interface ImageLayerObject {
  id: string;
  dataUrl: string;       // 透過PNG の base64
  originalWidth: number; // 元画像の幅
  originalHeight: number;// 元画像の高さ
  x: number;             // キャンバス上のX座標（中心基準）
  y: number;             // キャンバス上のY座標（中心基準）
  scale: number;         // 1.0 = 原寸
  rotation: number;      // degrees
  opacity: number;       // 0.0 ~ 1.0
  zIndex: 'front' | 'back';
}

// 手書きストローク（ステップ3で使う）
export interface DrawingStroke {
  id: string;
  points: { x: number; y: number }[];
  color: string;
  width: number;
  opacity: number;
  zIndex: 'front' | 'back';
}

// Stamp インターフェースに以下のプロパティを追加（既存プロパティはそのまま残す）
// Stamp に追加:
//   imageLayers?: ImageLayerObject[];
//   drawingStrokes?: DrawingStroke[];
//   flipH?: boolean;   // 左右反転
//   flipV?: boolean;   // 上下反転

// ExportConfig にも同じものを追加:
//   imageLayers?: ImageLayerObject[];
//   drawingStrokes?: DrawingStroke[];
//   flipH?: boolean;
//   flipV?: boolean;

■ 2. StampEditorModal.tsx のサブコンポーネント分離

components フォルダ内に以下のファイルを新規作成し、
StampEditorModal.tsx から該当部分を切り出してください。

(A) components/editor/ControlSlider.tsx
  - 現在 StampEditorModal 内にある ControlSlider コンポーネントをそのまま移動
  - Props の型を明示的に定義する（any をやめる）：
    interface ControlSliderProps {
      label: string;
      value: number;
      min: number;
      max: number;
      step?: number;   // default 1
      onChange: (value: number) => void;
      onCommit?: () => void;
      unit?: string;
    }
  - export して StampEditorModal から import して使う

(B) components/editor/TextEditPanel.tsx
  - mode === 'text' && selectedText の時に表示される青い編集パネル部分を切り出す
  - Props:
    interface TextEditPanelProps {
      selectedText: TextObject;
      onUpdateText: (id: string, updates: Partial<TextObject>) => void;
      onDeleteText: () => void;
      onCommit: () => void;  // addToHistory 用
    }
  - フォント選択、色選択、縦横切替、前面背面、サイズ/回転/カーブ/縁取りスライダーを含む
  - ControlSlider を import して使う

(C) components/editor/ImageControlPanel.tsx
  - mode === 'move' の時に表示されるグレーの「画像操作」パネルを切り出す
  - Props:
    interface ImageControlPanelProps {
      scale: number;
      rotation: number;
      onScaleChange: (value: number) => void;
      onRotationChange: (value: number) => void;
      onCommit: () => void;
    }
  - ControlSlider を import して使う

(D) components/editor/EditorToolbar.tsx
  - 上部のツールバー（表示倍率ズーム＋ーボタン、Undo/Redo、再切り出しボタン）を切り出す
  - Props:
    interface EditorToolbarProps {
      viewZoom: number;
      onViewZoomChange: (zoom: number) => void;
      historyIndex: number;
      historyLength: number;
      onUndo: () => void;
      onRedo: () => void;
      onReCrop?: () => void;
    }
  - ズームの startZoom / stopZoom ロジックもこのコンポーネント内に含める

(E) components/editor/ModeSelector.tsx
  - 下部のモード切替ボタン群（移動/テキスト/追加透過/消しゴム/復元）と
    消しゴムサイズスライダー、文字追加ボタン、リセットボタンを切り出す
  - Props:
    interface ModeSelectorProps {
      mode: string;
      onModeChange: (mode: 'move' | 'eraser' | 'wand' | 'restore' | 'text') => void;
      eraserSize: number;
      onEraserSizeChange: (size: number) => void;
      hasOriginalImage: boolean;
      onAddText: () => void;
      onReset: () => void;
    }

■ 3. StampEditorModal.tsx の修正

- 上記 (A)〜(E) を import して、元々あった場所にそのまま配置する
- StampEditorModal 自体にはキャンバス描画ロジック、ポインターイベント処理、
  状態管理（useState / useRef）はそのまま残す
- 切り出したのはあくまでUIパーツ（表示とボタン）の部分のみ

■ 4. zipService.ts の描画関数を整理

現在 createFinalImageBlob 内で「背面テキスト→画像→前面テキスト」の順で
描画していますが、今後レイヤーが増えるので描画を1つの関数にまとめてください。

export function renderAllLayers(
  ctx: CanvasRenderingContext2D,
  img: HTMLImageElement,
  config: ExportConfig,
  targetW: number,
  targetH: number
): void {
  ctx.clearRect(0, 0, targetW, targetH);

  const drawnW = img.width * config.scale;
  const drawnH = img.height * config.scale;
  const centerX = targetW / 2;
  const centerY = targetH / 2;

  // --- 背面レイヤー ---
  // 背面テキスト
  if (config.textObjects) {
    config.textObjects.filter(t => t.zIndex === 'back').forEach(t => drawTextOnCanvas(ctx, t));
  }
  // 背面画像レイヤー（将来用・今は空でOK）
  // if (config.imageLayers) { ... }
  // 背面手書き（将来用・今は空でOK）
  // if (config.drawingStrokes) { ... }

  // --- メイン画像 ---
  ctx.save();
  const cx = centerX + config.offsetX;
  const cy = centerY + config.offsetY;
  ctx.translate(cx, cy);
  if (config.rotation) {
    ctx.rotate((config.rotation * Math.PI) / 180);
  }
  // 反転（将来用・今は空でOK）
  // if (config.flipH || config.flipV) {
  //   ctx.scale(config.flipH ? -1 : 1, config.flipV ? -1 : 1);
  // }
  ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);
  ctx.restore();

  // --- 前面レイヤー ---
  // 前面手書き（将来用・今は空でOK）
  // 前面画像レイヤー（将来用・今は空でOK）
  // 前面テキスト
  if (config.textObjects) {
    config.textObjects.filter(t => t.zIndex !== 'back').forEach(t => drawTextOnCanvas(ctx, t));
  }
}

そして createFinalImageBlob 内の描画処理を renderAllLayers の呼び出しに置き換えてください：

img.onload = () => {
  renderAllLayers(ctx, img, config, targetW, targetH);
  canvas.toBlob((blob) => {
    resolve(blob);
  }, 'image/png');
};

StampEditorModal.tsx 内の drawCanvas 関数からも、描画順序が
renderAllLayers と一致するようにしてください（ただし drawCanvas は
エディタ用のUI要素（選択ハンドル、消しゴムカーソル等）の描画も含むので、
完全に renderAllLayers を使う必要はありません。描画順序だけ合わせてください）。

■ 5. 確認事項（重要）

以下を全て確認してください：
- 既存の全機能（移動、拡縮、回転、テキスト編集、消しゴム、復元、
  マジックワンド、ピンチズーム、ドラッグ並べ替え、ZIP書き出し、
  メイン/タブ編集、表示倍率変更）が修正前と同じように動作すること
- TypeScript のコンパイルエラーがないこと
- サブコンポーネントに分離した部分の見た目が変わっていないこと
- ControlSlider の＋ーボタンが以前修正したとおり正常に動作すること
  （タップで1ステップ、長押しで連続、離したら停止）

