■ 概要
作業途中のプロジェクトをブラウザに保存・復元できる機能を追加します。
- 自動保存：編集するたびに自動でIndexedDBに保存
- 手動保存：「保存」ボタンで即座に保存
- 復元：次回アクセス時に「前回の続きから再開しますか？」と確認して復元
- 複数の画像データを含むため、localStorage ではなく IndexedDB を使用します。

■ 1. lib/storage.ts を新規作成

IndexedDB のラッパーモジュールを作成してください。

import { Stamp, SourceImage, ExportConfig, MetaData } from '../types';

// 保存するプロジェクトデータの型
export interface ProjectData {
  version: number; // スキーマバージョン（将来の互換性用）。現在は 1
  savedAt: string; // ISO文字列
  stamps: Stamp[];
  sourceImages: SourceImageData[]; // File は保存できないので変換
  mainConfig: ExportConfig | null;
  tabConfig: ExportConfig | null;
  meta: MetaData;
  globalTolerance: number;
  gapTolerance: number;
  previewBg: string;
}

// File オブジェクトは IndexedDB に直接保存できないので
// Blob + メタ情報に変換して保存する
interface SourceImageData {
  id: string;
  url: string; // base64 DataURL に変換して保存
  blob: Blob;  // File を Blob として保存
  fileName: string;
  fileType: string;
  width: number;
  height: number;
}

const DB_NAME = 'stamp-cutter-db';
const DB_VERSION = 1;
const STORE_NAME = 'projects';
const PROJECT_KEY = 'current'; // 現在は1プロジェクトのみ

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

// SourceImage の File を base64 に変換するヘルパー
function fileToBase64(file: File | Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

// base64 を Blob に戻すヘルパー
function base64ToBlob(base64: string, type: string): Blob {
  const byteString = atob(base64.split(',')[1]);
  const ab = new ArrayBuffer(byteString.length);
  const ia = new Uint8Array(ab);
  for (let i = 0; i < byteString.length; i++) {
    ia[i] = byteString.charCodeAt(i);
  }
  return new Blob([ab], { type });
}

// プロジェクトを保存
export async function saveProject(
  stamps: Stamp[],
  sourceImages: SourceImage[],
  mainConfig: ExportConfig | null,
  tabConfig: ExportConfig | null,
  meta: MetaData,
  globalTolerance: number,
  gapTolerance: number,
  previewBg: string
): Promise<void> {
  try {
    // SourceImage の File を保存可能な形式に変換
    const sourceImageData: SourceImageData[] = await Promise.all(
      sourceImages.map(async (src) => ({
        id: src.id,
        url: await fileToBase64(src.file),
        blob: src.file,
        fileName: src.file.name,
        fileType: src.file.type,
        width: src.width,
        height: src.height,
      }))
    );

    const data: ProjectData = {
      version: 1,
      savedAt: new Date().toISOString(),
      stamps,
      sourceImages: sourceImageData,
      mainConfig,
      tabConfig,
      meta,
      globalTolerance,
      gapTolerance,
      previewBg,
    };

    const db = await openDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.put(data, PROJECT_KEY);

    return new Promise((resolve, reject) => {
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    });
  } catch (err) {
    console.error('プロジェクト保存に失敗:', err);
  }
}

// プロジェクトを読み込み
export async function loadProject(): Promise<ProjectData | null> {
  try {
    const db = await openDB();
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(PROJECT_KEY);

    return new Promise((resolve, reject) => {
      request.onsuccess = () => {
        db.close();
        resolve(request.result || null);
      };
      request.onerror = () => {
        db.close();
        reject(request.error);
      };
    });
  } catch (err) {
    console.error('プロジェクト読み込みに失敗:', err);
    return null;
  }
}

// プロジェクトを削除
export async function deleteProject(): Promise<void> {
  try {
    const db = await openDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.delete(PROJECT_KEY);

    return new Promise((resolve, reject) => {
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    });
  } catch (err) {
    console.error('プロジェクト削除に失敗:', err);
  }
}

// 保存データから SourceImage を復元するヘルパー
export function restoreSourceImages(data: SourceImageData[]): SourceImage[] {
  return data.map(d => {
    const blob = base64ToBlob(d.url, d.fileType);
    const file = new File([blob], d.fileName, { type: d.fileType });
    return {
      id: d.id,
      url: URL.createObjectURL(file),
      file,
      width: d.width,
      height: d.height,
    };
  });
}

// 保存データが存在するか確認
export async function hasExistingProject(): Promise<boolean> {
  const data = await loadProject();
  return data !== null;
}

■ 2. App.tsx に自動保存を追加

import { saveProject, loadProject, deleteProject, restoreSourceImages, hasExistingProject } from './lib/storage';

// 復元ダイアログ用の state を追加
const [showRestoreDialog, setShowRestoreDialog] = useState(false);
const [savedProjectDate, setSavedProjectDate] = useState<string>('');
const [isSaving, setIsSaving] = useState(false);
const [lastSavedAt, setLastSavedAt] = useState<string | null>(null);

// --- アプリ起動時の復元チェック ---
useEffect(() => {
  const checkSavedData = async () => {
    try {
      const data = await loadProject();
      if (data && data.stamps.length > 0) {
        setSavedProjectDate(data.savedAt);
        setShowRestoreDialog(true);
      }
    } catch (err) {
      console.error('復元チェックに失敗:', err);
    }
  };
  checkSavedData();
}, []);

// --- 復元処理 ---
const handleRestore = async () => {
  try {
    const data = await loadProject();
    if (!data) return;

    const restoredSources = restoreSourceImages(data.sourceImages);
    setSourceImages(restoredSources);
    setStamps(data.stamps);
    setMainConfig(data.mainConfig);
    setTabConfig(data.tabConfig);
    setMeta(data.meta);
    setGlobalTolerance(data.globalTolerance);
    setGapTolerance(data.gapTolerance);
    setPreviewBg(data.previewBg);
    setStep(AppStep.EDIT);
    setLastSavedAt(data.savedAt);
  } catch (err) {
    console.error('復元に失敗:', err);
    alert('データの復元に失敗しました');
  }
  setShowRestoreDialog(false);
};

const handleDiscardSave = async () => {
  await deleteProject();
  setShowRestoreDialog(false);
};

// --- 自動保存 ---
// step === EDIT の時に、stamps / mainConfig / tabConfig / meta 等が
// 変更されたら自動保存する（デバウンス付き）
useEffect(() => {
  if (step !== AppStep.EDIT) return;
  if (stamps.length === 0) return;

  const timer = setTimeout(async () => {
    try {
      await saveProject(
        stamps,
        sourceImages,
        mainConfig,
        tabConfig,
        meta,
        globalTolerance,
        gapTolerance,
        previewBg
      );
      setLastSavedAt(new Date().toISOString());
    } catch (err) {
      console.error('自動保存に失敗:', err);
    }
  }, 3000); // 3秒のデバウンス

  return () => clearTimeout(timer);
}, [step, stamps, sourceImages, mainConfig, tabConfig, meta, globalTolerance, gapTolerance, previewBg]);

// --- 手動保存 ---
const handleManualSave = async () => {
  if (stamps.length === 0) return;
  setIsSaving(true);
  try {
    await saveProject(
      stamps,
      sourceImages,
      mainConfig,
      tabConfig,
      meta,
      globalTolerance,
      gapTolerance,
      previewBg
    );
    setLastSavedAt(new Date().toISOString());
  } catch (err) {
    console.error('保存に失敗:', err);
    alert('保存に失敗しました');
  } finally {
    setIsSaving(false);
  }
};

// --- 新規プロジェクト開始 ---
// 既にある handleFileUpload の startProcessing の後、
// もしくは step が EDIT に移行した直後に、
// 自動保存が走るので特別な処理は不要。

■ 3. ヘッダーに保存ボタンと保存状態表示を追加

step === AppStep.EDIT の時のヘッダー内（「画像を追加」ボタンの近く）に
以下を追加：

  {/* 保存ボタン & 状態表示 */}
  <div className="flex items-center gap-2">
    <button
      onClick={handleManualSave}
      disabled={isSaving || stamps.length === 0}
      className="flex items-center gap-1 bg-white border border-gray-300 hover:bg-gray-50 
        text-gray-700 font-bold py-1.5 px-3 rounded-full shadow-sm transition-all 
        text-xs sm:text-sm disabled:opacity-50"
    >
      {isSaving ? (
        <Loader2 size={14} className="animate-spin" />
      ) : (
        <Save size={14} />
      )}
      <span className="hidden sm:inline">保存</span>
    </button>
    {lastSavedAt && (
      <span className="text-xs text-gray-400 hidden md:inline">
        {new Date(lastSavedAt).toLocaleTimeString('ja-JP', { 
          hour: '2-digit', 
          minute: '2-digit' 
        })} 保存済
      </span>
    )}
  </div>

※ Save アイコンは lucide-react から import。既に import 済みなら OK。
※ Loader2 も既に import 済みのはず。

■ 4. 復元確認ダイアログを追加

App.tsx の return 文内（最後のモーダル群の後）に追加：

  {showRestoreDialog && (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 text-center">
        <div className="bg-primary-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
          <Save size={32} className="text-primary-600" />
        </div>
        <h3 className="text-lg font-bold text-gray-800 mb-2">
          保存データが見つかりました
        </h3>
        <p className="text-sm text-gray-500 mb-1">
          前回の作業途中のデータがあります。
        </p>
        <p className="text-xs text-gray-400 mb-6">
          保存日時: {new Date(savedProjectDate).toLocaleString('ja-JP')}
        </p>
        <div className="space-y-3">
          <button
            onClick={handleRestore}
            className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold 
              py-3 rounded-xl shadow transition flex items-center justify-center gap-2"
          >
            <RotateCw size={18} />
            続きから再開する
          </button>
          <button
            onClick={handleDiscardSave}
            className="w-full bg-white border border-gray-300 hover:bg-gray-50 
              text-gray-600 font-bold py-3 rounded-xl shadow-sm transition 
              flex items-center justify-center gap-2"
          >
            <Trash2 size={18} />
            破棄して新しく始める
          </button>
        </div>
      </div>
    </div>
  )}

※ Trash2, RotateCw は既に import 済みのはず。

■ 5. ZIP ダウンロード後の保存データ更新

handleExport 関数の最後（ZIP ダウンロード成功後）に以下を追加：
  // 書き出し後も最新の状態を保存
  await saveProject(stamps, sourceImages, mainConfig, tabConfig, meta, globalTolerance, gapTolerance, previewBg);
  setLastSavedAt(new Date().toISOString());

■ 6. 新規プロジェクト時の保存データクリア

startProcessing 関数の先頭（画像処理開始前）に追加：
  await deleteProject(); // 新規処理開始時に古い保存データをクリア

※ startProcessing を async にする（既に async のはず）

■ 7. ブラウザタブを閉じる前の警告

step === EDIT の時にタブを閉じようとしたら警告を出す：

useEffect(() => {
  if (step !== AppStep.EDIT) return;

  const handleBeforeUnload = (e: BeforeUnloadEvent) => {
    e.preventDefault();
    e.returnValue = '';
  };

  window.addEventListener('beforeunload', handleBeforeUnload);
  return () => window.removeEventListener('beforeunload', handleBeforeUnload);
}, [step]);

■ 8. 確認事項

- 画像をアップロードして編集画面に入った後、3秒程度で自動保存されること
- ヘッダーの「保存」ボタンを押すと即座に保存されること
- 保存後に「○○:○○ 保存済」と表示されること
- ブラウザをリロードすると「保存データが見つかりました」ダイアログが出ること
- 「続きから再開する」を押すと、スタンプ・設定・テキストが復元されること
- 「破棄して新しく始める」を押すと、アップロード画面に戻ること
- 復元後もスタンプの編集（移動・テキスト・画像レイヤー・手書き等）が正常に動くこと
- 復元後も ZIP 書き出しが正常に動くこと
- 編集画面でブラウザタブを閉じようとすると警告が出ること
