                                  >
                                      <img src={img.url} className="w-full h-full object-cover" alt="source" />
                                  </button>
                              ))}
                          </div>
                      </div>
                  )}
              </div>
           </div>
        </div>
      )}

      {showProcessSelection && selectedSourceForNewStamp && (
         <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
           <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full p-6 relative">
              <button 
                onClick={() => {
                    setShowProcessSelection(false);
                    setSelectedSourceForNewStamp(null);
                }}
                className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
              >
                <XIcon size={24} />
              </button>

              <div className="flex justify-center mb-4">
                  <div className="w-24 h-24 rounded-lg overflow-hidden border border-gray-200 shadow-sm">
                      <img src={selectedSourceForNewStamp.url} className="w-full h-full object-cover" alt="selected" />
                  </div>
              </div>

              <h3 className="text-lg font-bold text-gray-800 mb-4 text-center">この画像をどうしますか？</h3>

              <div className="space-y-3">
                  <button 
                    onClick={() => processNewImage('auto')}
                    className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold py-3 rounded-xl shadow flex items-center justify-center gap-2"
                  >
                      <Wand2 size={20} />
                      自動で背景除去・切り出し
                  </button>
                  <button 
                    onClick={() => processNewImage('manual')}
                    className="w-full bg-white border-2 border-gray-200 hover:bg-gray-50 text-gray-700 font-bold py-3 rounded-xl shadow-sm flex items-center justify-center gap-2"
                  >
                      <Crop size={20} />
                      手動で範囲指定して切り出し
                  </button>
              </div>
           </div>
        </div>
      )}

      <ManualCropModal
        sourceImages={sourceImages}
        isOpen={isManualCropping}
        onClose={() => {
            setIsManualCropping(false);
            setTargetReplaceId(null);
            setManualCropInitialSourceId(undefined);
        }}
        onConfirm={handleManualCropConfirm}
        onAddSource={handleAddSourceFromModal}
        initialSourceId={manualCropInitialSourceId}
      />

      {showRestoreDialog && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 text-center">
            <div className="bg-primary-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
              <Save size={32} className="text-primary-600" />
            </div>
            <h3 className="text-lg font-bold text-gray-800 mb-2">
              保存データが見つかりました
            </h3>
            <p className="text-sm text-gray-500 mb-1">
              前回の作業途中のデータがあります。
            </p>
            <p className="text-xs text-gray-400 mb-6">
              保存日時: {new Date(savedProjectDate).toLocaleString('ja-JP')}
            </p>
            <div className="space-y-3">
              <button
                onClick={handleRestore}
                className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold 
                  py-3 rounded-xl shadow transition flex items-center justify-center gap-2"
              >
                <RotateCw size={18} />
                続きから再開する
              </button>
              <button
                onClick={handleDiscardSave}
                className="w-full bg-white border border-gray-300 hover:bg-gray-50 
                  text-gray-600 font-bold py-3 rounded-xl shadow-sm transition 
                  flex items-center justify-center gap-2"
              >
                <Trash2 size={18} />
                破棄して新しく始める
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

payload.text:
■ 概要
スタンプ編集画面で画像の左右反転・上下反転ができるようにします。
LINEスタンプではキャラの向きが重要なので、ボタン1つで反転できると便利です。

■ 1. StampEditorModal.tsx に状態追加

const [flipH, setFlipH] = useState(stamp.flipH ?? false);
const [flipV, setFlipV] = useState(stamp.flipV ?? false);

isOpen の useEffect 内でも初期化：
  setFlipH(stamp.flipH ?? false);
  setFlipV(stamp.flipV ?? false);

■ 2. ImageControlPanel に反転ボタンを追加

Props に追加：
  flipH: boolean;
  flipV: boolean;
  onFlipH: () => void;
  onFlipV: () => void;

ImageControlPanel 内のスライダー（サイズ・回転）の上に反転ボタンを配置：

  <div className="flex items-center gap-2 mb-2">
    <span className="text-xs text-gray-500 w-12 shrink-0">反転</span>
    <button
      onClick={onFlipH}
      className={`flex items-center gap-1 text-xs px-3 py-1.5 rounded border transition
        ${flipH ? 'bg-primary-100 border-primary-300 text-primary-700' : 'bg-white border-gray-300 text-gray-600 hover:bg-gray-50'}`}
    >
      <FlipHorizontal2 size={14} />
      左右
    </button>
    <button
      onClick={onFlipV}
      className={`flex items-center gap-1 text-xs px-3 py-1.5 rounded border transition
        ${flipV ? 'bg-primary-100 border-primary-300 text-primary-700' : 'bg-white border-gray-300 text-gray-600 hover:bg-gray-50'}`}
    >
      <FlipVertical2 size={14} />
      上下
    </button>
  </div>

※ FlipHorizontal2 と FlipVertical2 は lucide-react から import。
  もし存在しない場合は FlipHorizontal と FlipVertical を使ってください。
  それもなければ ArrowLeftRight と ArrowUpDown で代用。

■ 3. StampEditorModal から ImageControlPanel への受け渡し

  <ImageControlPanel
    scale={...}
    rotation={...}
    flipH={flipH}
    flipV={flipV}
    onFlipH={() => {
      setFlipH(prev => !prev);
      addToHistory({ flipH: !flipH });
    }}
    onFlipV={() => {
      setFlipV(prev => !prev);
      addToHistory({ flipV: !flipV });
    }}
    onScaleChange={...}
    onRotationChange={...}
    onCommit={...}
  />

■ 4. drawCanvas のメイン画像描画部分を修正

現在のメイン画像描画部分：
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);

これを以下に変更：
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.scale(flipH ? -1 : 1, flipV ? -1 : 1);  // ← 追加
  ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);

※ ctx.scale は ctx.rotate の後、ctx.drawImage の前に入れる。
※ 画像ハンドル（選択枠と四隅の□）の描画も scale の影響を受けるので、
  ハンドル描画は ctx.restore() の後に別途行うか、
  もしくはハンドル描画前に ctx.scale(flipH ? -1 : 1, flipV ? -1 : 1) を
  もう一度かけて戻す（反転を打ち消す）こと。
  一番簡単なのは、メイン画像描画を ctx.save/restore で囲んでから、
  その後にハンドルを別の ctx.save/restore で描画する方法：

  // メイン画像
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.scale(flipH ? -1 : 1, flipV ? -1 : 1);
  ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);
  ctx.restore();

  // ハンドル（反転の影響を受けない）
  if (mode === 'move') {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate((rotation * Math.PI) / 180);
    // ※ ctx.scale は入れない
    const hw = drawnW / 2;
    const hh = drawnH / 2;
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.strokeRect(-hw, -hh, drawnW, drawnH);
    const handleSize = 12;
    ctx.fillStyle = '#ffffff';
    const corners = [
      { x: -hw, y: -hh }, { x: hw, y: -hh },
      { x: -hw, y: hh }, { x: hw, y: hh }
    ];
    corners.forEach(c => {
      ctx.fillRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
      ctx.strokeRect(c.x - handleSize/2, c.y - handleSize/2, handleSize, handleSize);
    });
    ctx.restore();
  }

■ 5. HistoryState に flipH, flipV を追加

  flipH: boolean;
  flipV: boolean;

addToHistory のデフォルト値に追加：
  flipH,
  flipV,

undo / redo で復元：
  setFlipH(prevState.flipH ?? false);
  setFlipV(prevState.flipV ?? false);

初期 history にも含める。

■ 6. handleSave に追加

  const updatedStamp: Stamp = {
    ...stamp,
    ...
    flipH,
    flipV,
  };

■ 7. zipService.ts の renderAllLayers を修正

メイン画像描画部分に反転を追加：

  ctx.save();
  const cx = centerX + config.offsetX;
  const cy = centerY + config.offsetY;
  ctx.translate(cx, cy);
  if (config.rotation) {
    ctx.rotate((config.rotation * Math.PI) / 180);
  }
  if (config.flipH || config.flipV) {
    ctx.scale(config.flipH ? -1 : 1, config.flipV ? -1 : 1);
  }
  ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);
  ctx.restore();

■ 8. App.tsx のスタンプ一覧プレビュー（SVG）に反転を反映

SVG の <image> タグの transform に scale を追加：

  現在：
  transform={rotation ? `rotate(${rotation}, ${cx}, ${cy})` : undefined}

  変更後：
  transform={[
    rotation ? `rotate(${rotation}, ${cx}, ${cy})` : '',
    (stamp.flipH || stamp.flipV) ? `translate(${cx}, ${cy}) scale(${stamp.flipH ? -1 : 1}, ${stamp.flipV ? -1 : 1}) translate(${-cx}, ${-cy})` : ''
  ].filter(Boolean).join(' ') || undefined}

■ 9. useEffect の依存配列

drawCanvas の依存配列に flipH, flipV を追加。

■ 10. 確認事項

- move モードで「左右」ボタンを押すと画像が左右反転すること
- 「上下」ボタンを押すと画像が上下反転すること
- 反転状態がボタンの色で分かること（ON時はハイライト）
- 反転 + 回転 + 拡縮が組み合わさっても正しく描画されること
- 反転状態で画像のドラッグ移動が正常に動くこと
- 反転状態でハンドルによる拡縮が正常に動くこと
- Undo/Redo で反転状態が戻ること
- ZIP 書き出しに反転が反映されること
- App.tsx の一覧プレビューに反転が反映されること
- スマホでもボタンが押せること

