  const CanvasPreview = ({ config, width, height, onClick }: { config: ExportConfig | null, width: number, height: number, onClick?: () => void }) => {
      const canvasRef = useRef<HTMLCanvasElement>(null);
      const s = config ? stamps.find(x => x.id === config.id) : null;
      const layerCacheRef = useRef<Map<string, HTMLImageElement>>(new Map());

      useEffect(() => {
          if (!canvasRef.current || !config || !s) return;
          const ctx = canvasRef.current.getContext('2d');
          if (!ctx) return;

          // Preload layers if present
          if (config.imageLayers) {
            config.imageLayers.forEach(layer => {
                if (!layerCacheRef.current.has(layer.id)) {
                    const lImg = new Image();
                    lImg.onload = () => {
                        layerCacheRef.current.set(layer.id, lImg);
                        // Trigger redraw
                        draw();
                    };
                    lImg.src = layer.dataUrl;
                }
            });
          }

          const draw = () => {
              const img = new Image();
              img.onload = () => {
                  ctx.clearRect(0, 0, width, height);

                  const size = 10;
                  for(let y=0; y<height; y+=size) {
                      for(let x=0; x<width; x+=size) {
                          ctx.fillStyle = ((x/size + y/size) % 2 === 0) ? '#f3f4f6' : '#e5e7eb';
                          ctx.fillRect(x, y, size, size);
                      }
                  }

                  const drawnW = img.width * config.scale;
                  const drawnH = img.height * config.scale;
                  const centerX = width / 2;
                  const centerY = height / 2;
                  const x = centerX - (drawnW / 2) + config.offsetX;
                  const y = centerY - (drawnH / 2) + config.offsetY;

                  // Text Back
                  if (config.textObjects) {
                      config.textObjects.filter(t => t.zIndex === 'back').forEach(t => drawPreviewText(ctx, t));
                  }

                  // Layers Back
                  if (config.imageLayers) {
                      config.imageLayers.filter(l => l.zIndex === 'back').forEach(l => {
                          const lImg = layerCacheRef.current.get(l.id);
                          if (lImg) drawPreviewLayer(ctx, l, lImg);
                      });
                  }

                  // Strokes Back
                  if (config.drawingStrokes) {
                      config.drawingStrokes.filter(s => s.zIndex === 'back').forEach(s => drawPreviewStroke(ctx, s));
                  }

                  // Main Image
                  ctx.save();
                  const cx = centerX + config.offsetX;
                  const cy = centerY + config.offsetY;
                  ctx.translate(cx, cy);
                  if (config.rotation) {
                      ctx.rotate((config.rotation * Math.PI) / 180);
                  }
                  if (config.flipH || config.flipV) {
                      ctx.scale(config.flipH ? -1 : 1, config.flipV ? -1 : 1);
                  }
                  ctx.drawImage(img, -drawnW/2, -drawnH/2, drawnW, drawnH);
                  ctx.restore();

                  // Strokes Front
                  if (config.drawingStrokes) {
                      config.drawingStrokes.filter(s => s.zIndex !== 'back').forEach(s => drawPreviewStroke(ctx, s));
                  }

                  // Layers Front
                   if (config.imageLayers) {
                      config.imageLayers.filter(l => l.zIndex !== 'back').forEach(l => {
                          const lImg = layerCacheRef.current.get(l.id);
                          if (lImg) drawPreviewLayer(ctx, l, lImg);
                      });
                  }

                  // Text Front
                  if (config.textObjects) {
                      config.textObjects.filter(t => t.zIndex !== 'back').forEach(t => drawPreviewText(ctx, t));
                  }
              };
              img.src = config.customDataUrl || s.dataUrl;
          };

          draw();

      }, [config, s, width, height]);

      const drawPreviewLayer = (ctx: CanvasRenderingContext2D, layer: ImageLayerObject, img: HTMLImageElement) => {
          ctx.save();
          ctx.globalAlpha = layer.opacity;
          ctx.translate(layer.x, layer.y);
          ctx.rotate((layer.rotation * Math.PI) / 180);
          const w = layer.originalWidth * layer.scale;
          const h = layer.originalHeight * layer.scale;
          ctx.drawImage(img, -w/2, -h/2, w, h);
          ctx.restore();
      };

      const drawPreviewStroke = (ctx: CanvasRenderingContext2D, stroke: DrawingStroke) => {
        if (stroke.points.length < 2) return;
        ctx.save();
        ctx.globalAlpha = stroke.opacity;
        ctx.strokeStyle = stroke.color;
        ctx.lineWidth = stroke.width;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.beginPath();
        ctx.moveTo(stroke.points[0].x, stroke.points[0].y);
        for (let i = 1; i < stroke.points.length; i++) {
          ctx.lineTo(stroke.points[i].x, stroke.points[i].y);
        }
        ctx.stroke();
        ctx.globalAlpha = 1.0;
        ctx.restore();
      };

      const drawPreviewText = (ctx: CanvasRenderingContext2D, t: any) => {
           ctx.save();
           ctx.translate(t.x, t.y);
           ctx.rotate((t.rotation * Math.PI) / 180);
           ctx.font = `bold ${t.fontSize}px '${t.fontFamily}'`;
           ctx.textBaseline = 'middle';
           ctx.textAlign = 'center';
           ctx.lineJoin = 'round';

           if (t.outlineWidth > 0) {
               ctx.lineWidth = t.outlineWidth;
               ctx.strokeStyle = t.outlineColor;
               ctx.strokeText(t.text.split('\n')[0], 0, 0);
           }
           ctx.fillStyle = t.color;
           ctx.fillText(t.text.split('\n')[0], 0, 0);
           ctx.restore();
      };

      if (!config || !s) {
          return (
             <div 
                className="mt-2 border border-gray-200 rounded bg-gray-50 flex items-center justify-center text-xs text-gray-400"
