                                    disabled={!mainConfig}
                                    className="text-gray-400 hover:text-primary-600 disabled:opacity-30"
                                    title="メイン画像をダウンロード"
                                >
                                    <Save size={18} />
                                </button>
                            </div>
                            <select 
                                className="w-full border-gray-300 rounded-lg shadow-sm focus:ring-primary-500 focus:border-primary-500 mb-2 bg-primary-50"
                                value={mainConfig?.id || ''}
                                onChange={(e) => handleMainSelect(e.target.value)}
                            >
                                {stamps.map((s, i) => !s.isExcluded && (
                                    <option key={s.id} value={s.id}>No.{i+1} のスタンプ</option>
                                ))}
                            </select>
                            <CanvasPreview 
                                config={mainConfig} 
                                width={MAIN_WIDTH} 
                                height={MAIN_HEIGHT} 
                                onClick={() => {
                                    setEditingSpecialType('main');
                                    const s = stamps.find(x => x.id === mainConfig?.id);
                                    if(s) setEditingStamp(s);
                                }} 
                            />
                        </div>
                        <div>
                             <div className="flex justify-between items-end mb-1">
                                <label className="block text-sm font-medium text-gray-600">タブ画像 (96x74)</label>
                                <button
                                    onClick={() => downloadSpecialStamp(tabConfig, TAB_WIDTH, TAB_HEIGHT, 'tab.png')}
                                    disabled={!tabConfig}
                                    className="text-gray-400 hover:text-primary-600 disabled:opacity-30"
                                    title="タブ画像をダウンロード"
                                >
                                    <Save size={18} />
                                </button>
                            </div>
                            <select 
                                className="w-full border-gray-300 rounded-lg shadow-sm focus:ring-primary-500 focus:border-primary-500 mb-2 bg-primary-50"
                                value={tabConfig?.id || ''}
                                onChange={(e) => handleTabSelect(e.target.value)}
                            >
                                {stamps.map((s, i) => !s.isExcluded && (
                                    <option key={s.id} value={s.id}>No.{i+1} のスタンプ</option>
                                ))}
                            </select>
                            <CanvasPreview 
                                config={tabConfig} 
                                width={TAB_WIDTH} 
                                height={TAB_HEIGHT} 
                                onClick={() => {
                                    setEditingSpecialType('tab');
                                    const s = stamps.find(x => x.id === tabConfig?.id);
                                    if(s) setEditingStamp(s);
                                }}
                            />
                        </div>
                    </div>
                </div>

                <div className="bg-white p-6 rounded-2xl shadow-sm border border-primary-100">
                     <h3 className="font-bold text-gray-700 flex items-center gap-2 mb-4">
                        <Languages className="text-primary-500" size={20} />
                        スタンプ名・説明文
                    </h3>
                    <div className="space-y-4">
                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">タイトル（スタンプ名）</label>
                                    <CopyButton text={meta.stampNameJa} />
                                </div>
                                <TextCounter current={meta.stampNameJa.length} min={2} max={40} />
                            </div>
                            <input 
                                type="text" 
                                className={`w-full bg-primary-50 border rounded-md text-sm focus:ring-primary-500 focus:border-primary-500 ${meta.stampNameJa.length >= 40 ? 'border-red-300 bg-red-50' : 'border-primary-200'}`}
                                placeholder="例：かわいいうさぎスタンプ"
                                maxLength={40}
                                value={meta.stampNameJa}
                                onChange={e => setMeta({...meta, stampNameJa: e.target.value})}
                            />
                        </div>
                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">スタンプ説明文</label>
                                    <CopyButton text={meta.stampDescJa} />
                                </div>
                                <TextCounter current={meta.stampDescJa.length} min={10} max={160} />
                            </div>
                            <textarea 
                                className={`w-full bg-primary-50 border rounded-md text-sm focus:ring-primary-500 focus:border-primary-500 ${meta.stampDescJa.length >= 160 ? 'border-red-300 bg-red-50' : 'border-primary-200'}`}
                                rows={3}
                                placeholder="例：日常で使いやすいかわいいうさぎです。"
                                maxLength={160}
                                value={meta.stampDescJa}
                                onChange={e => setMeta({...meta, stampDescJa: e.target.value})}
                            />
                            <div className="mt-2">
                                <button 
                                    onClick={() => setDescriptionHintOpen(!descriptionHintOpen)}
                                    className="flex items-center gap-1 text-xs text-primary-600 font-bold hover:text-primary-700"
                                >
                                    {descriptionHintOpen ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
                                    説明文入力ヒント（タップで表示）
                                </button>
                                {descriptionHintOpen && (
                                    <div className="mt-2 p-3 bg-gray-100 rounded-lg text-xs text-gray-600 leading-relaxed border border-gray-200 animate-fade-in">
                                        <span className="font-bold text-gray-500 mb-1 block">入力例：</span>
                                        ｛キャラ名→｝○○のスタンプ。｛何系のスタンプか→｝毎日よく使う言葉がたくさん。｛イベント名など｝バレンタインに使える。｛含まれてる物も｝お煎餅もあるよ。｛誰向けか｝チョコ好きの方も煎餅好きの方もどうぞ！
                                        ｛検索ワードを入れる｝
                                    </div>
                                )}
                            </div>
                        </div>

                        <button 
                            onClick={handleTranslation}
                            disabled={isTranslating}
                            className="w-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white py-2 rounded-lg font-bold text-sm shadow hover:shadow-lg transition disabled:opacity-50"
                        >
                            {isTranslating ? 'AI翻訳中...' : '英語に翻訳'}
                        </button>

                        <div className="pt-2 border-t border-dashed">
                             <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">タイトル(English)</label>
                                    <CopyButton text={meta.stampNameEn} />
                                </div>
                                <TextCounter current={meta.stampNameEn.length} min={2} max={40} />
                            </div>
                             <input 
                                type="text" 
                                className="w-full bg-primary-50 border-primary-200 rounded-md text-sm focus:ring-primary-500 focus:border-primary-500"
                                maxLength={40}
                                value={meta.stampNameEn}
                                onChange={e => setMeta({...meta, stampNameEn: e.target.value})}
                             />
                        </div>
                        <div>
                             <div className="flex justify-between items-center mb-1">
                                <div className="flex items-center gap-2">
                                    <label className="text-xs font-bold text-gray-500">スタンプ説明文(English)</label>
                                    <CopyButton text={meta.stampDescEn} />
                                </div>
                                <TextCounter current={meta.stampDescEn.length} min={10} max={160} />
                            </div>
                             <textarea 
                                className="w-full bg-primary-50 border-primary-200 rounded-md text-sm focus:ring-primary-500 focus:border-primary-500"
                                rows={3}
                                maxLength={160}
                                value={meta.stampDescEn}
                                onChange={e => setMeta({...meta, stampDescEn: e.target.value})}
                             />
                        </div>
                    </div>
                </div>

                <div className="bg-primary-50 p-6 rounded-2xl shadow-inner border border-primary-100 space-y-4">
                    <div>
                        <h3 className="font-bold text-primary-800 flex items-center gap-2 mb-4">
                            <Download className="text-primary-600" size={20} />
                            書き出し
                        </h3>

                        <div className="flex items-center gap-2 mb-4">
                            <input 
                                type="checkbox" 
                                id="renumber"
                                checked={renumber} 
                                onChange={e => setRenumber(e.target.checked)}
                                className="rounded text-primary-600 focus:ring-primary-500"
                            />
                            <label htmlFor="renumber" className="text-sm text-gray-700">番号を振り直す (01.png〜)</label>
                        </div>

                        <button 
                            onClick={handleExport}
                            className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold py-3 rounded-xl shadow-lg shadow-primary-200 transition-all flex items-center justify-center gap-2"
                        >
                            <Download size={20} />
                            ZIPをダウンロード
                        </button>
                        <p className="text-xs text-center text-primary-600/70 mt-2">
                            スタンプ画像・メイン・タブ・テキストが含まれます
                        </p>
                    </div>

                    <div className="pt-4 border-t border-primary-200/50 space-y-3">
                        <a 
                            href="https://creator.line.me/ja/stickermaker/" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="w-full bg-white text-[#06C755] border border-[#06C755] hover:bg-[#06C755] hover:text-white font-bold py-3 rounded-xl shadow transition-all flex items-center justify-center gap-2 md:hidden"
                        >
                            <Smartphone size={18} />
                            LINEスタンプメーカー
                        </a>
                        <a 
                            href="https://creator.line.me/ja/" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="w-full bg-white text-gray-600 border border-gray-300 hover:bg-gray-100 font-bold py-3 rounded-xl shadow transition-all flex items-center justify-center gap-2"
                        >
                            <ExternalLink size={18} />
                            クリエイターズマーケット
                        </a>
                        <p className="text-xs text-center text-gray-500 mt-2">
                            スタンプ申請はこちら
                        </p>
                    </div>
                </div>

            </div>
          </div>
        )}
      </main>

      {/* Modals and Toast */}
      {editingStamp && (
        <StampEditorModal
          stamp={editingStamp}
          isOpen={!!editingStamp}
          onClose={() => {
              setEditingStamp(null);
              setEditingSpecialType(null);
          }}
          onSave={(updated) => {
              if (editingSpecialType) {
                  updateSpecialConfig(updated);
              } else {
                  updateStamp(updated);
              }
          }}
          onReCrop={() => handleReCropFromEditor(editingStamp)}
          initialPreviewBg={previewBg}
          targetWidth={editingSpecialType === 'main' ? MAIN_WIDTH : (editingSpecialType === 'tab' ? TAB_WIDTH : TARGET_WIDTH)}
          targetHeight={editingSpecialType === 'main' ? MAIN_HEIGHT : (editingSpecialType === 'tab' ? TAB_HEIGHT : TARGET_HEIGHT)}
          initialScale={
              editingSpecialType === 'main' ? mainConfig?.scale : 
              editingSpecialType === 'tab' ? tabConfig?.scale : 
              undefined
          }
          initialRotation={
              editingSpecialType === 'main' ? mainConfig?.rotation :
              editingSpecialType === 'tab' ? tabConfig?.rotation :
              undefined
          }
          initialOffset={
              editingSpecialType === 'main' ? {x: mainConfig?.offsetX || 0, y: mainConfig?.offsetY || 0} :
              editingSpecialType === 'tab' ? {x: tabConfig?.offsetX || 0, y: tabConfig?.offsetY || 0} :
              undefined
          }
          initialTextObjects={
              editingSpecialType === 'main' ? mainConfig?.textObjects :
              editingSpecialType === 'tab' ? tabConfig?.textObjects :
              undefined
          }
          initialImageLayers={
              editingSpecialType === 'main' ? mainConfig?.imageLayers :
              editingSpecialType === 'tab' ? tabConfig?.imageLayers :
              undefined
          }
          initialDrawingStrokes={
              editingSpecialType === 'main' ? mainConfig?.drawingStrokes :
              editingSpecialType === 'tab' ? tabConfig?.drawingStrokes :
              undefined
          }
        />
      )}

      {showSourceSelectModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
           <div className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 relative">
              <button 
                onClick={() => setShowSourceSelectModal(false)}
                className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
              >
                <XIcon size={24} />
              </button>

              <h3 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
                <Plus size={24} className="text-primary-600" />
                画像を追加
              </h3>

              <div className="space-y-4">
                  <div className="relative border-2 border-dashed border-primary-200 bg-primary-50 rounded-xl p-6 hover:bg-primary-100 transition cursor-pointer text-center group">
                      <input 
                          type="file" 
                          accept="image/png, image/jpeg"
                          onChange={handleUploadForNewStamp}
                          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                      />
                      <Upload className="mx-auto text-primary-500 mb-2 group-hover:scale-110 transition" size={32} />
                      <p className="font-bold text-primary-700">新しい画像をアップロード</p>
                  </div>

                  {sourceImages.length > 0 && (
                      <div>
                          <p className="text-xs font-bold text-gray-500 mb-2">またはアップロード済みから選択:</p>
                          <div className="grid grid-cols-4 gap-2">
                              {sourceImages.map(img => (
                                  <button 
                                    key={img.id}
                                    onClick={() => handleSelectExistingSource(img)}
                                    className="aspect-square rounded-lg border border-gray-200 overflow-hidden hover:ring-2 hover:ring-primary-500 transition relative"
                                  >
                                      <img src={img.url} className="w-full h-full object-cover" alt="source" />
                                  </button>
                              ))}
                          </div>
                      </div>
                  )}
              </div>
           </div>
        </div>
      )}

      {showProcessSelection && selectedSourceForNewStamp && (
         <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
           <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full p-6 relative">
              <button 
                onClick={() => {
                    setShowProcessSelection(false);
                    setSelectedSourceForNewStamp(null);
                }}
                className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
              >
                <XIcon size={24} />
              </button>

              <div className="flex justify-center mb-4">
                  <div className="w-24 h-24 rounded-lg overflow-hidden border border-gray-200 shadow-sm">
                      <img src={selectedSourceForNewStamp.url} className="w-full h-full object-cover" alt="selected" />
                  </div>
              </div>

              <h3 className="text-lg font-bold text-gray-800 mb-4 text-center">この画像をどうしますか？</h3>

              <div className="space-y-3">
                  <button 
                    onClick={() => processNewImage('auto')}
                    className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold py-3 rounded-xl shadow flex items-center justify-center gap-2"
                  >
                      <Wand2 size={20} />
                      自動で背景除去・切り出し
                  </button>
                  <button 
                    onClick={() => processNewImage('manual')}
                    className="w-full bg-white border-2 border-gray-200 hover:bg-gray-50 text-gray-700 font-bold py-3 rounded-xl shadow-sm flex items-center justify-center gap-2"
                  >
                      <Crop size={20} />
                      手動で範囲指定して切り出し
                  </button>
              </div>
           </div>
        </div>
      )}

      <ManualCropModal
        sourceImages={sourceImages}
        isOpen={isManualCropping}
        onClose={() => {
            setIsManualCropping(false);
            setTargetReplaceId(null);
            setManualCropInitialSourceId(undefined);
        }}
        onConfirm={handleManualCropConfirm}
        onAddSource={handleAddSourceFromModal}
        initialSourceId={manualCropInitialSourceId}
      />

      <TextSetModal
        isOpen={showTextSetModal}
        onClose={() => setShowTextSetModal(false)}
        stamps={stamps}
        onApply={(updatedStamps) => {
            setStamps(updatedStamps);
        }}
      />

      {showRestoreDialog && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 text-center">
            <div className="bg-primary-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
              <Save size={32} className="text-primary-600" />
            </div>
            <h3 className="text-lg font-bold text-gray-800 mb-2">
              保存データが見つかりました
            </h3>
            <p className="text-sm text-gray-500 mb-1">
              前回の作業途中のデータがあります。
            </p>
            <p className="text-xs text-gray-400 mb-6">
              保存日時: {new Date(savedProjectDate).toLocaleString('ja-JP')}
            </p>
            <div className="space-y-3">
              <button
                onClick={handleRestore}
                className="w-full bg-primary-600 hover:bg-primary-700 text-white font-bold 
                  py-3 rounded-xl shadow transition flex items-center justify-center gap-2"
              >
                <RotateCw size={18} />
                続きから再開する
              </button>
              <button
                onClick={handleDiscardSave}
                className="w-full bg-white border border-gray-300 hover:bg-gray-50 
                  text-gray-600 font-bold py-3 rounded-xl shadow-sm transition 
                  flex items-center justify-center gap-2"
              >
                <Trash2 size={18} />
                破棄して新しく始める
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Toast Notification */}
      {toastMessage && (
        <div className="fixed bottom-20 left-1/2 -translate-x-1/2 z-[60]
          bg-gray-800 text-white text-sm px-4 py-2 rounded-full shadow-lg
          pointer-events-none whitespace-nowrap animate-[fadeIn_0.3s_ease-in-out]">
          {toastMessage}
        </div>
      )}
    </div>
  );
}

payload.text:
■ UI修正まとめ（6件）

【修正1】テキスト一括追加モーダルの「サイズ」と「縁取り」の重なり修正

TextSetModal 内のサイズと縁取りのスライダーが横並び（grid 2列）に
なっていて、PC幅で重なっています。
スマホでは別の行になっていて問題ないとのことなので、
PCでも常に縦並び（1列）にしてください。

該当箇所の grid grid-cols-2 を grid grid-cols-1 に変更するか、
grid をやめて flex flex-col gap-3 にしてください。

サイズの行：
  <div className="flex items-center gap-2 w-full">
    <span className="text-xs text-gray-500 w-12 shrink-0">サイズ</span>
    <input type="range" ... className="flex-1 ..." />
    <span className="text-xs text-gray-400 w-8 text-right shrink-0">{fontSize}</span>
  </div>

縁取りの行：
  <div className="flex items-center gap-2 w-full">
    <span className="text-xs text-gray-500 w-12 shrink-0">縁取り</span>
    <input type="range" ... className="flex-1 ..." />
    <span className="text-xs text-gray-400 w-8 text-right shrink-0">{outlineWidth}</span>
    <label className="...カラーピッカー...">
      <input type="color" ... />
    </label>
  </div>

【修正2】編集画面（StampEditorModal）の文字色・縁取りのカスタムカラーピッカーを四角に変更

TextEditPanel 内のカスタムカラーピッカー（文字色用と縁取り色用）が
現在、丸にグラデーション背景になっています。
これを TextSetModal と同じスタイルの四角表示に変更してください。

文字色のカスタムカラーピッカー：
変更前：
  <label className="w-5 h-5 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500">

変更後：
  <label className="w-5 h-5 rounded border-2 border-gray-300 overflow-hidden cursor-pointer relative"
    style={{ backgroundColor: selectedText.color }}>
    <input 
      type="color" 
      className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
      value={selectedText.color}
      onChange={(e) => onUpdateText(selectedText.id, { color: e.target.value })}
    />
  </label>

縁取り色のカスタムカラーピッカーも同様：
変更前：
  <label className="w-5 h-5 rounded-full border border-gray-300 overflow-hidden cursor-pointer relative bg-gradient-to-br from-red-500 via-green-500 to-blue-500 ml-1">

変更後：
  <label className="w-5 h-5 rounded border-2 border-gray-300 overflow-hidden cursor-pointer relative ml-1"
    style={{ backgroundColor: selectedText.outlineColor }}>
    <input 
      type="color" 
      className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
      value={selectedText.outlineColor}
      onChange={(e) => onUpdateText(selectedText.id, { outlineColor: e.target.value })}
    />
  </label>

【修正3】テキスト一括追加モーダルのプレビューリスト（No.01→おはよう）を削除

TextSetModal 内の、入力テキストとスタンプ番号の対応を表示するリスト部分
（No.01 → おはよう、No.02 → こんにちは…のエリア）を丸ごと削除してください。

削除対象：
  <div className="mt-3 max-h-32 overflow-y-auto bg-gray-50 rounded-lg p-2 border">
    {lines.map((line, i) => (
      <div key={i} className="flex items-center gap-2 text-xs py-0.5">
        ...No.XX → テキスト...
      </div>
    ))}
  </div>

この部分を丸ごと削除。

代わりに、テキストエリアの下の注釈を少し詳しくしてください：
  <p className="text-xs text-gray-500 mt-1">
    有効なスタンプ {validCount}個 に対して、上から順に1つずつ割り当てます。
    空行はスキップされます。
  </p>

【修正4】画像レイヤーの透明度の％表示がスライダーから離れる問題

ImageLayerPanel 内の透明度スライダーで ControlSlider を使っている場合、
unit の表示が離れてしまう問題です。

ControlSlider の透明度部分で、値の表示方法を修正してください。
回転（°表示）と同じ幅に収まるようにします。

透明度の ControlSlider の呼び出し部分：
  <ControlSlider
    label="透明度"
    value={selectedLayer.opacity}
    min={0}
    max={1}
    step={0.01}
    onChange={(val: number) => onUpdateLayer(selectedLayer.id, { opacity: val })}
    onCommit={onCommit}
    unit="%"
  />

もし unit="%" で表示がおかしい場合、ControlSlider 内の
表示ロジックを確認してください。

ControlSlider の値表示部分を修正：
  {unit && (
    <span className="text-xs text-gray-400 w-12 text-right font-mono shrink-0">
      {unit === '%' ? Math.round(value * 100) + '%' : (step < 1 ? value.toFixed(2) : Math.round(value)) + unit}
    </span>
  )}

※ w-8 を w-12 に変更して、"100%" が収まるようにする。
※ unit が '%' の場合は value * 100 + '%' で表示する特別処理を追加。
※ shrink-0 を付けて幅が縮まないようにする。

さらに、透明度のスライダーも他のスライダーと同じ行に収まるように、
ImageLayerPanel のグリッドが grid-cols-2 なら透明度もその中に入れてください。
もし透明度だけ別の行になっている場合は、サイズ・回転・透明度を
grid-cols-1 sm:grid-cols-3 か、grid-cols-1 で縦に並べて統一してください。

【修正5】背景除去の透過度スライダーに＋ーボタンを追加

StampEditorModal 内の (mode === 'wand' || mode === 'eraser') && originalImage の時に
表示される背景除去の tolerance スライダーに、＋ーボタンを追加してください。

現在：
  <input type="range" min="1" max="100" value={tolerance} onChange={handleToleranceChange} ... />

