                            {lastSavedAt && (
                                <span className="text-xs text-gray-400 hidden lg:inline">
                                    {new Date(lastSavedAt).toLocaleTimeString('ja-JP', { 
                                        hour: '2-digit', 
                                        minute: '2-digit' 
                                    })} 保存済
                                </span>
