                        >
                            <Plus size={16} />
                            画像を追加
                        </button>
                    </div>
                )}
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto p-6 w-full flex-grow">
        {/* ... (rest of the component) ... */}

        {step === AppStep.UPLOAD && (
          <div className="flex flex-col items-center justify-center py-8 sm:py-12 animate-fade-in gap-6">
            <div className="bg-white p-6 sm:p-8 rounded-3xl shadow-xl text-center border-4 border-dashed border-primary-200 hover:border-primary-400 transition-colors cursor-pointer relative max-w-2xl w-full">
