import React, { useState } from 'react';
import { TextObject, Stamp, TARGET_WIDTH, TARGET_HEIGHT } from '../types';
import { X, Check, Layers, AlignVerticalJustifyCenter, AlignHorizontalJustifyCenter, Type } from 'lucide-react';
import { ControlSlider } from './editor/ControlSlider';

interface TextSetModalProps {
  isOpen: boolean;
  onClose: () => void;
  stamps: Stamp[];
  onApply: (updatedStamps: Stamp[]) => void;
}

export const TextSetModal: React.FC<TextSetModalProps> = ({ isOpen, onClose, stamps, onApply }) => {
  const [rawText, setRawText] = useState('');
  const [fontSize, setFontSize] = useState(40);
  const [fontFamily, setFontFamily] = useState('M PLUS Rounded 1c');
  const [color, setColor] = useState('#000000');
  const [outlineColor, setOutlineColor] = useState('#FFFFFF');
  const [outlineWidth, setOutlineWidth] = useState(4);
  const [isVertical, setIsVertical] = useState(false);
  const [zIndex, setZIndex] = useState<'front' | 'back'>('front');
  const [position, setPosition] = useState<'top' | 'center' | 'bottom'>('bottom');

  if (!isOpen) return null;

  const validStamps = stamps.filter(s => !s.isExcluded);
  const lines = rawText.split('\n');
  const filledLinesCount = lines.filter(l => l.trim()).length;

  const fontOptions = [
      { value: 'M PLUS Rounded 1c', label: '丸ゴシック' },
      { value: 'Noto Sans JP', label: 'ゴシック' },
      { value: 'Noto Serif JP', label: '明朝' },
  ];
  const textColorOptions = ['#000000', '#FFFFFF', '#ef4444', '#3b82f6', '#10b981', '#f97316', '#ec4899', '#4b3621'];

  const presets = [
      { label: '日常', texts: 'おはよう\nこんにちは\nこんばんは\nおやすみ\nありがとう\nごめんね\nOK!\nよろしく' },
      { label: '感情', texts: 'うれしい！\nかなしい…\nたのしい♪\nびっくり！\nおこ！\nてれてれ\nすき♡\nわーい！' },
      { label: '返事', texts: 'OK!\nNG!\nYes!\nNo!\n了解！\nりょ\nおけ！\nむり〜' },
  ];

  const handleApply = () => {
    const updatedStamps = stamps.map(stamp => {
      if (stamp.isExcluded) return stamp;

      const validIndex = validStamps.findIndex(s => s.id === stamp.id);
      if (validIndex === -1 || validIndex >= lines.length) return stamp;

      const text = lines[validIndex].trim();
      if (!text) return stamp;

      let posX: number;
      let posY: number;

      if (isVertical) {
        // 縦書き：Y は常に中央、X を左右で調整
        posY = TARGET_HEIGHT * 0.5;
        if (position === 'top') posX = TARGET_WIDTH * 0.85;       // 右寄せ
        else if (position === 'center') posX = TARGET_WIDTH * 0.5; // 中央
        else posX = TARGET_WIDTH * 0.15;                           // 左寄せ
      } else {
        // 横書き：X は常に中央、Y を上中下で調整
        posX = TARGET_WIDTH / 2;
        if (position === 'top') posY = TARGET_HEIGHT * 0.15;
        else if (position === 'center') posY = TARGET_HEIGHT * 0.5;
        else posY = TARGET_HEIGHT * 0.85;
      }

      const newTextObj: TextObject = {
        id: 'txt-set-' + Date.now().toString() + '-' + validIndex,
        text: text,
        x: posX,
        y: posY,
        fontSize: fontSize,
        fontFamily: fontFamily,
        color: color,
        isVertical: isVertical,
        outlineColor: outlineColor,
        outlineWidth: outlineWidth,
        zIndex: zIndex,
        rotation: 0,
        curvature: 0,
      };

      const existingTexts = stamp.textObjects ?? [];
      if (existingTexts.length >= 3) return stamp;

      return {
        ...stamp,
        textObjects: [...existingTexts, newTextObj],
      };
    });

    onApply(updatedStamps);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full flex flex-col max-h-[90vh]">
        <div className="p-4 border-b flex justify-between items-center bg-blue-50 rounded-t-xl shrink-0">
          <h3 className="font-bold text-gray-700 flex items-center gap-2">
            <Type className="text-blue-600" />
            テキスト一括追加
          </h3>
          <button onClick={onClose} className="p-1 hover:bg-gray-200 rounded-full"><X size={20} /></button>
        </div>

        <div className="p-4 overflow-y-auto flex-1 space-y-4">
            {/* Input Section */}
            <div>
                <div className="flex flex-wrap gap-2 mb-2 items-center">
                    <span className="text-xs font-bold text-gray-500">プリセット:</span>
                    {presets.map(p => (
                        <button key={p.label} onClick={() => setRawText(p.texts)} className="text-xs bg-gray-100 hover:bg-blue-100 px-2 py-1 rounded border hover:text-blue-700 transition">
                            {p.label}
                        </button>
                    ))}
                </div>
                <textarea 
                    className="w-full border-gray-300 rounded-lg text-sm p-3 focus:ring-blue-500 focus:border-blue-500"
                    rows={6}
                    placeholder="1行に1つずつテキストを入力&#13;&#10;例:&#13;&#10;おはよう&#13;&#10;こんにちは"
                    value={rawText}
                    onChange={e => setRawText(e.target.value)}
                />
                <p className="text-xs text-gray-500 mt-1">
                    有効なスタンプ {validStamps.length}個 に対して、上から順に1つずつ割り当てます。
                    空行はスキップされます。
                </p>
            </div>

            {/* Style Settings */}
            <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 flex flex-col gap-3">
                <div className="flex gap-2">
                    <select 
                        value={fontFamily} 
                        onChange={(e) => setFontFamily(e.target.value)}
                        className="text-sm border-gray-300 rounded flex-1"
                    >
                        {fontOptions.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
                    </select>
                </div>

                <div className="flex items-center gap-2 overflow-x-auto pb-1">
                    <span className="text-xs text-gray-500 shrink-0">文字色</span>
                    {textColorOptions.map(c => (
                        <button key={c} onClick={() => setColor(c)} className={`w-6 h-6 rounded-full border shrink-0 ${color === c ? 'ring-2 ring-blue-500' : 'border-gray-300'}`} style={{ backgroundColor: c }} />
                    ))}
                    <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-6 h-6 rounded overflow-hidden cursor-pointer border-0 p-0" />
                </div>

                <div className="flex flex-col gap-3">
                    <ControlSlider label="サイズ" value={fontSize} min={10} max={120} onChange={setFontSize} />
                    <div className="flex items-center gap-2 w-full">
                        <div className="flex-1 min-w-0">
                            <ControlSlider label="縁取り" value={outlineWidth} min={0} max={20} onChange={setOutlineWidth} />
                        </div>
                        <input type="color" value={outlineColor} onChange={e => setOutlineColor(e.target.value)} className="w-6 h-6 rounded cursor-pointer border-0 p-0 shrink-0" />
                    </div>
                </div>

                <div className="flex flex-wrap gap-2 pt-2 border-t border-blue-200/50 justify-center items-center">
                    <button onClick={() => setIsVertical(!isVertical)} className={`flex items-center gap-1 text-xs px-3 py-1.5 rounded border transition ${isVertical ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-gray-600 border-gray-300'}`}>
                        {isVertical ? <AlignVerticalJustifyCenter size={14}/> : <AlignHorizontalJustifyCenter size={14}/>} {isVertical ? '縦書き' : '横書き'}
                    </button>
                    <button onClick={() => setZIndex(zIndex === 'front' ? 'back' : 'front')} className={`flex items-center gap-1 text-xs px-3 py-1.5 rounded border transition ${zIndex === 'front' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-gray-600 border-gray-300'}`}>
                        <Layers size={14}/> {zIndex === 'front' ? '前面' : '背面'}
                    </button>

                    <div className="flex gap-1">
                        {isVertical ? (
                            <>
                            <button type="button" onClick={() => setPosition('bottom')} className={`px-3 py-1.5 rounded border text-xs ${position === 'bottom' ? 'bg-blue-200 border-blue-300 text-blue-800' : 'bg-white border-gray-300 text-gray-600'}`} title="左寄せ">左</button>
                            <button type="button" onClick={() => setPosition('center')} className={`px-3 py-1.5 rounded border text-xs ${position === 'center' ? 'bg-blue-200 border-blue-300 text-blue-800' : 'bg-white border-gray-300 text-gray-600'}`} title="中央">中</button>
                            <button type="button" onClick={() => setPosition('top')} className={`px-3 py-1.5 rounded border text-xs ${position === 'top' ? 'bg-blue-200 border-blue-300 text-blue-800' : 'bg-white border-gray-300 text-gray-600'}`} title="右寄せ">右</button>
                            </>
                        ) : (
                            <>
                            <button type="button" onClick={() => setPosition('top')} className={`px-3 py-1.5 rounded border text-xs ${position === 'top' ? 'bg-blue-200 border-blue-300 text-blue-800' : 'bg-white border-gray-300 text-gray-600'}`} title="上部">上</button>
                            <button type="button" onClick={() => setPosition('center')} className={`px-3 py-1.5 rounded border text-xs ${position === 'center' ? 'bg-blue-200 border-blue-300 text-blue-800' : 'bg-white border-gray-300 text-gray-600'}`} title="中央">中</button>
                            <button type="button" onClick={() => setPosition('bottom')} className={`px-3 py-1.5 rounded border text-xs ${position === 'bottom' ? 'bg-blue-200 border-blue-300 text-blue-800' : 'bg-white border-gray-300 text-gray-600'}`} title="下部">下</button>
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>

        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex justify-end gap-3 shrink-0">
            <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg text-sm">キャンセル</button>
            <button onClick={handleApply} disabled={filledLinesCount === 0} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg shadow hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 text-sm">
                <Check size={16} /> 一括追加
            </button>
        </div>
      </div>
    </div>
  );
};

payload.text:
■ 概要
全レイヤー（テキスト・画像レイヤー・手書き・スタンプ画像本体）に
描画順の数値（layerOrder）を持たせて、数値順に描画する仕組みに変更します。
このステップではUIは変更せず、データ構造と描画ロジックだけ変更します。
見た目・動作は変わらないはずです。

■ 1. types.ts の変更

TextObject の zIndex を変更：
  変更前: zIndex: 'front' | 'back';
  変更後: zIndex: 'front' | 'back'; // 後方互換のため残す
           layerOrder?: number;       // 追加：描画順（小さい方が下）

ImageLayerObject の zIndex を変更：
  変更前: zIndex: 'front' | 'back';
  変更後: zIndex: 'front' | 'back';
           layerOrder?: number;

DrawingStroke の zIndex を変更：
  変更前: zIndex: 'front' | 'back';
  変更後: zIndex: 'front' | 'back';
           layerOrder?: number;

Stamp に追加：
  mainImageLayerOrder?: number;  // スタンプ画像本体の描画順（デフォルト100）

ExportConfig に追加：
  mainImageLayerOrder?: number;

■ 2. デフォルトの layerOrder 値の方針

スタンプ画像本体のデフォルト: 100
背面（zIndex === 'back'）のレイヤー: 50（スタンプ画像より下）
前面（zIndex !== 'back'）のレイヤー: 150（スタンプ画像より上）

新規作成時の layerOrder 割り当て：
  - 背面指定で作成 → 現在の背面レイヤーの最大 layerOrder + 1（なければ50）
  - 前面指定で作成 → 現在の前面レイヤーの最大 layerOrder + 1（なければ150）

■ 3. layerOrder を自動付与するヘルパー関数を作成

lib/layerUtils.ts を新規作成：

  import { TextObject, ImageLayerObject, DrawingStroke } from '../types';

  // 全レイヤーのlayerOrderを取得する型
  export interface LayerItem {
    type: 'text' | 'imageLayer' | 'drawing' | 'mainImage';
    id: string;
    layerOrder: number;
  }

  // 既存データにlayerOrderが無い場合にデフォルト値を付与
  export function ensureLayerOrder(
    textObjects: TextObject[],
    imageLayers: ImageLayerObject[],
    drawingStrokes: DrawingStroke[],
    mainImageOrder?: number
  ): {
    textObjects: TextObject[];
    imageLayers: ImageLayerObject[];
    drawingStrokes: DrawingStroke[];
    mainImageLayerOrder: number;
  } {
    const mainOrder = mainImageOrder ?? 100;
    let backCounter = 10;
    let frontCounter = 110;

    const assignOrder = <T extends { zIndex: 'front' | 'back'; layerOrder?: number }>(
      items: T[]
    ): T[] => {
      return items.map(item => {
        if (item.layerOrder !== undefined && item.layerOrder !== null) {
          return item;
        }
        if (item.zIndex === 'back') {
          return { ...item, layerOrder: backCounter++ };
        } else {
          return { ...item, layerOrder: frontCounter++ };
        }
      });
    };

    return {
      textObjects: assignOrder(textObjects),
      imageLayers: assignOrder(imageLayers),
      drawingStrokes: assignOrder(drawingStrokes),
      mainImageLayerOrder: mainOrder,
    };
  }

  // 全レイヤーをlayerOrder順にソートしたリストを返す
  export function getSortedLayers(
    textObjects: TextObject[],
    imageLayers: ImageLayerObject[],
    drawingStrokes: DrawingStroke[],
    mainImageOrder: number
  ): LayerItem[] {
    const items: LayerItem[] = [];

    textObjects.forEach(t => {
      items.push({ type: 'text', id: t.id, layerOrder: t.layerOrder ?? (t.zIndex === 'back' ? 50 : 150) });
    });

    imageLayers.forEach(l => {
      items.push({ type: 'imageLayer', id: l.id, layerOrder: l.layerOrder ?? (l.zIndex === 'back' ? 50 : 150) });
    });

    drawingStrokes.forEach(s => {
      items.push({ type: 'drawing', id: s.id, layerOrder: s.layerOrder ?? (s.zIndex === 'back' ? 50 : 150) });
    });

    items.push({ type: 'mainImage', id: 'main', layerOrder: mainImageOrder });

    items.sort((a, b) => a.layerOrder - b.layerOrder);

    return items;
  }

  // 次のlayerOrderを取得（新規レイヤー作成用）
  export function getNextLayerOrder(
    textObjects: TextObject[],
    imageLayers: ImageLayerObject[],
    drawingStrokes: DrawingStroke[],
    mainImageOrder: number,
    position: 'front' | 'back'
  ): number {
    const all = getSortedLayers(textObjects, imageLayers, drawingStrokes, mainImageOrder);

    if (position === 'back') {
      // スタンプ画像より下で、最も大きいlayerOrder + 1
      const backItems = all.filter(a => a.layerOrder < mainImageOrder && a.type !== 'mainImage');
      if (backItems.length === 0) return mainImageOrder - 1;
      return Math.max(...backItems.map(a => a.layerOrder)) + 1;
    } else {
      // スタンプ画像より上で、最も大きいlayerOrder + 1
      const frontItems = all.filter(a => a.layerOrder > mainImageOrder && a.type !== 'mainImage');
      if (frontItems.length === 0) return mainImageOrder + 1;
      return Math.max(...frontItems.map(a => a.layerOrder)) + 1;
    }
  }

■ 4. zipService.ts の renderAllLayers を layerOrder ベースに書き換え

import { getSortedLayers } from './layerUtils'; を追加。

renderAllLayers のシグネチャに mainImageLayerOrder を追加：
  export function renderAllLayers(
    ctx: CanvasRenderingContext2D,
    img: HTMLImageElement,
    config: ExportConfig,
    targetW: number,
    targetH: number,
    layerImages?: Map<string, HTMLImageElement>
  ): void

内部で描画順をlayerOrderベースに変更：

  const textObjects = config.textObjects ?? [];
  const imageLayers = config.imageLayers ?? [];
  const drawingStrokes = config.drawingStrokes ?? [];
  const mainImageOrder = config.mainImageLayerOrder ?? 100;

  const sortedLayers = getSortedLayers(textObjects, imageLayers, drawingStrokes, mainImageOrder);

  const drawnW = img.width * config.scale;
  const drawnH = img.height * config.scale;
  const centerX = targetW / 2;
  const centerY = targetH / 2;

  for (const layer of sortedLayers) {
    if (layer.type === 'mainImage') {
      // スタンプ画像本体を描画
      ctx.save();
      const cx = centerX + config.offsetX;
      const cy = centerY + config.offsetY;
      ctx.translate(cx, cy);
      if (config.rotation) {
        ctx.rotate((config.rotation * Math.PI) / 180);
      }
      if (config.flipH || config.flipV) {
        ctx.scale(config.flipH ? -1 : 1, config.flipV ? -1 : 1);
      }
      ctx.drawImage(img, -drawnW / 2, -drawnH / 2, drawnW, drawnH);
      ctx.restore();

    } else if (layer.type === 'text') {
      const textObj = textObjects.find(t => t.id === layer.id);
      if (textObj) drawTextOnCanvas(ctx, textObj);

    } else if (layer.type === 'imageLayer') {
      const imageLayer = imageLayers.find(l => l.id === layer.id);
      if (imageLayer && layerImages) {
        const lImg = layerImages.get(imageLayer.id);
        if (lImg) {
          ctx.save();
          ctx.globalAlpha = imageLayer.opacity;
          ctx.translate(imageLayer.x, imageLayer.y);
          ctx.rotate((imageLayer.rotation * Math.PI) / 180);
          const w = imageLayer.originalWidth * imageLayer.scale;
          const h = imageLayer.originalHeight * imageLayer.scale;
          ctx.drawImage(lImg, -w / 2, -h / 2, w, h);
          ctx.globalAlpha = 1.0;
          ctx.restore();
        }
      }

    } else if (layer.type === 'drawing') {
      const stroke = drawingStrokes.find(s => s.id === layer.id);
      if (stroke) {
        if (stroke.points.length < 2) continue;
        ctx.save();
        ctx.globalAlpha = stroke.opacity;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        const tracePath = () => {
          ctx.beginPath();
          ctx.moveTo(stroke.points[0].x, stroke.points[0].y);
          for (let i = 1; i < stroke.points.length; i++) {
            ctx.lineTo(stroke.points[i].x, stroke.points[i].y);
          }
        };
        if (stroke.outlineWidth && stroke.outlineWidth > 0) {
          tracePath();
          ctx.strokeStyle = stroke.outlineColor || '#ffffff';
          ctx.lineWidth = stroke.width + (stroke.outlineWidth * 2);
          ctx.stroke();
        }
        tracePath();
        ctx.strokeStyle = stroke.color;
        ctx.lineWidth = stroke.width;
        ctx.stroke();
        ctx.globalAlpha = 1.0;
        ctx.restore();
      }
    }
  }

※ 旧コードの「背面テキスト→背面画像レイヤー→背面手書き→メイン画像→
  前面手書き→前面画像レイヤー→前面テキスト」の固定順の描画コードは
  全て削除して、上記のforループに置き換えてください。

■ 5. StampEditorModal の drawCanvas も同じ描画順に変更

StampEditorModal 内の drawCanvas 関数でも、
layerOrder ベースの描画順に変更してください。

import { getSortedLayers, ensureLayerOrder, getNextLayerOrder } from '../lib/layerUtils';

StampEditorModal に mainImageLayerOrder の state を追加：
  const [mainImageLayerOrder, setMainImageLayerOrder] = useState(
    stamp.mainImageLayerOrder ?? 100
  );

isOpen の useEffect で初期化：
  setMainImageLayerOrder(stamp.mainImageLayerOrder ?? 100);

drawCanvas 内の描画を layerOrder ベースに変更。
ただし、エディタ固有のUI要素（選択ハンドル、カーソル等）は
全レイヤー描画後に描画してください：

  // レイヤー描画
  const sortedLayers = getSortedLayers(textObjects, imageLayers, drawingStrokes, mainImageLayerOrder);

  for (const layer of sortedLayers) {
    if (layer.type === 'mainImage') {
      // スタンプ画像本体（既存のメイン画像描画コード）
      // ※ 反転対応含む
    } else if (layer.type === 'text') {
      const textObj = textObjects.find(t => t.id === layer.id);
      if (textObj) drawTextWithSelection(ctx, textObj);
    } else if (layer.type === 'imageLayer') {
      const imageLayer = imageLayers.find(l => l.id === layer.id);
      if (imageLayer) {
        const cachedImg = imageLayerCacheRef.current.get(imageLayer.id);
        if (cachedImg) drawImageLayer(ctx, imageLayer, cachedImg);
      }
    } else if (layer.type === 'drawing') {
      const stroke = drawingStrokes.find(s => s.id === layer.id);
      if (stroke) drawStroke(ctx, stroke);
    }
  }

  // 描画中のストローク（currentStroke）
  // カーソル表示
  // 移動モードのハンドル
  // ※ これらは全レイヤーの後に描画

※ メイン画像のハンドル描画は、forループ内ではなく、
  全レイヤー描画後にまとめて描画してください。

■ 6. 新規レイヤー作成時に layerOrder を付与

テキスト追加（handleAddText）：
  const newText: TextObject = {
    ...
    zIndex: 'front',
    layerOrder: getNextLayerOrder(textObjects, imageLayers, drawingStrokes, mainImageLayerOrder, 'front'),
    ...
  };

画像レイヤー追加（handleAddImageLayer / handleAddFromMaterial）：
  const newLayer: ImageLayerObject = {
    ...
    zIndex: 'front',
    layerOrder: getNextLayerOrder(textObjects, imageLayers, drawingStrokes, mainImageLayerOrder, 'front'),
    ...
  };

手書きストローク完了時（handlePointerUp 内）：
  const newStroke: DrawingStroke = {
    ...
    zIndex: penZIndex,
    layerOrder: getNextLayerOrder(textObjects, imageLayers, drawingStrokes, mainImageLayerOrder, penZIndex),
    ...
  };

■ 7. 前面/背面トグル時に layerOrder を更新

現在の前面/背面切り替えボタンは既存のまま動作させます。
ただし切り替え時に layerOrder も更新するようにしてください。

テキストの前面/背面切り替え：
  handleUpdateText(selectedText.id, { 
    zIndex: newZIndex,
    layerOrder: getNextLayerOrder(textObjects, imageLayers, drawingStrokes, mainImageLayerOrder, newZIndex)
  });

画像レイヤーの前面/背面切り替え：
  handleUpdateImageLayer(selectedImageLayerId, { 
    zIndex: newZIndex,
    layerOrder: getNextLayerOrder(textObjects, imageLayers, drawingStrokes, mainImageLayerOrder, newZIndex)
  });

手書きの前面/背面切り替え（penZIndex の変更時）：
  ※ 手書きは描画時に penZIndex を使うので、既存ストロークの
    zIndex は変更不要。新規ストロークに反映されればOK。

■ 8. handleSave に mainImageLayerOrder を含める

  const updatedStamp: Stamp = {
    ...stamp,
    ...
    mainImageLayerOrder,
  };

■ 9. HistoryState に mainImageLayerOrder を追加

  mainImageLayerOrder: number;

addToHistory のデフォルト値に追加：
  mainImageLayerOrder,

undo / redo で復元：
  setMainImageLayerOrder(prevState.mainImageLayerOrder ?? 100);

■ 10. App.tsx の StampPreview も layerOrder ベースに

StampPreview 内の renderAllLayers 呼び出しで、config に
mainImageLayerOrder を含めてください：

  const config: ExportConfig = {
    ...
    mainImageLayerOrder: stamp.mainImageLayerOrder ?? 100,
  };

■ 11. テキスト一括追加（TextSetModal）に layerOrder を追加

handleApply 内の newTextObj に layerOrder を追加：
  layerOrder: 150 + validIndex,
  ※ 一括追加のテキストは全て前面扱い

■ 12. 保存/復元の互換性

lib/storage.ts の sanitizedStamps 内で、
既存データに layerOrder がない場合のデフォルト値を補完：

  textObjects: (s.textObjects ?? []).map((t, i) => ({
    ...t,
    layerOrder: t.layerOrder ?? (t.zIndex === 'back' ? 10 + i : 150 + i),
    outlineColor: t.outlineColor ?? '#ffffff',
    outlineWidth: t.outlineWidth ?? 4,
  })),
  imageLayers: (s.imageLayers ?? []).map((l, i) => ({
    ...l,
    layerOrder: l.layerOrder ?? (l.zIndex === 'back' ? 30 + i : 170 + i),
  })),
  drawingStrokes: (s.drawingStrokes ?? []).map((d, i) => ({
    ...d,
    layerOrder: d.layerOrder ?? (d.zIndex === 'back' ? 20 + i : 160 + i),
    outlineColor: d.outlineColor ?? '#ffffff',
    outlineWidth: d.outlineWidth ?? 0,
  })),
  mainImageLayerOrder: s.mainImageLayerOrder ?? 100,

handleRestore 内でも同様に補完。

■ 13. useEffect の依存配列

drawCanvas の依存配列に mainImageLayerOrder を追加。

■ 14. 確認事項

- 既存の全機能が修正前と同じように動作すること
- 前面に設定したテキスト・画像レイヤー・手書きがスタンプ画像の上に描画されること
- 背面に設定したものがスタンプ画像の下に描画されること
- ZIP書き出しの描画順が正しいこと
- 一覧プレビューの描画順が正しいこと
- メイン画像・タブ画像の描画順が正しいこと
- 保存・復元後もレイヤー順が維持されること
- テキスト一括追加が正常に動作すること
- Undo/Redo でレイヤー順が正しく戻ること
- ※ このステップではレイヤー順を変更するUI は不要。
  既存の前面/背面ボタンがそのまま動けばOK。

