■ 概要
各パネル（テキスト・画像レイヤー・手書き）と画像操作パネルに
レイヤーの描画順を変更できるUIを追加します。
「前面/背面」の2択ボタンを、「1つ上へ / 1つ下へ」ボタンに変更し、
さらに現在のレイヤー順が一目で分かるレイヤーリストを表示します。

■ 1. lib/layerUtils.ts にレイヤー移動関数を追加

  // レイヤーを1つ上（前面方向）に移動
  export function moveLayerUp(
    targetType: 'text' | 'imageLayer' | 'drawing' | 'mainImage',
    targetId: string,
    textObjects: TextObject[],
    imageLayers: ImageLayerObject[],
    drawingStrokes: DrawingStroke[],
    mainImageOrder: number
  ): { textObjects: TextObject[]; imageLayers: ImageLayerObject[]; drawingStrokes: DrawingStroke[]; mainImageLayerOrder: number } {
    const sorted = getSortedLayers(textObjects, imageLayers, drawingStrokes, mainImageOrder);
    const currentIndex = sorted.findIndex(l => l.type === targetType && l.id === targetId);
    if (currentIndex === -1 || currentIndex === sorted.length - 1) {
      return { textObjects, imageLayers, drawingStrokes, mainImageLayerOrder: mainImageOrder };
    }

    // 1つ上のレイヤーと layerOrder を交換
    const current = sorted[currentIndex];
    const above = sorted[currentIndex + 1];

    return applySwap(current, above, textObjects, imageLayers, drawingStrokes, mainImageOrder);
  }

  // レイヤーを1つ下（背面方向）に移動
  export function moveLayerDown(
    targetType: 'text' | 'imageLayer' | 'drawing' | 'mainImage',
    targetId: string,
    textObjects: TextObject[],
    imageLayers: ImageLayerObject[],
    drawingStrokes: DrawingStroke[],
    mainImageOrder: number
  ): { textObjects: TextObject[]; imageLayers: ImageLayerObject[]; drawingStrokes: DrawingStroke[]; mainImageLayerOrder: number } {
    const sorted = getSortedLayers(textObjects, imageLayers, drawingStrokes, mainImageOrder);
    const currentIndex = sorted.findIndex(l => l.type === targetType && l.id === targetId);
    if (currentIndex === -1 || currentIndex === 0) {
      return { textObjects, imageLayers, drawingStrokes, mainImageLayerOrder: mainImageOrder };
    }

    const current = sorted[currentIndex];
    const below = sorted[currentIndex - 1];

    return applySwap(current, below, textObjects, imageLayers, drawingStrokes, mainImageOrder);
  }

  // 2つのレイヤーの layerOrder を交換する内部関数
  function applySwap(
    a: LayerItem,
    b: LayerItem,
    textObjects: TextObject[],
    imageLayers: ImageLayerObject[],
    drawingStrokes: DrawingStroke[],
    mainImageOrder: number
  ): { textObjects: TextObject[]; imageLayers: ImageLayerObject[]; drawingStrokes: DrawingStroke[]; mainImageLayerOrder: number } {
    const orderA = a.layerOrder;
    const orderB = b.layerOrder;

    let newTexts = [...textObjects];
    let newImages = [...imageLayers];
    let newStrokes = [...drawingStrokes];
    let newMainOrder = mainImageOrder;

    const setOrder = (item: LayerItem, newOrder: number) => {
      if (item.type === 'text') {
        newTexts = newTexts.map(t => t.id === item.id ? { ...t, layerOrder: newOrder } : t);
      } else if (item.type === 'imageLayer') {
        newImages = newImages.map(l => l.id === item.id ? { ...l, layerOrder: newOrder } : l);
      } else if (item.type === 'drawing') {
        newStrokes = newStrokes.map(s => s.id === item.id ? { ...s, layerOrder: newOrder } : s);
      } else if (item.type === 'mainImage') {
        newMainOrder = newOrder;
      }
    };

    setOrder(a, orderB);
    setOrder(b, orderA);

    return {
      textObjects: newTexts,
      imageLayers: newImages,
      drawingStrokes: newStrokes,
      mainImageLayerOrder: newMainOrder,
    };
  }

  // レイヤーの表示名を取得
  export function getLayerDisplayName(
    item: LayerItem,
    textObjects: TextObject[],
    imageLayers: ImageLayerObject[],
    drawingStrokes: DrawingStroke[]
  ): string {
    if (item.type === 'mainImage') return 'スタンプ画像';
    if (item.type === 'text') {
      const t = textObjects.find(x => x.id === item.id);
      return t ? `文字「${t.text.substring(0, 6)}${t.text.length > 6 ? '…' : ''}」` : '文字';
    }
    if (item.type === 'imageLayer') return '画像レイヤー';
    if (item.type === 'drawing') return '手書き';
    return '不明';
  }

■ 2. components/editor/LayerOrderPanel.tsx を新規作成

全モード共通で表示するレイヤー順リスト + 上下ボタンのパネルです。

  import React from 'react';
  import { ChevronUp, ChevronDown, Image, Type, Pen, Star } from 'lucide-react';
  import { LayerItem } from '../../lib/layerUtils';
  import { TextObject, ImageLayerObject, DrawingStroke } from '../../types';

  interface LayerOrderPanelProps {
    layers: LayerItem[];
    textObjects: TextObject[];
    imageLayers: ImageLayerObject[];
    drawingStrokes: DrawingStroke[];
    selectedType?: 'text' | 'imageLayer' | 'drawing' | 'mainImage' | null;
    selectedId?: string | null;
    onMoveUp: (type: string, id: string) => void;
    onMoveDown: (type: string, id: string) => void;
    onSelect: (type: string, id: string) => void;
    getLayerName: (item: LayerItem) => string;
  }

  export const LayerOrderPanel: React.FC<LayerOrderPanelProps> = ({
    layers, textObjects, imageLayers, drawingStrokes,
    selectedType, selectedId, onMoveUp, onMoveDown, onSelect, getLayerName
  }) => {
    // 上（前面）が上に来るように逆順で表示
    const displayLayers = [...layers].reverse();

    const getIcon = (type: string) => {
      switch (type) {
        case 'mainImage': return <Star size={12} className="text-green-500" />;
        case 'text': return <Type size={12} className="text-blue-500" />;
        case 'imageLayer': return <Image size={12} className="text-purple-500" />;
        case 'drawing': return <Pen size={12} className="text-orange-500" />;
        default: return null;
      }
    };

    const isSelected = (item: LayerItem) => {
      return item.type === selectedType && item.id === selectedId;
    };

    if (layers.length <= 1) return null;

    return (
      <div className="bg-gray-50 rounded-lg border border-gray-200 p-2">
        <div className="flex items-center justify-between mb-1">
          <span className="text-[10px] font-bold text-gray-400">レイヤー順（上が前面）</span>
        </div>
        <div className="flex flex-col gap-0.5 max-h-32 overflow-y-auto">
          {displayLayers.map((item, displayIndex) => {
            const actualIndex = layers.length - 1 - displayIndex;
            const isFirst = actualIndex === layers.length - 1; // 最前面
            const isLast = actualIndex === 0; // 最背面
            const selected = isSelected(item);

            return (
              <div
                key={`${item.type}-${item.id}`}
                onClick={() => onSelect(item.type, item.id)}
                className={`flex items-center gap-1 px-2 py-1 rounded text-xs cursor-pointer transition
                  ${selected ? 'bg-primary-100 border border-primary-300' : 'hover:bg-gray-100 border border-transparent'}`}
              >
                {getIcon(item.type)}
                <span className={`flex-1 truncate ${selected ? 'font-bold text-gray-700' : 'text-gray-500'}`}>
                  {getLayerName(item)}
                </span>
                <div className="flex items-center gap-0.5 shrink-0">
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); if (!isFirst) onMoveUp(item.type, item.id); }}
                    disabled={isFirst}
                    className="p-0.5 rounded hover:bg-gray-200 disabled:opacity-20 disabled:hover:bg-transparent"
                    title="1つ前面へ"
                  >
                    <ChevronUp size={12} />
                  </button>
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); if (!isLast) onMoveDown(item.type, item.id); }}
                    disabled={isLast}
                    className="p-0.5 rounded hover:bg-gray-200 disabled:opacity-20 disabled:hover:bg-transparent"
                    title="1つ背面へ"
                  >
                    <ChevronDown size={12} />
