      const adjustedLocalX = flipH ? -localX : localX; const adjustedLocalY = flipV ? -localY : localY;
      const imgX = (adjustedLocalX + drawnW / 2) / scale; const imgY = (adjustedLocalY + drawnH / 2) / scale;
