export async function removeGridLines(
  file: File,
  options?: {
    lineThickness?: number;    // この太さ以下を線とみなす（デフォルト8px）
    colorThreshold?: number;   // この明度以下を暗い線とみなす（デフォルト100）
    minLineLength?: number;    // この長さ以上を直線とみなす（画像幅/高さの割合、デフォルト0.2 = 20%）
  }
): Promise<File> {
  const lineThickness = options?.lineThickness ?? 8;
  const colorThresh = options?.colorThreshold ?? 100;
  const minLinePct = options?.minLineLength ?? 0.2;

  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (!ctx) return reject(new Error('Canvas context failed'));

      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;
      const w = canvas.width;
      const h = canvas.height;

      const minHLineLen = Math.floor(w * minLinePct);
      const minVLineLen = Math.floor(h * minLinePct);

      // 線ピクセル判定
      // r,g,b,a: ピクセル値
      // threshold: 暗い線の閾値
      const isLinePixel = (x: number, y: number): boolean => {
        const idx = (y * w + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        if (a < 128) return false; // 透明は無視

        const brightness = (r + g + b) / 3;

        // 1. 暗い色（黒〜濃いグレー）: 指定閾値以下
        if (brightness <= colorThresh) return true;

        // 2. 薄いグレー（明るい線）: AI生成のグリッド線によくあるパターン
        // 明るいが白(255)ではなく、彩度が低いもの
        const maxC = Math.max(r, g, b);
        const minC = Math.min(r, g, b);
        const saturation = maxC - minC;

        // 明るさ180〜250程度、彩度が低い(30未満)ものをグレーの線とみなす
        if (brightness >= 180 && brightness <= 250 && saturation < 30) {
            return true;
        }

        return false;
      };

      // ピクセルを白にする
      const setWhite = (x: number, y: number) => {
        const idx = (y * w + x) * 4;
        data[idx] = 255;
        data[idx + 1] = 255;
        data[idx + 2] = 255;
        data[idx + 3] = 255;
      };

      // 外枠線除去処理
      // 画像の端から内側に向かってスキャンし、連続する線ピクセルの行/列を除去する
      const removeBorderLines = (maxBorderWidth: number = 15) => {
        // 上辺: y = 0 から下へ
        for (let y = 0; y < maxBorderWidth && y < h; y++) {
            let linePixelCount = 0;
            for (let x = 0; x < w; x++) {
                if (isLinePixel(x, y)) linePixelCount++;
            }
            // 行の80%以上が線ピクセルなら、その行を白にする
            if (linePixelCount / w >= 0.8) {
                for (let x = 0; x < w; x++) setWhite(x, y);
            } else {
                break; // 連続していない行に達したら停止
            }
        }

        // 下辺: y = h-1 から上へ
        for (let y = h - 1; y >= h - maxBorderWidth && y >= 0; y--) {
            let linePixelCount = 0;
            for (let x = 0; x < w; x++) {
                if (isLinePixel(x, y)) linePixelCount++;
            }
            if (linePixelCount / w >= 0.8) {
                for (let x = 0; x < w; x++) setWhite(x, y);
            } else {
                break;
            }
        }

        // 左辺: x = 0 から右へ
        for (let x = 0; x < maxBorderWidth && x < w; x++) {
            let linePixelCount = 0;
            for (let y = 0; y < h; y++) {
                if (isLinePixel(x, y)) linePixelCount++;
            }
            if (linePixelCount / h >= 0.8) {
                for (let y = 0; y < h; y++) setWhite(x, y);
            } else {
                break;
            }
        }

        // 右辺: x = w-1 から左へ
        for (let x = w - 1; x >= w - maxBorderWidth && x >= 0; x--) {
            let linePixelCount = 0;
            for (let y = 0; y < h; y++) {
                if (isLinePixel(x, y)) linePixelCount++;
            }
            if (linePixelCount / h >= 0.8) {
                for (let y = 0; y < h; y++) setWhite(x, y);
            } else {
                break;
            }
        }
      };

      // 1. 外枠を除去
      removeBorderLines(20);

      // 2. 横線検出
      for (let y = 0; y < h; y++) {
        let consecutiveLinePixels = 0;
        let lineStartX = 0;
        const lineSegments: { start: number; end: number }[] = [];

        for (let x = 0; x < w; x++) {
          if (isLinePixel(x, y)) {
            if (consecutiveLinePixels === 0) lineStartX = x;
            consecutiveLinePixels++;
          } else {
            if (consecutiveLinePixels >= minHLineLen) {
              lineSegments.push({ start: lineStartX, end: x - 1 });
            }
            consecutiveLinePixels = 0;
          }
        }
        if (consecutiveLinePixels >= minHLineLen) {
          lineSegments.push({ start: lineStartX, end: w - 1 });
        }

        // 検出された横線セグメントを白にする
        for (const seg of lineSegments) {
          for (let dy = -Math.floor(lineThickness / 2); dy <= Math.floor(lineThickness / 2); dy++) {
            const ny = y + dy;
            if (ny < 0 || ny >= h) continue;
            for (let x = seg.start; x <= seg.end; x++) {
              if (isLinePixel(x, ny)) {
                setWhite(x, ny);
              }
            }
          }
        }
      }

      // 3. 縦線検出
      for (let x = 0; x < w; x++) {
        let consecutiveLinePixels = 0;
        let lineStartY = 0;
        const lineSegments: { start: number; end: number }[] = [];

        for (let y = 0; y < h; y++) {
          if (isLinePixel(x, y)) {
            if (consecutiveLinePixels === 0) lineStartY = y;
            consecutiveLinePixels++;
          } else {
            if (consecutiveLinePixels >= minVLineLen) {
              lineSegments.push({ start: lineStartY, end: y - 1 });
            }
            consecutiveLinePixels = 0;
          }
        }
        if (consecutiveLinePixels >= minVLineLen) {
          lineSegments.push({ start: lineStartY, end: h - 1 });
        }

        for (const seg of lineSegments) {
          for (let dx = -Math.floor(lineThickness / 2); dx <= Math.floor(lineThickness / 2); dx++) {
            const nx = x + dx;
            if (nx < 0 || nx >= w) continue;
            for (let y = seg.start; y <= seg.end; y++) {
              if (isLinePixel(nx, y)) {
                setWhite(nx, y);
              }
            }
          }
        }
      }

      ctx.putImageData(imageData, 0, 0);

      canvas.toBlob((blob) => {
        if (!blob) return reject(new Error('Blob conversion failed'));
        const newFile = new File([blob], file.name, { type: 'image/png' });
        resolve(newFile);
      }, 'image/png');
    };
    img.onerror = () => reject(new Error('Image load failed'));
    img.src = URL.createObjectURL(file);
  });
}

