■ グリッド線を検出したときだけ除去ボタンを表示する

【概要】
画像アップロード時にグリッド線の有無を自動判定し、
検出された場合のみ「グリッド線を除去する」ボタンを表示する。

【1】lib/gridRemoval.ts に検出専用の関数を追加

既存の removeGridLines 関数はそのまま残し、
新しく detectGridLines 関数を追加：

export async function detectGridLines(file: File): Promise<boolean> {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d')!;
      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, img.width, img.height);
      const { data, width, height } = imageData;

      const lineThickness = 4;
      const minLineLength = 0.3;

      // グレーの線ピクセル判定（既存ロジックと同じ基準）
      const isGrayLine = (r: number, g: number, b: number, a: number): boolean => {
        if (a < 128) return false;
        const brightness = (r + g + b) / 3;
        // 薄いグレー（明度160〜245、RGB差が小さい＝無彩色）
        return brightness >= 160 && brightness <= 245 
          && Math.abs(r - g) < 20 && Math.abs(g - b) < 20;
      };

      let detectedLines = 0;

      // 水平線の検出（画像の上端・下端の10%は除外）
      const yStart = Math.floor(height * 0.1);
      const yEnd = Math.floor(height * 0.9);
      for (let y = yStart; y < yEnd; y++) {
        let consecutive = 0;
        let maxConsecutive = 0;
        for (let x = 0; x < width; x++) {
          const idx = (y * width + x) * 4;
          if (isGrayLine(data[idx], data[idx+1], data[idx+2], data[idx+3])) {
            consecutive++;
            maxConsecutive = Math.max(maxConsecutive, consecutive);
          } else {
            consecutive = 0;
          }
        }
        if (maxConsecutive >= width * minLineLength) {
          // この行の前後 lineThickness 行以内に同様の線がないか確認
          // （太い線を1本としてカウント）
          detectedLines++;
          y += lineThickness; // 太さ分スキップ
        }
      }

      // 垂直線の検出（画像の左端・右端の10%は除外）
      const xStart = Math.floor(width * 0.1);
      const xEnd = Math.floor(width * 0.9);
      for (let x = xStart; x < xEnd; x++) {
        let consecutive = 0;
        let maxConsecutive = 0;
        for (let y = 0; y < height; y++) {
          const idx = (y * width + x) * 4;
          if (isGrayLine(data[idx], data[idx+1], data[idx+2], data[idx+3])) {
            consecutive++;
            maxConsecutive = Math.max(maxConsecutive, consecutive);
          } else {
            consecutive = 0;
          }
        }
        if (maxConsecutive >= height * minLineLength) {
          detectedLines++;
          x += lineThickness;
        }
      }

      // 2本以上検出されたらグリッドありと判定
      resolve(detectedLines >= 2);
    };
    img.onerror = () => resolve(false);
    img.src = URL.createObjectURL(file);
  });
}

