export async function removeGridLines(
  file: File,
  options?: {
    lineThreshold?: number;    // この太さ以下を線とみなす（デフォルト4px）
    colorThreshold?: number;   // この明度以上を薄い線とみなす（デフォルト160）
    minLineLength?: number;    // この長さ以上を直線とみなす（画像幅/高さの割合、デフォルト0.3 = 30%）
  }
): Promise<File> {
  const lineThickness = options?.lineThreshold ?? 4;
  const colorThresh = options?.colorThreshold ?? 160;
  const minLinePct = options?.minLineLength ?? 0.3;

  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (!ctx) return reject(new Error('Canvas context failed'));

      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;
      const w = canvas.width;
      const h = canvas.height;

      const minHLineLen = Math.floor(w * minLinePct);
      const minVLineLen = Math.floor(h * minLinePct);

      // ピクセルの明度を取得（グレースケール近似）
      const getBrightness = (x: number, y: number): number => {
        const idx = (y * w + x) * 4;
        return (data[idx] + data[idx + 1] + data[idx + 2]) / 3;
      };

      // ピクセルが「線っぽい色」かどうか（薄いグレー〜中程度のグレー）
      const isLineColor = (x: number, y: number): boolean => {
        const idx = (y * w + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];
        if (a < 128) return false; // 透明は無視
        const brightness = (r + g + b) / 3;
        // 薄いグレー（明るめ）の線を検出
        // 彩度が低い（グレーに近い）ことも条件
        const maxC = Math.max(r, g, b);
        const minC = Math.min(r, g, b);
        const saturation = maxC - minC;
        return brightness >= colorThresh && saturation < 50;
      };

      // ピクセルを白にする
      const setWhite = (x: number, y: number) => {
        const idx = (y * w + x) * 4;
        data[idx] = 255;
        data[idx + 1] = 255;
        data[idx + 2] = 255;
        data[idx + 3] = 255;
      };

      // --- 横線検出 ---
      for (let y = 0; y < h; y++) {
        // この行が「線」かチェック
        // lineThickness 分の行をまとめてチェック
        let consecutiveLinePixels = 0;
        let lineStartX = 0;
        const lineSegments: { start: number; end: number }[] = [];

        for (let x = 0; x < w; x++) {
          if (isLineColor(x, y)) {
            if (consecutiveLinePixels === 0) lineStartX = x;
            consecutiveLinePixels++;
          } else {
            if (consecutiveLinePixels >= minHLineLen) {
              lineSegments.push({ start: lineStartX, end: x - 1 });
            }
            consecutiveLinePixels = 0;
          }
        }
        if (consecutiveLinePixels >= minHLineLen) {
          lineSegments.push({ start: lineStartX, end: w - 1 });
        }

        // 検出された横線セグメントを白にする
        for (const seg of lineSegments) {
          // この行と前後 lineThickness/2 行も含めて白にする
          for (let dy = -Math.floor(lineThickness / 2); dy <= Math.floor(lineThickness / 2); dy++) {
            const ny = y + dy;
            if (ny < 0 || ny >= h) continue;
            for (let x = seg.start; x <= seg.end; x++) {
              // 線の色のピクセルだけ白にする（キャラの上を消さないように）
              if (isLineColor(x, ny)) {
                setWhite(x, ny);
              }
            }
          }
        }
      }

      // --- 縦線検出 ---
      for (let x = 0; x < w; x++) {
        let consecutiveLinePixels = 0;
        let lineStartY = 0;
        const lineSegments: { start: number; end: number }[] = [];

        for (let y = 0; y < h; y++) {
          if (isLineColor(x, y)) {
            if (consecutiveLinePixels === 0) lineStartY = y;
            consecutiveLinePixels++;
          } else {
            if (consecutiveLinePixels >= minVLineLen) {
              lineSegments.push({ start: lineStartY, end: y - 1 });
            }
            consecutiveLinePixels = 0;
          }
        }
        if (consecutiveLinePixels >= minVLineLen) {
          lineSegments.push({ start: lineStartY, end: h - 1 });
        }

        for (const seg of lineSegments) {
          for (let dx = -Math.floor(lineThickness / 2); dx <= Math.floor(lineThickness / 2); dx++) {
            const nx = x + dx;
            if (nx < 0 || nx >= w) continue;
            for (let y = seg.start; y <= seg.end; y++) {
              if (isLineColor(nx, y)) {
                setWhite(nx, y);
              }
            }
          }
        }
      }

      ctx.putImageData(imageData, 0, 0);

      canvas.toBlob((blob) => {
        if (!blob) return reject(new Error('Blob conversion failed'));
        const newFile = new File([blob], file.name, { type: 'image/png' });
        resolve(newFile);
      }, 'image/png');
    };
    img.onerror = () => reject(new Error('Image load failed'));
    img.src = URL.createObjectURL(file);
  });
}

export async function detectGridLines(file: File): Promise<boolean> {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const img = new Image();

    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) {
        URL.revokeObjectURL(url);
        return resolve(false);
      }

      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, img.width, img.height);
      const { data, width, height } = imageData;
      URL.revokeObjectURL(url);

      const lineThickness = 4;
      const minLineLength = 0.3; // 30%

      // グレーの線ピクセル判定
      const isGrayLine = (idx: number): boolean => {
        const r = data[idx];
        const g = data[idx+1];
        const b = data[idx+2];
        const a = data[idx+3];

        if (a < 128) return false;

        const brightness = (r + g + b) / 3;
        const maxC = Math.max(r, g, b);
        const minC = Math.min(r, g, b);
        const saturation = maxC - minC;

        // 薄いグレー（明度160〜245、彩度が低い）
        return brightness >= 160 && brightness <= 245 && saturation < 50;
      };

      let detectedLines = 0;

      // 水平線の検出（画像の上端・下端の10%は除外）
      const yStart = Math.floor(height * 0.1);
      const yEnd = Math.floor(height * 0.9);

      for (let y = yStart; y < yEnd; y++) {
        let consecutive = 0;
        let maxConsecutive = 0;
        for (let x = 0; x < width; x++) {
          if (isGrayLine((y * width + x) * 4)) {
            consecutive++;
            maxConsecutive = Math.max(maxConsecutive, consecutive);
          } else {
            consecutive = 0;
          }
        }
        if (maxConsecutive >= width * minLineLength) {
          detectedLines++;
          y += lineThickness; // 太さ分スキップ
        }
      }

      // 垂直線の検出（画像の左端・右端の10%は除外）
      const xStart = Math.floor(width * 0.1);
      const xEnd = Math.floor(width * 0.9);

      for (let x = xStart; x < xEnd; x++) {
        let consecutive = 0;
        let maxConsecutive = 0;
        for (let y = 0; y < height; y++) {
          if (isGrayLine((y * width + x) * 4)) {
            consecutive++;
            maxConsecutive = Math.max(maxConsecutive, consecutive);
          } else {
            consecutive = 0;
          }
        }
        if (maxConsecutive >= height * minLineLength) {
          detectedLines++;
          x += lineThickness;
        }
      }

      // 2本以上あればグリッドありとみなす
      resolve(detectedLines >= 2);
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      resolve(false);
    };
    img.src = url;
  });
}

