          rotation: 0,
          flipH: false,
          flipV: false,
          textObjects: stamp.textObjects ? JSON.parse(JSON.stringify(stamp.textObjects)) : [],
          imageLayers: stamp.imageLayers ? JSON.parse(JSON.stringify(stamp.imageLayers)) : [],
